fn shouldUseQ8_0ActivationQuant(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!q8_0ActivationQuantEnabled()) return false;
    if (out_dim < 512 or row_blocks < 3) return false;
    if (rows >= 16) return true;
    // Q8_0 f32-input decode remains memory dominated for CLIP/CLAP pooled
    // projections. Quantizing the small activation row once lets us reuse the
    // int8-dot prepared panel kernel instead of rereading/scaling f32 blocks
    // for every output column.
    return true;
}

fn shouldUseQ8_0GroupedActivationPair(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!shouldUseQ8_0ActivationQuant(rows, out_dim, row_blocks)) return false;
    if (rows >= 77 and out_dim >= 512) return false;
    return true;
}

fn shouldUseQ8_1GroupedActivationPair(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!shouldUseQ8_0ActivationQuant(rows, out_dim, row_blocks)) return false;
    if (rows >= 197 and out_dim >= 512) return false;
    return true;
}

fn shouldUseQ8_1GroupedActivationTriple(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!shouldUseQ8_0ActivationQuant(rows, out_dim, row_blocks)) return false;
    if (rows >= 77 and out_dim >= 512) return false;
    return true;
}

fn shouldUseQ8_0GroupedActivationTriple(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!shouldUseQ8_0ActivationQuant(rows, out_dim, row_blocks)) return false;
    if (rows == 77 and out_dim >= 512) return false;
    return true;
}

fn q8_0GroupedInterleavedOverride() ?bool {
    return null;
}

fn q8_0GroupedInterleavedEnabledForShape(rows: usize, out_dim: usize, row_blocks: usize, projection_count: usize) bool {
    if (q8_0GroupedInterleavedOverride()) |forced| return forced;
    _ = row_blocks;
    if (projection_count != 2 and projection_count != 3) return false;
    if (projection_count == 2 and rows >= 77 and out_dim >= 512) return false;
    return true;
}

fn shouldUseKFamilyQ8KActivationShape(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (out_dim < 512 or row_blocks < 1) return false;
    if (rows >= 16) return true;
    // Single-token pooled/MLP projections are dominated by repeated f32
    // dequant work. For CLIP/CLAP-sized K (768 => 3 QK blocks), quantizing
    // activations once and using the int8-dot direct kernel wins without
    // falling back to dequant-SGEMM.
    if (row_blocks >= 3) return true;
    return false;
}

fn shouldUseQ4Q5KQ8KActivationShape(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (out_dim < 512 or row_blocks < 1) return false;
    if (!(row_blocks == 2 or row_blocks == 3 or row_blocks == 6 or row_blocks == 8 or row_blocks == 12)) return false;

    // Keep q4/q5 activation quantization on the CLIP/CLAP-style buckets that
    // were measured. GLiNER extractor rows can be numerically sensitive near
    // extraction thresholds and should fall through to dense-dequant SGEMM.
    if (rows == 1 or rows == 2 or rows == 4 or rows == 9) return true;
    if (rows == 50 or rows == 64 or rows == 77 or rows == 197 or rows == 257 or rows == 308 or rows == 514) return true;
    if (rows > 0 and rows <= 308 and rows % 77 == 0) return true;
    return false;
}

fn shouldUseQ6_KQ8KActivationQuant(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!q6_kQ8KActivationQuantEnabled()) return false;
    return shouldUseKFamilyQ8KActivationShape(rows, out_dim, row_blocks);
}

fn shouldUseQ4_Q5_KQ8KActivationQuant(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!q4_q5_kQ8KActivationQuantEnabled()) return false;
    return shouldUseQ4Q5KQ8KActivationShape(rows, out_dim, row_blocks);
}

fn shouldUseQ8_KQ8KActivationQuant(rows: usize, out_dim: usize, row_blocks: usize) bool {
    if (!q8_kQ8KActivationQuantEnabled()) return false;
    return shouldUseKFamilyQ8KActivationShape(rows, out_dim, row_blocks);
}

fn convertTensorToOwnedF32(allocator: std.mem.Allocator, tensor: *const tensor_mod.Tensor) ![]f32 {
    return tensor.toOwnedF32(allocator);
}

fn convertTensorRowsToF32(
    tensor: *const tensor_mod.Tensor,
    row_start: usize,
    row_count: usize,
    row_width: usize,
    out: []f32,
) !void {
    std.debug.assert(out.len >= row_count * row_width);
    const elem_start = row_start * row_width;
    const elem_count = row_count * row_width;
    switch (tensor.dtype) {
        .f32 => {
            if (tensor.asFloat32IfAligned()) |src| {
                @memcpy(out[0..elem_count], src[elem_start .. elem_start + elem_count]);
            } else {
                const src_bytes: [*]const u8 = tensor.data.ptr;
                for (0..elem_count) |i| {
                    const offset = (elem_start + i) * 4;
                    const bits: u32 = @bitCast([4]u8{
                        src_bytes[offset],
                        src_bytes[offset + 1],
                        src_bytes[offset + 2],
                        src_bytes[offset + 3],
                    });
                    out[i] = @bitCast(bits);
                }
            }
        },
        .f16 => {
            const src_bytes: [*]const u8 = tensor.data.ptr;
            for (0..elem_count) |i| {
                const offset = (elem_start + i) * 2;
                const half: f16 = @bitCast([2]u8{ src_bytes[offset], src_bytes[offset + 1] });
                out[i] = @floatCast(half);
            }
        },
        .bf16 => {
            const src_bytes: [*]const u8 = tensor.data.ptr;
            for (0..elem_count) |i| {
                const offset = (elem_start + i) * 2;
                const bits: u16 = @bitCast([2]u8{ src_bytes[offset], src_bytes[offset + 1] });
                out[i] = @bitCast(@as(u32, bits) << 16);
            }
        },
        else => return error.UnsupportedTensorType,
    }
}

fn shouldBorrowEmbeddingTensor(name: []const u8) bool {
    return std.mem.eql(u8, name, "model.embed_tokens.weight") or
        std.mem.eql(u8, name, "language_model.embed_tokens.weight") or
        std.mem.eql(u8, name, "vision_tower.patch_embedder.position_embedding_table") or
        std.mem.eql(u8, name, "wte.weight");
}

fn shouldBorrowTypedWeightTensor(self: *const NativeCompute, name: []const u8, tensor: *const tensor_mod.Tensor) bool {
    if (shouldBorrowEmbeddingTensor(name)) return true;
    if (self.cache_embeddinggemma2_bf16_weights and !native.useBlas() and
        embeddinggemma2_weight_cache.nativeClass(name) != null and tensor.shape.len == 2 and
        tensor.shape[0] >= 64 and tensor.shape[1] >= 64 and
        (tensor.dtype == .bf16 or tensor.dtype == .f16)) return true;
    if (self.borrow_typed_matrix_weights and tensor.shape.len == 2 and
        (tensor.dtype == .f16 or tensor.dtype == .bf16)) return true;
    if (!self.borrow_bf16_linear_weights) return false;
    if (tensor.dtype != .bf16 or tensor.shape.len != 2) return false;
    if (std.mem.eql(u8, name, "lm_head.weight") or std.mem.eql(u8, name, "cls.output.weight")) return true;
    if (!std.mem.startsWith(u8, name, "model.layers.")) return false;
    return std.mem.endsWith(u8, name, ".self_attn.q_proj.weight") or
        std.mem.endsWith(u8, name, ".self_attn.k_proj.weight") or
        std.mem.endsWith(u8, name, ".self_attn.v_proj.weight") or
        std.mem.endsWith(u8, name, ".self_attn.o_proj.weight") or
        std.mem.endsWith(u8, name, ".mlp.gate_proj.weight") or
        std.mem.endsWith(u8, name, ".mlp.up_proj.weight") or
        std.mem.endsWith(u8, name, ".mlp.down_proj.weight");
}

// This existing lease also covers dense inputs: borrowed views do no cleanup,
// and each conversion owns only its own allocation, even for aliased inputs.
const WeightF32View = struct {
    data: []const f32,
    owned: ?[]f32 = null,

    inline fn deinit(view: @This(), allocator: std.mem.Allocator) void {
        if (view.owned) |owned| allocator.free(owned);
    }
};

fn denseWeightView(self: *NativeCompute, weight: CT) !WeightF32View {
    const buf = toBuf(weight);
    if (buf.data.len != 0) return .{ .data = buf.data };
    if (buf.source_tensor) |tensor| return tensorF32View(self, tensor);
    return error.MissingWeight;
}

fn denseTensorView(self: *NativeCompute, tensor: CT) !WeightF32View {
    const buf = toBuf(tensor);
    if (buf.data.len != 0 or buf.view_strides != null) return .{ .data = try getDataChecked(tensor) };
    if (buf.source_tensor) |source| return tensorF32View(self, source);
    if (buf.quantized_storage != null or buf.lazy_entry != null) {
        const converted = try toFloat32Op(self, tensor, self.allocator);
        return .{ .data = converted, .owned = converted };
    }
    return .{ .data = try getDataChecked(tensor) };
}

test "native dense input leases unwind converted aliased and borrowed inputs" {
    const Check = struct {
        fn run(a: std.mem.Allocator) !void {
            var store = WeightStore{ .allocator = a, .resident_weights = .{}, .lazy_weights = .{} };
            defer store.deinitOwned();
            var compute = NativeCompute.init(a, &store, null);
            defer compute.deinit();
            var half = [_]f16{ 1, 2, 3, 4 };
            const source = tensor_mod.Tensor{
                .data = std.mem.sliceAsBytes(half[0..]),
                .shape = &.{4},
                .dtype = .f16,
                .name = "lease",
                .allocator = a,
                .owns_data = false,
                .owns_shape = false,
            };
            const converted = try compute.makeBufWithEntry(empty_f32[0..], false, "lease", null, null, &source);
            defer freeTensor(&compute, converted);
            var values = [_]f32{ 1, 2, 3, 4 };
            const borrowed = try compute.makeBuf(&values, false);
            defer freeTensor(&compute, borrowed);
            for ([_]CT{ converted, borrowed }) |other| {
                const difference = try subtractOp(&compute, converted, other);
                defer freeTensor(&compute, difference);
                try std.testing.expectEqualSlices(f32, &.{ 0, 0, 0, 0 }, getData(difference));
                const quotient = try divideOp(&compute, converted, other);
                defer freeTensor(&compute, quotient);
                try std.testing.expectEqualSlices(f32, &.{ 1, 1, 1, 1 }, getData(quotient));
            }
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Check.run, .{});
}

fn borrowTensorF32IfAligned(tensor: *const tensor_mod.Tensor) ?[]const f32 {
    if (tensor.dtype != .f32) return null;
    return tensor.asFloat32IfAligned();
}

fn tensorF32View(self: *NativeCompute, tensor: *const tensor_mod.Tensor) !WeightF32View {
    if (borrowTensorF32IfAligned(tensor)) |data| {
        return .{ .data = data };
    }
    const converted = try convertTensorToOwnedF32(self.allocator, tensor);
    return .{ .data = converted, .owned = converted };
}

/// Row count from which f16 source-tensor linears convert weight blocks to
/// f32 and use system BLAS instead of the direct f16 kernel.
const f16_direct_gemm_max_rows_with_blas: usize = 32;

fn linearNoBiasSourceTensorChunked(
    self: *NativeCompute,
    input: []const f32,
    tensor: *const tensor_mod.Tensor,
    output: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    if (tensor.shape.len != 2) return error.UnsupportedTensorType;
    if (tensor.shape[0] != out_dim or tensor.shape[1] != in_dim) return error.ShapeMismatch;
    if (tensor.dtype != .f32 and tensor.dtype != .f16 and tensor.dtype != .bf16) {
        return error.UnsupportedTensorType;
    }
    if (rows == 0 or out_dim == 0) return;
    const weight_elements = std.math.mul(usize, in_dim, out_dim) catch return error.ShapeMismatch;
    const weight_bytes = tensor.dtype.byteCount(weight_elements) catch return error.ShapeMismatch;
    const input_elements = std.math.mul(usize, rows, in_dim) catch return error.ShapeMismatch;
    const output_elements = std.math.mul(usize, rows, out_dim) catch return error.ShapeMismatch;
    if (tensor.data.len != weight_bytes or input.len != input_elements or output.len != output_elements) return error.ShapeMismatch;

    // Fast path: f16 weights, naturally aligned, can be consumed directly by
    // sgemmTransBF16Weights without materializing an f32 copy.  This halves
    // the weight bandwidth -- the dominant cost for transformer linear ops.
    // Prefill-sized inputs are compute-bound instead; with system BLAS the
    // blocked f32 conversion below is several times faster there.
    if (tensor.dtype == .f16 and (rows < f16_direct_gemm_max_rows_with_blas or !native.useBlas())) {
        if (tensor.asFloat16IfAligned()) |weight_f16| {
            try self.dispatchSgemmTransBF16Weights(
                rows,
                out_dim,
                in_dim,
                1.0,
                input,
                weight_f16,
                0.0,
                output,
            );
            return;
        }
    }

    const target_weight_bytes: usize = 8 * 1024 * 1024;
    const scratch_row_elements = std.math.add(usize, in_dim, if (native.useBlas()) 0 else rows) catch return error.ShapeMismatch;
    const scratch_row_bytes = std.math.mul(usize, scratch_row_elements, @sizeOf(f32)) catch return error.ShapeMismatch;
    const block_rows = @max(@as(usize, 1), @min(out_dim, target_weight_bytes / @max(@as(usize, 1), scratch_row_bytes)));
    const scratch_bytes = std.math.mul(usize, block_rows, scratch_row_bytes) catch return error.ShapeMismatch;
    const scratch_estimate = run_memory.Estimate{
        .prompt_tokens = 0,
        .retained_tokens = 0,
        .kv_bytes = 0,
        .kv_tier = .host,
        .scratch_bytes = scratch_bytes,
        .scratch_tier = .host,
    };
    if (self.run_budget) |budget| try budget.reserveEstimate(scratch_estimate);
    defer if (self.run_budget) |budget| budget.releaseEstimate(scratch_estimate);
    const weight_block = try self.allocator.alloc(f32, block_rows * in_dim);
    defer self.allocator.free(weight_block);
    const output_block = try self.allocator.alloc(f32, if (native.useBlas()) 0 else rows * block_rows);
    defer self.allocator.free(output_block);

    var row_start: usize = 0;
    while (row_start < out_dim) : (row_start += block_rows) {
        if (self.io) |io| try io.checkCancel();
        const row_count = @min(block_rows, out_dim - row_start);
        try convertTensorRowsToF32(tensor, row_start, row_count, in_dim, weight_block[0 .. row_count * in_dim]);
        if (native.useBlas()) {
            try native.sgemmTransBStrided(
                self.io,
                rows,
                row_count,
                in_dim,
                1.0,
                input,
                weight_block[0 .. row_count * in_dim],
                0.0,
                output[row_start..],
                out_dim,
            );
            continue;
        }
        @memset(output_block[0 .. rows * row_count], 0.0);
        try self.dispatchSgemmTransB(
            rows,
            row_count,
            in_dim,
            1.0,
            input,
            weight_block[0 .. row_count * in_dim],
            0.0,
            output_block[0 .. rows * row_count],
        );
        for (0..rows) |r| {
            const src = output_block[r * row_count ..][0..row_count];
            const dst = output[r * out_dim + row_start ..][0..row_count];
            @memcpy(dst, src);
        }
    }
}

fn matmulRhsSourceTensorChunked(
    self: *NativeCompute,
    lhs: []const f32,
    rhs_tensor: *const tensor_mod.Tensor,
    output: []f32,
    m: usize,
    k: usize,
    n: usize,
) !void {
    if (rhs_tensor.shape.len != 2) return error.UnsupportedTensorType;
    if (rhs_tensor.shape[0] != k or rhs_tensor.shape[1] != n) return error.ShapeMismatch;
    if (rhs_tensor.dtype != .f32 and rhs_tensor.dtype != .f16 and rhs_tensor.dtype != .bf16) {
        return error.UnsupportedTensorType;
    }

    // Imported ONNX initializers already have row-major [K,N] f32 storage.
    // Pass that directly to BLAS instead of copying and transposing every
    // model weight on every request. Reduced/unaligned storage stays bounded.
    if (borrowTensorF32IfAligned(rhs_tensor)) |rhs| {
        return self.dispatchSgemm(m, n, k, 1.0, lhs, rhs, 1.0, output);
    }

    const target_weight_bytes: usize = 8 * 1024 * 1024;
    const k_block = @max(@as(usize, 1), @min(k, target_weight_bytes / (@max(@as(usize, 1), n) * @sizeOf(f32))));
    const lhs_block = try self.allocator.alloc(f32, m * k_block);
    defer self.allocator.free(lhs_block);
    const rhs_block = try self.allocator.alloc(f32, k_block * n);
    defer self.allocator.free(rhs_block);
    const rhs_block_transposed = try self.allocator.alloc(f32, n * k_block);
    defer self.allocator.free(rhs_block_transposed);

    var k_start: usize = 0;
    while (k_start < k) : (k_start += k_block) {
        const cur_k = @min(k_block, k - k_start);
        for (0..m) |row| {
            @memcpy(
                lhs_block[row * cur_k ..][0..cur_k],
                lhs[row * k + k_start ..][0..cur_k],
            );
        }
        try convertTensorRowsToF32(rhs_tensor, k_start, cur_k, n, rhs_block[0 .. cur_k * n]);
        for (0..cur_k) |ki| {
            for (0..n) |j| {
                rhs_block_transposed[j * cur_k + ki] = rhs_block[ki * n + j];
            }
        }
        try self.dispatchSgemmTransB(
            m,
            n,
            cur_k,
            1.0,
            lhs_block[0 .. m * cur_k],
            rhs_block_transposed[0 .. n * cur_k],
            1.0,
            output,
        );
    }
}

fn linearNoBiasLazyEntryChunked(
    self: *NativeCompute,
    input: []const f32,
    entry: *LazyWeightEntry,
    output: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    var maybe_loaded: ?LoadedWeight = null;
    defer if (maybe_loaded) |*loaded| loaded.deinit();
    const tensor: *const tensor_mod.Tensor = if (entry.loaded) |*loaded|
        if (loaded.quantized_storage == null) &loaded.tensor else return error.UnsupportedTensorType
    else blk: {
        const tensor_store = self.data.tensor_store orelse return error.MissingWeight;
        maybe_loaded = try tensor_store.loadTensorRef(&entry.tensor_ref);
        if (maybe_loaded.?.quantized_storage != null) return error.UnsupportedTensorType;
        break :blk &maybe_loaded.?.tensor;
    };
    // Forwards to the source-tensor path which handles the f16-aligned fast
    // path internally; this means lazy-loaded f16 weights also skip the
    // f16->f32 materialization step.
    try linearNoBiasSourceTensorChunked(self, input, tensor, output, rows, in_dim, out_dim);
}

fn loadEphemeralQuantizedLazyWeight(
    self: *NativeCompute,
    entry: *LazyWeightEntry,
    name: []const u8,
    prepare_matrix: bool,
) !?CT {
    if (!shouldDegradeQuantBudgetPressure(entry)) return null;
    const tensor_store = self.data.tensor_store orelse return null;
    var storage = (try tensor_store.loadQuantizedStorageRef(&entry.tensor_ref)) orelse return null;
    errdefer storage.deinit();
    if (prepare_matrix) try prepareNativeQuantizedStorage(&storage);
    return self.makeBufWithOwnedQuantizedStorage(name, entry, storage);
}

/// Weight storage and activation arithmetic are independent contracts. The
/// automatic profile preserves existing shape-selected Q8 activation kernels;
/// strict_f32 never rounds activations before a quantized weight projection.
pub const QuantizedActivationPolicy = enum { automatic, strict_f32 };

pub const NativeCompute = struct {
    allocator: std.mem.Allocator,
    data: *WeightStore,
    run_budget: ?*run_memory.RunBudget = null,
    quantized_activation_policy: QuantizedActivationPolicy = .automatic,
    weight_reservations: std.StringHashMapUnmanaged(ReservationState) = .empty,
    /// Opt in only for qualified model families whose projection consumers
    /// accept typed weights. Other native/PJRT callers keep their load policy.
    borrow_bf16_linear_weights: bool = false,
    /// Borrow every resident 2-D f16/bf16 weight for typed GEMM. Only for
    /// sessions whose 2-D weights are consumed exclusively by linear ops
    /// (native Moondream reads its embedding table on the host).
    borrow_typed_matrix_weights: bool = false,
    /// Granted only to immutable EmbeddingGemma2 inference sessions. The
    /// WeightStore owns admitted mirrors; request contexts only borrow them.
    cache_embeddinggemma2_bf16_weights: bool = false,
    embeddinggemma2_cache_reader: bool = false,
    weight_handles: std.StringHashMapUnmanaged(CT) = .empty,
    /// Optional Io for parallel GEMM dispatch.  When non-null, sgemm calls
    /// route through linalg's Io-aware variants and parallel work is
    /// scheduled on the runtime's thread pool.  When null, sgemm uses the
    /// process-wide futex pool inside lib/linalg directly.  Tests typically
    /// pass null; production session creation supplies the application's Io.
    io: ?std.Io = null,

    pub fn init(allocator: std.mem.Allocator, data: *WeightStore, run_budget: ?*run_memory.RunBudget) NativeCompute {
        initPrefetchQueue(data, allocator);
        return .{ .allocator = allocator, .data = data, .run_budget = run_budget };
    }

    pub fn initWithIo(
        allocator: std.mem.Allocator,
        data: *WeightStore,
        run_budget: ?*run_memory.RunBudget,
        io: std.Io,
    ) NativeCompute {
        initPrefetchQueue(data, allocator);
        return .{ .allocator = allocator, .data = data, .run_budget = run_budget, .io = io };
    }

    /// Release context-owned handles and reservations without destroying self.
    /// Stack/embedded owners must call this after releasing caller-owned tensors
    /// and before tearing down the borrowed weight store or run budget.
    pub fn deinit(self: *NativeCompute) void {
        deinitWeightHandles(self);
        if (self.embeddinggemma2_cache_reader) {
            platform.sync.lockYielding(&self.data.embeddinggemma2_f32_cache_lock);
            self.data.embeddinggemma2_f32_readers -= 1;
            self.data.embeddinggemma2_f32_cache_lock.unlock();
            self.embeddinggemma2_cache_reader = false;
        }
        var it = self.weight_reservations.iterator();
        while (it.next()) |entry| {
            if (self.run_budget) |budget| budget.release(entry.value_ptr.reservation);
            self.allocator.free(entry.key_ptr.*);
        }
        self.weight_reservations.deinit(self.allocator);
        self.weight_reservations = .empty;
    }

    // Dispatchers select the canonical Io API when this backend was constructed
    // with one; otherwise fall through to the *Sync escape hatch.  Cancellation
    // mid-matmul leaves C in a partial state -- caller's `errdefer` paths must
    // assume the output buffer is incompletely written when error.Canceled
    // surfaces.

    inline fn dispatchSgemmTransB(
        self: *const NativeCompute,
        m: usize,
        n: usize,
        k: usize,
        alpha: f32,
        a: []const f32,
        b: []const f32,
        beta: f32,
        c_out: []f32,
    ) error{Canceled}!void {
        if (self.io) |io| {
            return native.sgemmTransB(io, m, n, k, alpha, a, b, beta, c_out);
        }
        native.sgemmTransBSync(m, n, k, alpha, a, b, beta, c_out);
    }

    inline fn dispatchSgemm(
        self: *const NativeCompute,
        m: usize,
        n: usize,
        k: usize,
        alpha: f32,
        a: []const f32,
        b: []const f32,
        beta: f32,
        c_out: []f32,
    ) error{Canceled}!void {
        if (self.io) |io| {
            return native.sgemm(io, m, n, k, alpha, a, b, beta, c_out);
        }
        native.sgemmSync(m, n, k, alpha, a, b, beta, c_out);
    }

    inline fn dispatchSgemmTransBF16Weights(
        self: *const NativeCompute,
        m: usize,
        n: usize,
        k: usize,
        alpha: f32,
        a: []const f32,
        b: []const f16,
        beta: f32,
        c_out: []f32,
    ) error{Canceled}!void {
        if (self.io) |io| {
            return native.sgemmTransBF16Weights(io, m, n, k, alpha, a, b, beta, c_out);
        }
        native.sgemmTransBF16WeightsSync(m, n, k, alpha, a, b, beta, c_out);
    }

    /// Backend deinit also destroys self and requires an allocator-created
    /// context. Stack/embedded owners instead call NativeCompute.deinit.
    pub fn computeBackend(self: *NativeCompute) ComputeBackend {
        return .{ .ptr = self, .vtable = &vtable_impl };
    }

    pub fn importHostTensor(self: *NativeCompute, tensor: *const tensor_mod.Tensor) !CT {
        switch (tensor.dtype) {
            .i8, .i16, .i32, .i64, .u8, .bool_ => return copyIntegerTensorWithShape(self, tensor, tensor.shape),
            else => {},
        }
        const converted = try convertTensorToOwnedF32(self.allocator, tensor);
        errdefer self.allocator.free(converted);
        return self.importDenseTensor(tensor.name, tensor.dtype, tensor.shape, converted);
    }

    pub fn importOwnedStaticTensor(self: *NativeCompute, tensor: tensor_mod.Tensor) !CT {
        const can_keep_typed = switch (tensor.dtype) {
            .i8, .i16, .i32, .i64, .u8, .bool_ => true,
            else => tensor.shape.len == 2 and (tensor.dtype == .f32 or tensor.dtype == .f16 or tensor.dtype == .bf16),
        };
        if (can_keep_typed) {
            return self.makeBufWithOwnedSourceTensor(tensor);
        }

        var owned_tensor = tensor;
        defer owned_tensor.deinit();
        const converted = try convertTensorToOwnedF32(self.allocator, &owned_tensor);
        errdefer self.allocator.free(converted);
        return self.importDenseTensor(owned_tensor.name, owned_tensor.dtype, owned_tensor.shape, converted);
    }

    pub fn importDenseTensor(
        self: *NativeCompute,
        name: []const u8,
        dtype: tensor_mod.DType,
        shape: []const i64,
        data: []f32,
    ) !CT {
        const buf = try self.makeBuf(data, true);
        errdefer self.freeImportedTensor(buf);
        toBuf(buf).logical_shape = try self.allocator.dupe(i64, shape);
        toBuf(buf).declared_dtype = dtype;
        toBuf(buf).name = name;
        return buf;
    }

    fn freeImportedTensor(self: *NativeCompute, tensor: CT) void {
        self.computeBackend().free(tensor);
    }

    /// Exact integer inspection. Native integer payloads never pass through
    /// getData/toFloat32; compatibility float-index tensors are checked first.
    pub fn toInt64(_: *NativeCompute, tensor: CT, allocator: std.mem.Allocator) ![]i64 {
        const indices = try IndexReader.init(tensor);
        const output = try allocator.alloc(i64, indices.len);
        errdefer allocator.free(output);
        for (output, 0..) |*value, index| value.* = try indices.at(index);
        return output;
    }

    fn withLogicalShape(self: *NativeCompute, tensor: CT, shape: []const i64) !CT {
        const buf = toBuf(tensor);
        releaseLogicalShape(buf);
        if (shape.len <= buf.inline_logical_shape.len) {
            @memcpy(buf.inline_logical_shape[0..shape.len], shape);
            buf.logical_shape = buf.inline_logical_shape[0..shape.len];
            buf.logical_shape_inline = true;
        } else {
            buf.logical_shape = try self.allocator.dupe(i64, shape);
            buf.logical_shape_inline = false;
        }
        return tensor;
    }

    fn makeBuf(self: *NativeCompute, data: []f32, owned: bool) !CT {
        return self.makeBufWithEntry(data, owned, "", null, null, null);
    }

    fn makeOwnedBuf(self: *NativeCompute, data: []f32) !CT {
        errdefer self.allocator.free(data);
        return self.makeBuf(data, true);
    }

    fn makeBufWithEntry(
        self: *NativeCompute,
        data: []f32,
        owned: bool,
        name: []const u8,
        lazy_entry: ?*LazyWeightEntry,
        quantized_storage: ?*const QuantizedStorage,
        source_tensor: ?*const tensor_mod.Tensor,
    ) !CT {
        const b = try self.allocator.create(Buf);
        errdefer self.allocator.destroy(b);
        var shared_data_refcount: ?*usize = null;
        errdefer if (shared_data_refcount) |refcount| self.allocator.destroy(refcount);
        if (owned) {
            shared_data_refcount = try self.allocator.create(usize);
            shared_data_refcount.?.* = 1;
        }
        b.* = .{
            .data = data,
            .allocator = self.allocator,
            .owned = owned,
            .shared_data_refcount = shared_data_refcount,
            .logical_shape = null,
            .view_strides = null,
            .view_base_offset = 0,
            .declared_dtype = null,
            .name = name,
            .lazy_entry = lazy_entry,
            .quantized_storage = quantized_storage,
            .owned_quantized_storage = null,
            .source_tensor = source_tensor,
            .owned_source_tensor = null,
            .reservation = null,
        };
        return b;
    }

    fn makeBufWithOwnedQuantizedStorage(
        self: *NativeCompute,
        name: []const u8,
        lazy_entry: ?*LazyWeightEntry,
        storage: QuantizedStorage,
    ) !CT {
        const owned_storage = try self.allocator.create(QuantizedStorage);
        errdefer self.allocator.destroy(owned_storage);
        owned_storage.* = storage;
        const b = try self.allocator.create(Buf);
        b.* = .{
            .data = empty_f32[0..],
            .allocator = self.allocator,
            .owned = false,
            .shared_data_refcount = null,
            .logical_shape = null,
            .view_strides = null,
            .view_base_offset = 0,
            .declared_dtype = null,
            .name = name,
            .lazy_entry = lazy_entry,
            .quantized_storage = owned_storage,
            .owned_quantized_storage = owned_storage,
            .source_tensor = null,
            .owned_source_tensor = null,
            .reservation = null,
        };
        return b;
    }

    fn makeBufWithOwnedSourceTensor(self: *NativeCompute, tensor: tensor_mod.Tensor) !CT {
        // This function consumes tensor on both success and failure. Register
        // its cleanup before the first ownership-container allocation.
        var tensor_to_release = tensor;
        errdefer tensor_to_release.deinit();
        const owned_tensor = try self.allocator.create(tensor_mod.Tensor);
        errdefer self.allocator.destroy(owned_tensor);
        owned_tensor.* = tensor;

        const b = try self.allocator.create(Buf);
        errdefer self.allocator.destroy(b);
        b.* = .{
            .data = empty_f32[0..],
            .allocator = self.allocator,
            .owned = false,
            .shared_data_refcount = null,
            .logical_shape = null,
            .view_strides = null,
            .view_base_offset = 0,
            .declared_dtype = owned_tensor.dtype,
            .name = owned_tensor.name,
            .lazy_entry = null,
            .quantized_storage = null,
            .owned_quantized_storage = null,
            .source_tensor = owned_tensor,
            .owned_source_tensor = owned_tensor,
            .reservation = null,
        };
        return self.withLogicalShape(b, owned_tensor.shape);
    }
};

pub fn initPrefetchQueue(data: *WeightStore, allocator: std.mem.Allocator) void {
    if (data.prefetch_initialized) return;
    data.prefetch = PrefetchQueue.initWithPriority(allocator, data, &prefetchProcess, &prefetchPriority);
    data.prefetch_initialized = true;
    var lazy_it = data.lazy_weights.iterator();
    while (lazy_it.next()) |entry| {
        entry.value_ptr.guard = data.prefetch.lockHandle();
    }
}

pub fn startPrefetchWorker(data: *WeightStore) !void {
    try data.prefetch.start();
}

pub fn stopPrefetchWorker(data: *WeightStore) void {
    data.prefetch.stop();
}

/// Stops the worker and retires borrowed guards. Call before destroying
/// lazy_weights, whose entries still refer to this queue's Io and mutex.
pub fn deinitPrefetchQueue(data: *WeightStore) void {
    data.scalar_bounds.deinit(data.allocator);
    // Stop before releasing any cache state the worker can access.
    if (data.prefetch_initialized) data.prefetch.stop();
    deinitEmbeddingGemma2F32Cache(data);
    deinitGlinerHeadDenseCache(data);
    if (!data.prefetch_initialized) return;
    var lazy_it = data.lazy_weights.iterator();
    while (lazy_it.next()) |entry| entry.value_ptr.guard = null;
    data.prefetch.deinit();
    data.prefetch_initialized = false;
}

fn deinitEmbeddingGemma2F32Cache(data: *WeightStore) void {
    platform.sync.lockYielding(&data.embeddinggemma2_f32_cache_lock);
    defer data.embeddinggemma2_f32_cache_lock.unlock();
    var canonical = data.embeddinggemma2_canonical_panels.iterator();
    while (canonical.next()) |entry| {
        if (data.tier_cache) |*cache| cache.noteRelease(.host, entry.value_ptr.panels.data.len * @sizeOf(f32));
        entry.value_ptr.panels.deinit(data.allocator);
        data.allocator.free(entry.key_ptr.*);
    }
    data.embeddinggemma2_canonical_panels.deinit(data.allocator);
    data.embeddinggemma2_canonical_panels = .empty;
    var panels = data.embeddinggemma2_panels.valueIterator();
    while (panels.next()) |entry| {
        if (data.tier_cache) |*cache| cache.noteRelease(.host, entry.panels.data.len * @sizeOf(f32));
        entry.panels.deinit(data.allocator);
    }
    data.embeddinggemma2_panels.deinit(data.allocator);
    data.embeddinggemma2_panels = .empty;
    var it = data.embeddinggemma2_f32_cache.iterator();
    while (it.next()) |entry| {
        data.allocator.free(entry.key_ptr.*);
        data.allocator.free(entry.value_ptr.data);
        if (entry.value_ptr.prepared_shape) |shape| data.allocator.free(shape);
        if (data.tier_cache) |*cache| cache.noteRelease(.host, entry.value_ptr.bytes);
    }
    data.embeddinggemma2_f32_cache.deinit(data.allocator);
    data.embeddinggemma2_f32_cache = .empty;
    data.embeddinggemma2_f32_cache_bytes = 0;
    data.embeddinggemma2_constant_bytes = 0;
    data.embeddinggemma2_constant_count = 0;
    data.embeddinggemma2_f32_class_bytes = @splat(0);
    data.embeddinggemma2_panel_class_bytes = @splat(0);
}

/// A compute context pins all immutable mirrors it can borrow until teardown.
/// Reclamation never invalidates a live tensor, even across concurrent requests.
pub fn reclaimEmbeddingGemma2Weights(data: *WeightStore, class: embeddinggemma2_weight_cache.MetalClass) usize {
    data.prefetch.lock();
    defer data.prefetch.unlock();
    platform.sync.lockYielding(&data.embeddinggemma2_f32_cache_lock);
    defer data.embeddinggemma2_f32_cache_lock.unlock();
    if (data.embeddinggemma2_f32_readers != 0) return 0;
    var released: usize = 0;
    while (true) {
        var it = data.embeddinggemma2_canonical_panels.iterator();
        const key = blk: {
            while (it.next()) |entry| if (entry.value_ptr.class == class) break :blk entry.key_ptr.*;
            break :blk null;
        } orelse break;
        const entry = data.embeddinggemma2_canonical_panels.fetchRemove(key).?;
        const bytes = entry.value.panels.data.len * @sizeOf(f32);
        entry.value.panels.deinit(data.allocator);
        data.allocator.free(entry.key);
        data.embeddinggemma2_f32_cache_bytes -= bytes;
        data.embeddinggemma2_f32_class_bytes[@backingInt(class)] -= bytes;
        if (data.tier_cache) |*cache| cache.noteRelease(.host, bytes);
        released += bytes;
    }
    while (true) {
        var panels = data.embeddinggemma2_panels.iterator();
        const key = blk: {
            while (panels.next()) |entry| if (entry.value_ptr.class == class) break :blk entry.key_ptr.*;
            break :blk null;
        } orelse break;
        const entry = data.embeddinggemma2_panels.fetchRemove(key).?.value;
        const bytes = entry.panels.data.len * @sizeOf(f32);
        entry.panels.deinit(data.allocator);
        data.embeddinggemma2_f32_cache_bytes -= bytes;
        data.embeddinggemma2_f32_class_bytes[@backingInt(class)] -= bytes;
        data.embeddinggemma2_panel_class_bytes[@backingInt(class)] -= bytes;
        if (data.tier_cache) |*cache| cache.noteRelease(.host, bytes);
        released += bytes;
    }

    while (true) {
        var it = data.embeddinggemma2_f32_cache.iterator();
        const name = blk: {
            while (it.next()) |entry| if (embeddinggemma2_weight_cache.nativeClass(std.mem.sliceTo(entry.key_ptr.*, '|')) == class) break :blk entry.key_ptr.*;
            break :blk null;
        } orelse break;
        const entry = data.embeddinggemma2_f32_cache.fetchRemove(name).?;
        data.allocator.free(entry.value.data);
        if (entry.value.prepared_shape) |shape| {
            data.allocator.free(shape);
            data.embeddinggemma2_constant_bytes -= entry.value.bytes;
            data.embeddinggemma2_constant_count -= 1;
        }
        data.allocator.free(entry.key);
        data.embeddinggemma2_f32_cache_bytes -= entry.value.bytes;
        data.embeddinggemma2_f32_class_bytes[@backingInt(class)] -= entry.value.bytes;
        if (data.tier_cache) |*cache| cache.noteRelease(.host, entry.value.bytes);
        released += entry.value.bytes;
    }
    return released;
}

fn modelConstantOp(ctx: *anyopaque, key: []const u8, value: ?CT) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const policy = embeddinggemma2_weight_cache;
    if (!self.cache_embeddinggemma2_bf16_weights or !std.mem.startsWith(u8, key, "audio_tower.prepared.")) return null;
    const cache = if (self.data.tier_cache) |*cache| cache else return null;
    self.data.prefetch.lock();
    defer self.data.prefetch.unlock();
    platform.sync.lockYielding(&self.data.embeddinggemma2_f32_cache_lock);
    defer self.data.embeddinggemma2_f32_cache_lock.unlock();
    if (self.data.embeddinggemma2_f32_cache.get(key)) |entry| {
        if (!self.embeddinggemma2_cache_reader) {
            self.data.embeddinggemma2_f32_readers += 1;
            self.embeddinggemma2_cache_reader = true;
        }
        const tensor = try self.makeBuf(entry.data, false);
        errdefer freeTensor(self, tensor);
        return self.withLogicalShape(tensor, entry.prepared_shape orelse return error.InvalidTensorShape);
    }
    const input = value orelse return null;
    const data = toBuf(input).data;
    const bytes = try std.math.mul(usize, data.len, @sizeOf(f32));
    const used = self.data.embeddinggemma2_f32_class_bytes[@backingInt(policy.MetalClass.audio)];
    if (bytes == 0 or bytes > policy.prepared_max_bytes - self.data.embeddinggemma2_constant_bytes or self.data.embeddinggemma2_constant_count >= policy.prepared_max_entries or used > policy.audio_max_bytes or bytes > policy.audio_max_bytes - used or self.data.embeddinggemma2_f32_cache.count() >= policy.max_entries) return null;
    cache.reserve(.host, bytes) catch {
        cache.noteDenied(.host, bytes);
        return null;
    };
    var committed = false;
    errdefer if (!committed) cache.noteRelease(.host, bytes);
    const shape = try tensorShapeOp(self, input, self.data.allocator);
    errdefer if (!committed) self.data.allocator.free(shape);
    const name = try self.data.allocator.dupe(u8, key);
    errdefer if (!committed) self.data.allocator.free(name);
    const snapshot = try self.data.allocator.dupe(f32, data);
    errdefer if (!committed) self.data.allocator.free(snapshot);
    try self.data.embeddinggemma2_f32_cache.put(self.data.allocator, name, .{ .data = snapshot, .bytes = bytes, .prepared_shape = shape });
    self.data.embeddinggemma2_f32_cache_bytes += bytes;
    self.data.embeddinggemma2_constant_bytes += bytes;
    self.data.embeddinggemma2_constant_count += 1;
    committed = true;
    self.data.embeddinggemma2_f32_class_bytes[@backingInt(policy.MetalClass.audio)] += bytes;
    // Insertion has committed. A failed request handle cannot unwind the
    // model-owned allocation; publication must remain reusable on retry.
    if (!self.embeddinggemma2_cache_reader) {
        self.data.embeddinggemma2_f32_readers += 1;
        self.embeddinggemma2_cache_reader = true;
    }
    const tensor = try self.makeBuf(snapshot, false);
    errdefer freeTensor(self, tensor);
    return self.withLogicalShape(tensor, shape);
}

fn cachedEmbeddingGemma2F32Weight(self: *NativeCompute, name: []const u8, source: *const tensor_mod.Tensor) !?[]f32 {
    if (!self.cache_embeddinggemma2_bf16_weights or source.dtype != .bf16) return null;
    const class = embeddinggemma2_weight_cache.nativeClass(name) orelse return null;
    if (embeddinggemma2_weight_cache.projectionGroup(name)) |group| {
        var storage: [3][256]u8 = undefined;
        var names: [3][]const u8 = undefined;
        const siblings = try group.names(&storage, &names);
        var complete = true;
        for (siblings) |sibling| complete = complete and (self.data.resident_weights.contains(sibling) or self.data.lazy_weights.contains(sibling));
        if (complete) return null;
    }
    const class_index = @backingInt(class);
    const limit = embeddinggemma2_weight_cache.classLimit(class);
    const cache = if (self.data.tier_cache) |*cache| cache else return null;
    if (source.data.len % 2 != 0) return error.InvalidTensorShape;
    const bytes = std.math.mul(usize, source.data.len, 2) catch return null;
    if (bytes == 0 or bytes > limit) return null;
    platform.sync.lockYielding(&self.data.embeddinggemma2_f32_cache_lock);
    defer self.data.embeddinggemma2_f32_cache_lock.unlock();
    if (!self.embeddinggemma2_cache_reader) {
        self.data.embeddinggemma2_f32_readers += 1;
        self.embeddinggemma2_cache_reader = true;
    }
    if (self.data.embeddinggemma2_f32_cache.get(name)) |entry| {
        if (entry.bytes != bytes) return error.InvalidTensorShape;
        return entry.data;
    }
    if (self.data.embeddinggemma2_f32_cache.count() >= embeddinggemma2_weight_cache.max_entries or
        self.data.embeddinggemma2_f32_class_bytes[class_index] > limit or
        bytes > limit - self.data.embeddinggemma2_f32_class_bytes[class_index]) return null;
    cache.reserve(.host, bytes) catch {
        cache.noteDenied(.host, bytes);
        return null;
    };
    errdefer cache.noteRelease(.host, bytes);
    const owned_name = try self.data.allocator.dupe(u8, name);
    errdefer self.data.allocator.free(owned_name);
    const dense = try convertTensorToOwnedF32(self.data.allocator, source);
    errdefer self.data.allocator.free(dense);
    try self.data.embeddinggemma2_f32_cache.put(self.data.allocator, owned_name, .{ .data = dense, .bytes = bytes });
    self.data.embeddinggemma2_f32_cache_bytes += bytes;
    self.data.embeddinggemma2_f32_class_bytes[class_index] += bytes;
    return dense;
}

fn embeddingGemma2F32WeightOrFallback(self: *NativeCompute, name: []const u8, source: *const tensor_mod.Tensor) !?[]f32 {
    return cachedEmbeddingGemma2F32Weight(self, name, source) catch |err| switch (err) {
        error.OutOfMemory => null,
        else => return err,
    };
}

test "embeddinggemma2 native immutable mirrors survive request teardown and release admission on unload" {
    const a = std.testing.allocator;
    const name = "language_model.layers.0.self_attn.q_proj.weight";
    var bits = [_]u16{ 0x3f80, 0xc000, 0x3f00, 0x0001 };
    const expected = [_]f32{ 1, -2, 0.5, @bitCast(@as(u32, 0x00010000)) };
    var controller = run_memory.AdmissionController{};
    controller.configureSharedLimits(.{ .host_limit_bytes = 32 });
    defer controller.deinit();
    var store = WeightStore{ .allocator = a, .resident_weights = .empty, .lazy_weights = .empty, .tier_cache = tier_cache_mod.SharedCache.init(.{ .host_limit_bytes = 32 }) };
    defer store.resident_weights.deinit(a);
    defer store.tier_cache.?.deinitAdmission();
    try store.tier_cache.?.configureAdmission(a, &controller, .cpu, .{ .host_limit_bytes = 32, .combined_limit_bytes = 32 }, .{});
    initPrefetchQueue(&store, a);
    defer deinitPrefetchQueue(&store);
    try store.resident_weights.put(a, name, .{ .tensor = .{
        .data = std.mem.sliceAsBytes(&bits),
        .dtype = .bf16,
        .shape = &.{ 2, 2 },
        .name = name,
        .allocator = a,
        .owns_data = false,
        .owns_shape = false,
    } });
    var cached_ptr: ?[*]f32 = null;
    for (0..3) |_| {
        var request_budget = run_memory.RunBudget.init(.{ .host_limit_bytes = 32 });
        var request = NativeCompute.init(a, &store, &request_budget);
        request.cache_embeddinggemma2_bf16_weights = true;
        var cb = request.computeBackend();
        const weight = try cb.getWeight(name);
        try std.testing.expect(!toBuf(weight).owned);
        try std.testing.expectEqualSlices(f32, &expected, toBuf(weight).data);
        if (cached_ptr) |ptr| try std.testing.expect(ptr == toBuf(weight).data.ptr) else cached_ptr = toBuf(weight).data.ptr;
        cb.free(weight);
        request.deinit();
        try std.testing.expectEqual(@as(usize, 0), request_budget.host_weight_bytes);
        try std.testing.expectEqual(@as(usize, 16), store.tier_cache.?.host_bytes);
        try std.testing.expectEqual(@as(usize, 16), controller.snapshot().host_weight_bytes);
    }
    deinitEmbeddingGemma2F32Cache(&store);
    try std.testing.expectEqual(@as(usize, 0), store.tier_cache.?.host_bytes);
    try std.testing.expectEqual(@as(usize, 0), controller.snapshot().host_weight_bytes);
}

test "embeddinggemma2 native mirror denials and allocation failures preserve fallback and accounting" {
    const a = std.testing.allocator;
    const name = "language_model.norm.weight";
    var bits = [_]u16{ 0x3f80, 0xc000 };
    const source = tensor_mod.Tensor{ .data = std.mem.sliceAsBytes(&bits), .dtype = .bf16, .shape = &.{2}, .name = name, .allocator = a, .owns_data = false, .owns_shape = false };
    for (0..3) |fail_index| {
        var failing = std.testing.FailingAllocator.init(a, .{ .fail_index = fail_index });
        var store = WeightStore{ .allocator = failing.allocator(), .resident_weights = .empty, .lazy_weights = .empty, .tier_cache = tier_cache_mod.SharedCache.init(.{ .host_limit_bytes = 64 }) };
        defer deinitEmbeddingGemma2F32Cache(&store);
        var compute = NativeCompute{ .allocator = a, .data = &store, .cache_embeddinggemma2_bf16_weights = true };
        defer compute.deinit();
        try std.testing.expect((try embeddingGemma2F32WeightOrFallback(&compute, name, &source)) == null);
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqual(@as(usize, 0), store.embeddinggemma2_f32_cache.count());
        try std.testing.expectEqual(@as(usize, 0), store.tier_cache.?.host_bytes);
    }
    var store = WeightStore{ .allocator = a, .resident_weights = .empty, .lazy_weights = .empty, .tier_cache = tier_cache_mod.SharedCache.init(.{ .host_limit_bytes = 4 }) };
    initPrefetchQueue(&store, a);
    defer deinitPrefetchQueue(&store);
    defer store.resident_weights.deinit(a);
    try store.resident_weights.put(a, name, .{ .tensor = source });
    var compute = NativeCompute.init(a, &store, null);
    defer compute.deinit();
    try std.testing.expect((try embeddingGemma2F32WeightOrFallback(&compute, name, &source)) == null);
    compute.cache_embeddinggemma2_bf16_weights = true;
    var cb = compute.computeBackend();
    const weight = try cb.getWeight(name);
    defer cb.free(weight);
    try std.testing.expect(toBuf(weight).owned);
    try std.testing.expectEqualSlices(f32, &.{ 1, -2 }, toBuf(weight).data);
    try std.testing.expectEqual(@as(usize, 0), store.tier_cache.?.host_bytes);
    try std.testing.expectEqual(@as(usize, 0), store.embeddinggemma2_f32_cache.count());
    store.embeddinggemma2_f32_class_bytes[0] = embeddinggemma2_weight_cache.max_bytes;
    defer store.embeddinggemma2_f32_class_bytes[0] = 0;
    try std.testing.expect((try embeddingGemma2F32WeightOrFallback(&compute, name, &source)) == null);
    try std.testing.expect((try embeddingGemma2F32WeightOrFallback(&compute, "language_model.embed_tokens.weight", &source)) == null);
}

pub fn deinitGlinerHeadDenseCache(data: *WeightStore) void {
    while (!data.gliner_head_dense_cache_lock.tryLock()) {
        platform.time.yieldBriefly();
    }
    defer data.gliner_head_dense_cache_lock.unlock();

    var it = data.gliner_head_dense_cache.iterator();
    while (it.next()) |entry| {
        data.allocator.free(entry.key_ptr.*);
        data.allocator.free(entry.value_ptr.data);
        if (data.tier_cache) |*tier_cache| tier_cache.noteRelease(.host, entry.value_ptr.bytes);
    }
    data.gliner_head_dense_cache.deinit(data.allocator);
    data.gliner_head_dense_cache = .{};
    data.gliner_head_dense_cache_bytes = 0;
}

pub fn quantDequantCacheStats(data: *WeightStore) QuantDequantCacheStats {
    while (!data.gliner_head_dense_cache_lock.tryLock()) {
        platform.time.yieldBriefly();
    }
    defer data.gliner_head_dense_cache_lock.unlock();

    return .{
        .entries = data.gliner_head_dense_cache.count(),
        .bytes = data.gliner_head_dense_cache_bytes,
        .hits = data.quant_dequant_cache_hits,
        .misses = data.quant_dequant_cache_misses,
        .inserts = data.quant_dequant_cache_inserts,
        .disabled = data.quant_dequant_cache_disabled,
        .too_large = data.quant_dequant_cache_too_large,
        .capacity_denied = data.quant_dequant_cache_capacity_denied,
        .tier_denied = data.quant_dequant_cache_tier_denied,
        .scratch_fallbacks = data.quant_dequant_cache_scratch_fallbacks,
        .scratch_denied = data.quant_dequant_cache_scratch_denied,
    };
}

// --- SIMD helpers ---

// SIMD width / vector aliases canonically live in `quant_codec.zig`
// alongside the encoders.  The decoder dot kernels in this file still
// depend on them; keeping the local aliases as one-line indirections
// to the canonical source means a future physical move of the dot
// kernels into quant_codec is a pure file split rather than an API
// change.
const VEC_LEN = quant_codec.vec_len;
const F32xN = quant_codec.F32xN;
const I32xN = quant_codec.I32xN;
const I8xN = quant_codec.I8xN;
const U8xN = quant_codec.U8xN;
const U8x16 = @Vector(16, u8);
const U8x8 = @Vector(8, u8);
const I8x8 = @Vector(8, i8);
const I32x4 = @Vector(4, i32);
const F32x4 = @Vector(4, f32);
const F32x8 = @Vector(8, f32);
const I32x8 = @Vector(8, i32);
const empty_f32: [0]f32 = .{};
const empty_u8: [0]u8 = .{};

fn quantizedStorageBudgetBytes(storage: *const QuantizedStorage) usize {
    const prepared_bytes = storage.prepared.ownedBytes();
    const group_cache_bytes = if (storage.prepared_group_cache) |cache| cache.ownedBytes() else 0;
    if (storage.packed_expert) |packed_view| {
        const count: usize = @max(@as(usize, 1), @as(usize, @intCast(packed_view.expert_count)));
        return @max(@as(usize, 1), storage.raw_bytes.len / count) + prepared_bytes + group_cache_bytes;
    }
    return storage.raw_bytes.len + prepared_bytes + group_cache_bytes;
}

fn preparedKBlockAdditionalBytes(storage: *const QuantizedStorage) usize {
    const known = switch (storage.tensor_type) {
        .known => |value| value,
        else => return 0,
    };
    if (known != .Q1_0 and known != .Q4_0 and known != .Q4_1 and known != .Q5_0 and known != .Q5_1 and known != .Q2_K and known != .Q3_K and known != .Q4_K and known != .Q5_K and known != .Q6_K and known != .Q8_0 and known != .Q8_1 and known != .Q8_K) return 0;
    if ((known == .Q1_0 or known == .Q4_0 or known == .Q4_1 or known == .Q5_0 or known == .Q5_1 or known == .Q2_K or known == .Q3_K) and storage.packed_expert != null) return 0;
    if ((known == .Q5_K or known == .Q6_K) and storage.packed_expert != null) return 0;
    if ((known == .Q8_0 or known == .Q8_1 or known == .Q8_K) and storage.packed_expert != null) return 0;
    const block_size = gguf_tensor_types.bytesPerBlock(storage.tensor_type) orelse return 0;
    if (block_size == 0 or storage.raw_bytes.len % block_size != 0) return 0;
    const block_count = storage.raw_bytes.len / block_size;
    const prepared_block_size: usize = if (known == .Q8_0 or known == .Q8_1)
        prepared_q8_0_block_bytes
    else if (known == .Q1_0)
        prepared_q1_0_block_bytes
    else if (known == .Q4_0 or known == .Q4_1 or known == .Q5_0 or known == .Q5_1)
        prepared_legacy_block_bytes
    else if (known == .Q2_K or known == .Q3_K)
        prepared_k16_block_bytes
    else
        prepared_q4_k_block_bytes;
    var additional: usize = if (known != .Q8_K and storage.preparedBytes(.row_major_blocks) == null) block_count * prepared_block_size else 0;
    if (known == .Q1_0 and storage.preparedBytes(.panel4) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 128 == 0) additional += preparedQ1_0PanelByteSize(out_dim, in_dim / 128);
    }
    if ((known == .Q4_0 or known == .Q4_1 or known == .Q5_0 or known == .Q5_1) and storage.preparedBytes(.panel4) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 32 == 0) additional += preparedLegacyPanelByteSize(out_dim, in_dim / 32);
    }
    if ((known == .Q2_K or known == .Q3_K) and storage.preparedBytes(.panel4) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedK16PanelByteSize(out_dim, in_dim / 256);
    }
    if (known == .Q3_K and q3KNoDmnPanelPreparedEnabled() and storage.preparedBytes(.panel4_k16_no_min) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) {
            const row_blocks = in_dim / 256;
            if (q3KNoDmnPanelPreparedEnabledForShape(out_dim, row_blocks)) additional += preparedQ3KNoDmnPanelByteSize(out_dim, row_blocks);
        }
    }
    if (k16Panel8DirectEnabledFor(known) and storage.preparedBytes(.panel8) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedK16Panel8ByteSize(out_dim, in_dim / 256);
    }
    if (k16Panel16PreparedEnabledFor(known) and storage.preparedBytes(.panel16) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedK16Panel16ByteSize(out_dim, in_dim / 256);
    }
    if ((known == .Q8_0 or known == .Q8_1) and storage.preparedBytes(.panel4) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 32 == 0) additional += preparedQ8_0PanelByteSize(out_dim, in_dim / 32);
    }
    if ((known == .Q8_0 or known == .Q8_1) and q8_0Panel8PrepareEnabled() and storage.preparedBytes(.panel8) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 32 == 0) additional += preparedQ8_0Panel8ByteSize(out_dim, in_dim / 32);
    }
    if (known == .Q8_K and storage.preparedBytes(.panel4) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedQ8_KPanelByteSize(out_dim, in_dim / 256);
    }
    if (q8KPanel8DirectEnabled() and known == .Q8_K and storage.preparedBytes(.panel8) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedQ8_KPanel8ByteSize(out_dim, in_dim / 256);
    }
    if (q8KPanel16PreparedEnabled() and known == .Q8_K and storage.preparedBytes(.panel16) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedQ8_KPanel16ByteSize(out_dim, in_dim / 256);
    }
    if ((known == .Q4_K or known == .Q5_K or known == .Q6_K) and storage.preparedBytes(.panel4) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedKPanelByteSize(out_dim, in_dim / 256);
    }
    if ((known == .Q4_K or known == .Q5_K or known == .Q6_K) and storage.preparedBytes(.panel8) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedKPanel8ByteSizeForKnown(known, out_dim, in_dim / 256);
    }
    if ((known == .Q4_K or known == .Q5_K or (known == .Q6_K and q6KPanel16PreparedEnabled())) and storage.preparedBytes(.panel16) == null and storage.shape.len == 2 and storage.shape[0] > 0 and storage.shape[1] > 0) {
        const out_dim: usize = @intCast(storage.shape[0]);
        const in_dim: usize = @intCast(storage.shape[1]);
        if (in_dim % 256 == 0) additional += preparedKPanel16ByteSize(out_dim, in_dim / 256);
    }
    return additional;
}

fn expectedQuantizedStorageLoadBytes(storage: *const QuantizedStorage) usize {
    return quantizedStorageBudgetBytes(storage) + preparedKBlockAdditionalBytes(storage);
}

