}

fn preparedKPanel8ByteSizeForKnown(known: gguf_tensor_types.KnownTensorType, out_dim: usize, row_blocks: usize) usize {
    return if (known == .Q6_K) preparedQ6KPanel8ByteSize(out_dim, row_blocks) else preparedKPanel8ByteSize(out_dim, row_blocks);
}

fn preparedKPanel16ByteSize(out_dim: usize, row_blocks: usize) usize {
