fn preparedKQKVPanel16ByteSize(out_dim: usize, row_blocks: usize) usize {
    return (out_dim / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
}

fn preparedKQKVPanel16OwnedByteSize(
    out_dim: usize,
    row_blocks: usize,
    key_b: []const u8,
    key_c: []const u8,
) ?usize {
    const packed_bytes = preparedKQKVPanel16ByteSize(out_dim, row_blocks);
    const with_key_b = std.math.add(usize, packed_bytes, key_b.len) catch return null;
    return std.math.add(usize, with_key_b, key_c.len) catch null;
}

fn prepareQ8_0PanelPackedStorage(storage: *QuantizedStorage) !void {
    if (storage.preparedBytes(.panel4) != null) return;
    if (storage.packed_expert != null) return;
    if (storage.shape.len != 2 or storage.shape[0] <= 0 or storage.shape[1] <= 0) return;
    const prepared = storage.preparedBytes(.row_major_blocks) orelse return;
    const out_dim: usize = @intCast(storage.shape[0]);
    const in_dim: usize = @intCast(storage.shape[1]);
    if (in_dim % 32 != 0) return;
    const row_blocks = in_dim / 32;
    if (prepared.len != out_dim * row_blocks * prepared_q8_0_block_bytes) return error.InvalidQuantizedDataSize;

    const panel_size = preparedQ8_0PanelByteSize(out_dim, row_blocks);
    if (panel_size == 0) return;
    const panel = try storage.allocator.alloc(u8, panel_size);
    errdefer storage.allocator.free(panel);
    for (0..(out_dim / prepared_q8_0_panel_nr)) |panel_idx| {
        for (0..row_blocks) |block_idx| {
            const dest_base = (panel_idx * row_blocks + block_idx) * prepared_q8_0_panel_nr * prepared_q8_0_block_bytes;
            inline for (0..prepared_q8_0_panel_nr) |lane| {
                const out_row = panel_idx * prepared_q8_0_panel_nr + lane;
                const src_base = (out_row * row_blocks + block_idx) * prepared_q8_0_block_bytes;
                @memcpy(
                    panel[dest_base + lane * prepared_q8_0_block_bytes ..][0..prepared_q8_0_block_bytes],
                    prepared[src_base..][0..prepared_q8_0_block_bytes],
                );
            }
        }
    }
    storage.setPreparedBytes(.panel4, panel, prepared_q8_0_panel_nr, @intCast(row_blocks));
}

