    prepared_blocks_a: []const u8,
    prepared_blocks_b: []const u8,
    prepared_blocks_c: []const u8,
    bias_a: ?[]const f32 = null,
    bias_b: ?[]const f32 = null,
    bias_c: ?[]const f32 = null,
    output_a: []f32,
    output_b: []f32,
    output_c: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
    out_start: usize = 0,
    out_end: usize = 0,
    err: ?anyerror = null,
};

const QuantizedLinearWorkerCtx = struct {
