        }
    }
    storeF32x16(out_row0, o, acc0_lo, acc0_hi);
    storeF32x16(out_row1, o, acc1_lo, acc1_hi);
}

inline fn writeQ4Q5KPanel16TripleRows(
    comptime mr: usize,
    inputs: [mr][]const u8,
    panels: [3][]const u8,
    outputs: [3][mr][]f32,
    row_blocks: usize,
    o: usize,
) void {
    var acc: [3][mr][prepared_k_panel16_nr]f32 = @splat(@splat(@splat(0.0)));
    for (0..row_blocks) |block_idx| {
        const q8_off = block_idx * 292;
        const panel_off = ((o / prepared_k_panel16_nr) * row_blocks + block_idx) * prepared_k_panel16_block_bytes;
        const blocks = q4q5KTriplePanel16Block(panels[0], panels[1], panels[2], panel_off);
        const sums = if (mr == 4)
            dotQ4Q5KPreparedQ8KTriplePanel16MR4(inputs[0][q8_off..][0..292], inputs[1][q8_off..][0..292], inputs[2][q8_off..][0..292], inputs[3][q8_off..][0..292], blocks)
        else
            dotQ4Q5KPreparedQ8KTriplePanel16MR2(inputs[0][q8_off..][0..292], inputs[1][q8_off..][0..292], blocks);
        inline for (0..prepared_k_panel16_nr) |idx| inline for (.{ "a", "b", "c" }, 0..) |projection, pi| inline for (0..mr) |r| {
            acc[pi][r][idx] += @field(@field(sums, projection), .{ "r0", "r1", "r2", "r3" }[r])[idx];
        };
    }
    inline for (0..prepared_k_panel16_nr) |idx| inline for (0..3) |pi| inline for (0..mr) |r| {
        outputs[pi][r][o + idx] = acc[pi][r][idx];
    };
}

inline fn writeQ4Q5KPreparedQ8KPanel16TripleMR4Projection(
    q_input_row0: []const u8,
    q_input_row1: []const u8,
    q_input_row2: []const u8,
    q_input_row3: []const u8,
    panel16_blocks_a: []const u8,
    panel16_blocks_b: []const u8,
    panel16_blocks_c: []const u8,
    packed_qkv_panel16: ?[]const u8,
    out_a0: []f32,
    out_a1: []f32,
    out_a2: []f32,
    out_a3: []f32,
    out_b0: []f32,
    out_b1: []f32,
    out_b2: []f32,
    out_b3: []f32,
    out_c0: []f32,
    out_c1: []f32,
    out_c2: []f32,
    out_c3: []f32,
    row_blocks: usize,
    o: usize,
) void {
    if (packed_qkv_panel16) |packed_bytes| {
        writeQ4Q5KPreparedQ8KPackedQKVPanel16MR4ProjectionWithSums(false, q_input_row0, q_input_row1, q_input_row2, q_input_row3, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, packed_bytes, null, out_a0, out_a1, out_a2, out_a3, null, out_b0, out_b1, out_b2, out_b3, null, out_c0, out_c1, out_c2, out_c3, row_blocks, o);
        return;
    }

    writeQ4Q5KPanel16TripleRows(4, .{ q_input_row0, q_input_row1, q_input_row2, q_input_row3 }, .{ panel16_blocks_a, panel16_blocks_b, panel16_blocks_c }, .{ .{ out_a0, out_a1, out_a2, out_a3 }, .{ out_b0, out_b1, out_b2, out_b3 }, .{ out_c0, out_c1, out_c2, out_c3 } }, row_blocks, o);
}

inline fn writeQ4Q5KPreparedQ8KPanel16TripleMR2Projection(
    q_input_row0: []const u8,
    q_input_row1: []const u8,
    panel16_blocks_a: []const u8,
    panel16_blocks_b: []const u8,
    panel16_blocks_c: []const u8,
    packed_qkv_panel16: ?[]const u8,
    out_a0: []f32,
    out_a1: []f32,
    out_b0: []f32,
    out_b1: []f32,
    out_c0: []f32,
    out_c1: []f32,
    row_blocks: usize,
    o: usize,
) void {
    if (packed_qkv_panel16) |packed_bytes| {
        writeQ4Q5KPreparedQ8KPackedQKVPanel16MR2Projection(q_input_row0, q_input_row1, packed_bytes, out_a0, out_a1, out_b0, out_b1, out_c0, out_c1, row_blocks, o);
        return;
    }

    writeQ4Q5KPanel16TripleRows(2, .{ q_input_row0, q_input_row1 }, .{ panel16_blocks_a, panel16_blocks_b, panel16_blocks_c }, .{ .{ out_a0, out_a1 }, .{ out_b0, out_b1 }, .{ out_c0, out_c1 } }, row_blocks, o);
}

inline fn storeF32x16(out: []f32, o: usize, lo: F32x8, hi: F32x8) void {
    const lo_arr = f32x8ToArray(lo);
    const hi_arr = f32x8ToArray(hi);
    @memcpy(out[o..][0..8], &lo_arr);
    @memcpy(out[o + 8 ..][0..8], &hi_arr);
}

inline fn storeF32x16WithBias(out: []f32, bias: ?[]const f32, o: usize, lo: F32x8, hi: F32x8) void {
    if (bias) |values| {
        const bias_lo: F32x8 = values[o..][0..8].*;
        const bias_hi: F32x8 = values[o + 8 ..][0..8].*;
        storeF32x16(out, o, lo + bias_lo, hi + bias_hi);
    } else {
        storeF32x16(out, o, lo, hi);
    }
}

inline fn addBiasTile16(out: []f32, bias: ?[]const f32, o: usize) void {
    if (bias) |values| {
        const out_lo: F32x8 = out[o..][0..8].*;
        const out_hi: F32x8 = out[o + 8 ..][0..8].*;
        const bias_lo: F32x8 = values[o..][0..8].*;
        const bias_hi: F32x8 = values[o + 8 ..][0..8].*;
        storeF32x16(out, o, out_lo + bias_lo, out_hi + bias_hi);
    }
}

inline fn addBiasTile16Rows2(out0: []f32, out1: []f32, bias: ?[]const f32, o: usize) void {
    if (bias == null) return;
    addBiasTile16(out0, bias, o);
    addBiasTile16(out1, bias, o);
}

inline fn addBiasTile16Rows4(out0: []f32, out1: []f32, out2: []f32, out3: []f32, bias: ?[]const f32, o: usize) void {
    if (bias == null) return;
    addBiasTile16(out0, bias, o);
    addBiasTile16(out1, bias, o);
    addBiasTile16(out2, bias, o);
    addBiasTile16(out3, bias, o);
}

inline fn writeQ4Q5KPreparedQ8KPackedQKVPanel16MR4ProjectionWithSums(
    comptime prepared_sums: bool,
    q_input_row0: []const u8,
    q_input_row1: []const u8,
    q_input_row2: []const u8,
    q_input_row3: []const u8,
    activation_sums0: *const [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8,
    activation_sums1: *const [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8,
    activation_sums2: *const [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8,
    activation_sums3: *const [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8,
    activation_scales0: *const [q8_k_prepared_sum_stack_max_row_blocks]F32x8,
    activation_scales1: *const [q8_k_prepared_sum_stack_max_row_blocks]F32x8,
    activation_scales2: *const [q8_k_prepared_sum_stack_max_row_blocks]F32x8,
    activation_scales3: *const [q8_k_prepared_sum_stack_max_row_blocks]F32x8,
    packed_qkv_panel16: []const u8,
    bias_a: ?[]const f32,
    out_a0: []f32,
    out_a1: []f32,
    out_a2: []f32,
    out_a3: []f32,
    bias_b: ?[]const f32,
    out_b0: []f32,
    out_b1: []f32,
    out_b2: []f32,
    out_b3: []f32,
    bias_c: ?[]const f32,
    out_c0: []f32,
    out_c1: []f32,
    out_c2: []f32,
    out_c3: []f32,
    row_blocks: usize,
    o: usize,
) void {
    noteNativeQuantDispatch(.q4_q5_k_q8k_triple_packed_qkv_panel16_mr4);

    const q8_block_size: usize = 292;
    var acc_a0_lo: F32x8 = @splat(0.0);
    var acc_a0_hi: F32x8 = @splat(0.0);
    var acc_a1_lo: F32x8 = @splat(0.0);
    var acc_a1_hi: F32x8 = @splat(0.0);
    var acc_a2_lo: F32x8 = @splat(0.0);
    var acc_a2_hi: F32x8 = @splat(0.0);
    var acc_a3_lo: F32x8 = @splat(0.0);
    var acc_a3_hi: F32x8 = @splat(0.0);
    var acc_b0_lo: F32x8 = @splat(0.0);
    var acc_b0_hi: F32x8 = @splat(0.0);
    var acc_b1_lo: F32x8 = @splat(0.0);
    var acc_b1_hi: F32x8 = @splat(0.0);
    var acc_b2_lo: F32x8 = @splat(0.0);
    var acc_b2_hi: F32x8 = @splat(0.0);
    var acc_b3_lo: F32x8 = @splat(0.0);
    var acc_b3_hi: F32x8 = @splat(0.0);
    var acc_c0_lo: F32x8 = @splat(0.0);
    var acc_c0_hi: F32x8 = @splat(0.0);
    var acc_c1_lo: F32x8 = @splat(0.0);
    var acc_c1_hi: F32x8 = @splat(0.0);
    var acc_c2_lo: F32x8 = @splat(0.0);
    var acc_c2_hi: F32x8 = @splat(0.0);
    var acc_c3_lo: F32x8 = @splat(0.0);
    var acc_c3_hi: F32x8 = @splat(0.0);

    if (prepared_sums) {
        const packed_panel_base = (o / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
        for (0..row_blocks) |block_idx| {
            const q8_off = block_idx * q8_block_size;
            const qx0 = q_input_row0[q8_off + 4 ..][0..256];
            const qx1 = q_input_row1[q8_off + 4 ..][0..256];
            const qx2 = q_input_row2[q8_off + 4 ..][0..256];
            const qx3 = q_input_row3[q8_off + 4 ..][0..256];
            const packed_off = packed_panel_base + block_idx * prepared_k_qkv_panel16_block_bytes;
            const block = packed_qkv_panel16[packed_off..][0..prepared_k_qkv_panel16_block_bytes];

            for (0..8) |sub| {
                const q_off = sub * 32;
                const qsub0 = qx0[q_off..][0..32];
                const qsub1 = qx1[q_off..][0..32];
                const qsub2 = qx2[q_off..][0..32];
                const qsub3 = qx3[q_off..][0..32];
                const activation_sum0 = activation_sums0[block_idx][sub];
                const activation_sum1 = activation_sums1[block_idx][sub];
                const activation_sum2 = activation_sums2[block_idx][sub];
                const activation_sum3 = activation_sums3[block_idx][sub];
                const x_scale0 = activation_scales0[block_idx];
                const x_scale1 = activation_scales1[block_idx];
                const x_scale2 = activation_scales2[block_idx];
                const x_scale3 = activation_scales3[block_idx];
                const packed_accumulators = .{
                    .{ .{ &acc_a0_lo, &acc_a1_lo, &acc_a2_lo, &acc_a3_lo }, .{ &acc_a0_hi, &acc_a1_hi, &acc_a2_hi, &acc_a3_hi } },
                    .{ .{ &acc_b0_lo, &acc_b1_lo, &acc_b2_lo, &acc_b3_lo }, .{ &acc_b0_hi, &acc_b1_hi, &acc_b2_hi, &acc_b3_hi } },
                    .{ .{ &acc_c0_lo, &acc_c1_lo, &acc_c2_lo, &acc_c3_lo }, .{ &acc_c0_hi, &acc_c1_hi, &acc_c2_hi, &acc_c3_hi } },
                };
                inline for (0..3) |projection| {
                    q4q5PanelSubAccumulate(16, 4, .ready, true, .{ qsub0, qsub1, qsub2, qsub3 }, .{ x_scale0, x_scale1, x_scale2, x_scale3 }, .{ activation_sum0, activation_sum1, activation_sum2, activation_sum3 }, packedQKVPanel16SubProjectionView(block, sub, projection), packed_accumulators[projection]);
                }
            }
        }
    } else {
        const packed_panel_base = (o / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
        for (0..row_blocks) |block_idx| {
            const q8_off = block_idx * q8_block_size;
            const q8_block_r0 = q_input_row0[q8_off..][0..q8_block_size];
            const q8_block_r1 = q_input_row1[q8_off..][0..q8_block_size];
            const q8_block_r2 = q_input_row2[q8_off..][0..q8_block_size];
            const q8_block_r3 = q_input_row3[q8_off..][0..q8_block_size];
            const qx0 = q8_block_r0[4..260];
            const qx1 = q8_block_r1[4..260];
            const qx2 = q8_block_r2[4..260];
            const qx3 = q8_block_r3[4..260];
            const x_scale0: F32x8 = @splat(readF32Le(q8_block_r0[0..4]));
            const x_scale1: F32x8 = @splat(readF32Le(q8_block_r1[0..4]));
            const x_scale2: F32x8 = @splat(readF32Le(q8_block_r2[0..4]));
            const x_scale3: F32x8 = @splat(readF32Le(q8_block_r3[0..4]));
            const packed_off = packed_panel_base + block_idx * prepared_k_qkv_panel16_block_bytes;
            const block = packed_qkv_panel16[packed_off..][0..prepared_k_qkv_panel16_block_bytes];

            for (0..8) |sub| {
                const q_off = sub * 32;
                const qsub0 = qx0[q_off..][0..32];
                const qsub1 = qx1[q_off..][0..32];
                const qsub2 = qx2[q_off..][0..32];
                const qsub3 = qx3[q_off..][0..32];
                const activation_sum0: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block_r0, sub))));
                const activation_sum1: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block_r1, sub))));
                const activation_sum2: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block_r2, sub))));
                const activation_sum3: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block_r3, sub))));
                const packed_accumulators = .{
                    .{ .{ &acc_a0_lo, &acc_a1_lo, &acc_a2_lo, &acc_a3_lo }, .{ &acc_a0_hi, &acc_a1_hi, &acc_a2_hi, &acc_a3_hi } },
                    .{ .{ &acc_b0_lo, &acc_b1_lo, &acc_b2_lo, &acc_b3_lo }, .{ &acc_b0_hi, &acc_b1_hi, &acc_b2_hi, &acc_b3_hi } },
                    .{ .{ &acc_c0_lo, &acc_c1_lo, &acc_c2_lo, &acc_c3_lo }, .{ &acc_c0_hi, &acc_c1_hi, &acc_c2_hi, &acc_c3_hi } },
                };
                inline for (0..3) |projection| {
                    q4q5PanelSubAccumulate(16, 4, .ready, true, .{ qsub0, qsub1, qsub2, qsub3 }, .{ x_scale0, x_scale1, x_scale2, x_scale3 }, .{ activation_sum0, activation_sum1, activation_sum2, activation_sum3 }, packedQKVPanel16SubProjectionView(block, sub, projection), packed_accumulators[projection]);
                }
            }
        }
    }
    if (prepared_sums) {
        storeF32x16WithBias(out_a0, bias_a, o, acc_a0_lo, acc_a0_hi);
        storeF32x16WithBias(out_a1, bias_a, o, acc_a1_lo, acc_a1_hi);
        storeF32x16WithBias(out_a2, bias_a, o, acc_a2_lo, acc_a2_hi);
        storeF32x16WithBias(out_a3, bias_a, o, acc_a3_lo, acc_a3_hi);
        storeF32x16WithBias(out_b0, bias_b, o, acc_b0_lo, acc_b0_hi);
        storeF32x16WithBias(out_b1, bias_b, o, acc_b1_lo, acc_b1_hi);
        storeF32x16WithBias(out_b2, bias_b, o, acc_b2_lo, acc_b2_hi);
        storeF32x16WithBias(out_b3, bias_b, o, acc_b3_lo, acc_b3_hi);
        storeF32x16WithBias(out_c0, bias_c, o, acc_c0_lo, acc_c0_hi);
        storeF32x16WithBias(out_c1, bias_c, o, acc_c1_lo, acc_c1_hi);
        storeF32x16WithBias(out_c2, bias_c, o, acc_c2_lo, acc_c2_hi);
        storeF32x16WithBias(out_c3, bias_c, o, acc_c3_lo, acc_c3_hi);
    } else {
        storeF32x16(out_a0, o, acc_a0_lo, acc_a0_hi);
        storeF32x16(out_a1, o, acc_a1_lo, acc_a1_hi);
        storeF32x16(out_a2, o, acc_a2_lo, acc_a2_hi);
        storeF32x16(out_a3, o, acc_a3_lo, acc_a3_hi);
        storeF32x16(out_b0, o, acc_b0_lo, acc_b0_hi);
        storeF32x16(out_b1, o, acc_b1_lo, acc_b1_hi);
        storeF32x16(out_b2, o, acc_b2_lo, acc_b2_hi);
        storeF32x16(out_b3, o, acc_b3_lo, acc_b3_hi);
        storeF32x16(out_c0, o, acc_c0_lo, acc_c0_hi);
        storeF32x16(out_c1, o, acc_c1_lo, acc_c1_hi);
        storeF32x16(out_c2, o, acc_c2_lo, acc_c2_hi);
        storeF32x16(out_c3, o, acc_c3_lo, acc_c3_hi);
    }
}

inline fn writeQ4Q5KPreparedQ8KPackedQKVPanel16MR8ProjectionPreparedSums(
    q_input_rows: [8][]const u8,
    activation_sums: *const [8][q8_k_prepared_sum_stack_max_row_blocks][8]F32x8,
    activation_scales: *const [8][q8_k_prepared_sum_stack_max_row_blocks]F32x8,
    packed_qkv_panel16: []const u8,
    bias_a: ?[]const f32,
    out_a_rows: [8][]f32,
    bias_b: ?[]const f32,
    out_b_rows: [8][]f32,
    bias_c: ?[]const f32,
    out_c_rows: [8][]f32,
    row_blocks: usize,
    o: usize,
) void {
    noteNativeQuantDispatch(.q4_q5_k_q8k_triple_packed_qkv_panel16_mr8);

    const q8_block_size: usize = 292;
    var acc_a_lo: [8]F32x8 = @as([8]F32x8, @splat(@splat(0.0)));
    var acc_a_hi: [8]F32x8 = @as([8]F32x8, @splat(@splat(0.0)));
    var acc_b_lo: [8]F32x8 = @as([8]F32x8, @splat(@splat(0.0)));
    var acc_b_hi: [8]F32x8 = @as([8]F32x8, @splat(@splat(0.0)));
    var acc_c_lo: [8]F32x8 = @as([8]F32x8, @splat(@splat(0.0)));
    var acc_c_hi: [8]F32x8 = @as([8]F32x8, @splat(@splat(0.0)));

    const packed_panel_base = (o / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
    for (0..row_blocks) |block_idx| {
        var qx: [8][]const u8 = undefined;
        inline for (0..8) |row| {
            const q8_off = block_idx * q8_block_size;
            qx[row] = q_input_rows[row][q8_off + 4 ..][0..256];
        }
        const packed_off = packed_panel_base + block_idx * prepared_k_qkv_panel16_block_bytes;
        const block = packed_qkv_panel16[packed_off..][0..prepared_k_qkv_panel16_block_bytes];

        for (0..8) |sub| {
            const q_off = sub * 32;
            var qsubs: [8]*const [32]u8 = undefined;
            var x_scales: [8]F32x8 = undefined;
            var sums: [8]F32x8 = undefined;
            inline for (0..8) |row| {
                qsubs[row] = qx[row][q_off..][0..32];
                x_scales[row] = activation_scales[row][block_idx];
                sums[row] = activation_sums[row][block_idx][sub];
            }
            const packed_accumulators = .{
                q4q5PanelAccumulatorPointers(8, &acc_a_lo, &acc_a_hi),
                q4q5PanelAccumulatorPointers(8, &acc_b_lo, &acc_b_hi),
                q4q5PanelAccumulatorPointers(8, &acc_c_lo, &acc_c_hi),
            };
            inline for (0..3) |projection| {
                q4q5PanelSubAccumulate(16, 8, .ready, true, qsubs, x_scales, sums, packedQKVPanel16SubProjectionView(block, sub, projection), packed_accumulators[projection]);
            }
        }
    }

    inline for (0..8) |row| {
        storeF32x16WithBias(out_a_rows[row], bias_a, o, acc_a_lo[row], acc_a_hi[row]);
        storeF32x16WithBias(out_b_rows[row], bias_b, o, acc_b_lo[row], acc_b_hi[row]);
        storeF32x16WithBias(out_c_rows[row], bias_c, o, acc_c_lo[row], acc_c_hi[row]);
    }
}

const q4q5_packed_qkv_row_tile_groups = 4;
const q4q5_packed_qkv_mr8_row_tile_groups = 4;

fn linearQ4Q5KPreparedQ8KActivationTriplePanel16RowTileMR8(
    q_input: []const u8,
    bias_a: ?[]const f32,
    output_a: []f32,
    bias_b: ?[]const f32,
    output_b: []f32,
    bias_c: ?[]const f32,
    output_c: []f32,
    packed_qkv_panel16: []const u8,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
    out_start: usize,
    out_end: usize,
) usize {
    const values_per_block: usize = 256;
    const q8_block_size: usize = 292;
    std.debug.assert(in_dim % values_per_block == 0);
    std.debug.assert(out_start % prepared_k_panel16_nr == 0);
    std.debug.assert(out_end % prepared_k_panel16_nr == 0);
    const row_blocks = in_dim / values_per_block;
    if (row_blocks > q8_k_prepared_sum_stack_max_row_blocks) return 0;

    const input_row_stride = row_blocks * q8_block_size;
    const fast_rows = rows - (rows % 8);
    var r_tile: usize = 0;
    while (r_tile < fast_rows) : (r_tile += q4q5_packed_qkv_mr8_row_tile_groups * 8) {
        const groups = @min(q4q5_packed_qkv_mr8_row_tile_groups, (fast_rows - r_tile) / 8);
        var activation_sums: [q4q5_packed_qkv_mr8_row_tile_groups][8][q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_scales: [q4q5_packed_qkv_mr8_row_tile_groups][8][q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;

        for (0..groups) |group| {
            const r = r_tile + group * 8;
            inline for (0..8) |row| {
                const q_input_row = q_input[(r + row) * input_row_stride ..][0..input_row_stride];
                for (0..row_blocks) |block_idx| {
                    const q8_off = block_idx * q8_block_size;
                    const block = q_input_row[q8_off..][0..q8_block_size];
                    prepareQ8KActivationSums(block, &activation_sums[group][row][block_idx]);
                    activation_scales[group][row][block_idx] = @splat(readF32Le(block[0..4]));
                }
            }
        }

        var o: usize = out_start;
        while (o + prepared_k_panel16_nr <= out_end) : (o += prepared_k_panel16_nr) {
            for (0..groups) |group| {
                const r = r_tile + group * 8;
                var q_input_rows: [8][]const u8 = undefined;
                var out_a_rows: [8][]f32 = undefined;
                var out_b_rows: [8][]f32 = undefined;
                var out_c_rows: [8][]f32 = undefined;
                inline for (0..8) |row| {
                    q_input_rows[row] = q_input[(r + row) * input_row_stride ..][0..input_row_stride];
                    out_a_rows[row] = output_a[(r + row) * out_dim ..][0..out_dim];
                    out_b_rows[row] = output_b[(r + row) * out_dim ..][0..out_dim];
                    out_c_rows[row] = output_c[(r + row) * out_dim ..][0..out_dim];
                }
                writeQ4Q5KPreparedQ8KPackedQKVPanel16MR8ProjectionPreparedSums(
                    q_input_rows,
                    &activation_sums[group],
                    &activation_scales[group],
                    packed_qkv_panel16,
                    bias_a,
                    out_a_rows,
                    bias_b,
                    out_b_rows,
                    bias_c,
                    out_c_rows,
                    row_blocks,
                    o,
                );
            }
        }
    }
    return fast_rows;
}

fn linearQ4Q5KPreparedQ8KActivationTriplePanel16RowTileMR4(
    q_input: []const u8,
    bias_a: ?[]const f32,
    output_a: []f32,
    bias_b: ?[]const f32,
    output_b: []f32,
    bias_c: ?[]const f32,
    output_c: []f32,
    packed_qkv_panel16: []const u8,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
    out_start: usize,
    out_end: usize,
) usize {
    const values_per_block: usize = 256;
    const q8_block_size: usize = 292;
    std.debug.assert(in_dim % values_per_block == 0);
    std.debug.assert(out_start % prepared_k_panel16_nr == 0);
    std.debug.assert(out_end % prepared_k_panel16_nr == 0);
    const row_blocks = in_dim / values_per_block;
    if (row_blocks > q8_k_prepared_sum_stack_max_row_blocks) return 0;

    const input_row_stride = row_blocks * q8_block_size;
    const fast_rows = rows - (rows % 4);
    var r_tile: usize = 0;
    while (r_tile < fast_rows) : (r_tile += q4q5_packed_qkv_row_tile_groups * 4) {
        const groups = @min(q4q5_packed_qkv_row_tile_groups, (fast_rows - r_tile) / 4);
        var activation_sums0: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_sums1: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_sums2: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_sums3: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_scales0: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        var activation_scales1: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        var activation_scales2: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        var activation_scales3: [q4q5_packed_qkv_row_tile_groups][q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;

        for (0..groups) |group| {
            const r = r_tile + group * 4;
            const q_input_row0 = q_input[r * input_row_stride ..][0..input_row_stride];
            const q_input_row1 = q_input[(r + 1) * input_row_stride ..][0..input_row_stride];
            const q_input_row2 = q_input[(r + 2) * input_row_stride ..][0..input_row_stride];
            const q_input_row3 = q_input[(r + 3) * input_row_stride ..][0..input_row_stride];
            for (0..row_blocks) |block_idx| {
                const q8_off = block_idx * q8_block_size;
                const block0 = q_input_row0[q8_off..][0..q8_block_size];
                const block1 = q_input_row1[q8_off..][0..q8_block_size];
                const block2 = q_input_row2[q8_off..][0..q8_block_size];
                const block3 = q_input_row3[q8_off..][0..q8_block_size];
                prepareQ8KActivationSums(block0, &activation_sums0[group][block_idx]);
                prepareQ8KActivationSums(block1, &activation_sums1[group][block_idx]);
                prepareQ8KActivationSums(block2, &activation_sums2[group][block_idx]);
                prepareQ8KActivationSums(block3, &activation_sums3[group][block_idx]);
                activation_scales0[group][block_idx] = @splat(readF32Le(block0[0..4]));
                activation_scales1[group][block_idx] = @splat(readF32Le(block1[0..4]));
                activation_scales2[group][block_idx] = @splat(readF32Le(block2[0..4]));
                activation_scales3[group][block_idx] = @splat(readF32Le(block3[0..4]));
            }
        }

        var o: usize = out_start;
        while (o + prepared_k_panel16_nr <= out_end) : (o += prepared_k_panel16_nr) {
            for (0..groups) |group| {
                const r = r_tile + group * 4;
                const q_input_row0 = q_input[r * input_row_stride ..][0..input_row_stride];
                const q_input_row1 = q_input[(r + 1) * input_row_stride ..][0..input_row_stride];
                const q_input_row2 = q_input[(r + 2) * input_row_stride ..][0..input_row_stride];
                const q_input_row3 = q_input[(r + 3) * input_row_stride ..][0..input_row_stride];
                const out_a0 = output_a[r * out_dim ..][0..out_dim];
                const out_a1 = output_a[(r + 1) * out_dim ..][0..out_dim];
                const out_a2 = output_a[(r + 2) * out_dim ..][0..out_dim];
                const out_a3 = output_a[(r + 3) * out_dim ..][0..out_dim];
                const out_b0 = output_b[r * out_dim ..][0..out_dim];
                const out_b1 = output_b[(r + 1) * out_dim ..][0..out_dim];
                const out_b2 = output_b[(r + 2) * out_dim ..][0..out_dim];
                const out_b3 = output_b[(r + 3) * out_dim ..][0..out_dim];
                const out_c0 = output_c[r * out_dim ..][0..out_dim];
                const out_c1 = output_c[(r + 1) * out_dim ..][0..out_dim];
                const out_c2 = output_c[(r + 2) * out_dim ..][0..out_dim];
                const out_c3 = output_c[(r + 3) * out_dim ..][0..out_dim];
                writeQ4Q5KPreparedQ8KPackedQKVPanel16MR4ProjectionWithSums(true, q_input_row0, q_input_row1, q_input_row2, q_input_row3, &activation_sums0[group], &activation_sums1[group], &activation_sums2[group], &activation_sums3[group], &activation_scales0[group], &activation_scales1[group], &activation_scales2[group], &activation_scales3[group], packed_qkv_panel16, bias_a, out_a0, out_a1, out_a2, out_a3, bias_b, out_b0, out_b1, out_b2, out_b3, bias_c, out_c0, out_c1, out_c2, out_c3, row_blocks, o);
            }
        }
    }
    return fast_rows;
}

inline fn writeQ4Q5KPreparedQ8KPackedQKVPanel16MR2Projection(
    q_input_row0: []const u8,
    q_input_row1: []const u8,
    packed_qkv_panel16: []const u8,
    out_a0: []f32,
    out_a1: []f32,
    out_b0: []f32,
    out_b1: []f32,
    out_c0: []f32,
    out_c1: []f32,
    row_blocks: usize,
    o: usize,
) void {
    noteNativeQuantDispatch(.q4_q5_k_q8k_triple_packed_qkv_panel16_mr2);

    const q8_block_size: usize = 292;
    var acc_a0_lo: F32x8 = @splat(0.0);
    var acc_a0_hi: F32x8 = @splat(0.0);
    var acc_a1_lo: F32x8 = @splat(0.0);
    var acc_a1_hi: F32x8 = @splat(0.0);
    var acc_b0_lo: F32x8 = @splat(0.0);
    var acc_b0_hi: F32x8 = @splat(0.0);
    var acc_b1_lo: F32x8 = @splat(0.0);
    var acc_b1_hi: F32x8 = @splat(0.0);
    var acc_c0_lo: F32x8 = @splat(0.0);
    var acc_c0_hi: F32x8 = @splat(0.0);
    var acc_c1_lo: F32x8 = @splat(0.0);
    var acc_c1_hi: F32x8 = @splat(0.0);

    const packed_panel_base = (o / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
    for (0..row_blocks) |block_idx| {
        const q8_off = block_idx * q8_block_size;
        const q8_block_r0 = q_input_row0[q8_off..][0..q8_block_size];
        const q8_block_r1 = q_input_row1[q8_off..][0..q8_block_size];
        const qx0 = q8_block_r0[4..260];
        const qx1 = q8_block_r1[4..260];
        const x_scale0: F32x8 = @splat(readF32Le(q8_block_r0[0..4]));
        const x_scale1: F32x8 = @splat(readF32Le(q8_block_r1[0..4]));
        const packed_off = packed_panel_base + block_idx * prepared_k_qkv_panel16_block_bytes;
        const block = packed_qkv_panel16[packed_off..][0..prepared_k_qkv_panel16_block_bytes];

        for (0..8) |sub| {
            const q_off = sub * 32;
            const activation_sum0: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block_r0, sub))));
            const activation_sum1: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block_r1, sub))));
            const packed_accumulators = .{
                .{ .{ &acc_a0_lo, &acc_a1_lo }, .{ &acc_a0_hi, &acc_a1_hi } },
                .{ .{ &acc_b0_lo, &acc_b1_lo }, .{ &acc_b0_hi, &acc_b1_hi } },
                .{ .{ &acc_c0_lo, &acc_c1_lo }, .{ &acc_c0_hi, &acc_c1_hi } },
            };
            inline for (0..3) |projection| {
                q4q5PanelSubAccumulate(16, 2, .ready, true, .{ qx0[q_off..][0..32], qx1[q_off..][0..32] }, .{ x_scale0, x_scale1 }, .{ activation_sum0, activation_sum1 }, packedQKVPanel16SubProjectionView(block, sub, projection), packed_accumulators[projection]);
            }
        }
    }

    storeF32x16(out_a0, o, acc_a0_lo, acc_a0_hi);
    storeF32x16(out_a1, o, acc_a1_lo, acc_a1_hi);
    storeF32x16(out_b0, o, acc_b0_lo, acc_b0_hi);
    storeF32x16(out_b1, o, acc_b1_lo, acc_b1_hi);
    storeF32x16(out_c0, o, acc_c0_lo, acc_c0_hi);
    storeF32x16(out_c1, o, acc_c1_lo, acc_c1_hi);
}

inline fn writeQ4Q5KPreparedQ8KPackedQKVPanel16MR1ProjectionWithSums(
    comptime prepared_sums: bool,
    q_input_row: []const u8,
    activation_sums: *const [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8,
    activation_scales: *const [q8_k_prepared_sum_stack_max_row_blocks]F32x8,
    packed_qkv_panel16: []const u8,
    out_a: []f32,
    out_b: []f32,
    out_c: []f32,
    row_blocks: usize,
    o: usize,
) void {
    noteNativeQuantDispatch(.q4_q5_k_q8k_triple_packed_qkv_panel16_mr1);

    const q8_block_size: usize = 292;
    var acc_a_lo: F32x8 = @splat(0.0);
    var acc_a_hi: F32x8 = @splat(0.0);
    var acc_b_lo: F32x8 = @splat(0.0);
    var acc_b_hi: F32x8 = @splat(0.0);
    var acc_c_lo: F32x8 = @splat(0.0);
    var acc_c_hi: F32x8 = @splat(0.0);

    if (prepared_sums) {
        const packed_panel_base = (o / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
        for (0..row_blocks) |block_idx| {
            const q8_off = block_idx * q8_block_size;
            const qx = q_input_row[q8_off + 4 ..][0..256];
            const x_scale = activation_scales[block_idx];
            const packed_off = packed_panel_base + block_idx * prepared_k_qkv_panel16_block_bytes;
            const block = packed_qkv_panel16[packed_off..][0..prepared_k_qkv_panel16_block_bytes];

            for (0..8) |sub| {
                const q_off = sub * 32;
                const activation_sum = activation_sums[block_idx][sub];
                const packed_accumulators = .{
                    .{ .{&acc_a_lo}, .{&acc_a_hi} },
                    .{ .{&acc_b_lo}, .{&acc_b_hi} },
                    .{ .{&acc_c_lo}, .{&acc_c_hi} },
                };
                inline for (0..3) |projection| {
                    q4q5PanelSubAccumulate(16, 1, .ready, true, .{qx[q_off..][0..32]}, .{x_scale}, .{activation_sum}, packedQKVPanel16SubProjectionView(block, sub, projection), packed_accumulators[projection]);
                }
            }
        }
    } else {
        const packed_panel_base = (o / prepared_k_panel16_nr) * row_blocks * prepared_k_qkv_panel16_block_bytes;
        for (0..row_blocks) |block_idx| {
            const q8_off = block_idx * q8_block_size;
            const q8_block = q_input_row[q8_off..][0..q8_block_size];
            const qx = q8_block[4..260];
            const x_scale: F32x8 = @splat(readF32Le(q8_block[0..4]));
            const packed_off = packed_panel_base + block_idx * prepared_k_qkv_panel16_block_bytes;
            const block = packed_qkv_panel16[packed_off..][0..prepared_k_qkv_panel16_block_bytes];

            for (0..8) |sub| {
                const q_off = sub * 32;
                const activation_sum: F32x8 = @splat(@as(f32, @floatFromInt(q8KBlockSum(q8_block, sub))));
                const packed_accumulators = .{
                    .{ .{&acc_a_lo}, .{&acc_a_hi} },
                    .{ .{&acc_b_lo}, .{&acc_b_hi} },
                    .{ .{&acc_c_lo}, .{&acc_c_hi} },
                };
                inline for (0..3) |projection| {
                    q4q5PanelSubAccumulate(16, 1, .ready, true, .{qx[q_off..][0..32]}, .{x_scale}, .{activation_sum}, packedQKVPanel16SubProjectionView(block, sub, projection), packed_accumulators[projection]);
                }
            }
        }
    }

    storeF32x16(out_a, o, acc_a_lo, acc_a_hi);
    storeF32x16(out_b, o, acc_b_lo, acc_b_hi);
    storeF32x16(out_c, o, acc_c_lo, acc_c_hi);
}

fn linearQ4Q5KPreparedQ8KActivationTriplePanel16Range(
    q_input: []const u8,
    prepared_blocks_a: []const u8,
    panel16_blocks_a: []const u8,
    bias_a: ?[]const f32,
    output_a: []f32,
    prepared_blocks_b: []const u8,
    panel16_blocks_b: []const u8,
    bias_b: ?[]const f32,
    output_b: []f32,
    prepared_blocks_c: []const u8,
    panel16_blocks_c: []const u8,
    bias_c: ?[]const f32,
    output_c: []f32,
    packed_qkv_panel16: ?[]const u8,
    packed_qkv_panel16_mr2: bool,
    packed_qkv_panel16_mr8: bool,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
    out_start: usize,
    out_end: usize,
) void {
    @setEvalBranchQuota(50_000);
    const values_per_block: usize = 256;
    const q8_block_size: usize = 292;
    std.debug.assert(in_dim % values_per_block == 0);
    const row_blocks = in_dim / values_per_block;
    const input_row_stride = row_blocks * q8_block_size;
    const prepared_row_stride = row_blocks * prepared_q4_k_block_bytes;
    const triple_panel16_dot = q4q5TriplePanel16DotEnabled() or packed_qkv_panel16 != null;

    var r: usize = 0;
    if (q4q5PackedQKVPanel16RowTileEnabled() and
        packed_qkv_panel16_mr8 and
        packed_qkv_panel16 != null and
        row_blocks <= q8_k_prepared_sum_stack_max_row_blocks and
        out_start % prepared_k_panel16_nr == 0 and
        out_end % prepared_k_panel16_nr == 0)
    {
        r = linearQ4Q5KPreparedQ8KActivationTriplePanel16RowTileMR8(
            q_input,
            bias_a,
            output_a,
            bias_b,
            output_b,
            bias_c,
            output_c,
            packed_qkv_panel16.?,
            rows,
            in_dim,
            out_dim,
            out_start,
            out_end,
        );
    }
    if (q4q5PackedQKVPanel16RowTileEnabled() and
        !packed_qkv_panel16_mr8 and
        packed_qkv_panel16 != null and
        row_blocks <= q8_k_prepared_sum_stack_max_row_blocks and
        out_start % prepared_k_panel16_nr == 0 and
        out_end % prepared_k_panel16_nr == 0 and
        r < rows - (rows % 4))
    {
        const mr4_rows = linearQ4Q5KPreparedQ8KActivationTriplePanel16RowTileMR4(
            q_input,
            bias_a,
            output_a,
            bias_b,
            output_b,
            bias_c,
            output_c,
            packed_qkv_panel16.?,
            rows,
            in_dim,
            out_dim,
            out_start,
            out_end,
        );
        if (mr4_rows > r) r = mr4_rows;
    }
    // quant-kernel-codegen:begin CPU Q4 Q5 triple panel16 rows
    while (r + 4 <= rows) : (r += 4) {
        const q_input_row0 = q_input[r * input_row_stride ..][0..input_row_stride];
        const q_input_row1 = q_input[(r + 1) * input_row_stride ..][0..input_row_stride];
        const q_input_row2 = q_input[(r + 2) * input_row_stride ..][0..input_row_stride];
        const q_input_row3 = q_input[(r + 3) * input_row_stride ..][0..input_row_stride];
        const out_a0 = output_a[r * out_dim ..][0..out_dim];
        const out_a1 = output_a[(r + 1) * out_dim ..][0..out_dim];
        const out_a2 = output_a[(r + 2) * out_dim ..][0..out_dim];
        const out_a3 = output_a[(r + 3) * out_dim ..][0..out_dim];
        const out_b0 = output_b[r * out_dim ..][0..out_dim];
        const out_b1 = output_b[(r + 1) * out_dim ..][0..out_dim];
        const out_b2 = output_b[(r + 2) * out_dim ..][0..out_dim];
        const out_b3 = output_b[(r + 3) * out_dim ..][0..out_dim];
        const out_c0 = output_c[r * out_dim ..][0..out_dim];
        const out_c1 = output_c[(r + 1) * out_dim ..][0..out_dim];
        const out_c2 = output_c[(r + 2) * out_dim ..][0..out_dim];
        const out_c3 = output_c[(r + 3) * out_dim ..][0..out_dim];
        const use_projection_prepared_sums = row_blocks <= q8_k_prepared_sum_stack_max_row_blocks and (!triple_panel16_dot or packed_qkv_panel16 != null);
        var activation_sums0: [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_sums1: [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_sums2: [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_sums3: [q8_k_prepared_sum_stack_max_row_blocks][8]F32x8 = undefined;
        var activation_scales0: [q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        var activation_scales1: [q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        var activation_scales2: [q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        var activation_scales3: [q8_k_prepared_sum_stack_max_row_blocks]F32x8 = undefined;
        if (use_projection_prepared_sums) {
            for (0..row_blocks) |block_idx| {
                const q8_off = block_idx * q8_block_size;
                const block0 = q_input_row0[q8_off..][0..q8_block_size];
                const block1 = q_input_row1[q8_off..][0..q8_block_size];
                const block2 = q_input_row2[q8_off..][0..q8_block_size];
                const block3 = q_input_row3[q8_off..][0..q8_block_size];
                prepareQ8KActivationSums(block0, &activation_sums0[block_idx]);
                prepareQ8KActivationSums(block1, &activation_sums1[block_idx]);
                prepareQ8KActivationSums(block2, &activation_sums2[block_idx]);
                prepareQ8KActivationSums(block3, &activation_sums3[block_idx]);
                activation_scales0[block_idx] = @splat(readF32Le(block0[0..4]));
                activation_scales1[block_idx] = @splat(readF32Le(block1[0..4]));
                activation_scales2[block_idx] = @splat(readF32Le(block2[0..4]));
                activation_scales3[block_idx] = @splat(readF32Le(block3[0..4]));
            }
        }
        var o: usize = out_start;
        while (o < out_end and (o % prepared_k_panel16_nr) != 0) : (o += 1) {
            const prepared_row_a = prepared_blocks_a[o * prepared_row_stride ..][0..prepared_row_stride];
