        q8KQ8KWeightBlock(weight_raw, panel_blocks, row_blocks, row_stride, out_col + 1, block_idx, allow_panel),
        q8KQ8KWeightBlock(weight_raw, panel_blocks, row_blocks, row_stride, out_col + 2, block_idx, allow_panel),
        q8KQ8KWeightBlock(weight_raw, panel_blocks, row_blocks, row_stride, out_col + 3, block_idx, allow_panel),
