    panel8_blocks_a: ?[]const u8,
    panel8_blocks_b: ?[]const u8,
    output_a: []f32,
    output_b: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const row_blocks = try validatePreparedK16ActivationBlocks(prepared_blocks_a, panel_blocks_a, panel8_blocks_a, in_dim, out_dim);
    const row_blocks_b = try validatePreparedK16ActivationBlocks(prepared_blocks_b, panel_blocks_b, panel8_blocks_b, in_dim, out_dim);
    if (row_blocks_b != row_blocks) return error.InvalidQuantizedLinearShape;
    if (rows == 1 and in_dim <= small_row_q8_k_stack_max_in_dim) {
        const values_per_block: usize = 256;
        const q8_block_size: usize = 292;
        var q_input_buf: [small_row_q8_k_stack_max_in_dim / values_per_block * q8_block_size]u8 = undefined;
        const q_input = q_input_buf[0 .. row_blocks * q8_block_size];
        try quantizeQ8_KActivationRowsDispatch(io, input, q_input, rows, in_dim, row_blocks);
        try linearK16PreparedQ8KActivationPairDispatch(has_min, io, q_input, prepared_blocks_a, panel_blocks_a, panel8_blocks_a, prepared_blocks_b, panel_blocks_b, panel8_blocks_b, output_a, output_b, rows, in_dim, out_dim);
        return;
    }
    const q_input = try quantizeK16Activation(allocator, io, input, rows, in_dim, row_blocks);
    defer allocator.free(q_input);
    try linearK16PreparedQ8KActivationPairDispatch(has_min, io, q_input, prepared_blocks_a, panel_blocks_a, panel8_blocks_a, prepared_blocks_b, panel_blocks_b, panel8_blocks_b, output_a, output_b, rows, in_dim, out_dim);
}

fn linearK16PreparedQ8KActivationTriple(
    comptime has_min: bool,
    allocator: std.mem.Allocator,
    io: ?std.Io,
    input: []const f32,
    prepared_blocks_a: []const u8,
    prepared_blocks_b: []const u8,
    prepared_blocks_c: []const u8,
    panel_blocks_a: ?[]const u8,
    panel_blocks_b: ?[]const u8,
    panel_blocks_c: ?[]const u8,
    panel8_blocks_a: ?[]const u8,
    panel8_blocks_b: ?[]const u8,
    panel8_blocks_c: ?[]const u8,
    bias_a: ?[]const f32,
    bias_b: ?[]const f32,
    bias_c: ?[]const f32,
    output_a: []f32,
    output_b: []f32,
    output_c: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const row_blocks = try validatePreparedK16ActivationBlocks(prepared_blocks_a, panel_blocks_a, panel8_blocks_a, in_dim, out_dim);
    const row_blocks_b = try validatePreparedK16ActivationBlocks(prepared_blocks_b, panel_blocks_b, panel8_blocks_b, in_dim, out_dim);
    const row_blocks_c = try validatePreparedK16ActivationBlocks(prepared_blocks_c, panel_blocks_c, panel8_blocks_c, in_dim, out_dim);
    if (row_blocks_b != row_blocks or row_blocks_c != row_blocks) return error.InvalidQuantizedLinearShape;
    if (rows == 1 and in_dim <= small_row_q8_k_stack_max_in_dim) {
        const values_per_block: usize = 256;
        const q8_block_size: usize = 292;
        var q_input_buf: [small_row_q8_k_stack_max_in_dim / values_per_block * q8_block_size]u8 = undefined;
        const q_input = q_input_buf[0 .. row_blocks * q8_block_size];
        try quantizeQ8_KActivationRowsDispatch(io, input, q_input, rows, in_dim, row_blocks);
        try linearK16PreparedQ8KActivationTripleDispatch(has_min, io, q_input, prepared_blocks_a, panel_blocks_a, panel8_blocks_a, prepared_blocks_b, panel_blocks_b, panel8_blocks_b, prepared_blocks_c, panel_blocks_c, panel8_blocks_c, bias_a, bias_b, bias_c, output_a, output_b, output_c, rows, in_dim, out_dim);
        return;
    }
    const q_input = try quantizeK16Activation(allocator, io, input, rows, in_dim, row_blocks);
    defer allocator.free(q_input);
    try linearK16PreparedQ8KActivationTripleDispatch(has_min, io, q_input, prepared_blocks_a, panel_blocks_a, panel8_blocks_a, prepared_blocks_b, panel_blocks_b, panel8_blocks_b, prepared_blocks_c, panel_blocks_c, panel8_blocks_c, bias_a, bias_b, bias_c, output_a, output_b, output_c, rows, in_dim, out_dim);
}

