    try linearQ8_0Pair(allocator, io, input, weight_raw_a, weight_raw_b, prepared_blocks_a, prepared_blocks_b, prepared_panel_blocks_a, prepared_panel_blocks_b, prepared_panel8_blocks_a, prepared_panel8_blocks_b, null, null, output_a, output_b, rows, in_dim, out_dim);
}

// Cardinality is static; existing quantized and F32 microkernels retain their
// schedules. Only validation, activation ownership and plane routing are shared.
const ActivationProjectionCodec = enum { q1, q8 };

inline fn dispatchActivationProjections(
    comptime codec: ActivationProjectionCodec,
    comptime n: usize,
    io: ?std.Io,
    q_values: []const u8,
    scales: []const f32,
    weights: [n][]const u8,
    prepared: [n]?[]const u8,
    panels: [n]?[]const u8,
    panels8: [n]?[]const u8,
    biases: [n]?[]const f32,
    outputs: [n][]f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    if (codec == .q8) return dispatchQ8_0Projections(n, io, q_values, scales, weights, prepared, panels, panels8, biases, outputs, rows, in_dim, out_dim);
    if (n == 1) {
        return linearQ1_0PreparedActivationDispatch(io, q_values, scales, prepared[0].?, panels[0], biases[0], outputs[0], rows, in_dim, out_dim);
    } else if (n == 2) {
        return linearQ1_0PreparedActivationPairDispatch(io, q_values, scales, prepared[0].?, panels[0], prepared[1].?, panels[1], outputs[0], outputs[1], rows, in_dim, out_dim);
    } else {
        return linearQ1_0PreparedActivationTripleDispatch(io, q_values, scales, prepared[0].?, panels[0], prepared[1].?, panels[1], prepared[2].?, panels[2], biases[0], biases[1], biases[2], outputs[0], outputs[1], outputs[2], rows, in_dim, out_dim);
    }
}

// One ownership scope for the same Q8 activation representation. Codec policy
// retains the Q1 serial quantizer and the Q8 dispatching quantizer exactly.
inline fn applyQuantizedActivationProjections(
    comptime codec: ActivationProjectionCodec,
    comptime n: usize,
    comptime profile: bool,
    allocator: std.mem.Allocator,
    io: ?std.Io,
    input: []const f32,
    weights: [n][]const u8,
    prepared: [n]?[]const u8,
    panels: [n]?[]const u8,
    panels8: [n]?[]const u8,
    biases: [n]?[]const f32,
    outputs: [n][]f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const blocks = in_dim / 32;
    if (rows == 1 and in_dim <= small_row_q8_0_stack_max_in_dim) {
        var values_buf: [small_row_q8_0_stack_max_in_dim]u8 = undefined;
        var scales_buf: [small_row_q8_0_stack_max_in_dim / 32]f32 = undefined;
        const values = values_buf[0..in_dim];
        const scales = scales_buf[0..blocks];
        const quant_start = if (profile) nativeQuantPhaseStart() else 0;
        if (codec == .q1) quantizeQ8_0ActivationRows(input, values, scales, rows, in_dim, blocks) else try quantizeQ8_0ActivationRowsDispatch(io, input, values, scales, rows, in_dim, blocks);
        if (profile) noteNativeQuantPhase(.q8_0_activation_quant, quant_start);
        const compute_start = if (profile) nativeQuantPhaseStart() else 0;
        try dispatchActivationProjections(codec, n, io, values, scales, weights, prepared, panels, panels8, biases, outputs, rows, in_dim, out_dim);
        if (profile) noteNativeQuantPhase(.q8_0_compute, compute_start);
        return;
    }
    const alloc_start = if (profile) nativeQuantPhaseStart() else 0;
    const values = try allocator.alloc(u8, rows * blocks * 32);
    defer allocator.free(values);
    const scales = try allocator.alloc(f32, rows * blocks);
    defer allocator.free(scales);
    if (profile) noteNativeQuantPhase(.q8_0_activation_alloc, alloc_start);
    const quant_start = if (profile) nativeQuantPhaseStart() else 0;
    if (codec == .q1) quantizeQ8_0ActivationRows(input, values, scales, rows, in_dim, blocks) else try quantizeQ8_0ActivationRowsDispatch(io, input, values, scales, rows, in_dim, blocks);
    if (profile) noteNativeQuantPhase(.q8_0_activation_quant, quant_start);
    const compute_start = if (profile) nativeQuantPhaseStart() else 0;
    try dispatchActivationProjections(codec, n, io, values, scales, weights, prepared, panels, panels8, biases, outputs, rows, in_dim, out_dim);
    if (profile) noteNativeQuantPhase(.q8_0_compute, compute_start);
    return;
}

inline fn linearPreparedActivationProjections(
    comptime codec: ActivationProjectionCodec,
    comptime n: usize,
    allocator: std.mem.Allocator,
    io: ?std.Io,
    input: []const f32,
    prepared: [n][]const u8,
    panels: [n]?[]const u8,
    panels8: [n]?[]const u8,
    biases: [n]?[]const f32,
    outputs: [n][]f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    var blocks: [n]usize = undefined;
    var optional_prepared: [n]?[]const u8 = undefined;
    inline for (0..n) |plane| {
        blocks[plane] = if (codec == .q1)
            try validatePreparedQ1_0ActivationBlocks(prepared[plane], panels[plane], in_dim, out_dim)
        else
            try validatePreparedQ8_1ActivationBlocks(prepared[plane], panels[plane], rows, in_dim, out_dim);
        optional_prepared[plane] = prepared[plane];
    }
    inline for (1..n) |plane| if (blocks[plane] != blocks[0]) return error.InvalidQuantizedLinearShape;
    return applyQuantizedActivationProjections(codec, n, false, allocator, io, input, @splat(&empty_u8), optional_prepared, panels, panels8, biases, outputs, rows, in_dim, out_dim);
}

inline fn validateQ8_0ProjectionFamily(
    comptime n: usize,
    weights: [n][]const u8,
    prepared: [n]?[]const u8,
    panels: [n]?[]const u8,
    panels8: [n]?[]const u8,
    in_dim: usize,
    out_dim: usize,
) !usize {
    const values_per_block: usize = 32;
    if (in_dim % values_per_block != 0) return error.InvalidQuantizedLinearShape;
    const row_blocks = in_dim / values_per_block;
    inline for (weights) |weight| if (weight.len != out_dim * row_blocks * 34) return error.InvalidQuantizedDataSize;
    inline for (prepared) |maybe| if (maybe) |blocks| {
        if (blocks.len != out_dim * row_blocks * prepared_q8_0_block_bytes) return error.InvalidQuantizedDataSize;
    };
    inline for (panels) |maybe| if (maybe) |blocks| {
        if (blocks.len != preparedQ8_0PanelByteSize(out_dim, row_blocks)) return error.InvalidQuantizedDataSize;
    };
    inline for (panels8) |maybe| if (maybe) |blocks| {
        if (blocks.len != preparedQ8_0Panel8ByteSize(out_dim, row_blocks)) return error.InvalidQuantizedDataSize;
    };
    return row_blocks;
}

inline fn linearQ8_0Projections(
    comptime n: usize,
    allocator: std.mem.Allocator,
    io: ?std.Io,
    input: []const f32,
    weights: [n][]const u8,
    prepared: [n]?[]const u8,
    panels: [n]?[]const u8,
    panels8: [n]?[]const u8,
    biases: [n]?[]const f32,
    outputs: [n][]f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const row_blocks = try validateQ8_0ProjectionFamily(n, weights, prepared, panels, panels8, in_dim, out_dim);
    if (shouldUseQ8_0ActivationQuant(rows, out_dim, row_blocks))
        return applyQuantizedActivationProjections(.q8, n, false, allocator, io, input, weights, prepared, panels, panels8, biases, outputs, rows, in_dim, out_dim);
    if (try linearQ8_0ProjectedParallel(n, io, input, weights, prepared, panels, biases, outputs, rows, in_dim, out_dim)) return;
    inline for (0..n) |plane| q8_0F32Apply(input, weights[plane], prepared[plane], panels[plane], biases[plane], outputs[plane], rows, in_dim, out_dim, 0, out_dim);
}

inline fn dispatchQ8_0Projections(
    comptime n: usize,
    io: ?std.Io,
    q_values: []const u8,
    scales: []const f32,
    weights: [n][]const u8,
    prepared: [n]?[]const u8,
    panels: [n]?[]const u8,
    panels8: [n]?[]const u8,
    biases: [n]?[]const f32,
    outputs: [n][]f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    if (n == 1) {
        return linearQ8_0QuantizedInputDispatch(io, q_values, scales, weights[0], prepared[0], panels[0], panels8[0], biases[0], outputs[0], rows, in_dim, out_dim);
    } else if (n == 2) {
        return linearQ8_0QuantizedInputPairDispatch(io, q_values, scales, weights[0], prepared[0], panels[0], panels8[0], biases[0], outputs[0], weights[1], prepared[1], panels[1], panels8[1], biases[1], outputs[1], rows, in_dim, out_dim);
    } else {
        return linearQ8_0QuantizedInputTripleDispatch(io, q_values, scales, weights[0], prepared[0], panels[0], panels8[0], biases[0], outputs[0], weights[1], prepared[1], panels[1], panels8[1], biases[1], outputs[1], weights[2], prepared[2], panels[2], panels8[2], biases[2], outputs[2], rows, in_dim, out_dim);
    }
}

fn linearQ8_0Pair(
    allocator: std.mem.Allocator,
    io: ?std.Io,
    input: []const f32,
    weight_raw_a: []const u8,
    weight_raw_b: []const u8,
    prepared_blocks_a: ?[]const u8,
    prepared_blocks_b: ?[]const u8,
    prepared_panel_blocks_a: ?[]const u8,
    prepared_panel_blocks_b: ?[]const u8,
    prepared_panel8_blocks_a: ?[]const u8,
    prepared_panel8_blocks_b: ?[]const u8,
    bias_a: ?[]const f32,
    bias_b: ?[]const f32,
    output_a: []f32,
    output_b: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    return linearQ8_0Projections(2, allocator, io, input, .{ weight_raw_a, weight_raw_b }, .{ prepared_blocks_a, prepared_blocks_b }, .{ prepared_panel_blocks_a, prepared_panel_blocks_b }, .{ prepared_panel8_blocks_a, prepared_panel8_blocks_b }, .{ bias_a, bias_b }, .{ output_a, output_b }, rows, in_dim, out_dim);
}

fn linearQ8_0Triple(
    allocator: std.mem.Allocator,
    io: ?std.Io,
    input: []const f32,
    weight_raw_a: []const u8,
    weight_raw_b: []const u8,
    weight_raw_c: []const u8,
    prepared_blocks_a: ?[]const u8,
    prepared_blocks_b: ?[]const u8,
    prepared_blocks_c: ?[]const u8,
    prepared_panel_blocks_a: ?[]const u8,
    prepared_panel_blocks_b: ?[]const u8,
    prepared_panel_blocks_c: ?[]const u8,
    prepared_panel8_blocks_a: ?[]const u8,
    prepared_panel8_blocks_b: ?[]const u8,
    prepared_panel8_blocks_c: ?[]const u8,
    bias_a: ?[]const f32,
    bias_b: ?[]const f32,
    bias_c: ?[]const f32,
    output_a: []f32,
    output_b: []f32,
    output_c: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    return linearQ8_0Projections(3, allocator, io, input, .{ weight_raw_a, weight_raw_b, weight_raw_c }, .{ prepared_blocks_a, prepared_blocks_b, prepared_blocks_c }, .{ prepared_panel_blocks_a, prepared_panel_blocks_b, prepared_panel_blocks_c }, .{ prepared_panel8_blocks_a, prepared_panel8_blocks_b, prepared_panel8_blocks_c }, .{ bias_a, bias_b, bias_c }, .{ output_a, output_b, output_c }, rows, in_dim, out_dim);
}

fn linearNoBiasI2SActivationQuantized(
    allocator: std.mem.Allocator,
    input: []const f32,
    weight_raw: []const u8,
    output: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const tensor_type: gguf_tensor_types.TensorType = .{ .known = .I2_S };
    const block_size = gguf_tensor_types.bytesPerBlock(tensor_type).?;
    const values_per_block = gguf_tensor_types.valuesPerBlock(tensor_type).?;
    if (in_dim % values_per_block != 0) return error.InvalidQuantizedLinearShape;
    const row_blocks = in_dim / values_per_block;
    if (weight_raw.len < out_dim * row_blocks * block_size) return error.InvalidQuantizedDataSize;
    const quantized_input_row = try allocator.alloc(i8, in_dim);
    defer allocator.free(quantized_input_row);

    for (0..rows) |r| {
        const input_row = input[r * in_dim ..][0..in_dim];
        const out_row = output[r * out_dim ..][0..out_dim];
        const scale = bitnetActivationScale(input_row);
        quantizeBitnetActivationRow(input_row, scale, quantized_input_row);
        for (0..out_dim) |o| {
            const row_offset = o * row_blocks * block_size;
            var acc: f32 = 0.0;
            for (0..row_blocks) |block_idx| {
                const blk = weight_raw[row_offset + block_idx * block_size ..][0..block_size];
                const input_block = quantized_input_row[block_idx * values_per_block ..][0..values_per_block];
                acc += dotI2SBlockActivationQuantized(input_block, blk, scale);
            }
            out_row[o] = acc;
        }
    }
}

fn linearNoBiasI2SPairActivationQuantized(
    allocator: std.mem.Allocator,
    input: []const f32,
    weight_raw_a: []const u8,
    weight_raw_b: []const u8,
    output_a: []f32,
    output_b: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const tensor_type: gguf_tensor_types.TensorType = .{ .known = .I2_S };
    const block_size = gguf_tensor_types.bytesPerBlock(tensor_type).?;
    const values_per_block = gguf_tensor_types.valuesPerBlock(tensor_type).?;
    if (in_dim % values_per_block != 0) return error.InvalidQuantizedLinearShape;
    const row_blocks = in_dim / values_per_block;
    if (weight_raw_a.len < out_dim * row_blocks * block_size) return error.InvalidQuantizedDataSize;
    if (weight_raw_b.len < out_dim * row_blocks * block_size) return error.InvalidQuantizedDataSize;
    const quantized_input_row = try allocator.alloc(i8, in_dim);
    defer allocator.free(quantized_input_row);

    for (0..rows) |r| {
        const input_row = input[r * in_dim ..][0..in_dim];
        const out_row_a = output_a[r * out_dim ..][0..out_dim];
        const out_row_b = output_b[r * out_dim ..][0..out_dim];
        const scale = bitnetActivationScale(input_row);
        quantizeBitnetActivationRow(input_row, scale, quantized_input_row);
        for (0..out_dim) |o| {
            const row_offset = o * row_blocks * block_size;
            var acc_a: f32 = 0.0;
            var acc_b: f32 = 0.0;
            for (0..row_blocks) |block_idx| {
                const blk_a = weight_raw_a[row_offset + block_idx * block_size ..][0..block_size];
                const blk_b = weight_raw_b[row_offset + block_idx * block_size ..][0..block_size];
                const input_block = quantized_input_row[block_idx * values_per_block ..][0..values_per_block];
                acc_a += dotI2SBlockActivationQuantized(input_block, blk_a, scale);
                acc_b += dotI2SBlockActivationQuantized(input_block, blk_b, scale);
            }
            out_row_a[o] = acc_a;
            out_row_b[o] = acc_b;
        }
    }
}

fn linearNoBiasTL1ActivationQuantized(
    allocator: std.mem.Allocator,
    input: []const f32,
    weight_raw: []const u8,
    weight_shape: []const i64,
    output: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const view = try quant_codec.bitnetTL1View(weight_shape, weight_raw);
    const pair_lut = try allocator.alloc(f32, view.pairCount() * bitnet_tl_pair_lut_entries);
    defer allocator.free(pair_lut);

    for (0..rows) |r| {
        const input_row = input[r * in_dim ..][0..in_dim];
        const out_row = output[r * out_dim ..][0..out_dim];
        const scale = bitnetActivationScale(input_row);
        fillTL1ActivationPairLut(input_row, scale, view.weight_scale, pair_lut);
        for (0..out_dim) |o| {
            out_row[o] = try dotTL1LutRow(view, o, pair_lut);
        }
    }
}

fn linearNoBiasTL1PairActivationQuantized(
    allocator: std.mem.Allocator,
    input: []const f32,
    weight_raw_a: []const u8,
    weight_raw_b: []const u8,
    weight_shape_a: []const i64,
    weight_shape_b: []const i64,
    output_a: []f32,
    output_b: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const view_a = try quant_codec.bitnetTL1View(weight_shape_a, weight_raw_a);
    const view_b = try quant_codec.bitnetTL1View(weight_shape_b, weight_raw_b);
    const pair_lut_a = try allocator.alloc(f32, view_a.pairCount() * bitnet_tl_pair_lut_entries);
    defer allocator.free(pair_lut_a);
    const pair_lut_b = try allocator.alloc(f32, view_b.pairCount() * bitnet_tl_pair_lut_entries);
    defer allocator.free(pair_lut_b);

    for (0..rows) |r| {
        const input_row = input[r * in_dim ..][0..in_dim];
        const out_row_a = output_a[r * out_dim ..][0..out_dim];
        const out_row_b = output_b[r * out_dim ..][0..out_dim];
        const scale = bitnetActivationScale(input_row);
        fillTL1ActivationPairLut(input_row, scale, view_a.weight_scale, pair_lut_a);
        fillTL1ActivationPairLut(input_row, scale, view_b.weight_scale, pair_lut_b);
        for (0..out_dim) |o| {
            out_row_a[o] = try dotTL1LutRow(view_a, o, pair_lut_a);
            out_row_b[o] = try dotTL1LutRow(view_b, o, pair_lut_b);
        }
    }
}

fn linearNoBiasTL2ActivationQuantized(
    allocator: std.mem.Allocator,
    input: []const f32,
    weight_raw: []const u8,
    weight_shape: []const i64,
    output: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const view = try quant_codec.bitnetTL2View(weight_shape, weight_raw);
    const three_lut = try allocator.alloc(f32, view.threeCount() * bitnet_tl_three_lut_entries);
    defer allocator.free(three_lut);
    const two_lut = try allocator.alloc(f32, view.twoPairCount() * bitnet_tl_pair_lut_entries);
    defer allocator.free(two_lut);

    for (0..rows) |r| {
        const input_row = input[r * in_dim ..][0..in_dim];
        const out_row = output[r * out_dim ..][0..out_dim];
        const scale = bitnetActivationScale(input_row);
        fillTL2ActivationLuts(input_row, scale, view, three_lut, two_lut);
        for (0..out_dim) |o| {
            out_row[o] = try dotTL2LutRow(view, o, three_lut, two_lut);
        }
    }
}

fn linearNoBiasTL2PairActivationQuantized(
    allocator: std.mem.Allocator,
    input: []const f32,
    weight_raw_a: []const u8,
    weight_raw_b: []const u8,
    weight_shape_a: []const i64,
    weight_shape_b: []const i64,
    output_a: []f32,
    output_b: []f32,
    rows: usize,
    in_dim: usize,
    out_dim: usize,
) !void {
    const view_a = try quant_codec.bitnetTL2View(weight_shape_a, weight_raw_a);
    const view_b = try quant_codec.bitnetTL2View(weight_shape_b, weight_raw_b);
    const three_lut_a = try allocator.alloc(f32, view_a.threeCount() * bitnet_tl_three_lut_entries);
    defer allocator.free(three_lut_a);
    const two_lut_a = try allocator.alloc(f32, view_a.twoPairCount() * bitnet_tl_pair_lut_entries);
    defer allocator.free(two_lut_a);
    const three_lut_b = try allocator.alloc(f32, view_b.threeCount() * bitnet_tl_three_lut_entries);
    defer allocator.free(three_lut_b);
    const two_lut_b = try allocator.alloc(f32, view_b.twoPairCount() * bitnet_tl_pair_lut_entries);
    defer allocator.free(two_lut_b);

    for (0..rows) |r| {
        const input_row = input[r * in_dim ..][0..in_dim];
        const out_row_a = output_a[r * out_dim ..][0..out_dim];
        const out_row_b = output_b[r * out_dim ..][0..out_dim];
        const scale = bitnetActivationScale(input_row);
        fillTL2ActivationLuts(input_row, scale, view_a, three_lut_a, two_lut_a);
        fillTL2ActivationLuts(input_row, scale, view_b, three_lut_b, two_lut_b);
        for (0..out_dim) |o| {
            out_row_a[o] = try dotTL2LutRow(view_a, o, three_lut_a, two_lut_a);
            out_row_b[o] = try dotTL2LutRow(view_b, o, three_lut_b, two_lut_b);
        }
    }
}

const bitnet_tl_pair_lut_entries = 16;
const bitnet_tl_three_lut_entries = 32;
const bitnet_tl_simd_lanes = 8;

fn fillTL1ActivationPairLut(input_row: []const f32, scale: f32, weight_scale: f32, pair_lut: []f32) void {
    std.debug.assert(input_row.len % 2 == 0);
    std.debug.assert(pair_lut.len == (input_row.len / 2) * bitnet_tl_pair_lut_entries);

    for (0..input_row.len / 2) |pair_col| {
        const a0 = quantizeBitnetActivation(input_row[pair_col * 2 + 0], scale);
        const a1 = quantizeBitnetActivation(input_row[pair_col * 2 + 1], scale);
        const base = pair_col * bitnet_tl_pair_lut_entries;
        inline for (0..bitnet_tl_pair_lut_entries) |code| {
            const pair = quant_codec.bitnetTLPair(@intCast(code));
            pair_lut[base + code] = (a0 * @as(f32, @floatFromInt(pair[0])) + a1 * @as(f32, @floatFromInt(pair[1]))) * weight_scale;
        }
    }
}

fn fillTL2ActivationLuts(
    input_row: []const f32,
    scale: f32,
    view: quant_codec.BitnetTL2View,
    three_lut: []f32,
    two_lut: []f32,
) void {
    std.debug.assert(three_lut.len == view.threeCount() * bitnet_tl_three_lut_entries);
    std.debug.assert(two_lut.len == view.twoPairCount() * bitnet_tl_pair_lut_entries);

    for (0..view.threeCount()) |triple_col| {
        const col = triple_col * 3;
        const a0 = quantizeBitnetActivation(input_row[col + 0], scale);
        const a1 = quantizeBitnetActivation(input_row[col + 1], scale);
        const a2 = quantizeBitnetActivation(input_row[col + 2], scale);
        const base = triple_col * bitnet_tl_three_lut_entries;
        inline for (0..16) |code| {
            inline for (0..2) |negative_bit| {
                const triple = quant_codec.bitnetTL2Three(@intCast(code), negative_bit != 0);
                three_lut[base + code * 2 + negative_bit] =
                    (a0 * @as(f32, @floatFromInt(triple[0])) +
                        a1 * @as(f32, @floatFromInt(triple[1])) +
                        a2 * @as(f32, @floatFromInt(triple[2]))) * view.weight_scale;
            }
        }
    }

    for (0..view.twoPairCount()) |pair_col| {
        const col = view.three_cols + pair_col * 2;
        const a0 = quantizeBitnetActivation(input_row[col + 0], scale);
        const a1 = quantizeBitnetActivation(input_row[col + 1], scale);
        const base = pair_col * bitnet_tl_pair_lut_entries;
        inline for (0..bitnet_tl_pair_lut_entries) |code| {
            const pair = quant_codec.bitnetTLPair(@intCast(code));
            two_lut[base + code] = (a0 * @as(f32, @floatFromInt(pair[0])) + a1 * @as(f32, @floatFromInt(pair[1]))) * view.weight_scale;
        }
    }
}

fn dotTL1LutRow(view: quant_codec.BitnetTL1View, row: usize, pair_lut: []const f32) !f32 {
    const pair_count = view.pairCount();
    std.debug.assert(pair_lut.len == pair_count * bitnet_tl_pair_lut_entries);

    var vec_acc: @Vector(bitnet_tl_simd_lanes, f32) = @splat(0.0);
    var pair_col: usize = 0;
    while (pair_col + bitnet_tl_simd_lanes <= pair_count) : (pair_col += bitnet_tl_simd_lanes) {
        var lanes: @Vector(bitnet_tl_simd_lanes, f32) = @splat(0.0);
        inline for (0..bitnet_tl_simd_lanes) |lane| {
            const code = try view.pairCode(row, pair_col + lane);
            lanes[lane] = pair_lut[(pair_col + lane) * bitnet_tl_pair_lut_entries + @as(usize, @intCast(code))];
        }
        vec_acc += lanes;
    }

    var acc = @reduce(.Add, vec_acc);
    while (pair_col < pair_count) : (pair_col += 1) {
        const code = try view.pairCode(row, pair_col);
        acc += pair_lut[pair_col * bitnet_tl_pair_lut_entries + @as(usize, @intCast(code))];
    }
    return acc;
}

fn dotTL2LutRow(
    view: quant_codec.BitnetTL2View,
    row: usize,
    three_lut: []const f32,
    two_lut: []const f32,
) !f32 {
    const three_count = view.threeCount();
    const two_count = view.twoPairCount();
    std.debug.assert(three_lut.len == three_count * bitnet_tl_three_lut_entries);
    std.debug.assert(two_lut.len == two_count * bitnet_tl_pair_lut_entries);

    var vec_acc: @Vector(bitnet_tl_simd_lanes, f32) = @splat(0.0);
    var triple_col: usize = 0;
    while (triple_col + bitnet_tl_simd_lanes <= three_count) : (triple_col += bitnet_tl_simd_lanes) {
        var lanes: @Vector(bitnet_tl_simd_lanes, f32) = @splat(0.0);
        inline for (0..bitnet_tl_simd_lanes) |lane| {
            const code = try view.threeCode(row, triple_col + lane);
            const negative = try view.threeNegative(row, triple_col + lane);
            lanes[lane] = three_lut[(triple_col + lane) * bitnet_tl_three_lut_entries + @as(usize, @intCast(code)) * 2 + @intFromBool(negative)];
        }
        vec_acc += lanes;
    }

    var acc = @reduce(.Add, vec_acc);
    while (triple_col < three_count) : (triple_col += 1) {
        const code = try view.threeCode(row, triple_col);
        const negative = try view.threeNegative(row, triple_col);
        acc += three_lut[triple_col * bitnet_tl_three_lut_entries + @as(usize, @intCast(code)) * 2 + @intFromBool(negative)];
    }

    var pair_vec_acc: @Vector(bitnet_tl_simd_lanes, f32) = @splat(0.0);
    var pair_col: usize = 0;
    while (pair_col + bitnet_tl_simd_lanes <= two_count) : (pair_col += bitnet_tl_simd_lanes) {
        var lanes: @Vector(bitnet_tl_simd_lanes, f32) = @splat(0.0);
        inline for (0..bitnet_tl_simd_lanes) |lane| {
            const code = try view.twoPairCode(row, pair_col + lane);
            lanes[lane] = two_lut[(pair_col + lane) * bitnet_tl_pair_lut_entries + @as(usize, @intCast(code))];
        }
        pair_vec_acc += lanes;
    }
    acc += @reduce(.Add, pair_vec_acc);

    while (pair_col < two_count) : (pair_col += 1) {
        const code = try view.twoPairCode(row, pair_col);
        acc += two_lut[pair_col * bitnet_tl_pair_lut_entries + @as(usize, @intCast(code))];
    }
    return acc;
}

fn bitnetActivationScale(input_row: []const f32) f32 {
    var abs_max: f32 = 0.0;
    for (input_row) |value| {
        abs_max = @max(abs_max, @abs(value));
    }
    if (abs_max == 0.0) return 1.0;
    return abs_max / 127.0;
}

fn quantizeBitnetActivation(value: f32, scale: f32) f32 {
    if (scale == 0.0) return 0.0;
    const quantized = @min(@max(std.math.round(value / scale), -127.0), 127.0);
    return quantized * scale;
}

fn quantizeBitnetActivationInt8(value: f32, scale: f32) i8 {
    if (scale == 0.0) return 0;
    const quantized = @min(@max(std.math.round(value / scale), -127.0), 127.0);
    return @intCast(@as(i32, @intFromFloat(quantized)));
}

fn quantizeBitnetActivationRow(input_row: []const f32, scale: f32, quantized_row: []i8) void {
    std.debug.assert(input_row.len == quantized_row.len);
    for (input_row, quantized_row) |value, *out| {
        out.* = quantizeBitnetActivationInt8(value, scale);
    }
}

fn dotI8SBlock(input_block: []const f32, block: []const u8) f32 {
    const value: i8 = @bitCast(block[0]);
    return input_block[0] * @as(f32, @floatFromInt(value));
}

fn dotI2SBlockActivationQuantized(input_block: []const i8, block: []const u8, activation_scale: f32) f32 {
    std.debug.assert(input_block.len == 128);
    std.debug.assert(block.len == 32);

    const zero_i32: I32xN = @splat(0);
    const code_mask: U8xN = @splat(0x03);
    var acc: i32 = 0;
    inline for (0..4) |lane| {
        const shift: u3 = @intCast((3 - lane) * 2);
        const shift_vec: @Vector(VEC_LEN, u3) = @splat(shift);
        var vec_acc: I32xN = @splat(0);
        var group: usize = 0;
        while (group + VEC_LEN <= 32) : (group += VEC_LEN) {
            const packed_bytes: U8xN = block[group..][0..VEC_LEN].*;
            const codes: U8xN = (packed_bytes >> shift_vec) & code_mask;
            const activations_i8: I8xN = input_block[lane * 32 + group ..][0..VEC_LEN].*;
            const activations: I32xN = activations_i8;
            const pos_mask = codes == @as(U8xN, @splat(2));
            const neg_mask = codes == @as(U8xN, @splat(0));
            vec_acc += @select(i32, pos_mask, activations, zero_i32);
            vec_acc -= @select(i32, neg_mask, activations, zero_i32);
        }
        acc += @reduce(.Add, vec_acc);
        while (group < 32) : (group += 1) {
            const code: u2 = @intCast((block[group] >> shift) & 0x03);
            const activation: i32 = input_block[lane * 32 + group];
            switch (code) {
                0 => acc -= activation,
                2 => acc += activation,
                else => {},
            }
        }
    }
    return activation_scale * @as(f32, @floatFromInt(acc));
}

fn dotQ5_0Block(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const qh = std.mem.readInt(u32, block[2..6], .little);
    const qs = block[6..22];
    var acc: f32 = 0.0;
    for (qs, 0..) |packed_byte, i| {
        const lo4: i32 = packed_byte & 0x0F;
        const hi1: i32 = @intCast((qh >> @as(u5, @intCast(i))) & 1);
        acc += input_block[i] * @as(f32, @floatFromInt((lo4 | (hi1 << 4)) - 16));
    }
    for (qs, 0..) |packed_byte, i| {
        const lo4: i32 = packed_byte >> 4;
        const hi1: i32 = @intCast((qh >> @as(u5, @intCast(i + 16))) & 1);
        acc += input_block[16 + i] * @as(f32, @floatFromInt((lo4 | (hi1 << 4)) - 16));
    }
    return d * acc;
}

fn dotQ5_1Block(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const m = decodeFp16Le(block[2], block[3]);
    const qh = std.mem.readInt(u32, block[4..8], .little);
    const qs = block[8..24];
    var acc: f32 = 0.0;
    for (qs, 0..) |packed_byte, i| {
        const lo4: i32 = packed_byte & 0x0F;
        const hi1: i32 = @intCast((qh >> @as(u5, @intCast(i))) & 1);
        acc += input_block[i] * (d * @as(f32, @floatFromInt(lo4 | (hi1 << 4))) + m);
    }
    for (qs, 0..) |packed_byte, i| {
        const lo4: i32 = packed_byte >> 4;
        const hi1: i32 = @intCast((qh >> @as(u5, @intCast(i + 16))) & 1);
        acc += input_block[16 + i] * (d * @as(f32, @floatFromInt(lo4 | (hi1 << 4))) + m);
    }
    return acc;
}

fn dotQ1_0Block(input_block: []const f32, block: []const u8) f32 {
    // Q1_0: 2-byte fp16 scale, then 16 bytes = 128 sign bits (LSB-first within each byte).
    // bit == 1 → weight = +d, bit == 0 → weight = -d (matches dequantizeQ1_0).
    const d = decodeFp16Le(block[0], block[1]);
    const qs = block[2..18];
    const Vec8 = @Vector(8, f32);
    var acc: Vec8 = @splat(0.0);
    inline for (0..16) |byte_idx| {
        const b = qs[byte_idx];
        const signs: Vec8 = .{
            if ((b & 0x01) != 0) 1.0 else -1.0,
            if ((b & 0x02) != 0) 1.0 else -1.0,
            if ((b & 0x04) != 0) 1.0 else -1.0,
            if ((b & 0x08) != 0) 1.0 else -1.0,
            if ((b & 0x10) != 0) 1.0 else -1.0,
            if ((b & 0x20) != 0) 1.0 else -1.0,
            if ((b & 0x40) != 0) 1.0 else -1.0,
            if ((b & 0x80) != 0) 1.0 else -1.0,
        };
        const inp: Vec8 = input_block[byte_idx * 8 ..][0..8].*;
        acc += inp * signs;
    }
    return d * @reduce(.Add, acc);
}

fn dotQ4_0Block(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const qs = block[2..18];
    var acc: f32 = 0.0;
    for (qs, 0..) |packed_byte, i| {
        const lo = @as(f32, @floatFromInt(@as(i32, packed_byte & 0x0F) - 8));
        acc += input_block[i] * lo;
    }
    for (qs, 0..) |packed_byte, i| {
        const hi = @as(f32, @floatFromInt(@as(i32, packed_byte >> 4) - 8));
        acc += input_block[16 + i] * hi;
    }
    return d * acc;
}

fn dotQ4_1Block(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const m = decodeFp16Le(block[2], block[3]);
    const qs = block[4..20];
    var acc: f32 = 0.0;
    for (qs, 0..) |packed_byte, i| {
        const lo = @as(f32, @floatFromInt(packed_byte & 0x0F));
        acc += input_block[i] * (d * lo + m);
    }
    for (qs, 0..) |packed_byte, i| {
        const hi = @as(f32, @floatFromInt(packed_byte >> 4));
        acc += input_block[16 + i] * (d * hi + m);
    }
    return acc;
}

fn dotQ8_0Block(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const qs = block[2..34];
    var acc: F32xN = @splat(0.0);
    comptime var i: usize = 0;
    inline while (i < 32) : (i += VEC_LEN) {
        const raw: U8xN = qs[i..][0..VEC_LEN].*;
        const qi: I32xN = @as(@Vector(VEC_LEN, i8), @bitCast(raw));
        const qf: F32xN = @floatFromInt(qi);
        const inp: F32xN = input_block[i..][0..VEC_LEN].*;
        acc += inp * qf;
    }
    return d * @reduce(.Add, acc);
}

fn dotQ8_1Block(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    // block[2..4] stores d * sum(qs) for optimized dot products.
    const qs = block[4..36];
    var acc: F32xN = @splat(0.0);
    comptime var i: usize = 0;
    inline while (i < 32) : (i += VEC_LEN) {
        const raw: U8xN = qs[i..][0..VEC_LEN].*;
        const qi: I32xN = @as(@Vector(VEC_LEN, i8), @bitCast(raw));
        const qf: F32xN = @floatFromInt(qi);
        const inp: F32xN = input_block[i..][0..VEC_LEN].*;
        acc += inp * qf;
    }
    return d * @reduce(.Add, acc);
}

fn dotQ8_KBlock(input_block: []const f32, block: []const u8) f32 {
    const d = decodeF32Le(block[0], block[1], block[2], block[3]);
    const qs = block[4..260];
    var acc: F32xN = @splat(0.0);
    var i: usize = 0;
    while (i < 256) : (i += VEC_LEN) {
        const raw: U8xN = qs[i..][0..VEC_LEN].*;
        const qi: I32xN = @as(@Vector(VEC_LEN, i8), @bitCast(raw));
        const qf: F32xN = @floatFromInt(qi);
        const inp: F32xN = input_block[i..][0..VEC_LEN].*;
        acc += inp * qf;
    }
    return d * @reduce(.Add, acc);
}

fn dotQ8KQ8KBlock(q8_input: []const u8, q8_weight: []const u8) f32 {
    std.debug.assert(q8_input.len == 292);
    std.debug.assert(q8_weight.len == 292);
    const scale = readF32Le(q8_input[0..4]) * readF32Le(q8_weight[0..4]);
