fn dotIQ4NLBlock(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const qs = block[2..18];
    var acc: f32 = 0.0;
    for (qs, 0..) |packed_byte, i| {
        const q = quant_codec.iq4_nl_values[packed_byte & 0x0F];
        acc += input_block[i] * @as(f32, @floatFromInt(q));
    }
    for (qs, 0..) |packed_byte, i| {
        const q = quant_codec.iq4_nl_values[packed_byte >> 4];
        acc += input_block[16 + i] * @as(f32, @floatFromInt(q));
    }
    return d * acc;
}

fn dotIQ4XSBlock(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const scales_h = std.mem.readInt(u16, block[2..4], .little);
    const scales_l = block[4..8];
    const qs = block[8..136];
    var acc: f32 = 0.0;
    for (0..8) |ib| {
        const low: u16 = (scales_l[ib / 2] >> @as(u3, @intCast(4 * (ib % 2)))) & 0x0F;
        const high: u16 = (scales_h >> @as(u4, @intCast(2 * ib))) & 0x03;
        const ls = @as(i32, @intCast(low | (high << 4)));
        const dl = d * @as(f32, @floatFromInt(ls - 32));
        const q_base = ib * 16;
        const input_base = ib * 32;
        for (0..16) |j| {
            const q = quant_codec.iq4_nl_values[qs[q_base + j] & 0x0F];
            acc += input_block[input_base + j] * (dl * @as(f32, @floatFromInt(q)));
        }
        for (0..16) |j| {
            const q = quant_codec.iq4_nl_values[qs[q_base + j] >> 4];
            acc += input_block[input_base + 16 + j] * (dl * @as(f32, @floatFromInt(q)));
        }
    }
    return acc;
}

fn dotQ2_KBlock(input_block: []const f32, block: []const u8) f32 {
    const scales_raw = block[0..16];
    const d = decodeFp16Le(block[16], block[17]);
    const dmin = decodeFp16Le(block[18], block[19]);
    const qs = block[20..84];

    const mask_03: U8xN = @splat(0x03);
    var acc: F32xN = @splat(0.0);
    for (0..16) |sub| {
        const sc = @as(f32, @floatFromInt(scales_raw[sub] & 0x0F));
        const m = @as(f32, @floatFromInt(scales_raw[sub] >> 4));
        const dsc: F32xN = @splat(d * sc);
        const dmn: F32xN = @splat(dmin * m);
        const chunk = sub / 8;
        const group = (sub % 8) / 2;
        const l_base = (sub % 2) * 16;
        const q_base = chunk * 32;
        const shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast(group * 2)));
        const input_off = sub * 16;

        comptime var i: usize = 0;
        inline while (i < 16) : (i += VEC_LEN) {
            const raw: U8xN = qs[q_base + l_base + i ..][0..VEC_LEN].*;
            const q: I32xN = (raw >> shift) & mask_03;
            const inp: F32xN = input_block[input_off + i ..][0..VEC_LEN].*;
            acc += inp * (dsc * @as(F32xN, @floatFromInt(q)) - dmn);
        }
    }
    return @reduce(.Add, acc);
}

fn dotQ3_KBlock(input_block: []const f32, block: []const u8) f32 {
    const hmask = block[0..32];
    const qs = block[32..96];
    const scale_data = block[96..108];
    const d = decodeFp16Le(block[108], block[109]);

    var raw_scales: [16]i32 = undefined;
    for (0..4) |i| {
        raw_scales[i] = @as(i32, scale_data[i] & 0x0F) | (@as(i32, scale_data[8 + i] & 0x03) << 4);
        raw_scales[i + 4] = @as(i32, scale_data[4 + i] & 0x0F) | (@as(i32, (scale_data[8 + i] >> 2) & 0x03) << 4);
        raw_scales[i + 8] = @as(i32, (scale_data[i] >> 4) & 0x0F) | (@as(i32, (scale_data[8 + i] >> 4) & 0x03) << 4);
        raw_scales[i + 12] = @as(i32, (scale_data[4 + i] >> 4) & 0x0F) | (@as(i32, (scale_data[8 + i] >> 6) & 0x03) << 4);
    }

    const mask_03: U8xN = @splat(0x03);
    const mask_01: U8xN = @splat(0x01);
    const four: I32xN = @splat(4);
    var acc: F32xN = @splat(0.0);
    for (0..16) |sub| {
        const scale: F32xN = @splat(d * @as(f32, @floatFromInt(raw_scales[sub] - 32)));
        const chunk = sub / 8;
        const group = (sub % 8) / 2;
        const l_base = (sub % 2) * 16;
        const q_base = chunk * 32;
        const shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast(group * 2)));
        const hm_shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast(chunk * 4 + group)));
        const input_off = sub * 16;

        comptime var i: usize = 0;
        inline while (i < 16) : (i += VEC_LEN) {
            const l = l_base + i;
            const qs_raw: U8xN = qs[q_base + l ..][0..VEC_LEN].*;
            const hm_raw: U8xN = hmask[l..][0..VEC_LEN].*;
            const low2: I32xN = (qs_raw >> shift) & mask_03;
            const high1: I32xN = (hm_raw >> hm_shift) & mask_01;
            const q: I32xN = low2 + high1 * four - four;
            const inp: F32xN = input_block[input_off + i ..][0..VEC_LEN].*;
            acc += inp * (scale * @as(F32xN, @floatFromInt(q)));
        }
    }
    return @reduce(.Add, acc);
}

fn dotQ5_KBlock(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const dmin = decodeFp16Le(block[2], block[3]);
    const scales = block[4..16];
    const qh = block[16..48];
    const ql = block[48..176];

    var scs: [8]f32 = undefined;
    var mins: [8]f32 = undefined;
    unpackQ4KScaleMins(scales, &scs, &mins);

    const mask_0f: U8xN = @splat(0x0F);
    const mask_01: U8xN = @splat(0x01);
    const sixteen: I32xN = @splat(16);
    var acc: F32xN = @splat(0.0);
    for (0..8) |sub| {
        const dsc: F32xN = @splat(d * scs[sub]);
        const dmn: F32xN = @splat(dmin * mins[sub]);
        const chunk = sub / 2;
        const is_high = sub % 2 == 1;
        const ql_off = chunk * 32;
        const hb_shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast(sub)));
        const input_off = sub * 32;

        var i: usize = 0;
        while (i < 32) : (i += VEC_LEN) {
            const ql_raw: U8xN = ql[ql_off + i ..][0..VEC_LEN].*;
            const qh_raw: U8xN = qh[i..][0..VEC_LEN].*;
            const low: I32xN = if (is_high) ql_raw >> @as(@Vector(VEC_LEN, u3), @splat(4)) else ql_raw & mask_0f;
            const high: I32xN = (qh_raw >> hb_shift) & mask_01;
            const q: I32xN = low + high * sixteen;
            const inp: F32xN = input_block[input_off + i ..][0..VEC_LEN].*;
            acc += inp * (dsc * @as(F32xN, @floatFromInt(q)) - dmn);
        }
    }
    return @reduce(.Add, acc);
}

fn dotQ4_KBlock(input_block: []const f32, block: []const u8) f32 {
    const d = decodeFp16Le(block[0], block[1]);
    const dmin = decodeFp16Le(block[2], block[3]);
    const scales = block[4..16];
    const qs = block[16..144];

    var scs: [8]f32 = undefined;
    var mins: [8]f32 = undefined;
    unpackQ4KScaleMins(scales, &scs, &mins);

    const mask_0f: U8xN = @splat(0x0F);
    var acc: F32xN = @splat(0.0);
    var q_off: usize = 0;
    for (0..4) |chunk| {
        const sub = chunk * 2;
        const dsc0: F32xN = @splat(d * scs[sub]);
        const dmn0: F32xN = @splat(dmin * mins[sub]);
        const dsc1: F32xN = @splat(d * scs[sub + 1]);
        const dmn1: F32xN = @splat(dmin * mins[sub + 1]);
        const input_off = chunk * 64;

        var i: usize = 0;
        while (i < 32) : (i += VEC_LEN) {
            const raw: U8xN = qs[q_off + i ..][0..VEC_LEN].*;
            const lo: I32xN = raw & mask_0f;
            const inp: F32xN = input_block[input_off + i ..][0..VEC_LEN].*;
            acc += inp * (dsc0 * @as(F32xN, @floatFromInt(lo)) - dmn0);
        }
        i = 0;
        while (i < 32) : (i += VEC_LEN) {
            const raw: U8xN = qs[q_off + i ..][0..VEC_LEN].*;
            const hi: I32xN = raw >> @splat(4);
            const inp: F32xN = input_block[input_off + 32 + i ..][0..VEC_LEN].*;
            acc += inp * (dsc1 * @as(F32xN, @floatFromInt(hi)) - dmn1);
        }
        q_off += 32;
    }
    return @reduce(.Add, acc);
}

inline fn dotQ4KPreparedBlock(input_block: []const f32, prepared_block: []const u8) f32 {
    const rows = dotPreparedFloatRows(false, 1, .{input_block}, prepared_block);
    return rows[0];
}

inline fn dotQ4KPreparedBlockMR2NR1(
    input_block_r0: []const f32,
    input_block_r1: []const f32,
    prepared_block: []const u8,
) struct { f32, f32 } {
    const rows = dotPreparedFloatRows(false, 2, .{ input_block_r0, input_block_r1 }, prepared_block);
    return .{ rows[0], rows[1] };
}

// MR=1 NR=4: one input row × four prepared cols.  Used directly by the
// M-tail (when `rows` is odd) and as a building block for the 4-col single-
// row path in `linearNoBiasQ4KPreparedTiledRange`.
// Thin ABI leaves also serve the existing compile-time codec dispatch.
inline fn accumulateQ4KPreparedBlock4MR1(
    input_block: []const f32,
    prepared_block0: []const u8,
    prepared_block1: []const u8,
    prepared_block2: []const u8,
    prepared_block3: []const u8,
    acc0: *F32xN,
    acc1: *F32xN,
    acc2: *F32xN,
    acc3: *F32xN,
) void {
    accumulatePreparedFloatRows(false, 1, 4, .{input_block}, .{ prepared_block0, prepared_block1, prepared_block2, prepared_block3 }, .{.{ acc0, acc1, acc2, acc3 }});
}

inline fn accumulateQ4KPreparedBlock4MR2(
    input_block_r0: []const f32,
    input_block_r1: []const f32,
    prepared_block0: []const u8,
    prepared_block1: []const u8,
    prepared_block2: []const u8,
    prepared_block3: []const u8,
    acc_r0_0: *F32xN,
    acc_r0_1: *F32xN,
    acc_r0_2: *F32xN,
    acc_r0_3: *F32xN,
    acc_r1_0: *F32xN,
    acc_r1_1: *F32xN,
    acc_r1_2: *F32xN,
    acc_r1_3: *F32xN,
) void {
    accumulatePreparedFloatRows(false, 2, 4, .{ input_block_r0, input_block_r1 }, .{ prepared_block0, prepared_block1, prepared_block2, prepared_block3 }, .{ .{ acc_r0_0, acc_r0_1, acc_r0_2, acc_r0_3 }, .{ acc_r1_0, acc_r1_1, acc_r1_2, acc_r1_3 } });
}

inline fn preparedFloatInteger(comptime signed_q6: bool, raw: U8xN) if (signed_q6) I32xN else U8xN {
    return if (signed_q6) @as(I32xN, @as(@Vector(VEC_LEN, i8), @bitCast(raw))) else raw;
}

inline fn preparedFloatScaledWeight(comptime signed_q6: bool, quant: if (signed_q6) I32xN else U8xN, scale: F32xN, minimum: F32xN) F32xN {
    const decoded: F32xN = @floatFromInt(quant);
    return if (signed_q6) scale * decoded else scale * decoded - minimum;
}

inline fn preparedFloatWeight(comptime signed_q6: bool, raw: U8xN, scale: F32xN, minimum: F32xN) F32xN {
    return preparedFloatScaledWeight(signed_q6, preparedFloatInteger(signed_q6, raw), scale, minimum);
}

/// Share decoding while retaining MR1's per-column arithmetic/store schedule.
inline fn preparedFloatStep(comptime signed_q6: bool, comptime mr: usize, comptime nr: usize, inputs: [mr][]const f32, values: [nr][]const u8, offset: usize, scales: [nr]F32xN, minimums: [nr]F32xN, accumulators: [mr][nr]*F32xN) void {
    var x: [mr]F32xN = undefined;
    var raw: [nr]U8xN = undefined;
    if (comptime nr == 1) {
        raw[0] = values[0][offset..][0..VEC_LEN].*;
        if (comptime mr == 2) {
            const weight = preparedFloatWeight(signed_q6, raw[0], scales[0], minimums[0]);
            inline for (0..mr) |row| x[row] = inputs[row][offset..][0..VEC_LEN].*;
            inline for (0..mr) |row| accumulators[row][0].* += x[row] * weight;
            return;
        }
        // Keep the scalar signed-integer decode before its input load.
        const quant = preparedFloatInteger(signed_q6, raw[0]);
        x[0] = inputs[0][offset..][0..VEC_LEN].*;
        accumulators[0][0].* += x[0] * preparedFloatScaledWeight(signed_q6, quant, scales[0], minimums[0]);
        return;
    } else {
        inline for (0..mr) |row| x[row] = inputs[row][offset..][0..VEC_LEN].*;
        inline for (0..nr) |col| raw[col] = values[col][offset..][0..VEC_LEN].*;
    }
    if (comptime mr == 1) {
        inline for (0..nr) |col| accumulators[0][col].* += x[0] * preparedFloatWeight(signed_q6, raw[col], scales[col], minimums[col]);
    } else {
        var weights: [nr]F32xN = undefined;
        inline for (0..nr) |col| weights[col] = preparedFloatWeight(signed_q6, raw[col], scales[col], minimums[col]);
        inline for (0..mr) |row| inline for (0..nr) |col| {
            accumulators[row][col].* += x[row] * weights[col];
        };
    }
}

inline fn accumulatePreparedFloatRows(comptime signed_q6: bool, comptime mr: usize, comptime nr: usize, inputs: [mr][]const f32, blocks: [nr][]const u8, accumulators: [mr][nr]*F32xN) void {
    comptime std.debug.assert(mr == 1 or mr == 2);
    comptime std.debug.assert(nr == 1 or nr == 4);
    var values: [nr][]const u8 = undefined;
    inline for (0..nr) |col| {
        std.debug.assert(blocks[col].len == prepared_q4_k_block_bytes);
        values[col] = blocks[col][prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];
    }
    const halves = if (signed_q6) 1 else 2;
    for (0..(if (signed_q6) 16 else 4)) |chunk| {
        var scales: [halves][nr]F32xN = undefined;
        var minimums: [halves][nr]F32xN = undefined;
        inline for (0..nr) |col| inline for (0..halves) |half| {
            const sub = chunk * halves + half;
            scales[half][col] = @splat(if (signed_q6) preparedQ6KDsc(blocks[col], sub) else preparedQ4KDsc(blocks[col], sub));
            if (!signed_q6) minimums[half][col] = @splat(preparedQ4KDmn(blocks[col], sub));
        };
        inline for (0..halves) |half| {
            const base = chunk * (if (signed_q6) @as(usize, 16) else 64) + half * 32;
            if (comptime signed_q6) {
                comptime var i: usize = 0;
                inline while (i < 16) : (i += VEC_LEN) preparedFloatStep(true, mr, nr, inputs, values, base + i, scales[half], undefined, accumulators);
            } else {
                var i: usize = 0;
                while (i < 32) : (i += VEC_LEN) preparedFloatStep(false, mr, nr, inputs, values, base + i, scales[half], minimums[half], accumulators);
            }
        }
    }
}

inline fn dotPreparedFloatRows(comptime signed_q6: bool, comptime mr: usize, inputs: [mr][]const f32, block: []const u8) [mr]f32 {
    var acc: [mr][1]F32xN = @splat(@splat(@splat(0.0)));
    var outputs: [mr][1]*F32xN = undefined;
    inline for (0..mr) |row| outputs[row][0] = &acc[row][0];
    accumulatePreparedFloatRows(signed_q6, mr, 1, inputs, .{block}, outputs);
    var result: [mr]f32 = undefined;
    inline for (0..mr) |row| result[row] = @reduce(.Add, acc[row][0]);
    return result;
}

// MR=2 NR=4: two input rows × four prepared cols, eight accumulators.
//
// The whole reason this exists: dequantising a Q4_K block (computing
// `dsc * f32(q) - dmn` per lane) is the dominant compute in the kernel.
// MR=1 reloads the dequantised weight per row.  MR=2 computes the
// dequantised lane *once* and applies it to two input rows, halving the
// dequant work for the same total FMAs.
//
// 8 F32xN accumulators (8 ymm registers) leave half the AVX2 register
// file free for the splat constants and per-block scratch.  Going to
// MR=4/NR=4 (16 acc) spills on AVX2 and is left as a follow-up.

fn preparedQ6KDsc(prepared_block: []const u8, sub: usize) f32 {
    return readF32Le(prepared_block[sub * 4 ..][0..4]);
}

// Keep the scalar Q6 traversal lexical; its input/panel pointer schedule is qualified.
inline fn dotQ6KPreparedBlock(input_block: []const f32, prepared_block: []const u8) f32 {
    std.debug.assert(prepared_block.len == prepared_q4_k_block_bytes);
    const q_values = prepared_block[prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];

    var acc: F32xN = @splat(0.0);
    for (0..16) |sub| {
        const scale: F32xN = @splat(preparedQ6KDsc(prepared_block, sub));
        const q_off = sub * 16;
        const input_off = sub * 16;
        comptime var i: usize = 0;
        inline while (i < 16) : (i += VEC_LEN) {
            const raw: U8xN = q_values[q_off + i ..][0..VEC_LEN].*;
            const q = preparedFloatInteger(true, raw);
            const inp: F32xN = input_block[input_off + i ..][0..VEC_LEN].*;
            acc += inp * preparedFloatScaledWeight(true, q, scale, undefined);
        }
    }
    return @reduce(.Add, acc);
}

inline fn dotQ6KPreparedQ8KBlock(q8_block: []const u8, prepared_block: []const u8) f32 {
    std.debug.assert(q8_block.len == 292);
    std.debug.assert(prepared_block.len == prepared_q4_k_block_bytes);

    const qx = q8_block[4..260];
    const x_d = readF32Le(q8_block[0..4]);
    const q_values = prepared_block[prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];

    var acc: f32 = 0.0;
    for (0..16) |sub| {
        const scale = x_d * preparedQ6KDsc(prepared_block, sub);
        const q_off = sub * 16;
        const dot = dotI8I8Block16(qx[q_off..][0..16], q_values[q_off..][0..16]);
        acc += scale * @as(f32, @floatFromInt(dot));
    }
    return acc;
}

inline fn dotQ6KPreparedQ8KBlock4(
    q8_block: []const u8,
    prepared_block0: []const u8,
    prepared_block1: []const u8,
    prepared_block2: []const u8,
    prepared_block3: []const u8,
) struct { f32, f32, f32, f32 } {
    std.debug.assert(q8_block.len == 292);
    std.debug.assert(prepared_block0.len == prepared_q4_k_block_bytes);
    std.debug.assert(prepared_block1.len == prepared_q4_k_block_bytes);
    std.debug.assert(prepared_block2.len == prepared_q4_k_block_bytes);
    std.debug.assert(prepared_block3.len == prepared_q4_k_block_bytes);

    const qx = q8_block[4..260];
    const x_d = readF32Le(q8_block[0..4]);
    const q_values0 = prepared_block0[prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];
    const q_values1 = prepared_block1[prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];
    const q_values2 = prepared_block2[prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];
    const q_values3 = prepared_block3[prepared_q4_k_header_bytes..prepared_q4_k_block_bytes];

    var acc0: f32 = 0.0;
    var acc1: f32 = 0.0;
    var acc2: f32 = 0.0;
    var acc3: f32 = 0.0;
    for (0..16) |sub| {
        const q_off = sub * 16;
        const dots = dotI8I8Block4_16(
            qx[q_off..][0..16],
            q_values0[q_off..][0..16],
            q_values1[q_off..][0..16],
            q_values2[q_off..][0..16],
            q_values3[q_off..][0..16],
        );
        acc0 += (x_d * preparedQ6KDsc(prepared_block0, sub)) * @as(f32, @floatFromInt(dots[0]));
        acc1 += (x_d * preparedQ6KDsc(prepared_block1, sub)) * @as(f32, @floatFromInt(dots[1]));
        acc2 += (x_d * preparedQ6KDsc(prepared_block2, sub)) * @as(f32, @floatFromInt(dots[2]));
        acc3 += (x_d * preparedQ6KDsc(prepared_block3, sub)) * @as(f32, @floatFromInt(dots[3]));
    }
    return .{ acc0, acc1, acc2, acc3 };
}

inline fn q6KPanel8ScaleI32(panel_block: []const u8, sub: usize) I32x8 {
    const raw: U8x8 = panel_block[prepared_q6_k_panel8_scales_offset + sub * prepared_k_panel8_nr ..][0..prepared_k_panel8_nr].*;
    const signed: I8x8 = @bitCast(raw);
    return @intCast(signed);
}

inline fn q6KPanel8ValuesBase(sub: usize) usize {
    return prepared_q6_k_panel8_values_offset + sub * prepared_k_panel8_nr * 16;
}

inline fn q6KPanel8WeightScale(panel_block: []const u8) F32x8 {
    return readF32x8Le(panel_block[prepared_q6_k_panel8_d_offset..][0..32]);
}

inline fn q6KPanel8ScaledSdot16(acc: I32x4, raw_x: U8x16, raw_w: U8x16, scale: i32) I32x4 {
    return acc + aarch64Sdot16(@splat(0), raw_x, raw_w) * @as(I32x4, @splat(scale));
}

inline fn q6KPanel8ReduceWeighted8(acc: [8]I32x4) I32x8 {
    return .{
        @reduce(.Add, acc[0]),
        @reduce(.Add, acc[1]),
        @reduce(.Add, acc[2]),
        @reduce(.Add, acc[3]),
        @reduce(.Add, acc[4]),
        @reduce(.Add, acc[5]),
        @reduce(.Add, acc[6]),
        @reduce(.Add, acc[7]),
    };
}

/// Compile-time row ownership; fused MR4 deliberately retains two MR2 tiles.
inline fn q6KPanel8Rows(comptime mr: usize, comptime fused: bool, inputs: [mr][]const u8, panel: []const u8) [mr]F32x8 {
    comptime std.debug.assert(mr == 1 or mr == 2 or (!fused and mr == 4));
    inline for (inputs) |input| std.debug.assert(input.len == 292);
    std.debug.assert(panel.len == prepared_q6_k_panel8_block_bytes);
    const weight_scale = q6KPanel8WeightScale(panel);
    var final_scale: [mr]F32x8 = undefined;
    inline for (0..mr) |row| final_scale[row] = @as(F32x8, @splat(readF32Le(inputs[row][0..4]))) * weight_scale;
    const Accumulator = if (fused) [8]I32x4 else I32x8;
    var weighted: [mr]Accumulator = if (fused) @splat(@splat(@splat(0))) else @splat(@splat(0));
    // Preserve full unrolling only for the existing fused schedule.
    const traversal = if (fused) 16 else 1;
    inline for (0..traversal) |tile| {
        for (0..16 / traversal) |step| {
            const sub = tile + step;
            const off = 4 + sub * 16;
            const base = q6KPanel8ValuesBase(sub);
            if (comptime fused) {
                var x: [mr]U8x16 = undefined;
                inline for (0..mr) |row| x[row] = inputs[row][off..][0..16].*;
                const scales = q6KPanel8ScaleI32(panel, sub);
                inline for (0..8) |col| {
                    const w: U8x16 = panel[base + col * 16 ..][0..16].*;
                    inline for (0..mr) |row| weighted[row][col] = q6KPanel8ScaledSdot16(weighted[row][col], x[row], w, scales[col]);
                }
            } else {
                var w: [8]*const [16]u8 = undefined;
                inline for (0..8) |col| w[col] = panel[base + col * 16 ..][0..16];
                const dots = if (mr == 1)
                    [1]I32x8{dotI8I8Block8_16Vec(inputs[0][off..][0..16], w[0], w[1], w[2], w[3], w[4], w[5], w[6], w[7])}
                else if (mr == 2) blk: {
                    const d = dotI8I8Block8MR2RowsVec16(inputs[0][off..][0..16], inputs[1][off..][0..16], w[0], w[1], w[2], w[3], w[4], w[5], w[6], w[7]);
                    break :blk [2]I32x8{ d.r0, d.r1 };
                } else blk: {
                    const d = dotI8I8Block8MR4RowsVec16(inputs[0][off..][0..16], inputs[1][off..][0..16], inputs[2][off..][0..16], inputs[3][off..][0..16], w[0], w[1], w[2], w[3], w[4], w[5], w[6], w[7]);
                    break :blk [4]I32x8{ d.r0, d.r1, d.r2, d.r3 };
                };
                const scales = q6KPanel8ScaleI32(panel, sub);
                inline for (0..mr) |row| weighted[row] += dots[row] * scales;
            }
        }
    }
    var output: [mr]F32x8 = undefined;
    inline for (0..mr) |row| output[row] = final_scale[row] * @as(F32x8, @floatFromInt(if (fused) q6KPanel8ReduceWeighted8(weighted[row]) else weighted[row]));
    return output;
}

inline fn dotQ6KPreparedQ8KPanel8VecFusedSdot(q8_block: []const u8, panel_block: []const u8) F32x8 {
    const rows = q6KPanel8Rows(1, true, .{q8_block}, panel_block);
    return rows[0];
}

inline fn dotQ6KPreparedQ8KPanel8MR2VecFusedSdot(q8_block_r0: []const u8, q8_block_r1: []const u8, panel_block: []const u8) Panel8MR2VecSums {
    const rows = q6KPanel8Rows(2, true, .{ q8_block_r0, q8_block_r1 }, panel_block);
    return .{ .r0 = rows[0], .r1 = rows[1] };
}

inline fn dotQ6KPreparedQ8KPanel8MR4VecFusedSdot(q8_block_r0: []const u8, q8_block_r1: []const u8, q8_block_r2: []const u8, q8_block_r3: []const u8, panel_block: []const u8) Panel8MR4VecSums {
    const first = dotQ6KPreparedQ8KPanel8MR2VecFusedSdot(q8_block_r0, q8_block_r1, panel_block);
    const last = dotQ6KPreparedQ8KPanel8MR2VecFusedSdot(q8_block_r2, q8_block_r3, panel_block);
    return .{ .r0 = first.r0, .r1 = first.r1, .r2 = last.r0, .r3 = last.r1 };
}

const Panel8MR2VecSums = struct {
    r0: F32x8,
    r1: F32x8,
};

const Panel8MR4VecSums = struct {
    r0: F32x8,
    r1: F32x8,
    r2: F32x8,
    r3: F32x8,
};

inline fn dotQ6KPreparedQ8KPanel8Vec(q8_block: []const u8, panel_block: []const u8) F32x8 {
    // quant-kernel-codegen:begin CPU panel dot dotQ6KPreparedQ8KPanel8Vec
    if (q6KPanel8FusedSdotEnabled()) return dotQ6KPreparedQ8KPanel8VecFusedSdot(q8_block, panel_block);
    const rows = q6KPanel8Rows(1, false, .{q8_block}, panel_block);
    return rows[0];
    // quant-kernel-codegen:end CPU panel dot dotQ6KPreparedQ8KPanel8Vec
}

inline fn dotQ6KPreparedQ8KPanel8(q8_block: []const u8, panel_block: []const u8) [8]f32 {
    return f32x8ToArray(dotQ6KPreparedQ8KPanel8Vec(q8_block, panel_block));
}

inline fn dotQ6KPreparedQ8KPanel8MR2Vec(q8_block_r0: []const u8, q8_block_r1: []const u8, panel_block: []const u8) Panel8MR2VecSums {
    // quant-kernel-codegen:begin CPU panel dot dotQ6KPreparedQ8KPanel8MR2Vec
    if (q6KPanel8FusedSdotEnabled()) return dotQ6KPreparedQ8KPanel8MR2VecFusedSdot(q8_block_r0, q8_block_r1, panel_block);
    const rows = q6KPanel8Rows(2, false, .{ q8_block_r0, q8_block_r1 }, panel_block);
    return .{
        .r0 = rows[0],
        .r1 = rows[1],
    };
