fn dotQ6_KBlock(input_block: []const f32, block: []const u8) f32 {
    const ql = block[0..128];
    const qh = block[128..192];
    const scales = block[192..208];
    const d = decodeFp16Le(block[208], block[209]);

    const mask_0f: U8xN = @splat(0x0F);
    const mask_03: U8xN = @splat(0x03);
    const offset_32: I32xN = @splat(32);
    var acc: F32xN = @splat(0.0);
    for (0..16) |sub| {
        const scale: F32xN = @splat(d * @as(f32, @floatFromInt(@as(i8, @bitCast(scales[sub])))));
        const half = sub / 8;
        const group = (sub % 8) / 2;
        const l_base = (sub % 2) * 16;
        const ql_off = half * 64 + (group & 1) * 32;
        const qh_off = half * 32;
        const qh_shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast(group * 2)));
        const nibble_shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast((group / 2) * 4)));
        const input_off = sub * 16;

        // 16 elements in two SIMD passes of 8
        comptime var i: usize = 0;
        inline while (i < 16) : (i += VEC_LEN) {
            const l = l_base + i;
            const ql_raw: U8xN = ql[ql_off + l ..][0..VEC_LEN].*;
            const qh_raw: U8xN = qh[qh_off + l ..][0..VEC_LEN].*;
            const low4: I32xN = (ql_raw >> nibble_shift) & mask_0f;
            const high2: I32xN = (qh_raw >> qh_shift) & mask_03;
            const q: I32xN = (low4 | (high2 << @splat(4))) - offset_32;
            const inp: F32xN = input_block[input_off + i ..][0..VEC_LEN].*;
            acc += inp * (scale * @as(F32xN, @floatFromInt(q)));
        }
    }
    return @reduce(.Add, acc);
}

fn dotQ6_KQ8_KBlock(q8_block: []const u8, q6_block: []const u8) f32 {
    std.debug.assert(q8_block.len == 292);
    std.debug.assert(q6_block.len == 210);

    const qx = q8_block[4..260];
    const x_d = readF32Le(q8_block[0..4]);
    const ql = q6_block[0..128];
    const qh = q6_block[128..192];
    const scales = q6_block[192..208];
    const d = decodeFp16Le(q6_block[208], q6_block[209]);

    const mask_0f: U8xN = @splat(0x0F);
    const mask_03: U8xN = @splat(0x03);
    var acc: f32 = 0.0;
    for (0..16) |sub| {
        const half = sub / 8;
        const group = (sub % 8) / 2;
        const l_base = (sub % 2) * 16;
        const ql_off = half * 64 + (group & 1) * 32;
        const qh_off = half * 32;
        const qh_shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast(group * 2)));
        const nibble_shift: @Vector(VEC_LEN, u3) = @splat(@as(u3, @intCast((group / 2) * 4)));
        const input_off = sub * 16;

        var dot: I32xN = @splat(0);
        comptime var i: usize = 0;
        inline while (i < 16) : (i += VEC_LEN) {
            const l = l_base + i;
            const ql_raw: U8xN = ql[ql_off + l ..][0..VEC_LEN].*;
            const qh_raw: U8xN = qh[qh_off + l ..][0..VEC_LEN].*;
            const low4: I32xN = (ql_raw >> nibble_shift) & mask_0f;
            const high2: I32xN = (qh_raw >> qh_shift) & mask_03;
            const q_raw = low4 | (high2 << @splat(4));
            const x_raw: U8xN = qx[input_off + i ..][0..VEC_LEN].*;
            const x: I32xN = @as(@Vector(VEC_LEN, i8), @bitCast(x_raw));
            dot += q_raw * x;
        }
        const bsums = std.mem.readInt(i16, q8_block[260 + sub * 2 ..][0..2], .little);
        const centered_dot = @reduce(.Add, dot) - 32 * @as(i32, @intCast(bsums));
        const scale = d * @as(f32, @floatFromInt(@as(i8, @bitCast(scales[sub]))));
        acc += (x_d * scale) * @as(f32, @floatFromInt(centered_dot));
    }
    return acc;
}

fn unpackQ4KScaleMins(scales: []const u8, scs: *[8]f32, mins: *[8]f32) void {
    for (0..4) |j| {
        scs[j] = @floatFromInt(scales[j] & 63);
        mins[j] = @floatFromInt(scales[j + 4] & 63);
    }
    for (4..8) |j| {
        scs[j] = @floatFromInt((scales[j + 4] & 0x0F) | ((scales[j - 4] >> 6) << 4));
        mins[j] = @floatFromInt((scales[j + 4] >> 4) | ((scales[j] >> 6) << 4));
    }
}

fn unpackQ4KScaleMinsU8(scales: []const u8, scs: *[8]u8, mins: *[8]u8) void {
    for (0..4) |j| {
        scs[j] = scales[j] & 63;
        mins[j] = scales[j + 4] & 63;
    }
    for (4..8) |j| {
        scs[j] = (scales[j + 4] & 0x0F) | ((scales[j - 4] >> 6) << 4);
        mins[j] = (scales[j + 4] >> 4) | ((scales[j] >> 6) << 4);
    }
}

fn unpackQ4KValues(qs: []const u8, out: []u8) void {
    std.debug.assert(qs.len == 128);
    std.debug.assert(out.len == prepared_q4_k_values_bytes);
    for (0..4) |chunk| {
        const src_off = chunk * 32;
        const dst_off = chunk * 64;
        for (0..32) |i| {
            const packed_byte = qs[src_off + i];
            out[dst_off + i] = packed_byte & 0x0F;
            out[dst_off + 32 + i] = packed_byte >> 4;
        }
    }
}

const PackedQuantizedMatrixMeta = struct {
    layout: quant_codec.PackedExpertLinearMeta,
    row_blocks: usize,
    values_per_block: usize,
    block_size: usize,
};

fn packedQuantizedMatrixMeta(
    shape: []const i64,
    packed_view: QuantizedStorage.PackedExpertView,
    in_dim: usize,
    out_dim: usize,
    tensor_type: gguf_tensor_types.TensorType,
) !PackedQuantizedMatrixMeta {
    const expert_axis: usize = @intCast(packed_view.expert_axis);
    const layout = try quant_codec.packedExpertLinearMeta(
        shape,
        expert_axis,
        packed_view.expert_index,
        in_dim,
        out_dim,
        tensor_type,
    );
    return .{
        .layout = layout,
        .row_blocks = layout.row_blocks,
        .values_per_block = layout.values_per_block,
        .block_size = layout.block_size,
    };
}

fn packedExpertRowBlockBase(
    meta: PackedQuantizedMatrixMeta,
    packed_view: QuantizedStorage.PackedExpertView,
    row_index: usize,
) !usize {
    return quant_codec.packedExpertLinearRowBlockBase(
        meta.layout,
        packed_view.expert_index,
        row_index,
        packed_view.row_offset,
    );
}

const decodeFp16Le = quant_codec.decodeFp16Le;

fn decodeF32Le(b0: u8, b1: u8, b2: u8, b3: u8) f32 {
    const bits: u32 = @as(u32, b0) |
        (@as(u32, b1) << 8) |
        (@as(u32, b2) << 16) |
        (@as(u32, b3) << 24);
    return @bitCast(bits);
}

fn multiplyScalarOp(ctx: *anyopaque, input: CT, scale: f32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    var owned_output = try OwnedDenseOutput.copy(self, getData(input));
    defer owned_output.deinit();
    const values = owned_output.storage.?;
    for (values) |*value| value.* *= scale;
    return owned_output.intoLike(input);
}

fn reshape2dOp(ctx: *anyopaque, input: CT, rows: usize, cols: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if ((std.math.mul(usize, rows, cols) catch return error.InvalidTensorShape) != getData(input).len) return error.InvalidTensorShape;
    return try aliasDenseBufWithShape(self, input, &.{ @intCast(rows), @intCast(cols) });
}

fn embeddingHeadPrepareOp(ctx: *anyopaque, input: CT, weight: ?CT, gather: ?CT, p: ops.EmbeddingHeadParams) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    try p.validate();
    if ((p.gather != 0) != (gather != null) or (p.weighted != 0) != (weight != null)) return error.InvalidTensorShape;
    const source = try getDataChecked(input);
    if (source.len != @as(usize, p.source_rows) * p.stride) return error.InvalidTensorShape;
    const ids = if (gather) |g| try getDataChecked(g) else null;
    if (ids) |values| if (values.len != p.rows) return error.InvalidTensorShape;
    const weights = if (weight) |w| try getDataChecked(w) else null;
    if (weights) |values| if (values.len != p.dim) return error.InvalidTensorShape;
    var owned_output = try OwnedDenseOutput.alloc(self, @as(usize, p.rows) * p.heads * p.dim);
    defer owned_output.deinit();
    const out = owned_output.storage.?;
    const positions = try self.allocator.alloc(usize, if (p.rotate != 0) @as(usize, p.rows) * p.heads else 0);
    defer self.allocator.free(positions);
    for (0..p.rows) |row| {
        if (self.io) |io| try io.checkCancel();
        const index = if (ids) |values| blk: {
            const value = values[row];
            if (!std.math.isFinite(value) or value < 0 or value >= @as(f32, @floatFromInt(if (p.gather == 2) p.sequence else p.source_rows)) or @trunc(value) != value) return error.InvalidTensorShape;
            break :blk @as(usize, @intFromFloat(value));
        } else row;
        const src_row = if (p.gather == 2) row else index;
        if (src_row >= p.source_rows) return error.InvalidTensorShape;
        for (0..p.heads) |h| {
            const src = src_row * p.stride + p.start + h / (p.heads / p.source_heads) * p.dim;
            @memcpy(out[(row * p.heads + h) * p.dim ..][0..p.dim], source[src..][0..p.dim]);
            if (p.rotate != 0) positions[row * p.heads + h] = if (p.gather == 2) index else src_row % p.sequence;
        }
    }
    const ones: [512]f32 = @splat(1);
    activations_mod.rmsNorm(out, weights orelse ones[0..p.dim], p.dim, p.eps);
    if (p.rotate != 0) linalg.ropeCore(out, positions, p.dim, p.dim, p.theta, 1, false);
    if (p.scale != 1) for (out) |*value| {
        value.* *= p.scale;
    };
    const tensor = try owned_output.intoResult();
    errdefer freeTensor(self, tensor);
    return self.withLogicalShape(tensor, &.{ @intCast(p.rows * p.heads), @intCast(p.dim) });
}

fn modelScalarBoundsOp(ctx: *anyopaque, key: []const u8, value: ?[4]?f32) anyerror!?[4]?f32 {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (!self.cache_embeddinggemma2_bf16_weights) return null;
    return self.data.scalar_bounds.access(self.data.allocator, key, value);
}

fn rmsNormResidualOp(ctx: *anyopaque, input: CT, weight: CT, residual: CT, dim: usize, eps: f32, norm_scale: f32, output_scale: f32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    defer maybeDiscardMappedWeightAfterUse(self, weight);
    try prepareDataRead(input);
    try prepareDataRead(weight);
    try prepareDataRead(residual);
    const x = getData(input);
    const w = getData(weight);
    const res = getData(residual);
    if (dim == 0 or x.len == 0 or x.len % dim != 0 or w.len != dim or res.len != x.len) return error.InvalidTensorShape;
    var owned_output = try OwnedDenseOutput.alloc(self, x.len);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    activations_mod.rmsNormResidual(output, x, w, res, dim, eps, norm_scale, output_scale);
    return owned_output.intoLike(input);
}

fn clampSiluOp(ctx: *anyopaque, input: CT, min_value: ?f32, max_value: ?f32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    var owned_output = try OwnedDenseOutput.alloc(self, getData(input).len);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    activations_mod.clampSilu(output, getData(input), min_value, max_value);
    return owned_output.intoLike(input);
}

fn rmsNormOp(ctx: *anyopaque, input: CT, weight: CT, dim: usize, eps: f32) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    defer maybeDiscardMappedWeightAfterUse(self, weight);
    try prepareDataRead(input);
    try prepareDataRead(weight);
    const geometry = try kernel_geometry.DenseRows.init(getData(input).len, dim);
    var owned_output = try OwnedDenseOutput.copy(self, getData(input));
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    activations_mod.rmsNorm(output, getData(weight), geometry.width, eps);
    return owned_output.intoLike(input);
}

fn rmsNormConsumeInputOp(ctx: *anyopaque, input: CT, weight: CT, dim: usize, eps: f32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    defer maybeDiscardMappedWeightAfterUse(self, weight);
    const buf = uniqueOwnedDenseBuf(input) orelse return null;
    try prepareDataRead(weight);
    activations_mod.rmsNorm(buf.data, getData(weight), dim, eps);
    return input;
}

