    const rnd = prng.random();

    const q = try allocator.alloc(f32, tok * H);
    defer allocator.free(q);
    const k = try allocator.alloc(f32, tok * H);
    defer allocator.free(k);
    const v = try allocator.alloc(f32, tok * H);
    defer allocator.free(v);
    const q_r = try allocator.alloc(f32, rel_len * H);
    defer allocator.free(q_r);
    const k_r = try allocator.alloc(f32, rel_len * H);
    defer allocator.free(k_r);
    const d_o = try allocator.alloc(f32, tok * H);
    defer allocator.free(d_o);

    for (q) |*x| x.* = rnd.floatNorm(f32) * 0.3;
    for (k) |*x| x.* = rnd.floatNorm(f32) * 0.3;
    for (v) |*x| x.* = rnd.floatNorm(f32) * 0.3;
    for (q_r) |*x| x.* = rnd.floatNorm(f32) * 0.3;
    for (k_r) |*x| x.* = rnd.floatNorm(f32) * 0.3;
    for (d_o) |*x| x.* = rnd.floatNorm(f32);

    const mask = [_]i64{ 1, 1, 0, 1 };

    const grads = try debertaDisentangledAttentionBackwardHost(
        allocator,
        q,
        k,
        v,
        q_r,
        k_r,
        &mask,
        d_o,
        batch,
        seq_len,
        num_heads,
        head_dim,
    );
    defer allocator.free(grads.dQ);
    defer allocator.free(grads.dK);
    defer allocator.free(grads.dV);
    defer allocator.free(grads.dQ_r);
    defer allocator.free(grads.dK_r);

    {
        const j_pad = 2;
        const base = (0 * seq_len + j_pad) * H;
        for (0..head_dim) |d| {
            try std.testing.expectEqual(@as(f32, 0.0), grads.dK[base + d]);
            try std.testing.expectEqual(@as(f32, 0.0), grads.dV[base + d]);
        }
    }

    const eps: f32 = 1e-3;

    const lossFn = struct {
        fn f(a: std.mem.Allocator, qq: []const f32, kk: []const f32, vv: []const f32, qr: []const f32, kr: []const f32, m: []const i64, dgo: []const f32, bb: usize, sl: usize, nh: usize, hd: usize) !f32 {
            const out = try linalg.debertaDisentangledAttentionHost(a, qq, kk, vv, qr, kr, m, bb, sl, nh, hd);
            defer a.free(out);
            var s: f32 = 0.0;
            for (out, dgo) |o, gg| s += o * gg;
            return s;
        }
    }.f;

    const Param = struct { buf: []f32, grad: []const f32, name: []const u8 };
    const params = [_]Param{
        .{ .buf = q, .grad = grads.dQ, .name = "dQ" },
        .{ .buf = k, .grad = grads.dK, .name = "dK" },
        .{ .buf = v, .grad = grads.dV, .name = "dV" },
        .{ .buf = q_r, .grad = grads.dQ_r, .name = "dQ_r" },
        .{ .buf = k_r, .grad = grads.dK_r, .name = "dK_r" },
    };

    for (params) |p| {
        for (p.buf, 0..) |*elem, idx| {
            const orig = elem.*;
            elem.* = orig + eps;
            const lp = try lossFn(allocator, q, k, v, q_r, k_r, &mask, d_o, batch, seq_len, num_heads, head_dim);
            elem.* = orig - eps;
            const lm = try lossFn(allocator, q, k, v, q_r, k_r, &mask, d_o, batch, seq_len, num_heads, head_dim);
            elem.* = orig;

            const num_grad = (lp - lm) / (2.0 * eps);
            const ana_grad = p.grad[idx];
            const denom = @max(@as(f32, 1.0), @max(@abs(num_grad), @abs(ana_grad)));
            const rel_err = @abs(num_grad - ana_grad) / denom;
            std.testing.expect(rel_err < 1e-2) catch |e| {
                std.debug.print("{s}[{d}] num={d} ana={d} rel={d}\n", .{ p.name, idx, num_grad, ana_grad, rel_err });
                return e;
            };
        }
    }
}

/// T5 relative position bucket computation.
/// Maps a relative position (key_pos - query_pos) to a bucket index.
pub fn t5RelativePositionBucket(relative_position: i64, num_buckets_: usize, max_distance_: usize, bidirectional: bool) usize {
    return linalg.t5RelativePositionBucket(relative_position, num_buckets_, max_distance_, bidirectional);
}

fn multiplyOp(ctx: *anyopaque, a: CT, b: CT) anyerror!CT {
    return allocatingArithmetic(.multiply, ctx, a, b);
}
fn conv1dOp(ctx: *anyopaque, input: CT, weight: CT, bias: CT, batch: usize, in_channels: usize, out_channels: usize, time_steps: usize, kernel_size: usize, stride: usize, padding: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    // NCT/OIK is the height-one NCHW/OIHW layout. Share the accelerated,
    // bounded convolution implementation and retain scalar execution when
    // its optional im2col workspace cannot be admitted.
    if (conv2dOp(ctx, input, weight, bias, batch, in_channels, out_channels, 1, time_steps, 1, kernel_size, 1, stride, 0, padding, 1)) |result| {
        return self.withLogicalShape(result, &.{ @intCast(batch), @intCast(out_channels), @intCast((time_steps + 2 * padding - kernel_size) / stride + 1) });
    } else |err| switch (err) {
        error.OutOfMemory, error.UnsupportedShape => {},
        else => return err,
    }

    defer maybeDiscardMappedWeightAfterUse(self, weight);
    const in_data = getData(input);
    const w_data = getData(weight);
    const b_data = getData(bias);

    const out_time = (time_steps + 2 * padding - kernel_size) / stride + 1;
    const output = try self.allocator.alloc(f32, batch * out_channels * out_time);
    errdefer self.allocator.free(output);

    // Initialize with bias
    for (0..batch) |b| {
        for (0..out_channels) |oc| {
            const bias_val = b_data[oc];
            const out_base = (b * out_channels + oc) * out_time;
            for (0..out_time) |t| {
                output[out_base + t] = bias_val;
            }
        }
    }

    // Conv1d: output[b, oc, t] += sum over ic, k of input[b, ic, t*stride + k - padding] * weight[oc, ic, k]
    for (0..batch) |b| {
        for (0..out_channels) |oc| {
            for (0..out_time) |t| {
                var sum: f32 = 0.0;
                for (0..in_channels) |ic| {
                    for (0..kernel_size) |k| {
                        const in_t_signed: i64 = @as(i64, @intCast(t * stride + k)) - @as(i64, @intCast(padding));
                        if (in_t_signed >= 0 and in_t_signed < @as(i64, @intCast(time_steps))) {
                            const in_t: usize = @intCast(in_t_signed);
                            const in_idx = (b * in_channels + ic) * time_steps + in_t;
                            const w_idx = (oc * in_channels + ic) * kernel_size + k;
                            sum += in_data[in_idx] * w_data[w_idx];
                        }
                    }
                }
                output[(b * out_channels + oc) * out_time + t] += sum;
            }
        }
    }

    const result = try self.makeBuf(output, true);
    return self.withLogicalShape(result, &.{ @intCast(batch), @intCast(out_channels), @intCast(out_time) });
}

fn conv2dOp(ctx: *anyopaque, input: CT, weight: CT, bias: CT, batch: usize, in_channels: usize, out_channels: usize, height: usize, width: usize, kernel_h: usize, kernel_w: usize, stride_h: usize, stride_w: usize, padding_h: usize, padding_w: usize, groups: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    defer maybeDiscardMappedWeightAfterUse(self, weight);
    if (batch == 0 or in_channels == 0 or out_channels == 0 or height == 0 or width == 0 or kernel_h == 0 or kernel_w == 0 or stride_h == 0 or stride_w == 0 or groups == 0 or in_channels % groups != 0 or out_channels % groups != 0) return error.InvalidInputShape;

    const out_h = kernel_geometry.convolutionOutput(height, kernel_h, stride_h, padding_h) catch return error.InvalidInputShape;
    const out_w = kernel_geometry.convolutionOutput(width, kernel_w, stride_w, padding_w) catch return error.InvalidInputShape;

    const input_data = getData(input);
    const weight_data = getData(weight);
    const bias_data = getData(bias);
    const input_elems = std.math.mul(usize, std.math.mul(usize, batch, in_channels) catch return error.InvalidInputShape, std.math.mul(usize, height, width) catch return error.InvalidInputShape) catch return error.InvalidInputShape;
    const kernel_elems = std.math.mul(usize, kernel_h, kernel_w) catch return error.InvalidInputShape;
    const weight_elems = std.math.mul(usize, std.math.mul(usize, out_channels, in_channels / groups) catch return error.InvalidInputShape, kernel_elems) catch return error.InvalidInputShape;
    if (input_data.len != input_elems or weight_data.len != weight_elems or bias_data.len != out_channels) return error.InvalidInputShape;

    const output_area = std.math.mul(usize, out_h, out_w) catch return error.InvalidInputShape;
    const output_elems = std.math.mul(usize, std.math.mul(usize, batch, out_channels) catch return error.InvalidInputShape, output_area) catch return error.InvalidInputShape;
    const conv_temp_limit_elems: usize = 64 * 1024 * 1024;
    if (output_elems > conv_temp_limit_elems) {
        std.log.warn("conv2d refusing oversized output batch={d} in_channels={d} out_channels={d} height={d} width={d} kernel={d}x{d} stride={d}x{d} padding={d}x{d} groups={d} out={d}x{d} output_elems={d}", .{
            batch,
            in_channels,
            out_channels,
            height,
            width,
            kernel_h,
            kernel_w,
            stride_h,
            stride_w,
            padding_h,
            padding_w,
            groups,
            out_h,
            out_w,
            output_elems,
        });
        return error.UnsupportedShape;
    }
    const output = try self.allocator.alloc(f32, output_elems);
    errdefer self.allocator.free(output);

    if (groups == 1 and kernel_h == 1 and kernel_w == 1 and stride_h == 1 and stride_w == 1 and padding_h == 0 and padding_w == 0) {
        // Pointwise convolution is already a matrix product in channel-major
        // storage. No im2col buffer or output transpose is needed.
        for (0..batch) |b| {
            const batch_out = output[b * out_channels * output_area ..][0 .. out_channels * output_area];
            for (0..out_channels) |oc| @memset(batch_out[oc * output_area ..][0..output_area], bias_data[oc]);
            const batch_input = input_data[b * in_channels * output_area ..][0 .. in_channels * output_area];
            try self.dispatchSgemm(out_channels, output_area, in_channels, 1.0, weight_data, batch_input, 1.0, batch_out);
        }
        const result = try self.makeBuf(output, true);
        return self.withLogicalShape(result, &.{ @intCast(batch), @intCast(out_channels), @intCast(out_h), @intCast(out_w) });
    }

    if (groups == 1) {
        const rows = output_area;
        const k_dim = std.math.mul(usize, in_channels, kernel_elems) catch return error.InvalidInputShape;
        const cols_elems = try std.math.mul(usize, rows, k_dim);
        if (cols_elems > conv_temp_limit_elems) {
            std.log.warn("conv2d refusing oversized im2col rows={d} k_dim={d} cols_elems={d} batch={d} in_channels={d} out_channels={d} height={d} width={d} kernel={d}x{d} stride={d}x{d} padding={d}x{d}", .{
                rows,
                k_dim,
                cols_elems,
                batch,
                in_channels,
                out_channels,
                height,
                width,
                kernel_h,
                kernel_w,
                stride_h,
                stride_w,
                padding_h,
                padding_w,
            });
            return error.UnsupportedShape;
        }
        const cols = try self.allocator.alloc(f32, cols_elems);
        defer self.allocator.free(cols);

        for (0..batch) |b| {
            for (0..out_h) |oy| {
                for (0..out_w) |ox| {
                    const row = oy * out_w + ox;
                    const row_base = row * k_dim;
                    for (0..in_channels) |ic| {
                        for (0..kernel_h) |ky| {
                            for (0..kernel_w) |kx| {
                                const col_idx = ((ic * kernel_h + ky) * kernel_w) + kx;
                                const in_y_signed: i64 = @as(i64, @intCast(oy * stride_h + ky)) - @as(i64, @intCast(padding_h));
                                const in_x_signed: i64 = @as(i64, @intCast(ox * stride_w + kx)) - @as(i64, @intCast(padding_w));
                                cols[row_base + col_idx] = if (in_y_signed < 0 or in_x_signed < 0 or in_y_signed >= @as(i64, @intCast(height)) or in_x_signed >= @as(i64, @intCast(width))) 0.0 else blk: {
                                    const in_y: usize = @intCast(in_y_signed);
                                    const in_x: usize = @intCast(in_x_signed);
                                    const in_idx = ((b * in_channels + ic) * height + in_y) * width + in_x;
                                    break :blk input_data[in_idx];
                                };
                            }
                        }
                    }
                }
            }

            const batch_out = output[b * out_channels * rows ..][0 .. out_channels * rows];
            for (0..rows) |row| {
                const dst = batch_out[row * out_channels ..][0..out_channels];
                @memcpy(dst, bias_data[0..out_channels]);
            }
            try self.dispatchSgemmTransB(rows, out_channels, k_dim, 1.0, cols, weight_data, 1.0, batch_out);
        }

        const transposed = try self.allocator.alloc(f32, output.len);
        defer self.allocator.free(transposed);
        for (0..batch) |b| {
            const src_batch = output[b * out_channels * rows ..][0 .. out_channels * rows];
            const dst_batch = transposed[b * out_channels * rows ..][0 .. out_channels * rows];
            for (0..rows) |row| {
                for (0..out_channels) |oc| {
                    dst_batch[(oc * rows) + row] = src_batch[row * out_channels + oc];
                }
            }
        }
        @memcpy(output, transposed);
        const result = try self.makeBuf(output, true);
        return self.withLogicalShape(result, &.{ @intCast(batch), @intCast(out_channels), @intCast(out_h), @intCast(out_w) });
    }

    if (groups == in_channels and groups == out_channels) {
        const kernel_size = kernel_elems;
        for (0..batch) |b| {
            for (0..out_channels) |c| {
                const weight_channel = weight_data[c * kernel_size ..][0..kernel_size];
                const input_base = (b * in_channels + c) * height * width;
                const output_base = (b * out_channels + c) * out_h * out_w;
                for (0..out_h) |oy| {
                    const in_y_origin = oy * stride_h;
                    for (0..out_w) |ox| {
                        const in_x_origin = ox * stride_w;
                        var acc = bias_data[c];
                        for (0..kernel_h) |ky| {
                            const in_y_signed: i64 = @as(i64, @intCast(in_y_origin + ky)) - @as(i64, @intCast(padding_h));
                            if (in_y_signed < 0 or in_y_signed >= @as(i64, @intCast(height))) continue;
                            const in_y: usize = @intCast(in_y_signed);
                            const row_base = input_base + in_y * width;
                            const weight_row_base = ky * kernel_w;
                            for (0..kernel_w) |kx| {
                                const in_x_signed: i64 = @as(i64, @intCast(in_x_origin + kx)) - @as(i64, @intCast(padding_w));
                                if (in_x_signed < 0 or in_x_signed >= @as(i64, @intCast(width))) continue;
                                const in_x: usize = @intCast(in_x_signed);
                                acc += input_data[row_base + in_x] * weight_channel[weight_row_base + kx];
                            }
                        }
                        output[output_base + oy * out_w + ox] = acc;
                    }
                }
            }
        }

        const result = try self.makeBuf(output, true);
        return self.withLogicalShape(result, &.{ @intCast(batch), @intCast(out_channels), @intCast(out_h), @intCast(out_w) });
    }

    const in_per_group = in_channels / groups;
    const out_per_group = out_channels / groups;
    const rows = output_area;
    const k_dim = std.math.mul(usize, in_per_group, kernel_elems) catch return error.InvalidInputShape;
    const cols_elems = try std.math.mul(usize, rows, k_dim);
    if (cols_elems > conv_temp_limit_elems) {
        std.log.warn("conv2d refusing oversized grouped im2col rows={d} k_dim={d} cols_elems={d} batch={d} in_channels={d} out_channels={d} height={d} width={d} kernel={d}x{d} stride={d}x{d} padding={d}x{d} groups={d}", .{
            rows,
            k_dim,
            cols_elems,
            batch,
            in_channels,
            out_channels,
            height,
            width,
            kernel_h,
            kernel_w,
            stride_h,
            stride_w,
            padding_h,
            padding_w,
            groups,
        });
        return error.UnsupportedShape;
    }
    const cols = try self.allocator.alloc(f32, cols_elems);
    defer self.allocator.free(cols);
    const group_out = try self.allocator.alloc(f32, rows * out_per_group);
    defer self.allocator.free(group_out);
    const transposed = try self.allocator.alloc(f32, rows * out_per_group);
    defer self.allocator.free(transposed);

    for (0..batch) |b| {
        for (0..groups) |group| {
            const ic_base = group * in_per_group;
            const oc_base = group * out_per_group;

            for (0..out_h) |oy| {
                for (0..out_w) |ox| {
                    const row = oy * out_w + ox;
                    const row_base = row * k_dim;
                    for (0..in_per_group) |ic_group| {
                        const ic = ic_base + ic_group;
                        for (0..kernel_h) |ky| {
                            for (0..kernel_w) |kx| {
                                const col_idx = ((ic_group * kernel_h + ky) * kernel_w) + kx;
                                const in_y_signed: i64 = @as(i64, @intCast(oy * stride_h + ky)) - @as(i64, @intCast(padding_h));
                                const in_x_signed: i64 = @as(i64, @intCast(ox * stride_w + kx)) - @as(i64, @intCast(padding_w));
                                cols[row_base + col_idx] = if (in_y_signed < 0 or in_x_signed < 0 or in_y_signed >= @as(i64, @intCast(height)) or in_x_signed >= @as(i64, @intCast(width))) 0.0 else blk: {
                                    const in_y: usize = @intCast(in_y_signed);
                                    const in_x: usize = @intCast(in_x_signed);
                                    const in_idx = ((b * in_channels + ic) * height + in_y) * width + in_x;
                                    break :blk input_data[in_idx];
                                };
                            }
                        }
                    }
                }
            }

            for (0..rows) |row| {
                const dst = group_out[row * out_per_group ..][0..out_per_group];
                @memcpy(dst, bias_data[oc_base..][0..out_per_group]);
            }
            const weight_group = weight_data[oc_base * k_dim ..][0 .. out_per_group * k_dim];
            try self.dispatchSgemmTransB(rows, out_per_group, k_dim, 1.0, cols, weight_group, 1.0, group_out);

            for (0..rows) |row| {
                for (0..out_per_group) |oc_group| {
                    transposed[oc_group * rows + row] = group_out[row * out_per_group + oc_group];
                }
            }
            const batch_base = b * out_channels * rows;
            for (0..out_per_group) |oc_group| {
                const dst = output[batch_base + (oc_base + oc_group) * rows ..][0..rows];
                const src = transposed[oc_group * rows ..][0..rows];
                @memcpy(dst, src);
            }
        }
    }

    const result = try self.makeBuf(output, true);
    return self.withLogicalShape(result, &.{ @intCast(batch), @intCast(out_channels), @intCast(out_h), @intCast(out_w) });
}
fn averagePoolOp(ctx: *anyopaque, input: CT, attrs: *const @import("ml").graph.node.AveragePoolAttrs) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const buf = toBuf(input);
    const shape = buf.logical_shape orelse
        if (buf.quantized_storage) |storage| storage.shape else return error.UnsupportedShape;
    const spatial = attrs.num_spatial;
    const max_spatial = @import("ml").graph.node.AveragePoolAttrs.max_spatial;
    if (spatial == 0 or spatial > max_spatial or shape.len != @as(usize, spatial) + 2) return error.UnsupportedShape;
    if (shape[0] <= 0 or shape[1] <= 0) return error.InvalidInputShape;
    const planes = std.math.mul(usize, @intCast(shape[0]), @intCast(shape[1])) catch return error.InvalidInputShape;
    var input_spatial: [max_spatial]usize = @splat(1);
    var output_spatial: [max_spatial]usize = @splat(1);
    var input_strides: [max_spatial]usize = @splat(1);
    var output_strides: [max_spatial]usize = @splat(1);
    var window_steps: [max_spatial]usize = @splat(1);
    var pad_before: [max_spatial]usize = @splat(0);
    var logical_shape: [max_spatial + 2]i64 = @splat(0);
    @memcpy(logical_shape[0..shape.len], shape);
    var input_area: usize = 1;
    var output_area: usize = 1;
    var kernel_count: usize = 1;
    for (0..spatial) |reverse| {
        const axis = spatial - 1 - reverse;
        if (shape[axis + 2] <= 0) return error.InvalidInputShape;
        input_spatial[axis] = @intCast(shape[axis + 2]);
        const dimension = attrs.spatialOutput(axis, input_spatial[axis]) orelse return error.InvalidInputShape;
        output_spatial[axis] = dimension.size;
        pad_before[axis] = dimension.pad_before;
        logical_shape[axis + 2] = std.math.cast(i64, dimension.size) orelse return error.InvalidInputShape;
        input_strides[axis] = input_area;
        output_strides[axis] = output_area;
        window_steps[axis] = std.math.mul(usize, input_area, attrs.dilations[axis]) catch return error.InvalidInputShape;
        input_area = std.math.mul(usize, input_area, input_spatial[axis]) catch return error.InvalidInputShape;
        output_area = std.math.mul(usize, output_area, output_spatial[axis]) catch return error.InvalidInputShape;
        kernel_count = std.math.mul(usize, kernel_count, attrs.kernel[axis]) catch return error.InvalidInputShape;
    }
    const input_elems = std.math.mul(usize, planes, input_area) catch return error.InvalidInputShape;
    const output_elems = std.math.mul(usize, planes, output_area) catch return error.InvalidInputShape;
    if (output_elems > 64 * 1024 * 1024) return error.UnsupportedShape;
    const view = try denseTensorView(self, input);
    defer view.deinit(self.allocator);
    if (view.data.len != input_elems) return error.InvalidInputShape;
    const output = try self.allocator.alloc(f32, output_elems);

    for (0..output_area) |output_index| {
        var valid_counts: [max_spatial]usize = @splat(1);
        var first_positions: [max_spatial]i128 = @splat(0);
        var valid_count: usize = 1;
        for (0..spatial) |axis| {
            const coordinate = (output_index / output_strides[axis]) % output_spatial[axis];
            const base = @as(i128, @intCast(coordinate)) * attrs.strides[axis] - pad_before[axis];
            const dilation: i128 = attrs.dilations[axis];
            const kernel: i128 = attrs.kernel[axis];
            const first = @min(kernel, @max(0, @divFloor(-base + dilation - 1, dilation)));
            const end = @min(kernel, @max(0, @divFloor(@as(i128, @intCast(input_spatial[axis])) - 1 - base, dilation) + 1));
            valid_counts[axis] = @intCast(@max(0, end - first));
            first_positions[axis] = base + first * dilation;
            valid_count *= valid_counts[axis];
        }
        var window_base: usize = 0;
        if (valid_count != 0) {
            for (0..spatial) |axis| window_base += @as(usize, @intCast(first_positions[axis])) * input_strides[axis];
        }
        const divisor: f32 = @floatFromInt(if (attrs.count_include_pad) kernel_count else valid_count);
        for (0..planes) |plane| {
            var sum: f32 = 0;
            // Iterate only real input samples, not potentially enormous virtual padding.
            for (0..valid_count) |sample| {
                var remaining = sample;
                var offset = window_base;
                for (0..spatial) |reverse| {
                    const axis = spatial - 1 - reverse;
                    offset += (remaining % valid_counts[axis]) * window_steps[axis];
                    remaining /= valid_counts[axis];
                }
                sum += view.data[plane * input_area + offset];
            }
            output[plane * output_area + output_index] = sum / divisor;
        }
    }
    const result = try self.makeOwnedBuf(output);
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, logical_shape[0..shape.len]);
}

fn convTransposeOp(ctx: *anyopaque, request: *const ops.ConvTransposeRequest) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    defer maybeDiscardMappedWeightAfterUse(self, request.weight);

    if (request.num_spatial != 1 and request.num_spatial != 2) return error.UnsupportedShape;
    if (request.batch == 0 or request.in_channels == 0 or request.out_channels == 0 or
        request.groups == 0 or request.in_channels % request.groups != 0 or
        request.out_channels % request.groups != 0)
    {
        return error.InvalidInputShape;
    }

    for (0..request.num_spatial) |axis| {
        const expected = ops.convTransposeOutputDim(
            request.input_spatial[axis],
            request.kernel[axis],
            request.strides[axis],
            request.padding[axis],
            request.dilations[axis],
            request.output_padding[axis],
        ) orelse return error.InvalidInputShape;
        if (request.output_spatial[axis] != expected) return error.ShapeMismatch;
    }
    if (request.num_spatial == 1 and
        (request.input_spatial[1] != 1 or request.kernel[1] != 1 or
            request.output_spatial[1] != 1))
    {
        return error.InvalidInputShape;
    }

    const input_area = std.math.mul(usize, request.input_spatial[0], request.input_spatial[1]) catch return error.InvalidInputShape;
    const kernel_area = std.math.mul(usize, request.kernel[0], request.kernel[1]) catch return error.InvalidInputShape;
    const output_area = std.math.mul(usize, request.output_spatial[0], request.output_spatial[1]) catch return error.InvalidInputShape;
    const input_elems = std.math.mul(
        usize,
        std.math.mul(usize, request.batch, request.in_channels) catch return error.InvalidInputShape,
        input_area,
    ) catch return error.InvalidInputShape;
    const out_per_group = request.out_channels / request.groups;
    const weight_elems = std.math.mul(
        usize,
        std.math.mul(usize, request.in_channels, out_per_group) catch return error.InvalidInputShape,
        kernel_area,
    ) catch return error.InvalidInputShape;
    const output_elems = std.math.mul(
        usize,
        std.math.mul(usize, request.batch, request.out_channels) catch return error.InvalidInputShape,
        output_area,
    ) catch return error.InvalidInputShape;

    const conv_temp_limit_elems: usize = 64 * 1024 * 1024;
    if (output_elems > conv_temp_limit_elems) {
        std.log.warn(
            "convTranspose refusing oversized output batch={d} in_channels={d} out_channels={d} input={d}x{d} kernel={d}x{d} output={d}x{d} groups={d} output_elems={d}",
            .{
                request.batch,
                request.in_channels,
                request.out_channels,
                request.input_spatial[0],
                request.input_spatial[1],
                request.kernel[0],
                request.kernel[1],
                request.output_spatial[0],
                request.output_spatial[1],
                request.groups,
                output_elems,
            },
        );
        return error.UnsupportedShape;
    }
    const input_view = try denseTensorView(self, request.input);
    defer input_view.deinit(self.allocator);
    const weight_view = try denseTensorView(self, request.weight);
    defer weight_view.deinit(self.allocator);
    const input_data = input_view.data;
    const weight_data = weight_view.data;
    if (input_data.len != input_elems or weight_data.len != weight_elems) return error.InvalidInputShape;

    const output = try self.allocator.alloc(f32, output_elems);
    @memset(output, 0.0);

    const in_per_group = request.in_channels / request.groups;
    const horizontal_padding: i32 = if (request.num_spatial == 2) request.padding[1][0] else 0;
    for (0..request.batch) |batch| {
        for (0..request.groups) |group| {
            const input_channel_base = group * in_per_group;
            const output_channel_base = group * out_per_group;
            for (0..in_per_group) |input_channel_in_group| {
                const input_channel = input_channel_base + input_channel_in_group;
                const input_base = (batch * request.in_channels + input_channel) * input_area;
                const weight_channel_base = input_channel * out_per_group * kernel_area;
                for (0..request.input_spatial[0]) |input_y| {
                    for (0..request.input_spatial[1]) |input_x| {
                        const input_value = input_data[input_base + input_y * request.input_spatial[1] + input_x];
                        for (0..request.kernel[0]) |kernel_y| {
                            const output_y_signed =
                                @as(i128, @intCast(input_y)) * @as(i128, @intCast(request.strides[0])) -
                                @as(i128, request.padding[0][0]) +
                                @as(i128, @intCast(kernel_y)) * @as(i128, @intCast(request.dilations[0]));
                            if (output_y_signed < 0 or output_y_signed >= @as(i128, @intCast(request.output_spatial[0]))) continue;
                            const output_y: usize = @intCast(output_y_signed);
                            for (0..request.kernel[1]) |kernel_x| {
                                const output_x_signed =
                                    @as(i128, @intCast(input_x)) * @as(i128, @intCast(request.strides[1])) -
                                    @as(i128, horizontal_padding) +
                                    @as(i128, @intCast(kernel_x)) * @as(i128, @intCast(request.dilations[1]));
                                if (output_x_signed < 0 or output_x_signed >= @as(i128, @intCast(request.output_spatial[1]))) continue;
                                const output_x: usize = @intCast(output_x_signed);
                                const kernel_index = kernel_y * request.kernel[1] + kernel_x;
                                for (0..out_per_group) |output_channel_in_group| {
                                    const output_channel = output_channel_base + output_channel_in_group;
                                    const output_base = (batch * request.out_channels + output_channel) * output_area;
                                    const output_index = output_base + output_y * request.output_spatial[1] + output_x;
                                    const weight_index = weight_channel_base + output_channel_in_group * kernel_area + kernel_index;
                                    output[output_index] += input_value * weight_data[weight_index];
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    const result = try self.makeOwnedBuf(output);
    errdefer freeTensor(self, result);
    const logical_shape = if (request.num_spatial == 1)
        [_]i64{
            @intCast(request.batch),
            @intCast(request.out_channels),
            @intCast(request.output_spatial[0]),
            0,
        }
    else
        [_]i64{
            @intCast(request.batch),
            @intCast(request.out_channels),
            @intCast(request.output_spatial[0]),
            @intCast(request.output_spatial[1]),
        };
    return self.withLogicalShape(result, logical_shape[0 .. request.num_spatial + 2]);
}

/// Shared RoPE rotation core. Rotates `output` in-place using one position
/// value per head-sized chunk. `positions[tok]` gives the absolute position
/// for token index `tok`. Tokens with position 0 are identity (cos 0 = 1,
/// sin 0 = 0) so padded slots are left unchanged.
pub fn ropeCore(output: []f32, positions: []const usize, head_dim: usize, rope_dim: usize, theta: f32, freq_scale: f32, consecutive_pairs: bool) void {
    linalg.ropeCore(output, positions, head_dim, rope_dim, theta, freq_scale, consecutive_pairs);
}

// Axis selection specializes at compile time; heads share each token/pair's
// phase without changing its F32 expression or the two-component store order.
inline fn axisRopeCore(
    comptime vision: bool,
    comptime single_head: bool,
    output: []f32,
    input: []const f32,
    token_count: usize,
    head_dim: usize,
    theta: f32,
    freq_scale: f32,
    positions: []const u32,
    sections: [3]u32,
) void {
    const rotary_pairs = head_dim / 2;
    const chunks_per_token = if (single_head) 1 else input.len / head_dim / token_count;
    for (0..token_count) |token| {
        for (0..rotary_pairs) |pair| {
            const axis: usize = if (vision)
                @intFromBool(pair >= rotary_pairs / 2)
            else if (pair % 3 == 1 and pair < @as(usize, sections[1]) * 3)
                1
            else if (pair % 3 == 2 and pair < @as(usize, sections[2]) * 3)
                2
            else
                0;
            const position = positions[axis * token_count + token];
            const local_pair = if (vision) pair % (rotary_pairs / 2) else pair;
            const frequency_dim = if (vision) head_dim / 2 else head_dim;
            const exponent = @as(f32, @floatFromInt(2 * local_pair)) / @as(f32, @floatFromInt(frequency_dim));
            const frequency = 1.0 / std.math.pow(f32, theta, exponent);
            const angle = if (vision)
                @as(f32, @floatFromInt(position)) * frequency
            else
                @as(f32, @floatFromInt(position)) * freq_scale * frequency;
            const cosine = @cos(angle);
            const sine = @sin(angle);
            for (0..chunks_per_token) |head| {
                const base = (token * chunks_per_token + head) * head_dim;
                const left = input[base + pair];
                const right = input[base + rotary_pairs + pair];
                output[base + pair] = left * cosine - right * sine;
                output[base + rotary_pairs + pair] = left * sine + right * cosine;
            }
        }
    }
}

/// Reference Qwen3-VL interleaved M-RoPE. Section counts address rotary
/// pairs, and therefore sum to head_dim / 2.
pub fn mropeCore(
    output: []f32,
    input: []const f32,
    token_count: usize,
    head_dim: usize,
    theta: f32,
    freq_scale: f32,
    positions: []const u32,
    sections: [3]u32,
) !void {
    if (token_count == 0 or head_dim == 0 or head_dim % 2 != 0) return error.InvalidRoPEInput;
    if (positions.len != 3 * token_count or input.len != output.len or input.len % head_dim != 0)
        return error.InvalidRoPEInput;
    const rotary_pairs = head_dim / 2;
    if (@as(usize, sections[0]) + sections[1] + sections[2] != rotary_pairs)
        return error.InvalidRoPEInput;
    const total_chunks = input.len / head_dim;
    if (total_chunks % token_count != 0) return error.InvalidRoPEInput;
    const chunks_per_token = total_chunks / token_count;
    if (chunks_per_token == 0) return error.InvalidRoPEInput;

    axisRopeCore(false, false, output, input, token_count, head_dim, theta, freq_scale, positions, sections);
}

fn mropeOp(
    ctx: *anyopaque,
    input: CT,
    token_count: usize,
    head_dim: usize,
    theta: f32,
    freq_scale: f32,
    positions: []const u32,
    sections: [3]u32,
) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const data = getData(input);
    const output = try self.allocator.alloc(f32, data.len);
    errdefer self.allocator.free(output);
    try mropeCore(output, data, token_count, head_dim, theta, freq_scale, positions, sections);
    const result = try self.makeBuf(output, true);
    return propagateLogicalShapeLike(self, result, input);
}

/// Reference implementation of Qwen3-VL vision RoPE. The first half of
/// frequency pairs uses height and the second half uses width. Frequencies
/// restart at zero for each axis, matching the concatenated HF embedding.
pub fn visionRopeCore(
    output: []f32,
    input: []const f32,
    token_count: usize,
    head_dim: usize,
    theta: f32,
    positions: []const u32,
) !void {
    if (token_count == 0 or head_dim == 0 or head_dim % 4 != 0 or theta <= 0) {
        return error.InvalidRoPEInput;
    }
    if (positions.len != 2 * token_count or input.len != output.len or input.len % head_dim != 0) {
        return error.InvalidRoPEInput;
    }
    const total_chunks = input.len / head_dim;
    if (total_chunks % token_count != 0) return error.InvalidRoPEInput;
    const heads_per_token = total_chunks / token_count;
    if (heads_per_token == 0) return error.InvalidRoPEInput;
    if (heads_per_token == 1)
        axisRopeCore(true, true, output, input, token_count, head_dim, theta, 1, positions, .{ 0, 0, 0 })
    else
        axisRopeCore(true, false, output, input, token_count, head_dim, theta, 1, positions, .{ 0, 0, 0 });
}

fn visionNormRopeOp(ctx: *anyopaque, input: CT, weight: CT, p: ops.VisionNormRopeParams) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const data = getData(input);
    const w = getData(weight);
    const stride: usize = if (p.stride == 0) p.hidden else p.stride;
    if (p.start > stride or p.hidden > stride - p.start or p.rotate > 1 or p.weighted > 1) return error.InvalidTensorShape;
    if (p.rows == 0 or p.head_dim == 0 or p.head_dim % 4 != 0 or p.hidden % p.head_dim != 0 or p.grid_x == 0 or p.grid_y == 0 or p.theta <= 0 or data.len != @as(usize, p.rows) * stride or w.len != p.head_dim) return error.InvalidTensorShape;
    var owned_output = try OwnedDenseOutput.alloc(self, @as(usize, p.rows) * p.hidden);
    defer owned_output.deinit();
    const out = owned_output.storage.?;
    const quarter = p.head_dim / 4;
    // The spatial angles are independent of head, batch and layer weights.
    // Evaluate each axis/position once, rather than per head and output lane.
    const positions = try std.math.add(usize, p.grid_x, p.grid_y);
    const trig = try self.allocator.alloc(f32, if (p.rotate == 0) 0 else try std.math.mul(usize, positions, quarter * 2));
    defer self.allocator.free(trig);
    if (p.rotate != 0) for (0..quarter) |j| {
        const freq = 1 / std.math.pow(f32, p.theta, @as(f32, @floatFromInt(2 * j)) / @as(f32, @floatFromInt(p.head_dim / 2)));
        for (0..2) |axis| {
            const count = if (axis == 0) p.grid_x else p.grid_y;
            const first: usize = if (axis == 0) 0 else p.grid_x;
            for (0..count) |position| {
                const angle = @as(f32, @floatFromInt(position)) * freq;
                trig[((first + position) * quarter + j) * 2] = @cos(angle);
                trig[((first + position) * quarter + j) * 2 + 1] = @sin(angle);
            }
        }
    };
    for (0..p.rows) |row| {
        if (self.io) |io| try io.checkCancel();
        for (0..p.hidden / p.head_dim) |head| {
            const base = row * stride + p.start + head * p.head_dim;
            const destination = row * p.hidden + head * p.head_dim;
            var sum: f32 = 0;
            for (data[base..][0..p.head_dim]) |x| sum += x * x;
            const inv = 1 / @sqrt(sum / @as(f32, @floatFromInt(p.head_dim)) + p.eps);
            if (p.rotate == 0) {
                for (0..p.head_dim) |d| out[destination + d] = data[base + d] * inv * (if (p.weighted != 0) w[d] else 1) * p.scale;
                continue;
            }
            for (0..2) |axis| for (0..quarter) |j| {
                const ai = axis * 2 * quarter + j;
                const bi = ai + quarter;
                const position = if (axis == 0) row % p.grid_x else (row / p.grid_x) % p.grid_y;
                const offset = (((if (axis == 0) @as(usize, 0) else p.grid_x) + position) * quarter + j) * 2;
                const cosine = trig[offset];
                const sine = trig[offset + 1];
                const x = data[base + ai] * inv * (if (p.weighted != 0) w[ai] else 1);
                const y = data[base + bi] * inv * (if (p.weighted != 0) w[bi] else 1);
                out[destination + ai] = (x * cosine - y * sine) * p.scale;
                out[destination + bi] = (y * cosine + x * sine) * p.scale;
            };
        }
    }
    const tensor = try owned_output.intoResult();
    errdefer freeTensor(self, tensor);
    return try self.withLogicalShape(tensor, &.{ @intCast(p.rows), @intCast(p.hidden) });
}

fn visionRopeOp(
    ctx: *anyopaque,
    input: CT,
    token_count: usize,
    head_dim: usize,
    theta: f32,
    positions: []const u32,
) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const data = getData(input);
    const output = try self.allocator.alloc(f32, data.len);
    errdefer self.allocator.free(output);
    try visionRopeCore(output, data, token_count, head_dim, theta, positions);
    const result = try self.makeBuf(output, true);
    return propagateLogicalShapeLike(self, result, input);
}

/// Return the number of RoPE head chunks belonging to one token. Encoder
/// Q/K linears preserve the token-major `[batch * sequence, hidden]` shape,
/// so each token owns `hidden / head_dim` consecutive chunks. Falling back to
/// the historical layout inference keeps callers without that shape metadata
/// working, while preventing a batch-sized position stride for encoders.
fn ropeInto(self: *NativeCompute, input: CT, output: []f32, request: ops.kernel_descriptor.Rope) !void {
    const positions = try self.allocator.alloc(usize, request.total_chunks);
    defer self.allocator.free(positions);
    for (positions, 0..) |*position, chunk| position.* = request.positionAt(chunk);
    const data = getData(input);
    if (output.ptr != data.ptr) @memcpy(output, data);
    ropeCore(output, positions, request.head_dim, request.rope_dim, request.theta, request.freq_scale, request.consecutive_pairs);
}

fn ropeOp(ctx: *anyopaque, input: CT, seq_len: usize, head_dim: usize, rope_dim: usize, theta: f32, freq_scale: f32, position_offset: usize, consecutive_pairs: bool) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const request = try ops.kernel_descriptor.Rope.init(toBuf(input).logical_shape, getData(input).len, seq_len, head_dim, rope_dim, theta, freq_scale, position_offset, consecutive_pairs);
    var output = try OwnedDenseOutput.alloc(self, getData(input).len);
    defer output.deinit();
    try ropeInto(self, input, output.storage.?, request);
    return output.intoLike(input);
}

fn ropePerItemOp(
    ctx: *anyopaque,
    input: CT,
    batch: usize,
    max_seq_len: usize,
    head_dim: usize,
    rope_dim: usize,
    theta: f32,
    freq_scale: f32,
    query_lengths: []const usize,
    position_offsets: []const usize,
    consecutive_pairs: bool,
) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (query_lengths.len != batch or position_offsets.len != batch) return error.InvalidRoPEInput;

    const data = getData(input);
    const row_count = batch * max_seq_len;
    if (row_count == 0) return self.makeBuf(try self.allocator.dupe(f32, data), true);
    if (data.len % row_count != 0) return error.InvalidRoPEInput;

    const row_dim = data.len / row_count;
    if (row_dim % head_dim != 0) return error.InvalidRoPEInput;
    const num_heads = row_dim / head_dim;
    const output = try self.allocator.dupe(f32, data);
    errdefer self.allocator.free(output);

    // Build flat position array: one entry per head-sized chunk.
    // Layout is [batch][max_seq_len][num_heads], each chunk is head_dim floats.
    // Padded positions (pos >= query_lengths[b]) get 0, which is identity rotation.
    const total_tokens = row_count * num_heads;
    const positions = try self.allocator.alloc(usize, total_tokens);
    defer self.allocator.free(positions);
    @memset(positions, 0);

    for (0..batch) |b| {
        if (query_lengths[b] > max_seq_len) {
            return error.InvalidRoPEInput;
        }
        for (0..query_lengths[b]) |pos| {
            const absolute_pos = position_offsets[b] + pos;
            const row_base = (b * max_seq_len + pos) * num_heads;
            for (0..num_heads) |h| {
                positions[row_base + h] = absolute_pos;
            }
        }
    }

    ropeCore(output, positions, head_dim, rope_dim, theta, freq_scale, consecutive_pairs);
    return self.makeBuf(output, true);
}

fn gqaCausalAttentionOp(ctx: *anyopaque, q_ct: CT, k_ct: CT, v_ct: CT, attn_bias_ct: ?CT, batch: usize, seq_len: usize, num_heads: usize, num_kv_heads: usize, head_dim: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const Q = getData(q_ct);
    const K = getData(k_ct);
    const V = getData(v_ct);
    const bias: ?[]f32 = if (attn_bias_ct) |b| getData(b) else null;

    return gqaAttentionSlices(self, Q, K, V, bias, null, 0, null, seq_len, batch, seq_len, seq_len, 0, 0, num_heads, num_kv_heads, head_dim);
}

fn attentionSinkScores(sink: AttentionSinkMetadata, num_heads: usize) !?[]const f32 {
    if (sink.per_head_tensor) |tensor| {
        const scores = getData(tensor);
        if (scores.len < num_heads) return error.InvalidAttentionSinkShape;
        return scores[0..num_heads];
    }
    if (sink.slot != null) return error.UnsupportedAttentionSink;
    return null;
}

fn gqaAttentionSlices(
    self: *NativeCompute,
    Q: []const f32,
    K: []const f32,
    V: []const f32,
    bias: ?[]const f32,
    attn_or_mask: ?[]const u8,
    sliding_window: usize,
    sink_scores: ?[]const f32,
    total_sequence_len: usize,
    batch: usize,
    q_seq_len: usize,
    kv_seq_len: usize,
    query_position_offset: usize,
    kv_position_offset: usize,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) !CT {
    const output = if (sink_scores) |scores|
        try gqaAttentionSlicesSinkHost(self.allocator, Q, K, V, bias, attn_or_mask, sliding_window, scores, total_sequence_len, batch, q_seq_len, kv_seq_len, query_position_offset, kv_position_offset, num_heads, num_kv_heads, head_dim)
    else
        try flashCausalAttentionHost(self.allocator, Q, K, V, bias, attn_or_mask, sliding_window, batch, q_seq_len, kv_seq_len, query_position_offset, kv_position_offset, num_heads, num_kv_heads, head_dim);
    return self.makeBuf(output, true);
}

pub fn gqaAttentionSlicesSinkHost(
    allocator: std.mem.Allocator,
    Q: []const f32,
    K: []const f32,
    V: []const f32,
    bias: ?[]const f32,
    attn_or_mask: ?[]const u8,
    sliding_window: usize,
    sink_scores: []const f32,
    total_sequence_len: usize,
    batch: usize,
    q_seq_len: usize,
    kv_seq_len: usize,
    query_position_offset: usize,
    kv_position_offset: usize,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) ![]f32 {
    if (num_kv_heads == 0 or num_heads % num_kv_heads != 0) return error.InvalidAttentionShape;
    if (sink_scores.len < num_heads) return error.InvalidAttentionSinkShape;
    const H_q = num_heads * head_dim;
    const H_kv = num_kv_heads * head_dim;
    if (Q.len != batch * q_seq_len * H_q) return error.InvalidAttentionShape;
    if (K.len != batch * kv_seq_len * H_kv) return error.InvalidAttentionShape;
    if (V.len != batch * kv_seq_len * H_kv) return error.InvalidAttentionShape;

    const output = try allocator.alloc(f32, batch * q_seq_len * H_q);
    errdefer allocator.free(output);
    @memset(output, 0.0);

    const heads_per_group = num_heads / num_kv_heads;
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));
    for (0..batch) |b| {
        for (0..num_heads) |h| {
            const kv_h = h / heads_per_group;
            const sink_score = sink_scores[h];
            for (0..q_seq_len) |qi| {
                const q_ptr = Q[(b * q_seq_len + qi) * H_q + h * head_dim ..][0..head_dim];
                const out_ptr = output[(b * q_seq_len + qi) * H_q + h * head_dim ..][0..head_dim];
                var running_max = sink_score;
                var running_sum: f32 = 1.0;

                for (0..kv_seq_len) |ki| {
                    const query_pos = query_position_offset + qi;
                    const key_pos = kv_position_offset + ki;
                    if ((key_pos > query_pos and !allowsFutureAttention(attn_or_mask, total_sequence_len, query_pos, key_pos)) or !allowsPastAttention(sliding_window, query_pos, key_pos)) continue;

                    const k_ptr = K[(b * kv_seq_len + ki) * H_kv + kv_h * head_dim ..][0..head_dim];
                    const v_ptr = V[(b * kv_seq_len + ki) * H_kv + kv_h * head_dim ..][0..head_dim];
                    var score = linalg.dot(q_ptr, k_ptr) * scale;
                    if (bias) |bias_data| score += bias_data[h * q_seq_len * kv_seq_len + qi * kv_seq_len + ki];

                    const new_max = @max(running_max, score);
                    const prev_scale = @exp(running_max - new_max);
                    const score_scale = @exp(score - new_max);
                    if (prev_scale != 1.0) {
                        for (0..head_dim) |d| out_ptr[d] *= prev_scale;
                    }
                    linalg.axpy(score_scale, v_ptr, out_ptr);
                    running_sum = running_sum * prev_scale + score_scale;
                    running_max = new_max;
                }

                const inv_sum = 1.0 / running_sum;
                for (0..head_dim) |d| out_ptr[d] *= inv_sum;
            }
        }
    }
    return output;
}

// --- Flash Attention with tiled online softmax ---
//
// Instead of materializing the full [q_seq, kv_seq] score matrix, we tile Q
// into blocks of BLOCK_Q rows and stream over K/V in blocks of BLOCK_KV.
// For each Q-tile we maintain per-row running max and sum_exp accumulators
// (online softmax / Welford-style) and incrementally accumulate the output
// O_tile = softmax(Q_tile @ K^T / sqrt(d)) @ V without ever allocating more
// than [BLOCK_Q, BLOCK_KV] floats for the score tile.
//
// Memory: O(BLOCK_Q * BLOCK_KV + BLOCK_Q * head_dim) instead of O(seq^2).

/// Tiled flash causal attention supporting both MHA (num_heads == num_kv_heads)
/// and GQA (num_heads > num_kv_heads, evenly divisible).
pub fn flashCausalAttentionHost(
    allocator: std.mem.Allocator,
    Q: []const f32,
    K: []const f32,
    V: []const f32,
    bias: ?[]const f32,
    attn_or_mask: ?[]const u8,
    sliding_window: usize,
    batch: usize,
    q_seq_len: usize,
    kv_seq_len: usize,
    query_position_offset: usize,
    kv_position_offset: usize,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) ![]f32 {
    return linalg.flashCausalAttentionHost(
        allocator,
        Q,
        K,
        V,
        bias,
        attn_or_mask,
        sliding_window,
        batch,
        q_seq_len,
        kv_seq_len,
        query_position_offset,
        kv_position_offset,
        num_heads,
        num_kv_heads,
        head_dim,
    );
}

fn allowsFutureAttention(attn_or_mask: ?[]const u8, total_sequence_len: usize, query_pos: usize, key_pos: usize) bool {
    const mask = attn_or_mask orelse return false;
    if (query_pos >= total_sequence_len or key_pos >= total_sequence_len) return false;
    const idx = query_pos * total_sequence_len + key_pos;
    if (idx >= mask.len) return false;
    return mask[idx] != 0;
}

fn allowsPastAttention(sliding_window: usize, query_pos: usize, key_pos: usize) bool {
    if (key_pos > query_pos) return false;
    if (sliding_window == 0) return true;
    return query_pos - key_pos < sliding_window;
}

pub fn gqaCausalAttentionNaiveHost(
    allocator: std.mem.Allocator,
    Q: []const f32,
    K: []const f32,
    V: []const f32,
    batch: usize,
    seq_len: usize,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) ![]f32 {
    const H_q = std.math.mul(usize, num_heads, head_dim) catch return error.InvalidAttentionShape;
    const H_kv = std.math.mul(usize, num_kv_heads, head_dim) catch return error.InvalidAttentionShape;
    if (Q.len != batch * seq_len * H_q) return error.InvalidAttentionShape;
    if (K.len != batch * seq_len * H_kv) return error.InvalidAttentionShape;
    if (V.len != batch * seq_len * H_kv) return error.InvalidAttentionShape;
    if (num_heads % num_kv_heads != 0) return error.InvalidAttentionShape;

    const output = try allocator.alloc(f32, Q.len);
    errdefer allocator.free(output);
    @memset(output, 0.0);

    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));
    const heads_per_group = num_heads / num_kv_heads;
    var score_row = try allocator.alloc(f32, seq_len);
    defer allocator.free(score_row);

    for (0..batch) |b| {
        for (0..num_heads) |h| {
            const kv_h = h / heads_per_group;
            for (0..seq_len) |qi| {
                const q_base = (b * seq_len + qi) * H_q + h * head_dim;

                var row_max: f32 = -std.math.inf(f32);
                for (0..seq_len) |ki| {
                    if (ki > qi) {
                        score_row[ki] = -std.math.inf(f32);
                    } else {
                        const k_base = (b * seq_len + ki) * H_kv + kv_h * head_dim;
                        var d: f32 = 0.0;
                        for (0..head_dim) |dd| d += Q[q_base + dd] * K[k_base + dd];
                        score_row[ki] = d * scale;
                        if (score_row[ki] > row_max) row_max = score_row[ki];
                    }
                }

                var sum_exp: f32 = 0.0;
                for (0..seq_len) |ki| {
                    if (score_row[ki] == -std.math.inf(f32)) {
                        score_row[ki] = 0.0;
                    } else {
                        score_row[ki] = @exp(score_row[ki] - row_max);
                        sum_exp += score_row[ki];
                    }
                }
                if (sum_exp > 0.0) {
                    const inv_sum = 1.0 / sum_exp;
                    for (0..seq_len) |ki| score_row[ki] *= inv_sum;
                }

                const out_base = (b * seq_len + qi) * H_q + h * head_dim;
                for (0..seq_len) |vi| {
                    const w = score_row[vi];
                    if (w == 0.0) continue;
                    const v_base = (b * seq_len + vi) * H_kv + kv_h * head_dim;
                    for (0..head_dim) |dd| {
                        output[out_base + dd] += w * V[v_base + dd];
                    }
                }
            }
        }
    }

    return output;
}

fn gqaPagedAttentionOp(ctx: *anyopaque, q_ct: CT, k_ct: CT, v_ct: CT, attn_bias_ct: ?CT, attention: AttentionContext, batch: usize, num_heads: usize, num_kv_heads: usize, head_dim: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const Q = getData(q_ct);
    const K = getData(k_ct);
    const V = getData(v_ct);
    const bias: ?[]f32 = if (attn_bias_ct) |b| getData(b) else null;

    if (attention.kv_batch) |kv_batch| {
        if (attention.attn_or_mask != null) return error.AttentionOrMaskBatchUnsupported;
        if (kv_batch.len != batch) return error.InvalidPagedKvBatch;

        // Check if this is a mixed batch (per-item overrides present).
        const is_mixed = kv_batch[0].per_item_query_len != null;

        if (is_mixed) {
            // Mixed prefill+decode batch: each item has its own query_sequence_len.
            // Tokens are packed with padding to attention.query_sequence_len (the max).
            const max_q_rows = attention.query_sequence_len;
            const H_q = num_heads * head_dim;
            const H_kv = num_kv_heads * head_dim;
            const q_span = max_q_rows * H_q;
            const kv_span = max_q_rows * H_kv;
            const output = try self.allocator.alloc(f32, batch * q_span);
            errdefer self.allocator.free(output);
            @memset(output, 0.0);

            for (0..batch) |b| {
                const view = kv_batch[b];
                const item_q_len = view.per_item_query_len orelse attention.query_sequence_len;
                const item_total_len = view.per_item_total_len orelse attention.total_sequence_len;
                const item_kv_len = view.per_item_kv_len orelse attention.kv_sequence_len;
                const item_kv_pos_offset = view.per_item_kv_position_offset orelse attention.kv_position_offset;

                const item_attention: AttentionContext = .{
                    .mode = view.per_item_mode orelse attention.mode,
                    .total_sequence_len = item_total_len,
                    .query_sequence_len = item_q_len,
                    .kv_sequence_len = item_kv_len,
                    .kv_position_offset = item_kv_pos_offset,
                    .sliding_window = attention.sliding_window,
                    .kv_cache = view.kv_cache,
                    .kv_manager = view.kv_manager,
                    .kv_storage = view.kv_storage,
                    .kv_batch = null,
                    .layer_index = attention.layer_index,
                    .skip_kv_write = attention.skip_kv_write,
                    .attention_sink = attention.attention_sink,
                };

                // Slice this item's Q/K/V from the padded layout.
                const item_q_span = item_q_len * H_q;
                const item_kv_span = item_q_len * H_kv;
                const q_slice = Q[b * q_span ..][0..item_q_span];
                const k_slice = K[b * kv_span ..][0..item_kv_span];
                const v_slice = V[b * kv_span ..][0..item_kv_span];

                if (!attention.skip_kv_write)
                    try view.kv_manager.writeLayerKvSuffix(view.kv_cache.sequence_id, attention.layer_index, item_kv_len, item_q_len, k_slice, v_slice);
                const item_ct = try gqaPagedAttentionDirect(self, view.kv_manager, attention.layer_index, q_slice, bias, item_attention, num_heads, num_kv_heads, head_dim);
                defer freeTensor(self, item_ct);
                const item = getData(item_ct);
                @memcpy(output[b * q_span ..][0..item_q_span], item);
            }

            return self.makeBuf(output, true);
        }

        // Uniform batch: all items share the same sequence dimensions.
        const q_rows = attention.query_sequence_len;
        const H_q = num_heads * head_dim;
        const H_kv = num_kv_heads * head_dim;
        const q_span = q_rows * H_q;
        const kv_span = q_rows * H_kv;
        const output = try self.allocator.alloc(f32, batch * q_span);
        errdefer self.allocator.free(output);

        for (0..batch) |b| {
            const view = kv_batch[b];
            var item_attention = attention;
            item_attention.kv_batch = null;
            item_attention.kv_cache = view.kv_cache;
            item_attention.kv_manager = view.kv_manager;

            const q_slice = Q[b * q_span ..][0..q_span];
            const k_slice = K[b * kv_span ..][0..kv_span];
            const v_slice = V[b * kv_span ..][0..kv_span];

            if (!attention.skip_kv_write)
                try view.kv_manager.writeLayerKvSuffix(view.kv_cache.sequence_id, attention.layer_index, attention.kv_sequence_len, attention.query_sequence_len, k_slice, v_slice);
            const item_ct = try gqaPagedAttentionDirect(self, view.kv_manager, attention.layer_index, q_slice, bias, item_attention, num_heads, num_kv_heads, head_dim);
            defer freeTensor(self, item_ct);
            const item = getData(item_ct);
            @memcpy(output[b * q_span ..][0..q_span], item);
        }

        return self.makeBuf(output, true);
    }

    const sink_scores = try attentionSinkScores(attention.attention_sink, num_heads);
    if (batch > 1) {
        return gqaAttentionSlices(self, Q, K, V, bias, attention.attn_or_mask, attention.sliding_window, sink_scores, attention.total_sequence_len, batch, attention.query_sequence_len, attention.kv_sequence_len, attention.total_sequence_len - attention.query_sequence_len, attention.kv_position_offset, num_heads, num_kv_heads, head_dim);
    }

    const manager = attention.kv_manager orelse return gqaAttentionSlices(self, Q, K, V, bias, attention.attn_or_mask, attention.sliding_window, sink_scores, attention.total_sequence_len, batch, attention.query_sequence_len, attention.kv_sequence_len, attention.total_sequence_len - attention.query_sequence_len, attention.kv_position_offset, num_heads, num_kv_heads, head_dim);
    const kv = attention.kv_cache orelse return gqaAttentionSlices(self, Q, K, V, bias, attention.attn_or_mask, attention.sliding_window, sink_scores, attention.total_sequence_len, batch, attention.query_sequence_len, attention.kv_sequence_len, attention.total_sequence_len - attention.query_sequence_len, attention.kv_position_offset, num_heads, num_kv_heads, head_dim);

    if (!attention.skip_kv_write)
        try manager.writeLayerKvSuffix(kv.sequence_id, attention.layer_index, attention.kv_sequence_len, attention.query_sequence_len, K, V);
    _ = attention.mode;
    return gqaPagedAttentionDirect(self, manager, attention.layer_index, Q, bias, attention, num_heads, num_kv_heads, head_dim);
}

fn gqaPagedAttentionDirect(
    self: *NativeCompute,
    manager: *runtime.kv.manager.KvManager,
    layer_index: usize,
    Q: []const f32,
    bias: ?[]const f32,
    attention: AttentionContext,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) !CT {
    const kv = attention.kv_cache orelse return error.InvalidPagedKvState;
    const block_ids = if (kv.logical_blocks) |blocks|
        blocks
    else blk: {
        const table = manager.blockTable(kv.sequence_id) orelse return error.InvalidSequenceId;
        break :blk table.blocks.items;
    };
    const pool = manager.getPoolMut(kv.pool_id) orelse return error.InvalidPoolId;
    if (pool.config.dtype == .polar4 or pool.config.dtype == .turbo3) {
        return gqaPagedAttentionDirectTurboQuant(self, pool, block_ids, layer_index, Q, bias, attention, num_heads, num_kv_heads, head_dim);
    }

    const q_seq_len = attention.query_sequence_len;
    const kv_seq_len = attention.kv_sequence_len;
    const query_position_offset = attention.total_sequence_len - q_seq_len;
    const kv_position_offset = attention.kv_position_offset;
    const H_q = num_heads * head_dim;
    const heads_per_group = num_heads / num_kv_heads;
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));
    const sink_scores = try attentionSinkScores(attention.attention_sink, num_heads);
    const output = try self.allocator.alloc(f32, q_seq_len * H_q);
    errdefer self.allocator.free(output);
    @memset(output, 0.0);

    for (0..num_heads) |h| {
        const kv_h = h / heads_per_group;
        for (0..q_seq_len) |qi| {
            const q_ptr = Q[qi * H_q + h * head_dim ..].ptr;
            const out_ptr = output[qi * H_q + h * head_dim ..].ptr;
            var running_max = if (sink_scores) |scores| scores[h] else -std.math.inf(f32);
            var running_sum: f32 = if (sink_scores != null) 1.0 else 0.0;

            for (0..kv_seq_len) |token_idx| {
                const block_idx = token_idx / pool.config.page_size_tokens;
                const token_offset = token_idx % pool.config.page_size_tokens;
                if (block_idx >= block_ids.len) return error.InvalidPagedKvState;
                const block_id = block_ids[block_idx];
                const row = try pool.readToken(block_id, layer_index, token_offset);
                const k_ptr = row.k[kv_h * head_dim ..].ptr;
                const v_ptr = row.v[kv_h * head_dim ..].ptr;

                const query_pos = query_position_offset + qi;
                const key_pos = kv_position_offset + token_idx;
                if ((key_pos > query_pos and !allowsFutureAttention(attention.attn_or_mask, attention.total_sequence_len, query_pos, key_pos)) or !allowsPastAttention(attention.sliding_window, query_pos, key_pos)) continue;

                var score = linalg.dot(q_ptr[0..head_dim], k_ptr[0..head_dim]) * scale;
                if (bias) |bias_data| {
                    score += bias_data[h * q_seq_len * kv_seq_len + qi * kv_seq_len + key_pos];
                }

                const new_max = @max(running_max, score);
                const prev_scale: f32 = if (running_sum == 0.0) 0.0 else @exp(running_max - new_max);
                const score_scale = @exp(score - new_max);
                if (prev_scale != 1.0) {
                    for (0..head_dim) |d| out_ptr[d] *= prev_scale;
                }
                linalg.axpy(score_scale, v_ptr[0..head_dim], out_ptr[0..head_dim]);
                running_sum = running_sum * prev_scale + score_scale;
                running_max = new_max;
            }

            if (running_sum != 0.0) {
                const inv_sum = 1.0 / running_sum;
                for (0..head_dim) |d| out_ptr[d] *= inv_sum;
            }
        }
    }

    return self.makeBuf(output, true);
}

fn gqaPagedAttentionDirectTurboQuant(
    self: *NativeCompute,
    pool: *runtime.kv.storage.KvStorage,
    block_ids: []const runtime.kv.block.KvBlockId,
    layer_index: usize,
    Q: []const f32,
    bias: ?[]const f32,
    attention: AttentionContext,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) !CT {
    if (pool.config.num_kv_heads != num_kv_heads or pool.config.head_dim != head_dim) return error.InvalidPagedKvState;

    const q_seq_len = attention.query_sequence_len;
    const kv_seq_len = attention.kv_sequence_len;
    const query_position_offset = attention.total_sequence_len - q_seq_len;
    const kv_position_offset = attention.kv_position_offset;
    const H_q = num_heads * head_dim;
    const heads_per_group = num_heads / num_kv_heads;
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));
    const sink_scores = try attentionSinkScores(attention.attention_sink, num_heads);
    const output = try self.allocator.alloc(f32, q_seq_len * H_q);
    errdefer self.allocator.free(output);
    @memset(output, 0.0);

    for (0..num_heads) |h| {
        const kv_h = h / heads_per_group;
        for (0..q_seq_len) |qi| {
            const q_slice = Q[qi * H_q + h * head_dim ..][0..head_dim];
            var turbo3_projected_query: [runtime.kv.turboquant.turbo3_residual_bits_per_head]f32 = undefined;
            if (pool.config.dtype == .turbo3) {
                try runtime.kv.turboquant.projectTurbo3ResidualQuery(q_slice, &turbo3_projected_query, @intCast(head_dim), kv_h);
            }
            const out_ptr = output[qi * H_q + h * head_dim ..].ptr;
            var running_max = if (sink_scores) |scores| scores[h] else -std.math.inf(f32);
            var running_sum: f32 = if (sink_scores != null) 1.0 else 0.0;

            for (0..kv_seq_len) |token_idx| {
                const block_idx = token_idx / pool.config.page_size_tokens;
                const token_offset = token_idx % pool.config.page_size_tokens;
                if (block_idx >= block_ids.len) return error.InvalidPagedKvState;
                const block_id = block_ids[block_idx];

                const query_pos = query_position_offset + qi;
                const key_pos = kv_position_offset + token_idx;
                if ((key_pos > query_pos and !allowsFutureAttention(attention.attn_or_mask, attention.total_sequence_len, query_pos, key_pos)) or !allowsPastAttention(attention.sliding_window, query_pos, key_pos)) continue;

                const encoded = try pool.readEncodedToken(block_id, layer_index, token_offset);
                const v_row = try pool.readValueToken(block_id, layer_index, token_offset);
                const v_ptr = v_row[kv_h * head_dim ..].ptr;

                var score = switch (pool.config.dtype) {
                    .polar4 => try runtime.kv.turboquant.dotPolar4KeyFast(q_slice, encoded.k_bytes, @intCast(num_kv_heads), @intCast(head_dim), kv_h),
                    .turbo3 => blk: {
                        const base_bytes = runtime.kv.turboquant.turbo3KeyBytes(@intCast(num_kv_heads), @intCast(head_dim));
                        const residual_bytes = runtime.kv.turboquant.turbo3ResidualBytes(@intCast(num_kv_heads), @intCast(head_dim));
                        const base_score = try runtime.kv.turboquant.dotTurbo3KeyFast(q_slice, encoded.k_bytes[0..base_bytes], @intCast(num_kv_heads), @intCast(head_dim), kv_h);
                        const residual_score = try runtime.kv.turboquant.dotTurbo3ProjectedResidualSketch(&turbo3_projected_query, encoded.k_bytes[base_bytes..][0..residual_bytes], @intCast(num_kv_heads), @intCast(head_dim), kv_h);
                        break :blk base_score + runtime.kv.turboquant.turbo3_residual_default_scale * residual_score;
                    },
                    else => unreachable,
                };
                score *= scale;
                if (bias) |bias_data| {
                    score += bias_data[h * q_seq_len * kv_seq_len + qi * kv_seq_len + key_pos];
                }

                const new_max = @max(running_max, score);
                const prev_scale: f32 = if (running_sum == 0.0) 0.0 else @exp(running_max - new_max);
                const score_scale = @exp(score - new_max);
                if (prev_scale != 1.0) {
                    for (0..head_dim) |d| out_ptr[d] *= prev_scale;
                }
                linalg.axpy(score_scale, v_ptr[0..head_dim], out_ptr[0..head_dim]);
                running_sum = running_sum * prev_scale + score_scale;
                running_max = new_max;
            }

            if (running_sum != 0.0) {
                const inv_sum = 1.0 / running_sum;
                for (0..head_dim) |d| out_ptr[d] *= inv_sum;
            }
        }
    }

    return self.makeBuf(output, true);
}

// ── Primitive ops for training ─────────────────────────────────────────

/// Binary op helper that handles implicit trailing-dimension broadcasting.
/// When one operand is shorter and evenly divides the longer, it repeats cyclically.
fn primBinaryBroadcast(allocator: std.mem.Allocator, a_data: []const f32, b_data: []const f32, comptime op: enum { sub, div, add_prim, mul_prim, lt }) ![]f32 {
    const big = if (a_data.len >= b_data.len) a_data else b_data;
    const small = if (a_data.len >= b_data.len) b_data else a_data;
    const a_is_big = a_data.len >= b_data.len;
    if (small.len == 0 and big.len != 0) return error.ShapeMismatch;
    const output = try allocator.alloc(f32, big.len);

    if (small.len == big.len) {
        // Same size — fast path.
        for (big, small, 0..) |va, vb, i| {
            const a_val = if (a_is_big) va else vb;
            const b_val = if (a_is_big) vb else va;
            output[i] = switch (op) {
                .sub => a_val - b_val,
                .div => a_val / b_val,
                .add_prim => a_val + b_val,
                .mul_prim => a_val * b_val,
                .lt => if (a_val < b_val) @as(f32, 1.0) else @as(f32, 0.0),
            };
        }
    } else {
        // Broadcast: small repeats over trailing dim.
        for (0..big.len) |i| {
            const bi = i % small.len;
            const a_val = if (a_is_big) big[i] else small[bi];
            const b_val = if (a_is_big) small[bi] else big[i];
            output[i] = switch (op) {
                .sub => a_val - b_val,
                .div => a_val / b_val,
                .add_prim => a_val + b_val,
                .mul_prim => a_val * b_val,
                .lt => if (a_val < b_val) @as(f32, 1.0) else @as(f32, 0.0),
            };
        }
    }
    return output;
}

fn subtractOp(ctx: *anyopaque, a: CT, b: CT) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(a) != null and integerSource(b) != null) return integerBinaryOp(self, a, b, .subtract);
    if (try applyShapeAwareBinaryOp(self, a, b, .sub)) |result| {
        return result;
    }
    const a_view = try denseTensorView(self, a);
    defer a_view.deinit(self.allocator);
    const b_view = try denseTensorView(self, b);
    defer b_view.deinit(self.allocator);
    const output = try primBinaryBroadcast(self.allocator, a_view.data, b_view.data, .sub);
    const result = try self.makeOwnedBuf(output);
    errdefer freeTensor(self, result);
    return propagateLogicalShapeFromBinaryOperands(self, result, a, b);
}

fn divideOp(ctx: *anyopaque, a: CT, b: CT) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (try applyShapeAwareBinaryOp(self, a, b, .div)) |result| {
        return result;
    }
    const a_view = try denseTensorView(self, a);
    defer a_view.deinit(self.allocator);
    const b_view = try denseTensorView(self, b);
    defer b_view.deinit(self.allocator);
    const output = try primBinaryBroadcast(self.allocator, a_view.data, b_view.data, .div);
    const result = try self.makeOwnedBuf(output);
    errdefer freeTensor(self, result);
    return propagateLogicalShapeFromBinaryOperands(self, result, a, b);
}

fn negateOp(ctx: *anyopaque, input: CT) anyerror!CT {
    return primUnaryOp(.negate, ctx, input);
}

/// Allocating, consuming and planned primitives share one vector/scalar loop.
fn primitiveUnaryInto(comptime op: ops.kernel_descriptor.Unary, input: []const f32, output: []f32) void {
    if (op == .negate) {
        var i: usize = 0;
        while (i + VEC_LEN <= input.len) : (i += VEC_LEN) {
            const values: F32xN = input[i..][0..VEC_LEN].*;
            output[i..][0..VEC_LEN].* = -values;
        }
        while (i < input.len) : (i += 1) output[i] = -input[i];
        return;
    }
    for (input, output) |value, *target| {
        target.* = switch (op) {
            .sqrt => @sqrt(value),
            .rsqrt => 1.0 / @sqrt(value),
            .exp => @exp(value),
            .log => @log(value),
            .sin => @sin(value),
            .cos => @cos(value),
            .tanh => std.math.tanh(value),
            .abs => @abs(value),
            .erf => blk: {
                const x = @abs(value);
                const t = 1.0 / (1.0 + 0.3275911 * x);
                const poly = t * (0.254829592 + t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429))));
                const result = 1.0 - poly * @exp(-x * x);
                break :blk if (value >= 0) result else -result;
            },
            .negate => unreachable,
            else => @compileError("activation uses its existing specialized implementation"),
        };
    }
}

fn primUnaryOp(comptime op: ops.kernel_descriptor.Unary, ctx: *anyopaque, input: CT) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const data = getData(input);
    var owned_output = try OwnedDenseOutput.alloc(self, data.len);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    primitiveUnaryInto(op, data, output);
    return owned_output.intoLike(input);
}

fn primSqrtOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.sqrt, ctx, a);
}
fn primRsqrtOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.rsqrt, ctx, a);
}
fn primExpOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.exp, ctx, a);
}
fn primLogOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.log, ctx, a);
}
fn primSinOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.sin, ctx, a);
}
fn primCosOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.cos, ctx, a);
}
fn primTanhOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.tanh, ctx, a);
}
fn primAbsOp(ctx: *anyopaque, a: CT) anyerror!CT {
    return primUnaryOp(.abs, ctx, a);
}

fn primErfOp(ctx: *anyopaque, input: CT) anyerror!CT {
    return primUnaryOp(.erf, ctx, input);
}

fn lessThanOp(ctx: *anyopaque, a: CT, b: CT) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(a) != null or integerSource(b) != null) return exactLessThan(self, a, b);
    if (try applyShapeAwareBinaryOp(self, a, b, .lt)) |result| {
        return result;
    }
    const a_view = try denseTensorView(self, a);
    defer a_view.deinit(self.allocator);
    const b_view = try denseTensorView(self, b);
    defer b_view.deinit(self.allocator);
    const a_data = a_view.data;
    const b_data = b_view.data;
    const output = try primBinaryBroadcast(self.allocator, a_data, b_data, .lt);
    const result = try self.makeOwnedBuf(output);
    errdefer freeTensor(self, result);
    return propagateLogicalShapeFromBinaryOperands(self, result, a, b);
}

fn whereSelectOp(ctx: *anyopaque, cond: CT, on_true: CT, on_false: CT) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(cond) != null or integerSource(on_true) != null or integerSource(on_false) != null) return exactWhereSelect(self, cond, on_true, on_false);
    var c_shape_symbolic_buf: [8]i64 = undefined;
    var t_shape_symbolic_buf: [8]i64 = undefined;
    var f_shape_symbolic_buf: [8]i64 = undefined;
    const c_shape_symbolic = symbolicShapeForBroadcast(cond, &c_shape_symbolic_buf);
    const t_shape_symbolic = symbolicShapeForBroadcast(on_true, &t_shape_symbolic_buf);
    const f_shape_symbolic = symbolicShapeForBroadcast(on_false, &f_shape_symbolic_buf);
    const c_len = toBuf(cond).data.len;
    const t_len = toBuf(on_true).data.len;
    const f_len = toBuf(on_false).data.len;

    var loose_out_shape_buf: [8]i64 = undefined;
    const loose_out_rank = computeBroadcastShape3Loose(c_shape_symbolic, t_shape_symbolic, f_shape_symbolic, &loose_out_shape_buf) orelse blk: {
        break :blk importedFlattenedBroadcastFallbackShape(
            c_shape_symbolic,
            t_shape_symbolic,
            f_shape_symbolic,
            c_len,
            t_len,
            f_len,
            &loose_out_shape_buf,
        ) orelse {
            std.log.warn("where_select broadcast mismatch cond_shape={any} true_shape={any} false_shape={any} cond_len={d} true_len={d} false_len={d}", .{
                c_shape_symbolic,
                t_shape_symbolic,
                f_shape_symbolic,
                c_len,
                t_len,
                f_len,
            });
            return error.ShapeMismatch;
        };
    };
    const loose_out_shape = loose_out_shape_buf[0..loose_out_rank];

    var c_shape_buf: [8]i64 = undefined;
    var t_shape_buf: [8]i64 = undefined;
    var f_shape_buf: [8]i64 = undefined;
    var c_shape = concretizeBroadcastOperandShape(c_shape_symbolic, c_len, loose_out_shape, &c_shape_buf);
    var t_shape = concretizeBroadcastOperandShape(t_shape_symbolic, t_len, loose_out_shape, &t_shape_buf);
    var f_shape = concretizeBroadcastOperandShape(f_shape_symbolic, f_len, loose_out_shape, &f_shape_buf);
    var c_coerced_shape_buf: [8]i64 = undefined;
    var t_coerced_shape_buf: [8]i64 = undefined;
    var f_coerced_shape_buf: [8]i64 = undefined;
    c_shape = coerceImportedFlattenedBroadcastOperandShape(c_shape_symbolic, c_shape, c_len, loose_out_shape, &c_coerced_shape_buf);
    t_shape = coerceImportedFlattenedBroadcastOperandShape(t_shape_symbolic, t_shape, t_len, loose_out_shape, &t_coerced_shape_buf);
    f_shape = coerceImportedFlattenedBroadcastOperandShape(f_shape_symbolic, f_shape, f_len, loose_out_shape, &f_coerced_shape_buf);

    var out_shape_buf: [8]i64 = undefined;
    const out_rank = computeBroadcastShape3(c_shape, t_shape, f_shape, &out_shape_buf) orelse {
        std.log.warn("where_select broadcast mismatch cond_shape={any} true_shape={any} false_shape={any} cond_len={d} true_len={d} false_len={d}", .{
            c_shape,
            t_shape,
            f_shape,
            toBuf(cond).data.len,
            toBuf(on_true).data.len,
            toBuf(on_false).data.len,
        });
        return error.ShapeMismatch;
    };
    const out_shape = out_shape_buf[0..out_rank];
    const out_len = if (out_rank == 0) @as(usize, 1) else shapeNumel(out_shape);
    var c_strides_scratch: [8]usize = undefined;
    var t_strides_scratch: [8]usize = undefined;
    var f_strides_scratch: [8]usize = undefined;
    const c_plan = denseReadPlanForResolvedShape(cond, c_shape, c_strides_scratch[0..c_shape.len]);
    const t_plan = denseReadPlanForResolvedShape(on_true, t_shape, t_strides_scratch[0..t_shape.len]);
    const f_plan = denseReadPlanForResolvedShape(on_false, f_shape, f_strides_scratch[0..f_shape.len]);
    const c_access = classifyBroadcastReadAccess(c_plan, c_shape, out_shape);
    const t_access = classifyBroadcastReadAccess(t_plan, t_shape, out_shape);
    const f_access = classifyBroadcastReadAccess(f_plan, f_shape, out_shape);
    const c_repeat = if (c_access.mode == .general) detectBroadcastBlockRepeatPlan(c_plan, c_shape, out_shape) else null;
    const t_repeat = if (t_access.mode == .general) detectBroadcastBlockRepeatPlan(t_plan, t_shape, out_shape) else null;
    const f_repeat = if (f_access.mode == .general) detectBroadcastBlockRepeatPlan(f_plan, f_shape, out_shape) else null;
    const loop_repeat = c_repeat orelse t_repeat orelse f_repeat;
    if (loop_repeat) |repeat_plan| {
        if ((c_access.mode != .general or (c_repeat != null and sameBroadcastBlockRepeatLoop(repeat_plan, c_repeat.?))) and
            (t_access.mode != .general or (t_repeat != null and sameBroadcastBlockRepeatLoop(repeat_plan, t_repeat.?))) and
            (f_access.mode != .general or (f_repeat != null and sameBroadcastBlockRepeatLoop(repeat_plan, f_repeat.?))))
        {
            maybeLogLargeTensor("where_select", out_len, out_shape);
            const output = try self.allocator.alloc(f32, out_len);
            var raw_output: ?[]f32 = output;
            errdefer if (raw_output) |raw| self.allocator.free(raw);
            var out_offset: usize = 0;
            for (0..repeat_plan.prefix_count) |prefix_idx| {
                const cond_block = if (c_repeat) |plan|
                    c_plan.data[plan.base_offset + prefix_idx * plan.block_len ..][0..plan.block_len]
                else
                    empty_f32[0..];
                const true_block = if (t_repeat) |plan|
                    t_plan.data[plan.base_offset + prefix_idx * plan.block_len ..][0..plan.block_len]
                else
                    empty_f32[0..];
                const false_block = if (f_repeat) |plan|
                    f_plan.data[plan.base_offset + prefix_idx * plan.block_len ..][0..plan.block_len]
                else
                    empty_f32[0..];
                for (0..repeat_plan.repeat_count) |_| {
                    for (0..repeat_plan.block_len) |j| {
                        const i = out_offset + j;
                        const c_val = switch (c_access.mode) {
                            .scalar => c_plan.data[c_plan.base_offset],
                            .linear => c_plan.data[c_plan.base_offset + i],
                            .general => cond_block[j],
                        };
                        const t_val = switch (t_access.mode) {
                            .scalar => t_plan.data[t_plan.base_offset],
                            .linear => t_plan.data[t_plan.base_offset + i],
                            .general => true_block[j],
                        };
                        const f_val = switch (f_access.mode) {
                            .scalar => f_plan.data[f_plan.base_offset],
                            .linear => f_plan.data[f_plan.base_offset + i],
                            .general => false_block[j],
                        };
                        output[i] = if (c_val != 0.0) t_val else f_val;
                    }
                    out_offset += repeat_plan.block_len;
                }
            }
            if (out_offset != out_len) return error.ShapeMismatch;
            const result = try self.makeBuf(output, true);
            raw_output = null;
            errdefer freeTensor(self, result);
            return self.withLogicalShape(result, out_shape);
        }
    }
    if (c_access.mode == .general and t_access.mode != .general and f_access.mode != .general) {
        if (detectBroadcastBlockRepeatPlan(c_plan, c_shape, out_shape)) |repeat_plan| {
            maybeLogLargeTensor("where_select", out_len, out_shape);
            const output = try self.allocator.alloc(f32, out_len);
            var raw_output: ?[]f32 = output;
            errdefer if (raw_output) |raw| self.allocator.free(raw);
            var out_offset: usize = 0;
            for (0..repeat_plan.prefix_count) |prefix_idx| {
                const cond_base = repeat_plan.base_offset + prefix_idx * repeat_plan.block_len;
                const cond_block = c_plan.data[cond_base .. cond_base + repeat_plan.block_len];
                for (0..repeat_plan.repeat_count) |_| {
                    for (cond_block, 0..) |cond_val, j| {
                        const i = out_offset + j;
                        const t_offset = switch (t_access.mode) {
                            .scalar => t_plan.base_offset,
                            .linear => t_plan.base_offset + i,
                            .general => unreachable,
                        };
                        const f_offset = switch (f_access.mode) {
                            .scalar => f_plan.base_offset,
                            .linear => f_plan.base_offset + i,
                            .general => unreachable,
                        };
                        if (t_offset >= t_plan.data.len or f_offset >= f_plan.data.len) return error.ShapeMismatch;
                        output[i] = if (cond_val != 0.0) t_plan.data[t_offset] else f_plan.data[f_offset];
                    }
                    out_offset += repeat_plan.block_len;
                }
            }
            if (out_offset != out_len) return error.ShapeMismatch;
            const result = try self.makeBuf(output, true);
            raw_output = null;
            errdefer freeTensor(self, result);
            return self.withLogicalShape(result, out_shape);
        }
    }
    var c_stepper = if (c_access.mode == .general) BroadcastStepper.init(out_shape, c_shape, c_plan.strides) else null;
    var t_stepper = if (t_access.mode == .general) BroadcastStepper.init(out_shape, t_shape, t_plan.strides) else null;
    var f_stepper = if (f_access.mode == .general) BroadcastStepper.init(out_shape, f_shape, f_plan.strides) else null;

    maybeLogLargeTensor("where_select", out_len, out_shape);
    const output = try self.allocator.alloc(f32, out_len);
    var raw_output: ?[]f32 = output;
    errdefer if (raw_output) |raw| self.allocator.free(raw);
    for (0..out_len) |i| {
        const c_offset = switch (c_access.mode) {
            .scalar => c_plan.base_offset,
            .linear => c_plan.base_offset + i,
            .general => c_plan.base_offset + c_stepper.?.currentOffset(),
        };
        const t_offset = switch (t_access.mode) {
            .scalar => t_plan.base_offset,
            .linear => t_plan.base_offset + i,
            .general => t_plan.base_offset + t_stepper.?.currentOffset(),
        };
        const f_offset = switch (f_access.mode) {
            .scalar => f_plan.base_offset,
            .linear => f_plan.base_offset + i,
            .general => f_plan.base_offset + f_stepper.?.currentOffset(),
        };
        if (c_offset >= c_plan.data.len or t_offset >= t_plan.data.len or f_offset >= f_plan.data.len) {
            std.log.warn("where_select offset mismatch i={d} out_shape={any} cond_shape={any} true_shape={any} false_shape={any} offsets={d}/{d}/{d} lens={d}/{d}/{d} modes={s}/{s}/{s}", .{
                i,
                out_shape,
                c_shape,
                t_shape,
                f_shape,
                c_offset,
                t_offset,
                f_offset,
                c_plan.data.len,
                t_plan.data.len,
                f_plan.data.len,
                @tagName(c_access.mode),
                @tagName(t_access.mode),
                @tagName(f_access.mode),
            });
            return error.ShapeMismatch;
        }
        output[i] = if (c_plan.data[c_offset] != 0.0) t_plan.data[t_offset] else f_plan.data[f_offset];
        if (c_stepper) |*stepper| stepper.advance();
        if (t_stepper) |*stepper| stepper.advance();
        if (f_stepper) |*stepper| stepper.advance();
    }
    const result = try self.makeBuf(output, true);
    raw_output = null;
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, out_shape);
}

/// Compute strides for a given shape (row-major).
fn computeStrides(shape: []const i64, out: []usize) void {
    if (shape.len == 0) return;
    out[shape.len - 1] = 1;
    var j: usize = shape.len - 1;
    while (j > 0) {
        j -= 1;
        out[j] = out[j + 1] * @as(usize, @intCast(shape[j + 1]));
    }
}

/// Compute total number of elements from shape.
fn shapeNumel(shape: []const i64) usize {
    var n: usize = 1;
    for (shape) |d| n *= @as(usize, @intCast(d));
    return n;
}

fn safeShapeNumel(shape: []const i64) ?usize {
    var n: usize = 1;
    for (shape) |d| {
        if (d <= 0) return null;
        n = std.math.mul(usize, n, @intCast(d)) catch return null;
    }
    return n;
}

fn allShapeDimsPositive(shape: []const i64) bool {
    for (shape) |d| {
        if (d <= 0) return false;
    }
    return true;
}

fn allRepeatedBlocksEqual(data: []const f32, block_len: usize) bool {
    if (block_len == 0 or data.len == 0 or data.len % block_len != 0) return false;
    const repeats = data.len / block_len;
    if (repeats <= 1) return false;
    for (1..repeats) |repeat_idx| {
        const start = repeat_idx * block_len;
        if (!std.mem.eql(f32, data[0..block_len], data[start..][0..block_len])) {
            return false;
        }
    }
    return true;
}

fn resolveDeclaredBatchShape(shape: []const i64, batch_axes: []const u8, batch_size: usize) ?[8]i64 {
    if (batch_axes.len == 0 or batch_axes.len > 8) return null;

    var resolved: [8]i64 = undefined;
    var known_product: usize = 1;
    var unknown_index: ?usize = null;

    for (batch_axes, 0..) |axis, out_i| {
        if (axis >= shape.len) return null;
        const dim = shape[axis];
        if (dim > 0) {
            resolved[out_i] = dim;
            known_product = std.math.mul(usize, known_product, @intCast(dim)) catch return null;
            continue;
        }
        if (unknown_index != null) return null;
        unknown_index = out_i;
        resolved[out_i] = dim;
    }

    if (unknown_index) |idx| {
        if (known_product == 0 or batch_size % known_product != 0) return null;
        const inferred = batch_size / known_product;
        if (inferred == 0) return null;
        resolved[idx] = @intCast(inferred);
        return resolved;
    }

    if (known_product != batch_size) return null;
    return resolved;
}

fn primReduceSumOp(ctx: *anyopaque, input: CT, axes: []const u8, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    return primReduceOp(self, input, axes, input_shape, .sum);
}

fn primReduceMaxOp(ctx: *anyopaque, input: CT, axes: []const u8, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    return primReduceOp(self, input, axes, input_shape, .max);
}

fn primReduceMeanOp(ctx: *anyopaque, input: CT, axes: []const u8, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    return primReduceOp(self, input, axes, input_shape, .mean);
}

fn primArgMaxOp(ctx: *anyopaque, input: CT, axis: u8, keepdims: bool, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const in_data = getData(input);
    const effective_input_shape = storedOrDeclaredShape(input, input_shape);
    if (axis >= effective_input_shape.len) return error.ShapeMismatch;

    var resolved_input_shape_buf: [8]i64 = undefined;
    const resolved_input_shape = if (resolveShapeFromDataLen(effective_input_shape, in_data.len)) |resolved| blk: {
        resolved_input_shape_buf = resolved;
        break :blk resolved_input_shape_buf[0..effective_input_shape.len];
    } else blk: {
        for (0..effective_input_shape.len) |i| {
            resolved_input_shape_buf[i] = if (effective_input_shape[i] > 0) effective_input_shape[i] else 1;
        }
        break :blk resolved_input_shape_buf[0..effective_input_shape.len];
    };

    const rank = resolved_input_shape.len;
    const axis_dim_i64 = resolved_input_shape[axis];
    if (axis_dim_i64 <= 0) return error.ShapeMismatch;
    const axis_dim: usize = @intCast(axis_dim_i64);

    var outer: usize = 1;
    for (resolved_input_shape[0..axis]) |dim| outer *= @intCast(dim);
    var inner: usize = 1;
    for (resolved_input_shape[axis + 1 ..]) |dim| inner *= @intCast(dim);

    const out_numel = if (rank == 0) @as(usize, 1) else outer * inner;
    const output = try self.allocator.alloc(f32, out_numel);
    var raw_output: ?[]f32 = output;
    errdefer if (raw_output) |raw| self.allocator.free(raw);

    for (0..outer) |outer_idx| {
        for (0..inner) |inner_idx| {
            const base = outer_idx * axis_dim * inner + inner_idx;
            var best_idx: usize = 0;
            var best_val = in_data[base];
            for (1..axis_dim) |axis_idx| {
                const candidate = in_data[base + axis_idx * inner];
                if (candidate > best_val) {
                    best_val = candidate;
                    best_idx = axis_idx;
                }
            }
            output[outer_idx * inner + inner_idx] = @floatFromInt(best_idx);
        }
    }

    const result = try self.makeBuf(output, true);
    raw_output = null;
    errdefer freeTensor(self, result);
    var out_shape_buf: [8]i64 = undefined;
    var out_rank: usize = 0;
    if (keepdims) {
        out_rank = rank;
        for (0..rank) |i| out_shape_buf[i] = if (i == axis) 1 else resolved_input_shape[i];
    } else {
        for (0..rank) |i| {
            if (i == axis) continue;
            out_shape_buf[out_rank] = resolved_input_shape[i];
            out_rank += 1;
        }
    }
    return self.withLogicalShape(result, out_shape_buf[0..out_rank]);
}

fn reduceInto(input: []const f32, output: []f32, geometry: ops.kernel_descriptor.ReductionGeometry, mode: ops.kernel_descriptor.ReductionMode) void {
    switch (mode) {
        .sum, .mean => @memset(output, 0.0),
        .max => @memset(output, -std.math.inf(f32)),
    }
    var input_strides: [8]usize = undefined;
    var output_strides: [8]usize = undefined;
    var in_stride: usize = 1;
    var out_stride: usize = 1;
    var axis: usize = geometry.rank;
    while (axis > 0) {
        axis -= 1;
        input_strides[axis] = in_stride;
        output_strides[axis] = out_stride;
        in_stride *= geometry.dims[axis];
        out_stride *= @intCast(geometry.output_dims[axis]);
    }
    // Preserve the existing flat input traversal and accumulation order.
    for (input, 0..) |value, flat| {
        var remaining = flat;
        var output_index: usize = 0;
        for (0..geometry.rank) |d| {
            const coord = remaining / input_strides[d];
            remaining %= input_strides[d];
            if (!geometry.reduced(d)) output_index += coord * output_strides[d];
        }
        switch (mode) {
            .sum, .mean => output[output_index] += value,
            .max => output[output_index] = @max(output[output_index], value),
        }
    }
    if (mode == .mean) {
        const scale: f32 = 1.0 / @as(f32, @floatFromInt(geometry.reduce_count));
        for (output) |*value| value.* *= scale;
    }
}

fn primReduceOp(self: *NativeCompute, input: CT, axes: []const u8, input_shape: []const i64, mode: ops.kernel_descriptor.ReductionMode) anyerror!CT {
    const buf = toBuf(input);
    var materialized_input: ?[]f32 = null;
    defer if (materialized_input) |owned| self.allocator.free(owned);

    const in_data = blk: {
        if (buf.data.len != 0) break :blk getData(input);
        if (buf.source_tensor != null or buf.quantized_storage != null or buf.lazy_entry != null) {
            const dense = try toFloat32Op(self, input, self.allocator);
            materialized_input = dense;
            break :blk dense;
        }
        break :blk getData(input);
    };
    const effective_input_shape = storedOrDeclaredShape(input, input_shape);
    var resolved_input_shape_buf: [8]i64 = undefined;
    const resolved_input_shape = if (resolveShapeFromDataLen(effective_input_shape, in_data.len)) |resolved| blk: {
        resolved_input_shape_buf = resolved;
        break :blk resolved_input_shape_buf[0..effective_input_shape.len];
    } else blk: {
        for (0..effective_input_shape.len) |i| {
            resolved_input_shape_buf[i] = if (effective_input_shape[i] > 0) effective_input_shape[i] else 1;
        }
        break :blk resolved_input_shape_buf[0..effective_input_shape.len];
    };
    const geometry = try ops.kernel_descriptor.ReductionGeometry.init(resolved_input_shape, axes);
    if (in_data.len != geometry.input_count) return error.InvalidTensorShape;
    var owned_output = try OwnedDenseOutput.alloc(self, geometry.output_count);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    reduceInto(in_data, output, geometry, mode);

    return owned_output.intoShape(geometry.output_dims[0..geometry.rank]);
}

fn primReshapeOp(ctx: *anyopaque, input: CT, new_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(input)) |source| {
        if (new_shape.len > 8) return error.UnsupportedShape;
        const stored = tensorStoredShape(input) orelse return error.InvalidTensorShape;
        const count = integerTensorCount(source) catch return error.InvalidTensorShape;
        if (typedShapeNumel(new_shape)) |exact| {
            if (exact == count) return copyIntegerTensorWithShape(self, source, new_shape);
        }
        const resolved = inferReshapeShapeWithNumel(stored, new_shape, count) orelse return error.ShapeMismatch;
        return copyIntegerTensorWithShape(self, source, resolved[0..new_shape.len]);
    }
    const in_data = getData(input);
    if (tensorStoredShape(input)) |shape| {
        if (inferReshapeShapeWithNumel(shape, new_shape, in_data.len)) |resolved| {
            return aliasDenseBufWithShape(self, input, resolved[0..new_shape.len]) catch blk: {
                const in_view = try denseWeightView(self, input);
                defer in_view.deinit(self.allocator);
                const output = try self.allocator.dupe(f32, in_view.data);
                const result = try self.makeOwnedBuf(output);
                errdefer freeTensor(self, result);
                break :blk self.withLogicalShape(result, resolved[0..new_shape.len]);
            };
        }
    }
    if (tensorShapeOp(ctx, input, self.allocator)) |runtime_shape| {
        defer self.allocator.free(runtime_shape);
        if (inferReshapeShapeWithNumel(runtime_shape, new_shape, in_data.len)) |resolved| {
            return aliasDenseBufWithShape(self, input, resolved[0..new_shape.len]) catch blk: {
                const in_view = try denseWeightView(self, input);
                defer in_view.deinit(self.allocator);
                const output = try self.allocator.dupe(f32, in_view.data);
                const result = try self.makeOwnedBuf(output);
                errdefer freeTensor(self, result);
                break :blk self.withLogicalShape(result, resolved[0..new_shape.len]);
            };
        }
    } else |_| {}
    if (resolveShapeFromDataLen(new_shape, in_data.len)) |resolved| {
        return aliasDenseBufWithShape(self, input, resolved[0..new_shape.len]) catch blk: {
            const dense_view = try denseWeightView(self, input);
            defer dense_view.deinit(self.allocator);
            const output = try self.allocator.dupe(f32, dense_view.data);
            const result = try self.makeOwnedBuf(output);
            errdefer freeTensor(self, result);
            break :blk self.withLogicalShape(result, resolved[0..new_shape.len]);
        };
    }
    const stored_input_shape = tensorStoredShape(input);
    var symbolic_shape: [8]i64 = undefined;
    for (new_shape, 0..) |dim, i| {
        if (dim != 0) {
            symbolic_shape[i] = dim;
            continue;
        }
        if (stored_input_shape) |shape| {
            if (i < shape.len and shape[i] > 0) {
                symbolic_shape[i] = shape[i];
                continue;
            }
        }
        symbolic_shape[i] = -1;
    }
    return aliasDenseBufWithShape(self, input, symbolic_shape[0..new_shape.len]) catch blk: {
        const dense_view = try denseWeightView(self, input);
        defer dense_view.deinit(self.allocator);
        const output = try self.allocator.dupe(f32, dense_view.data);
        const result = try self.makeOwnedBuf(output);
        errdefer freeTensor(self, result);
        break :blk self.withLogicalShape(result, symbolic_shape[0..new_shape.len]);
    };
}

fn primTransposeOp(ctx: *anyopaque, input: CT, perm: []const u8, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const input_buf = toBuf(input);
    const effective_input_shape = storedOrDeclaredShape(input, input_shape);
    var resolved_shape_buf: [8]i64 = undefined;
    var resolved_perm_buf: [8]u8 = undefined;
    var should_attach_shape = true;
    const resolved_shape: []const i64, const resolved_perm: []const u8, const rank: usize = blk: {
        if (safeShapeNumel(effective_input_shape)) |numel| {
            _ = numel;
            break :blk .{ effective_input_shape, perm, effective_input_shape.len };
        }
        if (resolveShapeFromDataLen(effective_input_shape, input_buf.data.len)) |resolved| {
            for (0..effective_input_shape.len) |i| resolved_shape_buf[i] = resolved[i];
            break :blk .{ resolved_shape_buf[0..effective_input_shape.len], perm, effective_input_shape.len };
        }
        if (resolveShapeFromTensorMetadata(input, effective_input_shape, input_buf.data.len)) |resolved| {
            for (0..effective_input_shape.len) |i| resolved_shape_buf[i] = resolved[i];
            break :blk .{ resolved_shape_buf[0..effective_input_shape.len], perm, effective_input_shape.len };
        }
        const plan = collapseLeadingDynamicDimsForTranspose(effective_input_shape, perm, input_buf.data.len) orelse {
            std.log.warn("transpose symbolic shape unsupported shape={any} perm={any} len={d}", .{
                effective_input_shape,
                perm,
                input_buf.data.len,
            });
            return error.UnsupportedShape;
        };
        should_attach_shape = false;
        for (0..plan.rank) |i| {
            resolved_shape_buf[i] = plan.shape[i];
            resolved_perm_buf[i] = plan.perm[i];
        }
        break :blk .{ resolved_shape_buf[0..plan.rank], resolved_perm_buf[0..plan.rank], plan.rank };
    };
    // Compute output shape and strides.
    var out_shape: [8]i64 = undefined;
    kernel_geometry.transposeShape(resolved_shape, resolved_perm, &out_shape) catch return error.UnsupportedShape;
    const numel = if (safeShapeNumel(out_shape[0..rank])) |resolved_numel| resolved_numel else input_buf.data.len;

    var in_strides: [8]usize = undefined;
    const logical_in_strides = logicalStridesOrContiguous(input, resolved_shape, in_strides[0..rank]);
    var out_strides: [8]usize = undefined;
    computeStrides(out_shape[0..rank], out_strides[0..rank]);

    if (canAliasTranspose(resolved_shape, resolved_perm)) {
        const result = try aliasDenseBufWithShape(self, input, out_shape[0..rank]);
        if (!should_attach_shape) return result;
        return result;
    }

    var view_strides: [8]usize = undefined;
    for (0..rank) |d| view_strides[d] = logical_in_strides[resolved_perm[d]];
    if (makeDenseViewAlias(self, input, out_shape[0..rank], view_strides[0..rank], 0)) |view| {
        if (!should_attach_shape) return view;
        return view;
    } else |err| switch (err) {
        error.UnsupportedTensorType => {},
        else => return err,
    }

    const in_view = try denseWeightView(self, input);
    defer in_view.deinit(self.allocator);
    const in_data = in_view.data;
    var owned_output = try OwnedDenseOutput.alloc(self, numel);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    for (0..numel) |flat_out| {
        // Decompose output flat index.
        var remaining = flat_out;
        var flat_in: usize = 0;
        for (0..rank) |d| {
            const coord = remaining / out_strides[d];
            remaining %= out_strides[d];
            flat_in += coord * logical_in_strides[resolved_perm[d]];
        }
        output[flat_out] = in_data[flat_in];
    }
    const result = try owned_output.intoResult();
    if (!should_attach_shape) return result;
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, out_shape[0..rank]);
}

fn primBroadcastInDimOp(ctx: *anyopaque, input: CT, target_shape: []const i64, broadcast_axes: []const u8, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(input)) |source| {
        const plan = try @import("binary_broadcast.zig").SelectionPlan.broadcast(storedOrDeclaredShape(input, input_shape), target_shape, broadcast_axes);
        if (plan.counts[0] != try integerTensorCount(source)) return error.ShapeMismatch;
        if (plan.identity()) return copyIntegerTensorWithShape(self, source, plan.shape[0..plan.rank]);
        const width = source.dtype.byteSize();
        const bytes = try self.allocator.alloc(u8, try std.math.mul(usize, plan.count, width));
        var transferred = false;
        defer if (!transferred) self.allocator.free(bytes);
        for (0..plan.count) |i| {
            const offset = plan.offsets(i)[0] * width;
            @memcpy(bytes[i * width ..][0..width], source.data[offset..][0..width]);
        }
        transferred = true;
        return takeOwnedIntegerBytes(self, bytes, source.dtype, plan.shape[0..plan.rank]);
    }
    const input_buf = toBuf(input);
    const out_rank = target_shape.len;
    const effective_input_shape = storedOrDeclaredShape(input, input_shape);
    const in_rank = effective_input_shape.len;
    const axis_count = @min(broadcast_axes.len, in_rank);
    var resolved_input_shape_buf: [8]i64 = undefined;
    const resolved_input_shape = if (resolveShapeFromDataLen(effective_input_shape, input_buf.data.len)) |resolved| blk: {
        resolved_input_shape_buf = resolved;
        break :blk resolved_input_shape_buf[0..in_rank];
    } else blk: {
        for (0..in_rank) |i| {
            resolved_input_shape_buf[i] = if (effective_input_shape[i] > 0) effective_input_shape[i] else 1;
        }
        break :blk resolved_input_shape_buf[0..in_rank];
    };
    var resolved_target_shape: [8]i64 = undefined;
    const out_numel = try kernel_geometry.resolveBroadcastOutput(resolved_input_shape, target_shape, broadcast_axes, &resolved_target_shape);
    if (axis_count == in_rank and out_numel == shapeNumel(resolved_input_shape)) {
        var can_alias = true;
        for (0..out_rank) |d| {
            var mapped_input_dim: ?usize = null;
            for (broadcast_axes[0..axis_count], 0..) |ax, in_d| {
                if (ax == d) {
                    mapped_input_dim = in_d;
                    break;
                }
            }
            if (mapped_input_dim) |in_d| {
                if (resolved_target_shape[d] != resolved_input_shape[in_d]) {
                    can_alias = false;
                    break;
                }
            } else if (resolved_target_shape[d] != 1) {
                can_alias = false;
                break;
            }
        }
        if (can_alias) {
            if (aliasDenseBufWithShape(self, input, resolved_target_shape[0..out_rank])) |aliased| {
                return aliased;
            } else |_| {}
        }
    }
    if (axis_count == 0) {
        const view = try denseTensorView(self, input);
        defer view.deinit(self.allocator);
        if (view.data.len > 0) {
            const in_data = view.data;
            const output = try self.allocator.alloc(f32, out_numel);
            var raw_output: ?[]f32 = output;
            errdefer if (raw_output) |raw| self.allocator.free(raw);
            @memset(output, in_data[0]);
            const result = try self.makeBuf(output, true);
            raw_output = null;
            errdefer freeTensor(self, result);
            return self.withLogicalShape(result, resolved_target_shape[0..out_rank]);
        }
        return error.UnsupportedShape;
    }

    var out_strides: [8]usize = undefined;
    computeStrides(resolved_target_shape[0..out_rank], out_strides[0..out_rank]);

    // Build input strides in the output coordinate system.
    var in_strides: [8]usize = undefined;
    const logical_in_strides = logicalStridesOrContiguous(input, resolved_input_shape, in_strides[0..in_rank]);

    if (toBuf(input).lazy_entry == null and toBuf(input).quantized_storage == null and toBuf(input).source_tensor == null and toBuf(input).owned_quantized_storage == null and toBuf(input).owned_source_tensor == null) {
        var view_strides: [8]usize = undefined;
        var can_view = true;
        for (0..out_rank) |d| {
            view_strides[d] = 0;
            for (broadcast_axes[0..axis_count], 0..) |ax, in_d| {
                if (ax == d) {
                    if (resolved_input_shape[in_d] > 1 and resolved_input_shape[in_d] != resolved_target_shape[d]) {
                        can_view = false;
                    }
                    view_strides[d] = if (resolved_input_shape[in_d] > 1) logical_in_strides[in_d] else 0;
                    break;
                }
            }
        }
        if (can_view) {
            if (makeDenseViewAlias(self, input, resolved_target_shape[0..out_rank], view_strides[0..out_rank], 0)) |view| {
                return view;
            } else |err| switch (err) {
                error.UnsupportedTensorType => {},
                else => return err,
            }
        }
    }

    const view = try denseTensorView(self, input);
    defer view.deinit(self.allocator);
    const in_data = view.data;
    // Materialization returns contiguous logical data, including source tensors.
    computeStrides(resolved_input_shape, in_strides[0..in_rank]);
    const output = try self.allocator.alloc(f32, out_numel);
    var raw_output: ?[]f32 = output;
    errdefer if (raw_output) |raw| self.allocator.free(raw);
    for (0..out_numel) |flat_out| {
        var remaining = flat_out;
        var flat_in: usize = 0;
        for (0..out_rank) |d| {
            const coord = remaining / out_strides[d];
            remaining %= out_strides[d];
            // Check if this output dim corresponds to an input dim.
            for (broadcast_axes[0..axis_count], 0..) |ax, in_d| {
                if (ax == d) {
                    // If the input dim is 1, broadcast (coord stays 0).
                    if (resolved_input_shape[in_d] > 1) {
                        const input_extent = @as(usize, @intCast(resolved_input_shape[in_d]));
                        const target_extent = @as(usize, @intCast(resolved_target_shape[d]));
                        const input_coord = if (target_extent == input_extent)
                            coord
                        else if (target_extent > input_extent and target_extent % input_extent == 0)
                            coord % input_extent
                        else
                            return error.ShapeMismatch;
                        flat_in += input_coord * in_strides[in_d];
                    }
                    break;
                }
            }
        }
        if (flat_in >= in_data.len) return error.ShapeMismatch;
        output[flat_out] = in_data[flat_in];
    }
    const result = try self.makeBuf(output, true);
    raw_output = null;
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, resolved_target_shape[0..out_rank]);
}

fn denseDotInto(lhs: []const f32, rhs: []const f32, output: []f32, plan: ops.kernel_descriptor.Dot) void {
    // Preserve NativeCompute's f64 accumulator and batch/row/column traversal.
    for (0..plan.batch_count) |batch| {
        const lhs_base = batch * plan.m * plan.k;
        const rhs_base = batch * plan.n * plan.k;
        const output_base = batch * plan.m * plan.n;
        for (0..plan.m) |row| for (0..plan.n) |column| {
            var acc: f64 = 0;
            for (0..plan.k) |inner| {
                const li = lhs_base + (if (plan.lhs_contract_last) row * plan.k + inner else inner * plan.m + row);
                const ri = rhs_base + (if (plan.rhs_contract_last) column * plan.k + inner else inner * plan.n + column);
                acc += @as(f64, lhs[li]) * @as(f64, rhs[ri]);
            }
            output[output_base + row * plan.n + column] = @floatCast(acc);
        };
    }
}

fn primDotGeneralOp(ctx: *anyopaque, lhs: CT, rhs: CT, lhs_shape: []const i64, rhs_shape: []const i64, lhs_contracting: []const u8, rhs_contracting: []const u8, lhs_batch: []const u8, rhs_batch: []const u8) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const lhs_buf = toBuf(lhs);
    const lhs_len = tensorLogicalElementCount(lhs, lhs_shape) orelse lhs_buf.data.len;
    var rhs_resolved_shape_buf: [8]i64 = undefined;
    var rhs_effective_shape = storedOrDeclaredShape(rhs, rhs_shape);
    var lhs_resolved_shape_buf: [8]i64 = undefined;
    var lhs_effective_shape = storedOrDeclaredShape(lhs, lhs_shape);
    if (lhs_contracting.len == 1 and rhs_contracting.len == 1) {
        if (resolveDotOperandShapeFromPeer(
            lhs_len,
            lhs_shape,
            tensorStoredShape(lhs),
            rhs_effective_shape,
            lhs_contracting[0],
            lhs_batch,
            rhs_contracting[0],
            rhs_batch,
        )) |resolved| {
            lhs_resolved_shape_buf = resolved;
            lhs_effective_shape = lhs_resolved_shape_buf[0..lhs_shape.len];
        }

        const rhs_len = if (toBuf(rhs).source_tensor) |tensor| tensor.elementCount() else toBuf(rhs).data.len;
        if (resolveDotOperandShapeFromPeer(
            rhs_len,
            rhs_shape,
            tensorStoredShape(rhs),
            lhs_effective_shape,
            rhs_contracting[0],
            rhs_batch,
            lhs_contracting[0],
            lhs_batch,
        )) |resolved| {
            rhs_resolved_shape_buf = resolved;
            rhs_effective_shape = rhs_resolved_shape_buf[0..rhs_shape.len];
        }
    }

    if (lhs_batch.len == 0 and rhs_batch.len == 0 and lhs_contracting.len == 0 and rhs_contracting.len == 0) {
        if (lhs_effective_shape.len == 1 and rhs_effective_shape.len == 1) {
            const lhs_view = try denseWeightView(self, lhs);
            defer lhs_view.deinit(self.allocator);
            const rhs_view = try denseWeightView(self, rhs);
            defer rhs_view.deinit(self.allocator);

            const m = positiveShapeDim(lhs_effective_shape, 0) catch lhs_view.data.len;
            const n = positiveShapeDim(rhs_effective_shape, 0) catch rhs_view.data.len;
            if (m != lhs_view.data.len or n != rhs_view.data.len) return error.ShapeMismatch;

            const output = try self.allocator.alloc(f32, m * n);
            var raw_output: ?[]f32 = output;
            errdefer if (raw_output) |raw| self.allocator.free(raw);
            for (0..m) |i| {
                for (0..n) |j| {
                    output[i * n + j] = lhs_view.data[i] * rhs_view.data[j];
                }
            }

            const result = try self.makeBuf(output, true);
            raw_output = null;
            errdefer freeTensor(self, result);
            const out_shape = [_]i64{ @intCast(m), @intCast(n) };
            return self.withLogicalShape(result, &out_shape);
        }
    }

    // Handle common case: 2D matmul (no batch dims, one contracting dim each).
    if (lhs_batch.len == 0 and lhs_contracting.len == 1 and rhs_contracting.len == 1) {
        const lhs_rank = lhs_effective_shape.len;
        const rhs_rank = rhs_effective_shape.len;

        if (lhs_rank == 2 and rhs_rank == 2) {
            const lc = lhs_contracting[0];
            const rc = rhs_contracting[0];
            const k = positiveShapeDim(lhs_effective_shape, lc) catch try positiveShapeDim(rhs_effective_shape, rc);

            // Determine M, N based on which dims are contracting.
            const m = positiveShapeDim(lhs_effective_shape, 1 - lc) catch try resolveSymbolicDimFromElementCount(lhs_len, k);
            const rhs_buf = toBuf(rhs);
            const rhs_len = if (rhs_buf.source_tensor != null) 0 else rhs_buf.data.len;
            const n = positiveShapeDim(rhs_effective_shape, 1 - rc) catch try resolveSymbolicDimFromElementCount(rhs_len, k);

            const output = try self.allocator.alloc(f32, m * n);
            var raw_output: ?[]f32 = output;
            errdefer if (raw_output) |raw| self.allocator.free(raw);
            @memset(output, 0.0);

            if (lc == 1 and rc == 0) {
                if (lhs_buf.view_strides == null and rhs_buf.view_strides == null) {
                    const lhs_data = getData(lhs);
                    if (toBuf(rhs).source_tensor) |rhs_tensor| {
                        try matmulRhsSourceTensorChunked(self, lhs_data, rhs_tensor, output, m, k, n);
                        const result = try self.makeBuf(output, true);
                        raw_output = null;
                        errdefer freeTensor(self, result);
                        return self.withLogicalShape(result, &.{ @intCast(m), @intCast(n) });
                    }
                }
            }

            if (lhs_buf.view_strides == null and rhs_buf.view_strides == null and rhs_buf.source_tensor == null) {
                const lhs_data = getData(lhs);
                const rhs_dense = getData(rhs);
                denseDotInto(lhs_data, rhs_dense, output, .{ .batch_count = 1, .m = m, .n = n, .k = k, .lhs_contract_last = lc == 1, .rhs_contract_last = rc == 1 });
                const result = try self.makeBuf(output, true);
                raw_output = null;
                errdefer freeTensor(self, result);
                const out_shape = [_]i64{ @intCast(m), @intCast(n) };
                return self.withLogicalShape(result, &out_shape);
            }

            const lhs_base = lhs_buf.data;
            const rhs_base = if (rhs_buf.source_tensor == null) rhs_buf.data else &.{};
            var lhs_stride_scratch: [8]usize = undefined;
            var rhs_stride_scratch: [8]usize = undefined;
            const lhs_strides = logicalStridesOrContiguous(lhs, lhs_effective_shape, lhs_stride_scratch[0..lhs_effective_shape.len]);
            const rhs_strides = if (rhs_buf.source_tensor == null) logicalStridesOrContiguous(rhs, rhs_effective_shape, rhs_stride_scratch[0..rhs_effective_shape.len]) else &.{};

            if (rhs_buf.source_tensor) |rhs_tensor| {
                const rhs_view = try tensorF32View(self, rhs_tensor);
                defer rhs_view.deinit(self.allocator);
                for (0..m) |i| {
                    for (0..n) |j| {
                        var acc: f64 = 0.0;
                        for (0..k) |ki| {
                            const lhs_val = rank2TensorRead(lhs_base, lhs_strides, 1 - lc, lc, i, ki);
                            const rhs_val = if (rc == 0) rhs_view.data[ki * n + j] else rhs_view.data[j * k + ki];
                            acc += @as(f64, lhs_val) * @as(f64, rhs_val);
                        }
                        output[i * n + j] = @floatCast(acc);
                    }
                }
            } else {
                for (0..m) |i| {
                    for (0..n) |j| {
                        var acc: f64 = 0.0;
                        for (0..k) |ki| {
                            const lhs_val = rank2TensorRead(lhs_base, lhs_strides, 1 - lc, lc, i, ki);
                            const rhs_val = rank2TensorRead(rhs_base, rhs_strides, rc, 1 - rc, ki, j);
                            acc += @as(f64, lhs_val) * @as(f64, rhs_val);
                        }
                        output[i * n + j] = @floatCast(acc);
                    }
                }
            }

            const result = try self.makeBuf(output, true);
            raw_output = null;
            errdefer freeTensor(self, result);
            const out_shape = [_]i64{ @intCast(m), @intCast(n) };
            return self.withLogicalShape(result, &out_shape);
        }
    }

    // Batched case: lhs_batch.len >= 1, 1 contracting dim.
    if (lhs_batch.len >= 1 and lhs_contracting.len == 1 and rhs_contracting.len == 1) {
        const lc = lhs_contracting[0];
        const rc = rhs_contracting[0];
        const k = positiveShapeDim(lhs_effective_shape, lc) catch try positiveShapeDim(rhs_effective_shape, rc);
        const lhs_has_batch = lhs_batch.len > 0;
        const rhs_has_batch = rhs_batch.len > 0;

        // Common ONNX linear case: lhs is rank>2 with batch attrs, rhs is a shared
        // rank-2 weight matrix. Flatten lhs leading rows and apply one GEMM.
        if (rhs_effective_shape.len == 2 and lc == lhs_effective_shape.len - 1 and rc == 0 and lhs_len % k == 0) {
            const rhs_k = positiveShapeDim(rhs_effective_shape, 0) catch return error.UnsupportedShape;
            const n = positiveShapeDim(rhs_effective_shape, 1) catch return error.UnsupportedShape;
            var effective_rows = lhs_len / k;
            var effective_k = k;
            var output_rank = lhs_effective_shape.len;
            var output_shape = copyShape(lhs_effective_shape);
            output_shape[output_rank - 1] = @intCast(n);
            if (lhs_shape.len == output_rank) {
                for (0..output_rank - 1) |i| {
                    if (lhs_shape[i] <= 0) output_shape[i] = lhs_shape[i];
                }
            }

            if (rhs_k != k and lhs_effective_shape.len >= 2 and lhs_len % rhs_k == 0) {
                var suffix_product: usize = 1;
                var suffix_start: ?usize = null;
                var idx = lhs_effective_shape.len;
                while (idx > 0) {
                    idx -= 1;
                    const dim = positiveShapeDim(lhs_effective_shape, idx) catch break;
                    suffix_product = std.math.mul(usize, suffix_product, dim) catch break;
                    if (suffix_product == rhs_k) {
                        suffix_start = idx;
                        break;
                    }
                    if (suffix_product > rhs_k) break;
                }
                if (suffix_start) |start| {
                    effective_k = rhs_k;
                    effective_rows = lhs_len / effective_k;
                    output_rank = start + 1;
                    for (0..start) |i| {
                        output_shape[i] = if (i < lhs_shape.len and lhs_shape[i] <= 0) lhs_shape[i] else lhs_effective_shape[i];
                    }
                    output_shape[start] = @intCast(n);
                }
            }

            const output = try self.allocator.alloc(f32, effective_rows * n);
            var raw_output: ?[]f32 = output;
            errdefer if (raw_output) |raw| self.allocator.free(raw);
            @memset(output, 0.0);
            const lhs_buf2 = toBuf(lhs);
            const rhs_buf2 = toBuf(rhs);
            if (lhs_buf2.view_strides == null and rhs_buf2.view_strides == null and rhs_buf2.source_tensor != null) {
                const lhs_data = getData(lhs);
                matmulRhsSourceTensorChunked(self, lhs_data, rhs_buf2.source_tensor.?, output, effective_rows, effective_k, n) catch |err| switch (err) {
                    error.ShapeMismatch => {
                        const rhs_view = try tensorF32View(self, rhs_buf2.source_tensor.?);
                        defer rhs_view.deinit(self.allocator);
                        if (rhs_buf2.source_tensor.?.shape.len != 2) return err;

                        const rhs_rows: usize = @intCast(rhs_buf2.source_tensor.?.shape[0]);
                        const rhs_cols: usize = @intCast(rhs_buf2.source_tensor.?.shape[1]);
                        if (rhs_rows == n and rhs_cols == effective_k and rhs_view.data.len == n * effective_k) {
                            try self.dispatchSgemmTransB(effective_rows, n, effective_k, 1.0, lhs_data, rhs_view.data, 0.0, output);
                        } else if (rhs_rows == effective_k and rhs_cols == n and rhs_view.data.len == effective_k * n) {
                            try self.dispatchSgemm(effective_rows, n, effective_k, 1.0, lhs_data, rhs_view.data, 0.0, output);
                        } else {
                            return err;
                        }
                    },
                    else => return err,
                };
            } else if (lhs_buf2.view_strides == null and rhs_buf2.view_strides == null) {
                const lhs_data = getData(lhs);
                const rhs_data = getData(rhs);
                if (rhs_data.len != effective_k * n) return error.UnsupportedShape;
                try self.dispatchSgemm(effective_rows, n, effective_k, 1.0, lhs_data, rhs_data, 0.0, output);
            } else {
                var lhs_stride_scratch: [8]usize = undefined;
                const lhs_strides = logicalStridesOrContiguous(lhs, lhs_effective_shape, lhs_stride_scratch[0..lhs_effective_shape.len]);
                if (rhs_buf2.source_tensor) |rhs_tensor| {
                    const rhs_view = try tensorF32View(self, rhs_tensor);
                    defer rhs_view.deinit(self.allocator);
                    for (0..effective_rows) |row| {
                        for (0..n) |col| {
                            var acc: f64 = 0.0;
                            for (0..effective_k) |ki| {
                                const lhs_val = try flattenedPrefixLastDimRead(lhs_effective_shape, lhs_strides, lhs_buf2.data, row, ki);
                                acc += @as(f64, lhs_val) * @as(f64, rhs_view.data[ki * n + col]);
                            }
                            output[row * n + col] = @floatCast(acc);
                        }
                    }
                } else {
                    const rhs_data = getData(rhs);
                    for (0..effective_rows) |row| {
                        for (0..n) |col| {
                            var acc: f64 = 0.0;
                            for (0..effective_k) |ki| {
                                const lhs_val = try flattenedPrefixLastDimRead(lhs_effective_shape, lhs_strides, lhs_buf2.data, row, ki);
                                acc += @as(f64, lhs_val) * @as(f64, rhs_data[ki * n + col]);
                            }
                            output[row * n + col] = @floatCast(acc);
                        }
                    }
                }
            }
            const result = try self.makeBuf(output, true);
            raw_output = null;
            errdefer freeTensor(self, result);
            return self.withLogicalShape(result, output_shape[0..output_rank]);
        }

        const rhs_buf2 = toBuf(rhs);
        const rhs_view = if (rhs_buf2.view_strides != null or rhs_buf2.source_tensor != null) try denseWeightView(self, rhs) else null;
        defer if (rhs_view) |view| view.deinit(self.allocator);
        const rhs_raw_data = if (rhs_view) |view| view.data else rhs_buf2.data;

        // Find the non-batch, non-contracting dims.
        var lhs_free: ?usize = null;
        var lhs_free_axis: ?u8 = null;
        for (0..lhs_effective_shape.len) |d| {
            var is_batch = false;
            for (lhs_batch) |bd| {
                if (bd == d) {
                    is_batch = true;
                    break;
                }
            }
            if (!is_batch and d != lc) {
                lhs_free = positiveShapeDim(lhs_effective_shape, d) catch null;
                lhs_free_axis = @intCast(d);
                break;
            }
        }
        var rhs_free: ?usize = null;
        var rhs_free_axis: ?u8 = null;
        for (0..rhs_effective_shape.len) |d| {
            var is_batch = false;
            for (rhs_batch) |bd| {
                if (bd == d) {
                    is_batch = true;
                    break;
                }
            }
            if (!is_batch and d != rc) {
                rhs_free = positiveShapeDim(rhs_effective_shape, d) catch null;
                rhs_free_axis = @intCast(d);
                break;
            }
        }

        var lhs_batch_shape_buf: [8]i64 = undefined;
        var rhs_batch_shape_buf: [8]i64 = undefined;
        var out_batch_shape_buf: [8]i64 = undefined;
        const lhs_batch_shape = blk: {
            for (lhs_batch, 0..) |bd, i| lhs_batch_shape_buf[i] = lhs_effective_shape[bd];
            break :blk lhs_batch_shape_buf[0..lhs_batch.len];
        };
        const rhs_batch_shape = blk: {
            for (rhs_batch, 0..) |bd, i| rhs_batch_shape_buf[i] = rhs_effective_shape[bd];
            break :blk rhs_batch_shape_buf[0..rhs_batch.len];
        };
        const symbolic_batch_dims =
            (lhs_has_batch and !allShapeDimsPositive(lhs_batch_shape)) or
            (rhs_has_batch and !allShapeDimsPositive(rhs_batch_shape));
        var flattened_batch_broadcast = false;
        const out_batch_shape = blk: {
            if (symbolic_batch_dims) break :blk &.{};
            if (lhs_has_batch and rhs_has_batch) {
                if (lhs_batch_shape.len != rhs_batch_shape.len) return error.UnsupportedShape;
                const lhs_batch_numel = safeShapeNumel(lhs_batch_shape) orelse return error.UnsupportedShape;
                const rhs_batch_numel = safeShapeNumel(rhs_batch_shape) orelse return error.UnsupportedShape;
                for (lhs_batch_shape, rhs_batch_shape, 0..) |ld, rd, i| {
                    if (ld == rd or ld == 1) {
                        out_batch_shape_buf[i] = rd;
                    } else if (rd == 1) {
                        out_batch_shape_buf[i] = ld;
                    } else if (lhs_batch_numel > rhs_batch_numel and lhs_batch_numel % rhs_batch_numel == 0) {
                        flattened_batch_broadcast = true;
                        for (lhs_batch_shape, 0..) |dim, j| out_batch_shape_buf[j] = dim;
                        break :blk out_batch_shape_buf[0..lhs_batch_shape.len];
                    } else if (rhs_batch_numel > lhs_batch_numel and rhs_batch_numel % lhs_batch_numel == 0) {
                        flattened_batch_broadcast = true;
                        for (rhs_batch_shape, 0..) |dim, j| out_batch_shape_buf[j] = dim;
                        break :blk out_batch_shape_buf[0..rhs_batch_shape.len];
                    } else {
                        return error.UnsupportedShape;
                    }
                }
                break :blk out_batch_shape_buf[0..lhs_batch_shape.len];
            }
            if (lhs_has_batch) {
                for (lhs_batch_shape, 0..) |dim, i| {
                    if (dim <= 0) return error.UnsupportedShape;
                    out_batch_shape_buf[i] = dim;
                }
                break :blk out_batch_shape_buf[0..lhs_batch_shape.len];
            }
            for (rhs_batch_shape, 0..) |dim, i| {
                if (dim <= 0) return error.UnsupportedShape;
                out_batch_shape_buf[i] = dim;
            }
            break :blk out_batch_shape_buf[0..rhs_batch_shape.len];
        };

        const lhs_symbolic_batch_factor: ?usize = blk: {
            if (!lhs_has_batch) break :blk 1;
            if (allShapeDimsPositive(lhs_batch_shape)) break :blk safeShapeNumel(lhs_batch_shape) orelse return error.UnsupportedShape;
            if (rhs_has_batch and rhs_batch_shape.len == lhs_batch_shape.len and allShapeDimsPositive(rhs_batch_shape)) {
                break :blk safeShapeNumel(rhs_batch_shape) orelse return error.UnsupportedShape;
            }
            break :blk null;
        };
        const rhs_symbolic_batch_factor: ?usize = blk: {
            if (!rhs_has_batch) break :blk 1;
            if (allShapeDimsPositive(rhs_batch_shape)) break :blk safeShapeNumel(rhs_batch_shape) orelse return error.UnsupportedShape;
            if (lhs_has_batch and lhs_batch_shape.len == rhs_batch_shape.len and allShapeDimsPositive(lhs_batch_shape)) {
                break :blk safeShapeNumel(lhs_batch_shape) orelse return error.UnsupportedShape;
            }
            break :blk null;
        };

        if (symbolic_batch_dims and
            ((lhs_has_batch and lhs_free == null and lhs_symbolic_batch_factor == null) or
                (rhs_has_batch and rhs_free == null and rhs_symbolic_batch_factor == null)))
        {
            std.log.warn("dot_general symbolic batch/free ambiguity lhs_shape={any} rhs_shape={any} lhs_len={d} rhs_len={d} lhs_batch={any} rhs_batch={any} lc={d} rc={d}", .{
                lhs_effective_shape,
                rhs_effective_shape,
                lhs_len,
                rhs_raw_data.len,
                lhs_batch,
                rhs_batch,
                lc,
                rc,
            });
            return error.UnsupportedShape;
        }

        const m = lhs_free orelse try resolveSymbolicDimFromElementCount(
            lhs_len,
            (if (lhs_has_batch and !symbolic_batch_dims)
                safeShapeNumel(lhs_batch_shape) orelse return error.UnsupportedShape
            else if (lhs_symbolic_batch_factor) |factor|
                factor
            else
                1) * k,
        );
        const n = rhs_free orelse try resolveSymbolicDimFromElementCount(
            rhs_raw_data.len,
            (if (rhs_has_batch and !symbolic_batch_dims)
                safeShapeNumel(rhs_batch_shape) orelse return error.UnsupportedShape
            else if (rhs_symbolic_batch_factor) |factor|
                factor
            else
                1) * k,
        );
        var lhs_batch_elems = blk: {
            if (!lhs_has_batch) break :blk 1;
            if (!symbolic_batch_dims) break :blk safeShapeNumel(lhs_batch_shape) orelse return error.UnsupportedShape;
            if (lhs_free != null) break :blk resolveSymbolicDimFromElementCount(lhs_len, m * k) catch if (lhs_symbolic_batch_factor) |factor| factor else return error.UnsupportedShape;
            if (lhs_symbolic_batch_factor) |factor| break :blk factor;
            break :blk resolveSymbolicDimFromElementCount(lhs_len, m * k) catch return error.UnsupportedShape;
        };
        var rhs_batch_elems = blk: {
            if (!rhs_has_batch) break :blk 1;
            if (!symbolic_batch_dims) break :blk safeShapeNumel(rhs_batch_shape) orelse return error.UnsupportedShape;
            if (rhs_free != null) break :blk resolveSymbolicDimFromElementCount(rhs_raw_data.len, k * n) catch if (rhs_symbolic_batch_factor) |factor| factor else return error.UnsupportedShape;
            if (rhs_symbolic_batch_factor) |factor| break :blk factor;
            break :blk resolveSymbolicDimFromElementCount(rhs_raw_data.len, k * n) catch return error.UnsupportedShape;
        };
        const lhs_buf2 = toBuf(lhs);
        const lhs_view = if (lhs_buf2.view_strides != null or lhs_buf2.source_tensor != null) try denseWeightView(self, lhs) else null;
        defer if (lhs_view) |view| view.deinit(self.allocator);
        const lhs_data = if (lhs_view) |view| view.data else lhs_buf2.data;
        var effective_rhs_raw_data = rhs_raw_data;
        if (symbolic_batch_dims and lhs_batch_elems != rhs_batch_elems) {
            const lhs_expected_rhs_len = lhs_batch_elems * k * n;
            if (lhs_expected_rhs_len > 0 and rhs_raw_data.len % lhs_expected_rhs_len == 0 and allRepeatedBlocksEqual(rhs_raw_data, lhs_expected_rhs_len)) {
                effective_rhs_raw_data = rhs_raw_data[0..lhs_expected_rhs_len];
                rhs_batch_elems = lhs_batch_elems;
            }
            const rhs_expected_lhs_len = rhs_batch_elems * m * k;
            if (rhs_expected_lhs_len > 0 and lhs_data.len % rhs_expected_lhs_len == 0 and allRepeatedBlocksEqual(lhs_data, rhs_expected_lhs_len)) {
                lhs_batch_elems = rhs_batch_elems;
            }
        }
        const batch_size = blk: {
            if (!symbolic_batch_dims) {
                break :blk if (out_batch_shape.len > 0)
                    safeShapeNumel(out_batch_shape) orelse return error.UnsupportedShape
                else
                    1;
            }
            if (lhs_batch_elems == rhs_batch_elems) break :blk lhs_batch_elems;
            if (lhs_batch_elems == 1) break :blk rhs_batch_elems;
            if (rhs_batch_elems == 1) break :blk lhs_batch_elems;
            if (lhs_batch_elems > rhs_batch_elems and lhs_batch_elems % rhs_batch_elems == 0) break :blk lhs_batch_elems;
            if (rhs_batch_elems > lhs_batch_elems and rhs_batch_elems % lhs_batch_elems == 0) break :blk rhs_batch_elems;
            return error.UnsupportedShape;
        };
        const expected_lhs_len = lhs_batch_elems * m * k;
        const expected_rhs_len = rhs_batch_elems * k * n;
        const rhs_data = blk: {
            if (effective_rhs_raw_data.len == expected_rhs_len) break :blk effective_rhs_raw_data;
            if (expected_rhs_len > 0 and effective_rhs_raw_data.len % expected_rhs_len == 0 and rhs_effective_shape.len > 0 and rhs_effective_shape[0] == 1) {
                if (allRepeatedBlocksEqual(effective_rhs_raw_data, expected_rhs_len)) {
                    break :blk effective_rhs_raw_data[0..expected_rhs_len];
                }
            }
            break :blk effective_rhs_raw_data;
        };
        if (lhs_data.len != expected_lhs_len) {
            std.log.warn("dot_general lhs size mismatch lhs_shape={any} rhs_shape={any} lhs_len={d} rhs_len={d} expected_lhs={d} expected_rhs={d} batch_size={d} m={d} n={d} k={d} lhs_free={?d} rhs_free={?d} lhs_batch={any} rhs_batch={any}", .{
                lhs_effective_shape,
                rhs_effective_shape,
                lhs_data.len,
                rhs_raw_data.len,
                expected_lhs_len,
                expected_rhs_len,
                batch_size,
                m,
                n,
                k,
                lhs_free,
                rhs_free,
                lhs_batch,
                rhs_batch,
            });
            return error.UnsupportedShape;
        }
        if (rhs_data.len != expected_rhs_len) {
            std.log.warn("dot_general rhs size mismatch lc={d} rc={d} lhs_shape={any} rhs_shape={any} lhs_declared={any} rhs_declared={any} lhs_stored={?any} rhs_stored={?any} lhs_len={d} rhs_len={d} expected_lhs={d} expected_rhs={d} batch_size={d} m={d} n={d} k={d} lhs_free={?d} rhs_free={?d} lhs_batch={any} rhs_batch={any}", .{
                lc,
                rc,
                lhs_effective_shape,
                rhs_effective_shape,
                lhs_shape,
                rhs_shape,
                tensorStoredShape(lhs),
                tensorStoredShape(rhs),
                lhs_data.len,
                rhs_raw_data.len,
                expected_lhs_len,
                expected_rhs_len,
                batch_size,
                m,
                n,
                k,
                lhs_free,
                rhs_free,
                lhs_batch,
                rhs_batch,
            });
            return error.UnsupportedShape;
        }
        const output_len = batch_size * m * n;
        maybeLogLargeTensor("dot_general", output_len, null);
        const output = try self.allocator.alloc(f32, output_len);
        var raw_output: ?[]f32 = output;
        errdefer if (raw_output) |raw| self.allocator.free(raw);
        @memset(output, 0.0);

        var out_batch_strides: [8]usize = undefined;
        if (!symbolic_batch_dims and out_batch_shape.len > 0) computeStrides(out_batch_shape, out_batch_strides[0..out_batch_shape.len]);
        var lhs_batch_strides: [8]usize = undefined;
        if (!symbolic_batch_dims and lhs_has_batch and lhs_batch_shape.len > 0) computeStrides(lhs_batch_shape, lhs_batch_strides[0..lhs_batch_shape.len]);
        var rhs_batch_strides: [8]usize = undefined;
        if (!symbolic_batch_dims and rhs_has_batch and rhs_batch_shape.len > 0) computeStrides(rhs_batch_shape, rhs_batch_strides[0..rhs_batch_shape.len]);
        if (symbolic_batch_dims or lhs_free_axis == null or rhs_free_axis == null) {
            for (0..batch_size) |b| {
                const lhs_batch_index = if (symbolic_batch_dims or flattened_batch_broadcast)
                    if (lhs_batch_elems == 1) 0 else b % lhs_batch_elems
                else if (lhs_has_batch and out_batch_shape.len > 0)
                    broadcastIndexForOutput(b, out_batch_shape, out_batch_strides[0..out_batch_shape.len], lhs_batch_shape, lhs_batch_strides[0..lhs_batch_shape.len])
                else
                    0;
                const rhs_batch_index = if (symbolic_batch_dims or flattened_batch_broadcast)
                    if (rhs_batch_elems == 1) 0 else b % rhs_batch_elems
                else if (rhs_has_batch and out_batch_shape.len > 0)
                    broadcastIndexForOutput(b, out_batch_shape, out_batch_strides[0..out_batch_shape.len], rhs_batch_shape, rhs_batch_strides[0..rhs_batch_shape.len])
                else
                    0;
                const lhs_off = if (lhs_has_batch) lhs_batch_index * m * k else 0;
                const rhs_off = if (rhs_has_batch) rhs_batch_index * k * n else 0;
                const out_off = b * m * n;
                try self.dispatchSgemm(m, n, k, 1.0, lhs_data[lhs_off..][0 .. m * k], rhs_data[rhs_off..][0 .. k * n], 0.0, output[out_off..][0 .. m * n]);
            }
        } else {
            var lhs_stride_scratch: [8]usize = undefined;
            var rhs_stride_scratch: [8]usize = undefined;
            const lhs_strides = logicalStridesOrContiguous(lhs, lhs_effective_shape, lhs_stride_scratch[0..lhs_effective_shape.len]);
            const rhs_strides = logicalStridesOrContiguous(rhs, rhs_effective_shape, rhs_stride_scratch[0..rhs_effective_shape.len]);

            for (0..batch_size) |b| {
                const lhs_batch_offset = if (lhs_has_batch and flattened_batch_broadcast)
                    broadcastTensorOffsetForOutputBatch(
                        if (lhs_batch_elems == 1) 0 else b % lhs_batch_elems,
                        lhs_batch_shape,
                        lhs_batch_strides[0..lhs_batch_shape.len],
                        lhs_batch_shape,
                        lhs_batch,
                        lhs_strides,
                    )
                else if (lhs_has_batch and out_batch_shape.len > 0)
                    broadcastTensorOffsetForOutputBatch(
                        b,
                        out_batch_shape,
                        out_batch_strides[0..out_batch_shape.len],
                        lhs_batch_shape,
                        lhs_batch,
                        lhs_strides,
                    )
                else
                    0;
                const rhs_batch_offset = if (rhs_has_batch and flattened_batch_broadcast)
                    broadcastTensorOffsetForOutputBatch(
                        if (rhs_batch_elems == 1) 0 else b % rhs_batch_elems,
                        rhs_batch_shape,
                        rhs_batch_strides[0..rhs_batch_shape.len],
                        rhs_batch_shape,
                        rhs_batch,
                        rhs_strides,
                    )
                else if (rhs_has_batch and out_batch_shape.len > 0)
                    broadcastTensorOffsetForOutputBatch(
                        b,
                        out_batch_shape,
                        out_batch_strides[0..out_batch_shape.len],
                        rhs_batch_shape,
                        rhs_batch,
                        rhs_strides,
                    )
                else
                    0;
                const out_off = b * m * n;
                for (0..m) |i| {
                    for (0..n) |j| {
                        var acc: f64 = 0.0;
                        for (0..k) |ki| {
                            const lhs_offset = lhs_batch_offset + i * lhs_strides[lhs_free_axis.?] + ki * lhs_strides[lc];
                            const rhs_offset = rhs_batch_offset + ki * rhs_strides[rc] + j * rhs_strides[rhs_free_axis.?];
                            if (lhs_offset >= lhs_data.len or rhs_offset >= rhs_data.len) return error.UnsupportedShape;
                            acc += @as(f64, lhs_data[lhs_offset]) * @as(f64, rhs_data[rhs_offset]);
                        }
                        output[out_off + i * n + j] = @floatCast(acc);
                    }
                }
            }
        }
        const result = try self.makeBuf(output, true);
        raw_output = null;
        errdefer freeTensor(self, result);
        var out_shape: [8]i64 = undefined;
        var out_rank: usize = 0;
        if (resolveDeclaredBatchShape(lhs_shape, lhs_batch, batch_size)) |resolved_batch| {
            for (resolved_batch[0..lhs_batch.len]) |dim| {
                out_shape[out_rank] = dim;
                out_rank += 1;
            }
        } else if (resolveDeclaredBatchShape(rhs_shape, rhs_batch, batch_size)) |resolved_batch| {
            for (resolved_batch[0..rhs_batch.len]) |dim| {
                out_shape[out_rank] = dim;
                out_rank += 1;
            }
        } else if (!symbolic_batch_dims) {
            for (out_batch_shape) |dim| {
                out_shape[out_rank] = dim;
                out_rank += 1;
            }
        } else if (lhs_has_batch and allShapeDimsPositive(lhs_batch_shape) and (safeShapeNumel(lhs_batch_shape) orelse 0) == batch_size) {
            for (lhs_batch_shape) |dim| {
                out_shape[out_rank] = dim;
                out_rank += 1;
            }
        } else if (rhs_has_batch and allShapeDimsPositive(rhs_batch_shape) and (safeShapeNumel(rhs_batch_shape) orelse 0) == batch_size) {
            for (rhs_batch_shape) |dim| {
                out_shape[out_rank] = dim;
                out_rank += 1;
            }
        } else if (lhs_batch.len == 1 or rhs_batch.len == 1) {
            out_shape[out_rank] = @intCast(batch_size);
            out_rank += 1;
        }
        out_shape[out_rank] = @intCast(m);
        out_rank += 1;
        out_shape[out_rank] = @intCast(n);
        out_rank += 1;

        var all_positive = true;
        var has_zero_dim = false;
        for (out_shape[0..out_rank]) |dim| {
            if (dim <= 0) {
                all_positive = false;
                if (dim == 0) has_zero_dim = true;
            }
        }
        if (all_positive) {
            return self.withLogicalShape(result, out_shape[0..out_rank]);
        }
        if (!has_zero_dim and out_rank > 0) {
            return self.withLogicalShape(result, out_shape[0..out_rank]);
        }
        return result;
    }

    return error.UnsupportedPrimitiveOp;
}

/// Scan each independent axis lane in place. Integer addition wraps just as
/// the Metal integer scan does, without rounding through floating point.
fn scanAxis(comptime T: type, values: []align(1) T, outer: usize, width: usize, inner: usize, exclusive: bool, reverse: bool) void {
    for (0..outer) |batch| for (0..inner) |channel| {
        var sum: T = 0;
        for (0..width) |step| {
            const index = (batch * width + (if (reverse) width - 1 - step else step)) * inner + channel;
            const value = values[index];
            if (exclusive) values[index] = sum;
            sum = if (@typeInfo(T) == .int) sum +% value else sum + value;
            if (!exclusive) values[index] = sum;
        }
    };
}

/// Compare without promoting the integer to floating point, even at i64's
/// limits. A finite in-range f32's truncated integer part fits exactly in i64.
fn integerFloatLess(integer: i64, floating: f32, reverse: bool) bool {
    if (std.math.isNan(floating)) return false;
    if (floating >= 9223372036854775808.0) return !reverse;
    if (floating < -9223372036854775808.0) return reverse;
    const integral: i64 = @intFromFloat(floating);
    const integral_float: f32 = @floatFromInt(integral);
    return if (reverse)
        integral < integer or (integral == integer and floating < integral_float)
    else
        integer < integral or (integer == integral and floating > integral_float);
}

fn exactLessThan(self: *NativeCompute, a: CT, b: CT) !CT {
    const lhs = if (integerSource(a) != null) try IndexReader.init(a) else null;
    const rhs = if (integerSource(b) != null) try IndexReader.init(b) else null;
    const lf = if (lhs == null) try denseTensorView(self, a) else null;
    defer if (lf) |view| view.deinit(self.allocator);
    const rf = if (rhs == null) try denseTensorView(self, b) else null;
    defer if (rf) |view| view.deinit(self.allocator);
    const ln = if (lhs) |reader| reader.len else lf.?.data.len;
    const rn = if (rhs) |reader| reader.len else rf.?.data.len;
    const lflat = [_]i64{@intCast(ln)};
    const rflat = [_]i64{@intCast(rn)};
    const plan = try @import("binary_broadcast.zig").Plan.init(tensorStoredShape(a) orelse &lflat, tensorStoredShape(b) orelse &rflat);
    if (plan.lhs_count != ln or plan.rhs_count != rn) return error.ShapeMismatch;
    const data = try self.allocator.alloc(f32, plan.count);
    const result = try self.makeOwnedBuf(data);
    errdefer freeTensor(self, result);
    // Select the operand kinds once. Flat/scalar maps avoid divisions and
    // coalesced axes keep general broadcasting bounded without input copies.
    if (lhs) |left| {
        if (rhs) |right| {
            for (data, 0..) |*value, i| {
                const offsets = plan.offsets(i);
                value.* = @floatFromInt(@intFromBool(try left.at(offsets.lhs) < try right.at(offsets.rhs)));
            }
        } else {
            for (data, 0..) |*value, i| {
                const offsets = plan.offsets(i);
                value.* = @floatFromInt(@intFromBool(integerFloatLess(try left.at(offsets.lhs), rf.?.data[offsets.rhs], false)));
            }
        }
    } else {
        for (data, 0..) |*value, i| {
            const offsets = plan.offsets(i);
            value.* = @floatFromInt(@intFromBool(integerFloatLess(try rhs.?.at(offsets.rhs), lf.?.data[offsets.lhs], true)));
        }
    }
    return self.withLogicalShape(result, plan.shape[0..plan.rank]);
}

fn integerBinaryOp(self: *NativeCompute, a: CT, b: CT, comptime kind: enum { add, subtract, multiply }) !CT {
    const lhs = integerSource(a) orelse return error.UnsupportedTensorType;
    const rhs = integerSource(b) orelse return error.UnsupportedTensorType;
    if (lhs.dtype != rhs.dtype or lhs.dtype == .bool_) return error.UnsupportedTensorType;
    const left = try IndexReader.init(a);
    const right = try IndexReader.init(b);
    const plan = try @import("binary_broadcast.zig").Plan.init(tensorStoredShape(a) orelse lhs.shape, tensorStoredShape(b) orelse rhs.shape);
    if (plan.lhs_count != left.len or plan.rhs_count != right.len) return error.ShapeMismatch;
    const count = plan.count;
    const shape = plan.shape[0..plan.rank];
    const bytes = try self.allocator.alloc(u8, try lhs.dtype.byteCount(count));
    defer self.allocator.free(bytes);
    for (0..count) |i| {
        const offsets = plan.offsets(i);
        const x: u64 = @bitCast(try left.at(offsets.lhs));
        const y: u64 = @bitCast(try right.at(offsets.rhs));
        const result = switch (kind) {
            .add => x +% y,
            .subtract => x -% y,
            .multiply => x *% y,
        };
        switch (lhs.dtype) {
            .i8, .u8 => bytes[i] = @truncate(result),
            .i16 => std.mem.writeInt(u16, bytes[i * 2 ..][0..2], @truncate(result), .little),
            .i32 => std.mem.writeInt(u32, bytes[i * 4 ..][0..4], @truncate(result), .little),
            .i64 => std.mem.writeInt(u64, bytes[i * 8 ..][0..8], result, .little),
            else => unreachable,
        }
    }
    const dtype: ops.GraphDType = switch (lhs.dtype) {
        inline else => |tag| @field(ops.GraphDType, @tagName(tag)),
    };
    return (try fromConstantBytesOp(self, bytes, dtype, shape)).?;
}

fn cumulativeSumOp(ctx: *anyopaque, input: CT, axis: u8, exclusive: bool, reverse: bool) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    var flat_shape: [1]i64 = undefined;
    const shape = tensorStoredShape(input) orelse blk: {
        flat_shape[0] = @intCast((try getDataChecked(input)).len);
        break :blk &flat_shape;
    };
    if (shape.len > 8 or axis >= shape.len) return error.InvalidTensorShape;
    const count = typedShapeNumel(shape) orelse return error.InvalidTensorShape;
    const outer = typedShapeNumel(shape[0..axis]) orelse return error.InvalidTensorShape;
    const inner = typedShapeNumel(shape[axis + 1 ..]) orelse return error.InvalidTensorShape;
    const width: usize = @intCast(shape[axis]);
    if (integerSource(input)) |source| {
        if (source.dtype == .bool_) return error.UnsupportedTensorType;
        if (try integerTensorCount(source) != count) return error.ShapeMismatch;
        const output = try copyIntegerTensorWithShape(self, source, shape);
        const data = toBuf(output).owned_source_tensor.?.data;
        switch (source.dtype) {
            .i8 => scanAxis(i8, std.mem.bytesAsSlice(i8, data), outer, width, inner, exclusive, reverse),
            .i16 => scanAxis(i16, std.mem.bytesAsSlice(i16, data), outer, width, inner, exclusive, reverse),
            .u8 => scanAxis(u8, data, outer, width, inner, exclusive, reverse),
            .i32 => scanAxis(i32, std.mem.bytesAsSlice(i32, data), outer, width, inner, exclusive, reverse),
            .i64 => scanAxis(i64, std.mem.bytesAsSlice(i64, data), outer, width, inner, exclusive, reverse),
            else => unreachable,
        }
        return output;
    }
    // Other physical integer types must not fall through the float scan.
    switch (try tensorDTypeOp(ctx, input)) {
        .i8, .i16, .i32, .i64, .u8, .bool_ => return error.UnsupportedTensorType,
        else => {},
    }
    const source = try getDataChecked(input);
    if (source.len != count) return error.ShapeMismatch;
    const data = try self.allocator.dupe(f32, source);
    const output = try self.makeOwnedBuf(data);
    errdefer self.computeBackend().free(output);
    scanAxis(f32, data, outer, width, inner, exclusive, reverse);
    return self.withLogicalShape(output, shape);
}

fn exactWhereSelect(self: *NativeCompute, cond: CT, yes: CT, no: CT) !CT {
    const dtype: tensor_mod.DType = if (integerSource(yes)) |source| source.dtype else .f32;
    const false_dtype: tensor_mod.DType = if (integerSource(no)) |source| source.dtype else .f32;
    if (dtype != false_dtype) return error.UnsupportedTensorType;
    var views: [3]?WeightF32View = @splat(null);
    defer for (&views) |*view| {
        if (view.*) |v| v.deinit(self.allocator);
    };
    var shapes: [3][]const i64 = undefined;
    var flat: [3][1]i64 = undefined;
    var bytes: [3][]const u8 = undefined;
    var counts: [3]usize = undefined;
    for ([_]CT{ cond, yes, no }, 0..) |input, i| {
        if (integerSource(input)) |source| {
            counts[i] = try integerTensorCount(source);
            bytes[i] = source.data;
        } else {
            views[i] = try denseTensorView(self, input);
            counts[i] = views[i].?.data.len;
            bytes[i] = std.mem.sliceAsBytes(views[i].?.data);
        }
        flat[i][0] = @intCast(counts[i]);
        shapes[i] = tensorStoredShape(input) orelse &flat[i];
    }
    const plan = try @import("binary_broadcast.zig").SelectionPlan.where(shapes[0], shapes[1], shapes[2]);
    if (!std.mem.eql(usize, &counts, &plan.counts)) return error.ShapeMismatch;
    const condition = if (integerSource(cond) != null) try IndexReader.init(cond) else null;
    const width = if (integerSource(yes)) |source| source.dtype.byteSize() else @sizeOf(f32);
    const output = try self.allocator.alloc(u8, try std.math.mul(usize, plan.count, width));
    var transferred = false;
    defer if (!transferred) self.allocator.free(output);
    for (0..plan.count) |i| {
        const offsets = plan.offsets(i);
        const take_true = if (condition) |reader| try reader.at(offsets[0]) != 0 else views[0].?.data[offsets[0]] != 0;
        const branch: usize = if (take_true) 1 else 2;
        @memcpy(output[i * width ..][0..width], bytes[branch][offsets[branch] * width ..][0..width]);
    }
    if (dtype == .f32) {
        const data = try self.allocator.alloc(f32, plan.count);
        @memcpy(std.mem.sliceAsBytes(data), output);
        const result = try self.makeOwnedBuf(data);
        errdefer freeTensor(self, result);
        return self.withLogicalShape(result, plan.shape[0..plan.rank]);
    }
    transferred = true;
    return takeOwnedIntegerBytes(self, output, dtype, plan.shape[0..plan.rank]);
}

/// Takes ownership on success and failure, avoiding a second output copy.
fn takeOwnedIntegerBytes(self: *NativeCompute, data: []u8, dtype: tensor_mod.DType, shape: []const i64) !CT {
    const owned_shape = self.allocator.dupe(i64, shape) catch |err| {
        self.allocator.free(data);
        return err;
    };
    return self.makeBufWithOwnedSourceTensor(.{ .data = data, .dtype = dtype, .shape = owned_shape, .name = "", .allocator = self.allocator, .owns_data = true, .owns_shape = true });
}

fn integerSource(input: CT) ?*const tensor_mod.Tensor {
    const source = toBuf(input).source_tensor orelse return null;
    return switch (source.dtype) {
        .i8, .i16, .i32, .i64, .u8, .bool_ => source,
        else => null,
    };
}

fn integerTensorCount(tensor: *const tensor_mod.Tensor) !usize {
    switch (tensor.dtype) {
        .i8, .i16, .i32, .i64, .u8, .bool_ => {},
        else => return error.UnsupportedTensorType,
    }
    const expected = tensorExpectedDenseByteLen(tensor) orelse return error.InvalidTensorShape;
    if (tensor.data.len != expected) return error.InvalidTensorShape;
    return expected / tensor.dtype.byteSize();
}

fn typedShapeNumel(shape: []const i64) ?usize {
    var count: usize = 1;
    for (shape) |dim| {
        if (dim < 0) return null;
        count = std.math.mul(usize, count, @intCast(dim)) catch return null;
    }
    return count;
}

/// A non-owning exact reader. bytesAsSlice retains align(1), allowing safe
/// reads from mapped or deliberately unaligned integer tensor payloads.
const IndexReader = struct {
    source: ?*const tensor_mod.Tensor,
    legacy: []const f32,
    len: usize,

    fn init(indices: CT) !IndexReader {
        if (integerSource(indices)) |source|
            return .{ .source = source, .legacy = &.{}, .len = try integerTensorCount(source) };
        const data = getData(indices);
        return .{ .source = null, .legacy = data, .len = data.len };
    }

    fn at(self: IndexReader, index: usize) !i64 {
        if (index >= self.len) return error.IndexOutOfBounds;
        if (self.source) |source| return switch (source.dtype) {
            .i8 => std.mem.bytesAsSlice(i8, source.data)[index],
            .i16 => std.mem.bytesAsSlice(i16, source.data)[index],
            .u8, .bool_ => source.data[index],
            .i32 => std.mem.bytesAsSlice(i32, source.data)[index],
            .i64 => std.mem.bytesAsSlice(i64, source.data)[index],
            else => unreachable,
        };
        const value: f64 = self.legacy[index];
        if (!std.math.isFinite(value) or value < -9223372036854775808.0 or value >= 9223372036854775808.0)
            return error.InvalidIndex;
        return @intFromFloat(value);
    }

    fn normalized(self: IndexReader, index: usize, extent: usize) !usize {
        const signed_extent = std.math.cast(i64, extent) orelse return error.InvalidTensorShape;
        var value = try self.at(index);
        if (value < 0) value += signed_extent;
        if (value < 0 or value >= signed_extent) return error.IndexOutOfBounds;
        return @intCast(value);
    }
};

fn copyIntegerTensorWithShape(self: *NativeCompute, source: *const tensor_mod.Tensor, shape: []const i64) !CT {
    const count = try integerTensorCount(source);
    if ((typedShapeNumel(shape) orelse return error.InvalidTensorShape) != count) return error.ShapeMismatch;
    const raw = try self.allocator.dupe(u8, source.data);
    var transferred = false;
    errdefer if (!transferred) self.allocator.free(raw);
    const owned_shape = try self.allocator.dupe(i64, shape);
    // makeBufWithOwnedSourceTensor takes ownership even if it fails.
    transferred = true;
    return self.makeBufWithOwnedSourceTensor(.{ .data = raw, .dtype = source.dtype, .shape = owned_shape, .name = "", .allocator = self.allocator, .owns_data = true, .owns_shape = true });
}

fn typedGather(self: *NativeCompute, input: CT, indices: CT, axis: u8, declared_shape: []const i64) !CT {
    const index = try IndexReader.init(indices);
    const source_shape = storedOrDeclaredShape(input, declared_shape);
    const input_count = typedShapeNumel(source_shape) orelse return error.InvalidTensorShape;
    if (source_shape.len == 0 or source_shape.len > 8 or axis >= source_shape.len) return error.UnsupportedShape;
    const source = toBuf(input).source_tensor;
    // Typed gather is a fallible strict interface. Materialize at most once,
    // preserving the input view and the original error if allocation fails.
    const dense = if (source == null) try getDataChecked(input) else &.{};
    const actual_count = if (source) |tensor| tensor.elementCount() else dense.len;
    if (input_count != actual_count) return error.ShapeMismatch;
    const fallback_index_shape = [_]i64{@intCast(index.len)};
    const index_shape = tensorStoredShape(indices) orelse &fallback_index_shape;
    if ((typedShapeNumel(index_shape) orelse return error.InvalidTensorShape) != index.len) return error.ShapeMismatch;
    const output_rank = source_shape.len - 1 + index_shape.len;
    if (output_rank > 8) return error.UnsupportedShape;
    const prefix = typedShapeNumel(source_shape[0..axis]) orelse return error.InvalidTensorShape;
    const suffix = typedShapeNumel(source_shape[axis + 1 ..]) orelse return error.InvalidTensorShape;
    const extent = std.math.cast(usize, source_shape[axis]) orelse return error.InvalidTensorShape;
    const output_count = try std.math.mul(usize, try std.math.mul(usize, prefix, index.len), suffix);
    // Validate every index before any output storage allocation, including
    // empty suffixes and integer tables whose payload is never widened.
    for (0..index.len) |i| _ = try index.normalized(i, extent);
    var shape_buffer: [8]i64 = undefined;
    @memcpy(shape_buffer[0..axis], source_shape[0..axis]);
    @memcpy(shape_buffer[axis..][0..index_shape.len], index_shape);
    @memcpy(shape_buffer[axis + index_shape.len ..][0 .. source_shape.len - axis - 1], source_shape[axis + 1 ..]);
    const output_shape = shape_buffer[0..output_rank];
    if (integerSource(input)) |integer| {
        _ = try integerTensorCount(integer);
        const width = integer.dtype.byteSize();
        const raw = try self.allocator.alloc(u8, try std.math.mul(usize, output_count, width));
        var transferred = false;
        errdefer if (!transferred) self.allocator.free(raw);
        for (0..prefix) |p| for (0..index.len) |i| {
            const selected = try index.normalized(i, extent);
            const from = (p * extent + selected) * suffix * width;
            const to = (p * index.len + i) * suffix * width;
            @memcpy(raw[to..][0 .. suffix * width], integer.data[from..][0 .. suffix * width]);
        };
        const owned_shape = try self.allocator.dupe(i64, output_shape);
        transferred = true;
        return self.makeBufWithOwnedSourceTensor(.{ .data = raw, .dtype = integer.dtype, .shape = owned_shape, .name = "", .allocator = self.allocator, .owns_data = true, .owns_shape = true });
    }
    const output = try self.allocator.alloc(f32, output_count);
    errdefer self.allocator.free(output);
    for (0..prefix) |p| for (0..index.len) |i| {
        const selected = try index.normalized(i, extent);
        const from = (p * extent + selected) * suffix;
        const to = (p * index.len + i) * suffix;
        if (source) |tensor| {
            try convertTensorRowsToF32(tensor, p * extent + selected, 1, suffix, output[to..][0..suffix]);
        } else @memcpy(output[to..][0..suffix], dense[from..][0..suffix]);
    };
    const result = try self.makeBuf(output, true);
    return self.withLogicalShape(result, output_shape);
}

test "native typed gather preserves view materialization OOM and retry" {
    const a = std.testing.allocator;
    const Budget = @import("../runtime/bounded_allocator.zig").BoundedAllocator;
    // Deny each materialization allocation with both an owned sibling and a
    // borrowed source. The optional clone deliberately has no view fallback.
    for ([_]bool{ false, true }) |owned_source| {
        for ([_]bool{ false, true }) |backing_failure| {
            for (0..2) |failure_allocation| {
                var failing = std.testing.FailingAllocator.init(a, .{});
                var budget = Budget{ .backing = failing.allocator(), .limit = 64 * 1024 };
                var store = WeightStore{ .allocator = a, .resident_weights = .{}, .lazy_weights = .{} };
                defer store.deinitOwned();
                var compute = NativeCompute.init(budget.allocator(), &store, null);
                defer compute.deinit();
                const cb = compute.computeBackend();
                var original = [_]f32{ 1, 2, 3, 4, 5, 6 };
                const source = if (owned_source) try cb.fromFloat32Shape(&original, &.{ 2, 3 }) else borrowed: {
                    const value = try compute.makeBuf(&original, false);
                    errdefer cb.free(value);
                    break :borrowed try compute.withLogicalShape(value, &.{ 2, 3 });
                };
                defer cb.free(source);
                const view = try cb.primTranspose(source, &.{ 1, 0 }, &.{ 2, 3 });
                defer cb.free(view);
                const indices = (try cb.fromInt32Shape(&.{ 2, 0 }, &.{2})).?;
                defer cb.free(indices);
                const before = toBuf(view).*;
                try std.testing.expect(before.view_strides != null);
                try std.testing.expectEqual(@as(?CT, null), try cb.cloneTensorShape(view, &.{ 3, 2 }));
                const live = budget.live;
                if (backing_failure) {
                    failing.fail_index = failing.alloc_index + failure_allocation;
                } else {
                    budget.limit = live + if (failure_allocation == 0) @as(usize, 0) else @sizeOf(@TypeOf(original));
                }
                try std.testing.expectError(error.OutOfMemory, cb.primGather(view, indices, 0, &.{ 3, 2 }));
                try std.testing.expectEqual(live, budget.live);
                try std.testing.expectEqual(!backing_failure, budget.denied);
                try std.testing.expectEqual(before.data.ptr, toBuf(view).data.ptr);
                try std.testing.expectEqual(before.shared_data_refcount, toBuf(view).shared_data_refcount);
                try std.testing.expectEqual(before.logical_shape.?.ptr, toBuf(view).logical_shape.?.ptr);
                try std.testing.expectEqual(before.view_strides.?.ptr, toBuf(view).view_strides.?.ptr);
                try std.testing.expectEqualSlices(f32, &original, toBuf(source).data);
                try std.testing.expectEqualSlices(i64, &.{ 3, 2 }, toBuf(view).logical_shape.?);

                failing.fail_index = std.math.maxInt(usize);
                budget.limit = 64 * 1024;
                const retry = try cb.primGather(view, indices, 0, &.{ 3, 2 });
                defer cb.free(retry);
                const actual = try cb.toFloat32(retry, a);
                defer a.free(actual);
                try std.testing.expectEqualSlices(f32, &.{ 3, 6, 1, 4 }, actual);
                try std.testing.expectEqualSlices(f32, &original, toBuf(source).data);
                try std.testing.expect(toBuf(view).view_strides == null);
            }
        }
    }
}

test "native typed gather preserves genuine malformed view errors" {
    const a = std.testing.allocator;
    var store = WeightStore{ .allocator = a, .resident_weights = .{}, .lazy_weights = .{} };
    defer store.deinitOwned();
    var compute = NativeCompute.init(a, &store, null);
    defer compute.deinit();
    const cb = compute.computeBackend();
    const source = try cb.fromFloat32Shape(&.{ 1, 2, 3, 4, 5, 6 }, &.{ 2, 3 });
    defer cb.free(source);
    const view = try cb.primTranspose(source, &.{ 1, 0 }, &.{ 2, 3 });
    defer cb.free(view);
    const indices = (try cb.fromInt32Shape(&.{1}, &.{1})).?;
    defer cb.free(indices);
    toBuf(view).view_base_offset = 6;
    try std.testing.expectError(error.InvalidTensorShape, cb.primGather(view, indices, 0, &.{ 3, 2 }));
    try std.testing.expect(toBuf(view).view_strides != null);
    toBuf(view).view_base_offset = 0;
    const retry = try cb.primGather(view, indices, 0, &.{ 3, 2 });
    defer cb.free(retry);
    const actual = try cb.toFloat32(retry, a);
    defer a.free(actual);
    try std.testing.expectEqualSlices(f32, &.{ 2, 5 }, actual);
}

fn typedScatterAdd(self: *NativeCompute, input: CT, indices: CT, input_shape: []const i64, output_shape: []const i64, axis: u8) !CT {
    if (axis != 0 or input_shape.len != 2 or output_shape.len != 2) return error.UnsupportedPrimitiveOp;
    const index = try IndexReader.init(indices);
    const count = typedShapeNumel(input_shape) orelse return error.InvalidTensorShape;
    const output_count = typedShapeNumel(output_shape) orelse return error.InvalidTensorShape;
    const n = std.math.cast(usize, input_shape[0]) orelse return error.InvalidTensorShape;
    const width = std.math.cast(usize, input_shape[1]) orelse return error.InvalidTensorShape;
    const out_rows = std.math.cast(usize, output_shape[0]) orelse return error.InvalidTensorShape;
    if (width == 0 or input_shape[1] != output_shape[1] or index.len != n) return error.ShapeMismatch;
    for (0..n) |i| _ = try index.normalized(i, out_rows);
    const input_view = try denseTensorView(self, input);
    defer input_view.deinit(self.allocator);
    if (input_view.data.len != count) return error.ShapeMismatch;
    const output = try self.allocator.alloc(f32, output_count);
    errdefer self.allocator.free(output);
    @memset(output, 0);
    for (0..n) |i| {
        const selected = try index.normalized(i, out_rows);
        for (0..width) |column| output[selected * width + column] += input_view.data[i * width + column];
    }
    const result = try self.makeBuf(output, true);
    return self.withLogicalShape(result, output_shape);
}

fn primScatterAddOp(ctx: *anyopaque, input: CT, indices: CT, input_shape: []const i64, indices_shape: []const i64, axis: u8) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(indices) != null) return typedScatterAdd(self, input, indices, input_shape, indices_shape, axis);
    const in_data = getData(input);
    const idx_data = getData(indices);
    // The compatibility float-index route retains its historical axis0 behavior.

    // Simple case: input is [N, D], indices is [N] (as f32-encoded ints).
    // Output rows come from indices_shape[0] (the graph's declared output dim),
    // falling back to max(indices)+1 if indices_shape is unavailable.
    if (input_shape.len == 2) {
        const n = @as(usize, @intCast(input_shape[0]));
        const d = @as(usize, @intCast(input_shape[1]));
        // Use indices_shape to determine output rows when available.
        const out_rows: usize = if (indices_shape.len > 0)
            @as(usize, @intCast(indices_shape[0]))
        else blk: {
            var max_idx: usize = 0;
            for (idx_data) |v| {
                const idx = @as(usize, @intFromFloat(v));
                if (idx > max_idx) max_idx = idx;
            }
            break :blk max_idx + 1;
        };
        const output = try self.allocator.alloc(f32, out_rows * d);
        errdefer self.allocator.free(output);
        @memset(output, 0.0);
        for (0..n) |i| {
            const row = @as(usize, @intFromFloat(idx_data[i]));
            if (row >= out_rows) return error.IndexOutOfBounds;
            for (0..d) |j| {
                output[row * d + j] += in_data[i * d + j];
            }
        }
        return self.makeBuf(output, true);
    }

    return error.UnsupportedPrimitiveOp;
}

fn primGatherOp(ctx: *anyopaque, input: CT, indices: CT, axis: u8, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(indices) != null or integerSource(input) != null) return typedGather(self, input, indices, axis, input_shape);
    const idx_data = getData(indices);
    const effective_input_shape = storedOrDeclaredShape(input, input_shape);
    const source_tensor = toBuf(input).source_tensor;
    const indices_shape = tensorStoredShape(indices);
    var resolved_input_shape_buf: [8]i64 = undefined;
    var resolved_indices_shape_buf: [8]i64 = undefined;
    var runtime_shape_owned: ?[]i64 = null;
    var runtime_indices_shape_owned: ?[]i64 = null;
    defer if (runtime_shape_owned) |shape| self.allocator.free(shape);
    defer if (runtime_indices_shape_owned) |shape| self.allocator.free(shape);
    const input_elem_count = if (source_tensor) |tensor| tensor.elementCount() else toBuf(input).data.len;
    var resolved_input_shape = if (resolveShapeFromDataLen(effective_input_shape, input_elem_count)) |resolved| blk: {
        resolved_input_shape_buf = resolved;
        break :blk resolved_input_shape_buf[0..effective_input_shape.len];
    } else effective_input_shape;
    var resolved_indices_shape = if (indices_shape) |shape|
        if (resolveShapeFromDataLen(shape, idx_data.len)) |resolved| blk: {
            resolved_indices_shape_buf = resolved;
            break :blk resolved_indices_shape_buf[0..shape.len];
        } else shape
    else
        null;

    for (resolved_input_shape) |dim| {
        if (dim > 0) continue;
        if (tensorShapeOp(ctx, input, self.allocator)) |runtime_shape| {
            runtime_shape_owned = runtime_shape;
            resolved_input_shape = if (resolveShapeFromDataLen(runtime_shape, input_elem_count)) |resolved| blk: {
                resolved_input_shape_buf = resolved;
                break :blk resolved_input_shape_buf[0..runtime_shape.len];
            } else runtime_shape;
        } else |_| {}
        break;
    }

    if (resolved_indices_shape) |shape| {
        for (shape) |dim| {
            if (dim > 0) continue;
            if (tensorShapeOp(ctx, indices, self.allocator)) |runtime_shape| {
                runtime_indices_shape_owned = runtime_shape;
                resolved_indices_shape = if (resolveShapeFromDataLen(runtime_shape, idx_data.len)) |resolved| blk: {
                    resolved_indices_shape_buf = resolved;
                    break :blk resolved_indices_shape_buf[0..runtime_shape.len];
                } else runtime_shape;
            } else |_| {}
            break;
        }
    }

    if (resolved_indices_shape) |idx_shape| {
        const axis_index = @as(usize, axis);
        const gather_nd_style = axis == 0 and idx_shape.len >= 1 and idx_shape[idx_shape.len - 1] > 1 and idx_shape[idx_shape.len - 1] <= effective_input_shape.len;
        if (axis_index < resolved_input_shape.len and source_tensor == null and idx_shape.len > 0 and !gather_nd_style) {
            const in_data = getData(input);

            var normalized_idx_shape_buf: [8]i64 = undefined;
            const normalized_idx_shape = blk: {
                if (idx_shape.len > 1 and idx_data.len == 1) {
                    var all_ones = true;
                    for (idx_shape) |dim| {
                        if (dim != 1) {
                            all_ones = false;
                            break;
                        }
                    }
                    if (all_ones) {
                        normalized_idx_shape_buf[0] = 1;
                        break :blk normalized_idx_shape_buf[0..1];
                    }
                }
                break :blk idx_shape;
            };

            const geometry = kernel_geometry.GatherAxis.init(std.math.maxInt(usize), resolved_input_shape, axis_index) catch return error.UnsupportedShape;
            const prefix_count = geometry.prefix;
            const axis_extent = geometry.extent;
            const suffix_size = geometry.suffix;

            const index_count = idx_data.len;
            var owned_output = try OwnedDenseOutput.alloc(self, try geometry.count(index_count));
            defer owned_output.deinit();
            const output = owned_output.storage.?;
            for (0..prefix_count) |prefix_idx| {
                for (0..index_count) |idx_pos| {
                    var gather_index = @as(i64, @intFromFloat(idx_data[idx_pos]));
                    if (gather_index < 0) gather_index += @as(i64, @intCast(axis_extent));
                    if (gather_index < 0 or gather_index >= axis_extent) return error.IndexOutOfBounds;
                    const gather_pos = @as(usize, @intCast(gather_index));
                    const src_offset = (prefix_idx * axis_extent + gather_pos) * suffix_size;
                    const dst_offset = (prefix_idx * index_count + idx_pos) * suffix_size;
                    if (src_offset + suffix_size > in_data.len or dst_offset + suffix_size > output.len) return error.ShapeMismatch;
                    @memcpy(output[dst_offset..][0..suffix_size], in_data[src_offset..][0..suffix_size]);
                }
            }

            var out_shape_buf: [8]i64 = undefined;
            const out_rank = try kernel_geometry.gatherShape(resolved_input_shape, normalized_idx_shape, axis_index, &out_shape_buf);

            const result = try owned_output.intoResult();
            errdefer freeTensor(self, result);
            return self.withLogicalShape(result, out_shape_buf[0..out_rank]);
        }
    }

    if (axis == 0) {
        if (resolved_indices_shape) |idx_shape| {
            if (idx_shape.len >= 1) {
                const index_depth = idx_shape[idx_shape.len - 1];
                if (index_depth > 1 and index_depth <= effective_input_shape.len) {
                    const in_data = getData(input);
                    if (source_tensor != null) {
                        std.log.warn("gather axis0 source-tensor gather_nd unsupported input_shape={any} effective_shape={any} indices_shape={?any} index_depth={d} axis={d}", .{
                            input_shape,
                            effective_input_shape,
                            indices_shape,
                            index_depth,
                            axis,
                        });
                        return error.UnsupportedPrimitiveOp;
                    }

                    const k = @as(usize, @intCast(index_depth));
                    var gather_shape_buf: [8]i64 = undefined;
                    @memcpy(gather_shape_buf[0..resolved_input_shape.len], resolved_input_shape);
                    var idx_prefix_count: usize = 1;
                    for (idx_shape[0 .. idx_shape.len - 1]) |dim| {
                        if (dim <= 0) return error.UnsupportedShape;
                        idx_prefix_count *= @as(usize, @intCast(dim));
                    }
                    if (idx_prefix_count * k > idx_data.len) return error.ShapeMismatch;

                    for (0..k) |coord_idx| {
                        if (gather_shape_buf[coord_idx] > 0) continue;
                        var max_coord: usize = 0;
                        for (0..idx_prefix_count) |prefix_idx| {
                            const coord = @as(usize, @intFromFloat(idx_data[prefix_idx * k + coord_idx]));
                            if (coord > max_coord) max_coord = coord;
                        }
                        gather_shape_buf[coord_idx] = @as(i64, @intCast(max_coord + 1));
                    }

                    var slice_size: usize = 1;
                    for (gather_shape_buf[k..resolved_input_shape.len]) |dim| {
                        if (dim <= 0) return error.UnsupportedShape;
                        slice_size *= @as(usize, @intCast(dim));
                    }

                    const output_len = idx_prefix_count * slice_size;
                    var owned_output = try OwnedDenseOutput.alloc(self, output_len);
                    defer owned_output.deinit();
                    const output = owned_output.storage.?;

                    var coord_strides: [8]usize = undefined;
                    for (0..k) |dim_idx| {
                        var stride: usize = 1;
                        for ((dim_idx + 1)..k) |next_idx| {
                            const dim = gather_shape_buf[next_idx];
                            if (dim <= 0) return error.UnsupportedShape;
                            stride *= @as(usize, @intCast(dim));
                        }
                        coord_strides[dim_idx] = stride;
                    }

                    for (0..idx_prefix_count) |prefix_idx| {
                        var flat_index: usize = 0;
                        for (0..k) |coord_idx| {
                            const coord = @as(usize, @intFromFloat(idx_data[prefix_idx * k + coord_idx]));
                            const dim = @as(usize, @intCast(gather_shape_buf[coord_idx]));
                            if (coord >= dim) {
                                std.log.warn("gather_nd OOB coord_idx={d} coord={d} dim={d} data_shape={any} resolved={any} gather_shape={any} idx_shape={?any} prefix_idx={d} input_len={d}", .{
                                    coord_idx,
                                    coord,
                                    dim,
                                    effective_input_shape,
                                    resolved_input_shape,
                                    gather_shape_buf[0..resolved_input_shape.len],
                                    resolved_indices_shape,
                                    prefix_idx,
                                    in_data.len,
                                });
                                return error.IndexOutOfBounds;
                            }
                            flat_index += coord * coord_strides[coord_idx];
                        }
                        const src_offset = flat_index * slice_size;
                        const dst_offset = prefix_idx * slice_size;
                        if (src_offset + slice_size > in_data.len or dst_offset + slice_size > output.len) return error.ShapeMismatch;
                        @memcpy(output[dst_offset..][0..slice_size], in_data[src_offset..][0..slice_size]);
                    }

                    var out_shape_buf: [8]i64 = undefined;
                    var out_rank: usize = 0;
                    for (idx_shape[0 .. idx_shape.len - 1]) |dim| {
                        out_shape_buf[out_rank] = dim;
                        out_rank += 1;
                    }
                    for (gather_shape_buf[k..resolved_input_shape.len]) |dim| {
                        out_shape_buf[out_rank] = dim;
                        out_rank += 1;
                    }

                    const result = try owned_output.intoResult();
                    errdefer freeTensor(self, result);
                    return self.withLogicalShape(result, out_shape_buf[0..out_rank]);
                }
            }
        }
    }

    if ((indices_shape == null or indices_shape.?.len == 0) and idx_data.len == 1) {
        const axis_index = @as(usize, axis);
        if (axis_index >= resolved_input_shape.len) return error.UnsupportedShape;
        if (source_tensor != null) return error.UnsupportedPrimitiveOp;

        var prefix_count: usize = 1;
        for (resolved_input_shape[0..axis_index]) |dim| {
            if (dim <= 0) return error.UnsupportedShape;
            prefix_count *= @as(usize, @intCast(dim));
        }
        const axis_extent_i64 = resolved_input_shape[axis_index];
        if (axis_extent_i64 <= 0) return error.UnsupportedShape;
        const axis_extent = @as(usize, @intCast(axis_extent_i64));

        var suffix_size: usize = 1;
        for (resolved_input_shape[axis_index + 1 ..]) |dim| {
            if (dim <= 0) return error.UnsupportedShape;
            suffix_size *= @as(usize, @intCast(dim));
        }

        var gather_index = @as(i64, @intFromFloat(idx_data[0]));
        if (gather_index < 0) gather_index += @as(i64, @intCast(axis_extent));
        if (gather_index < 0 or gather_index >= axis_extent) return error.IndexOutOfBounds;
        const gather_pos = @as(usize, @intCast(gather_index));

        const in_data = getData(input);
        var owned_output = try OwnedDenseOutput.alloc(self, prefix_count * suffix_size);
        defer owned_output.deinit();
        const output = owned_output.storage.?;
        for (0..prefix_count) |prefix_idx| {
            const src_offset = (prefix_idx * axis_extent + gather_pos) * suffix_size;
            const dst_offset = prefix_idx * suffix_size;
            if (src_offset + suffix_size > in_data.len or dst_offset + suffix_size > output.len) return error.ShapeMismatch;
            @memcpy(output[dst_offset..][0..suffix_size], in_data[src_offset..][0..suffix_size]);
        }

        var out_shape_buf: [8]i64 = undefined;
        var out_rank: usize = 0;
        for (resolved_input_shape, 0..) |dim, dim_idx| {
            if (dim_idx == axis_index) continue;
            out_shape_buf[out_rank] = dim;
            out_rank += 1;
        }

        const result = try owned_output.intoResult();
        errdefer freeTensor(self, result);
        return self.withLogicalShape(result, out_shape_buf[0..out_rank]);
    }

    // Simple: input [M, D], indices [N] → output [N, D]
    if (effective_input_shape.len == 2) {
        const in_data = getData(input);
        const max_row = blk: {
            var max_idx: usize = 0;
            for (idx_data) |v| {
                const idx = @as(usize, @intFromFloat(v));
                if (idx > max_idx) max_idx = idx;
            }
            break :blk max_idx;
        };
        const inferred_layout = inferGather2DLayoutFromElementCount(input_elem_count, max_row);
        const d = positiveShapeDim(resolved_input_shape, 1) catch blk: {
            if (source_tensor) |tensor| {
                if (tensor.shape.len == 2 and tensor.shape[1] > 0) {
                    break :blk @as(usize, @intCast(tensor.shape[1]));
                }
            }
            if (inferred_layout) |layout| {
                break :blk layout.dim;
            }
            const rows = positiveShapeDim(resolved_input_shape, 0) catch {
                std.log.warn("gather unresolved 2d shape shape={any} resolved={any} data_len={d} elem_count={d} source_tensor={any} max_row={d}", .{
                    effective_input_shape,
                    resolved_input_shape,
                    in_data.len,
                    input_elem_count,
                    source_tensor != null,
                    max_row,
                });
                return error.UnsupportedShape;
            };
            if (rows == 0 or in_data.len % rows != 0) return error.UnsupportedShape;
            break :blk in_data.len / rows;
        };
        const n = idx_data.len;
        var owned_output = try OwnedDenseOutput.alloc(self, n * d);
        defer owned_output.deinit();
        const output = owned_output.storage.?;
        var out_shape_buf: [8]i64 = @splat(0);
        var out_rank: usize = 0;
        if (indices_shape) |idx_shape| {
            for (idx_shape) |dim| {
                out_shape_buf[out_rank] = dim;
                out_rank += 1;
            }
        } else {
            out_shape_buf[0] = @intCast(n);
            out_rank = 1;
        }
        out_shape_buf[out_rank] = @intCast(d);
        out_rank += 1;
        if (source_tensor) |tensor| {
            const rows = positiveShapeDim(resolved_input_shape, 0) catch blk_rows: {
                if (inferred_layout) |layout| {
                    break :blk_rows layout.rows;
                }
                if (tensor.shape.len == 2 and tensor.shape[0] > 0) {
                    break :blk_rows @as(usize, @intCast(tensor.shape[0]));
                }
                const elem_count = tensor.elementCount();
                if (elem_count == 0 or elem_count % d != 0) return error.UnsupportedShape;
                break :blk_rows elem_count / d;
            };
            for (0..n) |i| {
                var row_i64 = @as(i64, @intFromFloat(idx_data[i]));
                if (row_i64 < 0) row_i64 += @as(i64, @intCast(rows));
                if (row_i64 < 0) return error.IndexOutOfBounds;
                const row = @as(usize, @intCast(row_i64));
                if (row >= rows) {
                    std.log.warn("gather source_tensor OOB row={d} rows={d} d={d} input_shape={any} resolved={any} tensor_shape={any} idx_len={d} idx_sample={d:.3}", .{
                        row,
                        rows,
                        d,
                        effective_input_shape,
                        resolved_input_shape,
                        tensor.shape,
                        idx_data.len,
                        idx_data[i],
                    });
                    return error.IndexOutOfBounds;
                }
                try convertTensorRowsToF32(tensor, row, 1, d, output[i * d ..][0..d]);
            }
            const result = try owned_output.intoResult();
            errdefer freeTensor(self, result);
            return self.withLogicalShape(result, out_shape_buf[0..out_rank]);
        }
        const rows = positiveShapeDim(resolved_input_shape, 0) catch blk_rows: {
            if (inferred_layout) |layout| {
                break :blk_rows layout.rows;
            }
            if (d == 0 or in_data.len % d != 0) return error.UnsupportedShape;
            break :blk_rows in_data.len / d;
        };
        for (0..n) |i| {
            var row_i64 = @as(i64, @intFromFloat(idx_data[i]));
            if (row_i64 < 0) row_i64 += @as(i64, @intCast(rows));
            if (row_i64 < 0) return error.IndexOutOfBounds;
            const row = @as(usize, @intCast(row_i64));
            if (row >= rows or (row + 1) * d > in_data.len) {
                std.log.warn("gather dense OOB row={d} rows={d} d={d} input_shape={any} resolved={any} in_len={d} idx_len={d} idx_sample={d:.3}", .{
                    row,
                    rows,
                    d,
                    effective_input_shape,
                    resolved_input_shape,
                    in_data.len,
                    idx_data.len,
                    idx_data[i],
                });
                return error.IndexOutOfBounds;
            }
            @memcpy(output[i * d ..][0..d], in_data[row * d ..][0..d]);
        }
        const result = try owned_output.intoResult();
        errdefer freeTensor(self, result);
        return self.withLogicalShape(result, out_shape_buf[0..out_rank]);
    }

    std.log.warn("gather unsupported axis={d} input_shape={any} effective_shape={any} indices_shape={?any} source_tensor={any}", .{
        axis,
        input_shape,
        effective_input_shape,
        indices_shape,
        source_tensor != null,
    });
    return error.UnsupportedPrimitiveOp;
}

fn primSliceOp(ctx: *anyopaque, input: CT, starts: []const i64, limits: []const i64, strides: []const i64, input_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (integerSource(input)) |source| {
        const plan = try @import("slice_plan.zig").Plan.init(storedOrDeclaredShape(input, input_shape), starts, limits, strides, input_shape);
        if (plan.input_count != try integerTensorCount(source)) return error.ShapeMismatch;
        const width = source.dtype.byteSize();
        const bytes = try self.allocator.alloc(u8, try std.math.mul(usize, plan.count, width));
        if (plan.count > 0) {
            if (plan.contiguous()) {
                @memcpy(bytes, source.data[@as(usize, @intCast(plan.base)) * width ..][0..bytes.len]);
            } else for (0..plan.count) |i| {
                @memcpy(bytes[i * width ..][0..width], source.data[plan.offset(i) * width ..][0..width]);
            }
        }
        return takeOwnedIntegerBytes(self, bytes, source.dtype, plan.shape[0..plan.rank]);
    }
    const in_data = getData(input);
    const rank = input_shape.len;
    if (rank > 8 or starts.len < rank or limits.len < rank or strides.len < rank) return error.UnsupportedShape;

    const effective_input_shape = storedOrDeclaredShape(input, input_shape);
    var full_range_passthrough = effective_input_shape.len == rank;
    if (full_range_passthrough) {
        for (0..rank) |d| {
            const dim = effective_input_shape[d];
            const limit = limits[d];
            const limit_covers_axis = if (limit < 0)
                true
            else if (dim > 0)
                limit >= dim
            else
                false;
            if (starts[d] != 0 or strides[d] != 1 or !limit_covers_axis) {
                full_range_passthrough = false;
                break;
            }
        }
    }
    if (full_range_passthrough) {
        return aliasDenseBufWithShape(self, input, effective_input_shape) catch blk: {
            const dense_view = try denseWeightView(self, input);
            defer dense_view.deinit(self.allocator);
            var owned_output = try OwnedDenseOutput.copy(self, dense_view.data);
            defer owned_output.deinit();
            const result = try owned_output.intoResult();
            errdefer freeTensor(self, result);
            break :blk self.withLogicalShape(result, effective_input_shape);
        };
    }

    var resolved_input_shape_buf: [8]i64 = undefined;
    const resolved_input_shape = if (resolveShapeFromDataLen(effective_input_shape, in_data.len)) |resolved| blk: {
        resolved_input_shape_buf = resolved;
        break :blk resolved_input_shape_buf[0..rank];
    } else blk: {
        if (effective_input_shape.len != rank or !allShapeDimsPositive(effective_input_shape)) return error.UnsupportedShape;
        break :blk effective_input_shape;
    };

    // Compute output shape.
    var out_shape: [8]i64 = undefined;
    var out_numel: usize = 1;
    var normalized_starts: [8]usize = undefined;
    var normalized_strides: [8]usize = undefined;
    for (0..rank) |d| {
        const dim = resolved_input_shape[d];
        if (dim < 0 or strides[d] <= 0) return error.UnsupportedShape;
        const slice = kernel_geometry.SliceAxis.init(true, dim, starts[d], limits[d], strides[d], input_shape[d] < 0) catch return error.UnsupportedShape;
        out_shape[d] = slice.size;
        out_numel = std.math.mul(usize, out_numel, @as(usize, @intCast(slice.size))) catch return error.UnsupportedShape;
        normalized_starts[d] = slice.start;
        normalized_strides[d] = slice.stride;
    }
    var in_strides: [8]usize = undefined;
    computeStrides(resolved_input_shape, in_strides[0..rank]);
    var out_strides: [8]usize = undefined;
    computeStrides(out_shape[0..rank], out_strides[0..rank]);

    var owned_output = try OwnedDenseOutput.alloc(self, out_numel);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    for (0..out_numel) |flat_out| {
        var remaining = flat_out;
        var flat_in: usize = 0;
        for (0..rank) |d| {
            const out_coord = remaining / out_strides[d];
            remaining %= out_strides[d];
            const in_coord = normalized_starts[d] + out_coord * normalized_strides[d];
            flat_in += in_coord * in_strides[d];
        }
        if (flat_in >= in_data.len) return error.ShapeMismatch;
        output[flat_out] = in_data[flat_in];
    }
    const result = try owned_output.intoResult();
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, out_shape[0..rank]);
}

fn primConcatPrimOp(ctx: *anyopaque, a: CT, b: CT, axis: u8, a_shape: []const i64, b_shape: []const i64) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const a_view = try denseTensorView(self, a);
    defer a_view.deinit(self.allocator);
    const b_view = try denseTensorView(self, b);
    defer b_view.deinit(self.allocator);
    const a_data = a_view.data;
    const b_data = b_view.data;
    const effective_a_shape_raw = storedOrDeclaredShape(a, a_shape);
    const effective_b_shape_raw = storedOrDeclaredShape(b, b_shape);
    const effective_a_shape = if (effective_a_shape_raw.len != effective_b_shape_raw.len and a_shape.len == b_shape.len) a_shape else effective_a_shape_raw;
    const effective_b_shape = if (effective_a_shape_raw.len != effective_b_shape_raw.len and a_shape.len == b_shape.len) b_shape else effective_b_shape_raw;
    var resolved_a_shape_buf: [8]i64 = undefined;
    var resolved_b_shape_buf: [8]i64 = undefined;
    const resolved_a_shape = if (resolveShapeFromTensorMetadata(a, effective_a_shape, a_data.len)) |resolved| blk: {
        resolved_a_shape_buf = resolved;
        break :blk resolved_a_shape_buf[0..effective_a_shape.len];
    } else if (resolveConcatShapeFromDataLen(effective_a_shape, axis, a_data.len)) |resolved| blk: {
        resolved_a_shape_buf = resolved;
        break :blk resolved_a_shape_buf[0..effective_a_shape.len];
    } else effective_a_shape;
    const resolved_b_shape = if (resolveShapeFromTensorMetadata(b, effective_b_shape, b_data.len)) |resolved| blk: {
        resolved_b_shape_buf = resolved;
        break :blk resolved_b_shape_buf[0..effective_b_shape.len];
    } else if (resolveConcatShapeFromDataLen(effective_b_shape, axis, b_data.len)) |resolved| blk: {
        resolved_b_shape_buf = resolved;
        break :blk resolved_b_shape_buf[0..effective_b_shape.len];
    } else effective_b_shape;
    const rank = resolved_a_shape.len;

    if (rank == 1 and axis == 0) {
        var owned_output = try OwnedDenseOutput.alloc(self, a_data.len + b_data.len);
        defer owned_output.deinit();
        const out = owned_output.storage.?;
        @memcpy(out[0..a_data.len], a_data);
        @memcpy(out[a_data.len..][0..b_data.len], b_data);
        const result = try owned_output.intoResult();
        errdefer freeTensor(self, result);
        const out_shape = [_]i64{@intCast(a_data.len + b_data.len)};
        return self.withLogicalShape(result, &out_shape);
    }

    // Compute output shape.
    var out_shape: [8]i64 = undefined;
    for (0..rank) |d| {
        if (d == axis) {
            out_shape[d] = resolved_a_shape[d] + resolved_b_shape[d];
        } else if (resolved_a_shape[d] == resolved_b_shape[d]) {
            out_shape[d] = resolved_a_shape[d];
        } else if (resolved_a_shape[d] == 1) {
            out_shape[d] = resolved_b_shape[d];
        } else if (resolved_b_shape[d] == 1) {
            out_shape[d] = resolved_a_shape[d];
        } else {
            out_shape[d] = resolved_a_shape[d];
        }
    }

    if (axis == 0) {
        const inner = if (rank > 1) safeShapeNumel(resolved_a_shape[1..]) orelse return error.UnsupportedShape else 1;
        if (inner == 0) return error.UnsupportedShape;
        if (a_data.len % inner != 0 or b_data.len % inner != 0) return error.UnsupportedShape;
        out_shape[0] = @intCast((a_data.len + b_data.len) / inner);
        var owned_output = try OwnedDenseOutput.alloc(self, a_data.len + b_data.len);
        defer owned_output.deinit();
        const out = owned_output.storage.?;
        @memcpy(out[0..a_data.len], a_data);
        @memcpy(out[a_data.len..][0..b_data.len], b_data);
        const result = try owned_output.intoResult();
        errdefer freeTensor(self, result);
        return self.withLogicalShape(result, out_shape[0..rank]);
    }

    const a_layout = resolveConcatLayout(resolved_a_shape, axis, a_data.len) orelse {
        std.log.warn("concat layout unresolved axis={d} a_shape={any} b_shape={any} a_len={d} b_len={d}", .{
            axis,
            resolved_a_shape,
            resolved_b_shape,
            a_data.len,
            b_data.len,
        });
        return error.UnsupportedShape;
    };
    const b_layout = resolveConcatLayout(resolved_b_shape, axis, b_data.len) orelse {
        std.log.warn("concat layout unresolved axis={d} a_shape={any} b_shape={any} a_len={d} b_len={d}", .{
            axis,
            resolved_a_shape,
            resolved_b_shape,
            a_data.len,
            b_data.len,
        });
        return error.UnsupportedShape;
    };
    if (a_layout.outer != b_layout.outer or a_layout.inner != b_layout.inner) {
        const generic_result = concatWithResolvedBroadcastShapes(self, a, b, axis, resolved_a_shape, resolved_b_shape, out_shape[0..rank]) catch |err| switch (err) {
            error.InvalidTensorShape, error.UnsupportedShape => null,
            else => return err,
        };
        if (generic_result) |result| {
            return result;
        }
        if (a_layout.inner == b_layout.inner and (a_layout.outer == 1 or b_layout.outer == 1)) {
            const outer = @max(a_layout.outer, b_layout.outer);
            const a_chunk = a_layout.axis_size * a_layout.inner;
            const b_chunk = b_layout.axis_size * b_layout.inner;
            const out_chunk = (a_layout.axis_size + b_layout.axis_size) * a_layout.inner;
            var owned_output = try OwnedDenseOutput.alloc(self, outer * out_chunk);
            defer owned_output.deinit();
            const output = owned_output.storage.?;
            for (0..outer) |o| {
                const a_src = if (a_layout.outer == 1) 0 else o * a_chunk;
                const b_src = if (b_layout.outer == 1) 0 else o * b_chunk;
                @memcpy(output[o * out_chunk ..][0..a_chunk], a_data[a_src..][0..a_chunk]);
                @memcpy(output[o * out_chunk + a_chunk ..][0..b_chunk], b_data[b_src..][0..b_chunk]);
            }
            const result = try owned_output.intoResult();
            errdefer freeTensor(self, result);
            if (resolveShapeFromDataLen(out_shape[0..rank], output.len)) |resolved_out_shape| {
                return self.withLogicalShape(result, resolved_out_shape[0..rank]);
            }
            return self.withLogicalShape(result, out_shape[0..rank]);
        }
        if (allKnownDimsAreOne(resolved_a_shape) and allKnownDimsAreOne(resolved_b_shape)) {
            var owned_output = try OwnedDenseOutput.alloc(self, a_data.len + b_data.len);
            defer owned_output.deinit();
            const out = owned_output.storage.?;
            @memcpy(out[0..a_data.len], a_data);
            @memcpy(out[a_data.len..][0..b_data.len], b_data);
            const result = try owned_output.intoResult();
            errdefer freeTensor(self, result);
            const flat_out_shape = [_]i64{@intCast(a_data.len + b_data.len)};
            return self.withLogicalShape(result, &flat_out_shape);
        }
        std.log.warn("concat layout mismatch axis={d} a_shape={any} b_shape={any} a_len={d} b_len={d} a_layout={any} b_layout={any}", .{
            axis,
            resolved_a_shape,
            resolved_b_shape,
            a_data.len,
            b_data.len,
            a_layout,
            b_layout,
        });
        return error.ShapeMismatch;
    }
    const out_numel = a_data.len + b_data.len;

    // For concat, we copy chunks along the concat axis.
    // Compute the "outer" (before axis), "inner" (after axis) sizes.
    const geometry = kernel_geometry.ConcatAxis{ .outer = a_layout.outer, .inner = a_layout.inner, .a_axis = a_layout.axis_size, .b_axis = b_layout.axis_size };
    const outer = geometry.outer;
    const inner = geometry.inner;
    const a_axis = geometry.a_axis;
    const b_axis = geometry.b_axis;
    if (try geometry.count() != out_numel) return error.ShapeMismatch;

    var owned_output = try OwnedDenseOutput.alloc(self, out_numel);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    for (0..outer) |o| {
        const a_chunk = a_axis * inner;
        const b_chunk = b_axis * inner;
        const out_chunk = (a_axis + b_axis) * inner;
        @memcpy(output[o * out_chunk ..][0..a_chunk], a_data[o * a_chunk ..][0..a_chunk]);
        @memcpy(output[o * out_chunk + a_chunk ..][0..b_chunk], b_data[o * b_chunk ..][0..b_chunk]);
    }
    const result = try owned_output.intoResult();
    errdefer freeTensor(self, result);
    if (resolveShapeFromDataLen(out_shape[0..rank], out_numel)) |resolved_out_shape| {
        return self.withLogicalShape(result, resolved_out_shape[0..rank]);
    }
    if (safeShapeNumel(out_shape[0..rank]) != null) {
        return self.withLogicalShape(result, out_shape[0..rank]);
    }
    return result;
}

/// Shared numerical loop for allocating and assigned-output execution.
fn softmaxInto(data: []const f32, output: []f32, geometry: kernel_geometry.DenseRows) void {
    const d = geometry.width;
    const rows = geometry.rows;
    for (0..rows) |r| {
        const row = data[r * d ..][0..d];
        const out = output[r * d ..][0..d];

        // Find max for numerical stability.
        var max_val: f32 = -std.math.inf(f32);
        for (row) |v| max_val = @max(max_val, v);

        // exp(x - max) and sum.
        var sum: f32 = 0;
        for (out, row) |*o, v| {
            o.* = @exp(v - max_val);
            sum += o.*;
        }

        // Normalize.
        const inv_sum = 1.0 / sum;
        for (out) |*o| o.* *= inv_sum;
    }
}

fn primSoftmaxOp(ctx: *anyopaque, input: CT, dim: u32) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const data = getData(input);
    const d = resolveSoftmaxLastDim(input, dim) orelse return error.InvalidTensorShape;
    const geometry = kernel_geometry.DenseRows.init(data.len, d) catch return error.InvalidTensorShape;
    var owned_output = try OwnedDenseOutput.alloc(self, data.len);
    defer owned_output.deinit();
    const output = owned_output.storage.?;

    softmaxInto(data, output, geometry);
    return owned_output.intoLike(input);
}

fn softmaxConsumeOp(_: *anyopaque, input: CT, dim: u32) anyerror!?CT {
    const buf = ownedDenseBufWithMaxSharedRefs(input, 2) orelse return null;
    const d = resolveSoftmaxLastDim(input, dim) orelse return error.InvalidTensorShape;
    const geometry = kernel_geometry.DenseRows.init(buf.data.len, d) catch return error.InvalidTensorShape;
    activations_mod.softmax(buf.data, geometry.width);
    return input;
}

fn primLogSoftmaxOp(ctx: *anyopaque, input: CT, dim: u32) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const data = getData(input);
    const d = resolveSoftmaxLastDim(input, dim) orelse return error.InvalidTensorShape;
    const geometry = kernel_geometry.DenseRows.init(data.len, d) catch return error.InvalidTensorShape;
    var owned_output = try OwnedDenseOutput.copy(self, data);
    defer owned_output.deinit();
    const output = owned_output.storage.?;
    activations_mod.logSoftmaxInPlace(output, geometry.width);
    return owned_output.intoLike(input);
}

fn logSoftmaxConsumeOp(_: *anyopaque, input: CT, dim: u32) anyerror!?CT {
    const buf = ownedDenseBufWithMaxSharedRefs(input, 2) orelse return null;
    const d = resolveSoftmaxLastDim(input, dim) orelse return error.InvalidTensorShape;
    const geometry = kernel_geometry.DenseRows.init(buf.data.len, d) catch return error.InvalidTensorShape;
    activations_mod.logSoftmaxInPlace(buf.data, geometry.width);
    return input;
}

fn fromFloat32Op(ctx: *anyopaque, data: []const f32) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const owned = try self.allocator.dupe(f32, data);
    errdefer self.allocator.free(owned);
    return self.makeBuf(owned, true);
}

fn bceSigmoid(x: f32) f32 {
    return if (x >= 0) 1.0 / (1.0 + @exp(-x)) else blk: {
        const e = @exp(x);
        break :blk e / (1.0 + e);
    };
}

fn maskedBceWithLogitsLossOp(ctx: *anyopaque, request: *const ops.MaskedBceWithLogitsRequest) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const logits = getData(request.logits);
    const labels = getData(request.labels);
    const mask = getData(request.mask);
    if (labels.len != logits.len or mask.len != logits.len) return error.ShapeMismatch;

    var numerator: f32 = 0.0;
    var denom: f32 = 0.0;
    for (logits, 0..) |logit, i| {
        const m = mask[i];
        // `mask` is a per-position loss weight (validity gate for m==0, and a real
        // weight for m>0 — e.g. hard-negative weighting). It must NOT scale the
        // logit/label into the BCE: BCE runs on the raw logit, and m weights the
        // resulting loss + reduction denominator. (For m in {0,1} this is identical
        // to the previous logit*m form, so 0/1-mask parity is unchanged.) Skip m==0
        // so a non-finite masked logit (Inf*0 = NaN) cannot poison the scalar loss.
        if (m == 0) continue;
        const label = labels[i];
        const bce = @max(logit, 0.0) - label * logit + @log(1.0 + @exp(-@abs(logit)));
        const label_weight = label * request.positive_weight + (1.0 - label) * request.negative_weight;
        numerator += bce * label_weight * m;
        denom += m * label_weight;
    }

    const value = if (request.mean_reduction) numerator / (denom + request.eps) else numerator;
    const output = try self.allocator.alloc(f32, 1);
    output[0] = value;
    const result = try self.makeOwnedBuf(output);
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, request.output_shape);
}

fn maskedBceWithLogitsBackwardOp(ctx: *anyopaque, request: *const ops.MaskedBceWithLogitsBackwardRequest) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const logits = getData(request.logits);
    const labels = getData(request.labels);
    const mask = getData(request.mask);
    const upstream = getData(request.upstream);
    if (labels.len != logits.len or mask.len != logits.len or upstream.len == 0) return error.ShapeMismatch;

    var denom: f32 = 0.0;
    if (request.mean_reduction) {
        for (labels, 0..) |label, i| {
            const m = mask[i];
            if (m == 0) continue;
            const label_weight = label * request.positive_weight + (1.0 - label) * request.negative_weight;
            denom += m * label_weight;
        }
        denom += request.eps;
    }

    const scale = if (request.mean_reduction) upstream[0] / denom else upstream[0];
    const output = try self.allocator.alloc(f32, logits.len);
    var raw_output: ?[]f32 = output;
    errdefer if (raw_output) |raw| self.allocator.free(raw);
    for (logits, 0..) |logit, i| {
        const m = mask[i];
        // Masked positions have zero gradient; write 0 explicitly (output is
        // freshly allocated, not zeroed) and skip the arithmetic so a non-finite
        // masked logit (Inf*0 = NaN) cannot leak into the gradient.
        if (m == 0) {
            output[i] = 0;
            continue;
        }
        // Gradient of the raw-logit forward: d/dlogit [ m * label_weight * BCE(logit) ]
        // = m * label_weight * (sigmoid(logit) - label). Matches the forward's use of
        // the raw logit with m as a pure loss weight (identical to the old form at m==1).
        const label = labels[i];
        const label_weight = label * request.positive_weight + (1.0 - label) * request.negative_weight;
        output[i] = scale * label_weight * m * (bceSigmoid(logit) - label);
    }
    const result = try self.makeBuf(output, true);
    raw_output = null;
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, request.logits_shape);
}

fn fromBorrowedFloat32ShapeOp(ctx: *anyopaque, data: []const f32, shape: []const i32) !CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const result = try self.makeBuf(@constCast(data), false);
    errdefer freeTensor(self, result);
    var logical: [8]i64 = undefined;
    if (shape.len == 0 or shape.len > logical.len) return error.InvalidTensorShape;
    for (shape, logical[0..shape.len]) |dim, *dest| dest.* = dim;
    return self.withLogicalShape(result, logical[0..shape.len]);
}
fn hostFloat32ReadOp(_: *anyopaque, tensor: CT) !?[]const f32 {
    const buf = toBuf(tensor);
    if (buf.view_strides != null or buf.source_tensor != null or buf.quantized_storage != null or buf.data.len == 0) return null;
    return try getDataChecked(tensor);
}
fn hostFloat32WriteOp(ctx: *anyopaque, tensor: CT) !?[]f32 {
    const buf = toBuf(tensor);
    if (!buf.owned or buf.tensor_refs != 1 or buf.retained_parent != null or buf.lazy_entry != null or buf.weight_handle_name != null or (buf.shared_data_refcount != null and buf.shared_data_refcount.?.* != 1)) return null;
    return if (try hostFloat32ReadOp(ctx, tensor)) |data| @constCast(data) else null;
}

fn fromFloat32ShapeOp(ctx: *anyopaque, data: []const f32, shape: []const i32) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const owned = try self.allocator.dupe(f32, data);
    errdefer self.allocator.free(owned);
    const logical_shape = try self.allocator.alloc(i64, shape.len);
    errdefer self.allocator.free(logical_shape);
    for (shape, 0..) |dim, i| logical_shape[i] = dim;

    const buf = try self.makeBuf(owned, true);
    toBuf(buf).logical_shape = logical_shape;
    return buf;
}

fn convertDTypeOp(ctx: *anyopaque, input: CT, target: ops.GraphDType) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const source = integerSource(input);
    const target_integer = switch (target) {
        .i8, .i16, .i32, .i64, .u8, .bool_ => true,
        else => false,
    };
    if (!target_integer) {
        if (source == null) return null;
        const data = try convertTensorToOwnedF32(self.allocator, source.?);
        const output = try self.makeOwnedBuf(data);
        errdefer self.computeBackend().free(output);
        return self.withLogicalShape(output, source.?.shape);
    }
    const floats = if (source == null) try getDataChecked(input) else &.{};
    const count = if (source) |tensor| try integerTensorCount(tensor) else floats.len;
    const fallback = [_]i64{@intCast(count)};
    const shape = tensorStoredShape(input) orelse &fallback;
    const bytes = try self.allocator.alloc(u8, try std.math.mul(usize, count, target.byteSize()));
    defer self.allocator.free(bytes);
    const reader = if (source != null) try IndexReader.init(input) else null;
    for (0..count) |i| {
        var value: i64 = undefined;
        if (reader) |exact| {
            value = try exact.at(i);
        } else {
            const f: f64 = floats[i];
            if (target == .bool_) {
                bytes[i] = @intFromBool(f != 0);
                continue;
            }
            if (!std.math.isFinite(f) or f < -9223372036854775808.0 or f >= 9223372036854775808.0) return error.InvalidIntegerCast;
            value = @intFromFloat(f);
        }
        switch (target) {
            .i8, .u8 => bytes[i] = @truncate(@as(u64, @bitCast(value))),
            .i16 => std.mem.writeInt(u16, bytes[i * 2 ..][0..2], @truncate(@as(u64, @bitCast(value))), .little),
            .i32 => std.mem.writeInt(u32, bytes[i * 4 ..][0..4], @truncate(@as(u64, @bitCast(value))), .little),
            .i64 => std.mem.writeInt(i64, bytes[i * 8 ..][0..8], value, .little),
            .bool_ => bytes[i] = @intFromBool(value != 0),
            else => unreachable,
        }
    }
    return fromConstantBytesOp(ctx, bytes, target, shape);
}

fn fromConstantBytesOp(ctx: *anyopaque, data: []const u8, dtype: ops.GraphDType, shape: []const i64) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const storage_dtype: tensor_mod.DType = switch (dtype) {
        inline .i8, .i16, .i32, .i64, .u8, .bool_ => |tag| @field(tensor_mod.DType, @tagName(tag)),
        else => return null,
    };
    if (shape.len > 8) return error.InvalidTensorShape;
    const count = typedShapeNumel(shape) orelse return error.InvalidTensorShape;
    if (data.len != try storage_dtype.byteCount(count)) return error.InvalidTensorShape;
    const raw = try self.allocator.dupe(u8, data);
    var transferred = false;
    errdefer if (!transferred) self.allocator.free(raw);
    const owned_shape = try self.allocator.dupe(i64, shape);
    transferred = true;
    return self.makeBufWithOwnedSourceTensor(.{ .data = raw, .dtype = storage_dtype, .shape = owned_shape, .name = "", .allocator = self.allocator, .owns_data = true, .owns_shape = true });
}

fn fromInt32ShapeOp(ctx: *anyopaque, data: []const i32, shape: []const i32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (shape.len > 8) return error.InvalidShape;
    var logical_shape: [8]i64 = undefined;
    for (shape, 0..) |dim, index| logical_shape[index] = dim;
    if ((typedShapeNumel(logical_shape[0..shape.len]) orelse return error.InvalidShape) != data.len) return error.InvalidShape;
    const tensor = try tensor_mod.Tensor.initInt32(self.allocator, "", logical_shape[0..shape.len], data);
    return try self.makeBufWithOwnedSourceTensor(tensor);
}

/// Host segment-masked attention over token-major Q/K/V (no staging copies).
fn segmentAttentionOp(ctx: *anyopaque, q: CT, k: CT, v: CT, request: *const ops.SegmentAttention) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const q_values = try getDataChecked(q);
    const k_values = try getDataChecked(k);
    const v_values = try getDataChecked(v);
    const short = if (!self.cache_embeddinggemma2_bf16_weights and !platform.env.getenvBool("ANTFLY_INFERENCE_DISABLE_SHORT_SEGMENT_ATTENTION"))
        try @import("short_segment_attention.zig").execute(self.allocator, self.io, q_values, k_values, v_values, request)
    else
        null;
    // The immutable weight-cache grant identifies EmbeddingGemma2 sessions.
    // Wider tiles amortize BLAS calls for moderate inputs and global heads;
    // long 256-dimensional sliding heads keep their narrower work ranges.
    const wide = self.cache_embeddinggemma2_bf16_weights and request.queries >= 256 and
        (request.queries <= 512 or request.head_dim == 512);
    const out = short orelse if (wide and request.keys > 512)
        try segmentAttentionForSession(native.WideSegmentAttentionGemm(1024), self, q_values, k_values, v_values, request)
    else if (wide)
        try segmentAttentionForSession(native.WideSegmentAttentionGemm(512), self, q_values, k_values, v_values, request)
    else
        try segmentAttentionForSession(native.SegmentAttentionGemm, self, q_values, k_values, v_values, request);
    const result = try self.makeOwnedBuf(out);
    errdefer freeTensor(self, result);
    return try self.withLogicalShape(result, &.{ @intCast(request.queries), @intCast(request.num_heads * request.head_dim) });
}

fn segmentAttentionGroupedOp(ctx: *anyopaque, q: CT, k: CT, v: CT, request: *const ops.SegmentAttentionGrouped) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const r = request.visibility;
    if (request.control) |control| try control.check();
    const hidden = try std.math.mul(usize, r.num_heads, r.head_dim);
    const output_count = try std.math.mul(usize, r.queries, hidden);
    const head_scratch = try std.math.mul(usize, try std.math.add(usize, r.queries, r.keys), try std.math.mul(usize, r.head_dim, 2));
    const bytes = try std.math.mul(usize, try std.math.add(usize, try std.math.add(usize, output_count, head_scratch), 512 * 1024), @sizeOf(f32));
    if (bytes > request.workspace_limit_bytes) return null;
    const out = if (r.queries >= 256 and (r.queries <= 512 or r.head_dim == 512))
        try groupedAttentionForSession(native.WideSegmentAttentionGemm(1024), self, q, k, v, request)
    else
        try groupedAttentionForSession(native.SegmentAttentionGemm, self, q, k, v, request);
    const result = try self.makeOwnedBuf(out);
    errdefer freeTensor(self, result);
    if (request.control) |control| try control.check();
    return try self.withLogicalShape(result, &.{ @intCast(r.queries), @intCast(hidden) });
}
fn groupedAttentionForSession(comptime Gemm: type, self: *NativeCompute, q: CT, k: CT, v: CT, request: *const ops.SegmentAttentionGrouped) ![]f32 {
    const r = request.visibility;
    // Portable head workers own parallelism. BLAS keeps its own GEMM scheduler.
    const scratch = (r.queries * r.num_heads * r.head_dim * 3 + r.keys * request.num_kv_heads * r.head_dim * 2 + r.num_heads * 128 * 512) * @sizeOf(f32);
    if (!native.useBlas() and self.io != null and r.queries >= 128 and r.num_heads <= 4 and scratch <= request.workspace_limit_bytes) {
        const Portable = struct {
            pub const query_block = 128;
            pub const key_block = 512;
            pub const sgemmSync = linalg.sgemmSequential;
            pub const sgemmTransBSync = linalg.sgemmTransBSequential;
        };
        return linalg.segmentAttentionGroupedHostWithGemmParallelIo(Portable, self.allocator, self.io.?, try getDataChecked(q), try getDataChecked(k), try getDataChecked(v), r.ranges, r.query_positions, r.key_positions, r.window, r.queries, r.keys, r.num_heads, request.num_kv_heads, r.head_dim, request.score_scale);
    }
    return linalg.segmentAttentionGroupedHostWithGemmIo(Gemm, self.allocator, self.io, try getDataChecked(q), try getDataChecked(k), try getDataChecked(v), r.ranges, r.query_positions, r.key_positions, r.window, r.queries, r.keys, r.num_heads, request.num_kv_heads, r.head_dim, request.score_scale);
}

fn segmentAttentionForSession(comptime Gemm: type, self: *NativeCompute, q: []const f32, k: []const f32, v: []const f32, request: *const ops.SegmentAttention) ![]f32 {
    // Parallel heads remain bounded to the qualified moderate embedding shapes.
    // Each job owns separate scratch; all allocation/accounting stays on this
    // thread. Short and long inputs keep the sequential schedule and footprint.
    if (self.cache_embeddinggemma2_bf16_weights and self.io != null and native.useBlas() and
        request.queries >= 128 and request.queries <= 512 and request.keys <= 512 and
        request.num_heads >= 2 and request.num_heads <= 4)
    {
        return linalg.segmentAttentionHostWithGemmParallelIo(Gemm, self.allocator, self.io.?, q, k, v, request.ranges, request.query_positions, request.key_positions, request.window, request.queries, request.keys, request.num_heads, request.head_dim);
    }
    return linalg.segmentAttentionHostWithGemmSerialIo(Gemm, self.allocator, self.io, q, k, v, request.ranges, request.query_positions, request.key_positions, request.window, request.queries, request.keys, request.num_heads, request.head_dim);
}

test "embeddinggemma2 CPU adaptive segment tiles preserve generic masks empty rows and independent attention" {
    const a = std.testing.allocator;
    const queries = 257;
    const heads = 2;
    const dim = 8;
    const hidden = heads * dim;
    var store = WeightStore{ .allocator = a, .resident_weights = .{}, .lazy_weights = .{} };
    defer store.resident_weights.deinit(a);
    var compute = NativeCompute.init(a, &store, null);
    compute.io = std.testing.io;
    defer compute.deinit();
    const q_values = try a.alloc(f32, queries * hidden);
    defer a.free(q_values);
    for (q_values, 0..) |*value, i| value.* = @sin(@as(f32, @floatFromInt(i % 53))) * 0.3;
    const q = try fromFloat32ShapeOp(&compute, q_values, &.{ queries, hidden });
    defer freeTensor(&compute, q);
    var q_positions: [queries]i32 = undefined;
    var ranges: [queries * 6]u32 = undefined;
    for (&q_positions, 0..) |*position, i| position.* = @as(i32, @intCast(i % 23)) - 11;
    for ([_]usize{ 511, 1031 }) |keys| {
        const k_values = try a.alloc(f32, keys * hidden);
        defer a.free(k_values);
        const v_values = try a.alloc(f32, k_values.len);
        defer a.free(v_values);
        for (k_values, v_values, 0..) |*key, *value, i| {
            key.* = @cos(@as(f32, @floatFromInt(i % 47))) * 0.25;
            value.* = @as(f32, @floatFromInt(@as(i32, @intCast(i % 37)) - 18)) / 19;
        }
        const k = try fromFloat32ShapeOp(&compute, k_values, &.{ @intCast(keys), hidden });
        defer freeTensor(&compute, k);
        const v = try fromFloat32ShapeOp(&compute, v_values, &.{ @intCast(keys), hidden });
        defer freeTensor(&compute, v);
        const k_positions = try a.alloc(i32, keys);
        defer a.free(k_positions);
        for (k_positions, 0..) |*position, i| position.* = @as(i32, @intCast(i % 29)) - 14;
        for (0..queries) |i| {
            ranges[i * 6 ..][0..6].* = if (i % 11 == 0)
                .{ 0, 0, 0, 0, 0, 0 }
            else if (i % 3 == 0)
                .{ @intCast(keys - 137), @intCast(keys), 0, 83, 61, 157 }
            else
                .{ 83, 157, 0, 83, 137, @intCast(keys) };
        }
        for ([_]u32{ std.math.maxInt(u32), 3 }) |window| {
            const expected = try linalg.segmentAttentionHost(a, q_values, k_values, v_values, &ranges, &q_positions, k_positions, window, queries, keys, heads, dim);
            defer a.free(expected);
            for ([_]bool{ false, true }) |embeddinggemma2| {
                compute.cache_embeddinggemma2_bf16_weights = embeddinggemma2;
                const output = (try segmentAttentionOp(&compute, q, k, v, &.{ .ranges = &ranges, .query_positions = &q_positions, .key_positions = k_positions, .window = window, .queries = queries, .keys = keys, .num_heads = heads, .head_dim = dim })) orelse return error.ExpectedSegmentAttention;
                defer freeTensor(&compute, output);
                const actual = try getDataChecked(output);
                for (actual, expected) |value, reference| try std.testing.expectApproxEqAbs(reference, value, 1e-5);
                for (0..queries) |i| if (i % 11 == 0) {
                    for (actual[i * hidden ..][0..hidden]) |value| try std.testing.expectEqual(@as(f32, 0), value);
                };
            }
        }
    }
}

test "embeddinggemma2 CPU segment attention output transfer frees data on allocation failure" {
    const Case = struct {
        fn run(a: std.mem.Allocator) !void {
            const queries = 128;
            const keys = 7;
            const heads = 2;
            const dim = 3;
            const hidden = heads * dim;
            var store = WeightStore{ .allocator = a, .resident_weights = .{}, .lazy_weights = .{} };
            defer store.resident_weights.deinit(a);
            var compute = NativeCompute.init(a, &store, null);
            compute.io = std.testing.io;
            compute.cache_embeddinggemma2_bf16_weights = true;
            defer compute.deinit();
            var q_data: [queries * hidden]f32 = @splat(0.25);
            var k_data: [keys * hidden]f32 = @splat(-0.5);
            var v_data: [keys * hidden]f32 = @splat(0.75);
            const q = try compute.makeBuf(&q_data, false);
            defer freeTensor(&compute, q);
            const k = try compute.makeBuf(&k_data, false);
            defer freeTensor(&compute, k);
            const v = try compute.makeBuf(&v_data, false);
            defer freeTensor(&compute, v);
            const q_positions: [queries]i32 = @splat(0);
            const k_positions: [keys]i32 = @splat(0);
            var ranges: [queries * 6]u32 = undefined;
            for (0..queries) |i| ranges[i * 6 ..][0..6].* = .{ 0, keys, 0, 0, 0, 0 };
            const output = (try segmentAttentionOp(&compute, q, k, v, &.{ .ranges = &ranges, .query_positions = &q_positions, .key_positions = &k_positions, .window = std.math.maxInt(u32), .queries = queries, .keys = keys, .num_heads = heads, .head_dim = dim })) orelse return error.ExpectedSegmentAttention;
            defer freeTensor(&compute, output);
            for (try getDataChecked(output)) |value| try std.testing.expectApproxEqAbs(@as(f32, 0.75), value, 1e-6);
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Case.run, .{});
}

fn retainImmutableTensorOp(_: *anyopaque, tensor: CT) anyerror!?CT {
    const source = toBuf(tensor);
    source.tensor_refs = try std.math.add(usize, source.tensor_refs, 1);
    return tensor;
}

fn cloneTensorShapeOp(ctx: *anyopaque, input: CT, shape: []const i32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const source = integerSource(input) orelse return null;
    if (shape.len > 8) return error.InvalidShape;
    var logical_shape: [8]i64 = undefined;
    for (shape, 0..) |dim, index| logical_shape[index] = dim;
    return try copyIntegerTensorWithShape(self, source, logical_shape[0..shape.len]);
}

fn readFloat32IntoOp(ctx: *anyopaque, tensor: CT, output: []f32) anyerror!bool {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const source = toBuf(tensor);
    if (source.quantized_storage != null or source.lazy_entry != null) return false;
    const view = try denseTensorView(self, tensor);
    defer view.deinit(self.allocator);
    if (output.len != view.data.len) return error.InvalidTensorShape;
    @memcpy(output, view.data);
    return true;
}

fn toFloat32Op(ctx: *anyopaque, tensor: CT, allocator: std.mem.Allocator) anyerror![]f32 {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const buf = toBuf(tensor);
    if (buf.data.len != 0 or buf.view_strides != null) return allocator.dupe(f32, try getDataChecked(tensor));
    if (buf.source_tensor) |source| return convertTensorToOwnedF32(allocator, source);
    if (buf.quantized_storage) |storage| {
        var elem_count: usize = 1;
        for (storage.shape) |dim| {
            if (dim <= 0) return error.UnsupportedShape;
            elem_count *= @as(usize, @intCast(dim));
        }
        const out = try allocator.alloc(f32, elem_count);
        try quant_codec.dequantizeToFloat32(storage.tensor_type, storage.raw_bytes, out);
        return out;
    }
    if (buf.lazy_entry) |entry| {
        if (entry.loaded) |*loaded| {
            if (loaded.quantized_storage) |*storage| {
                var elem_count: usize = 1;
                for (storage.shape) |dim| {
                    if (dim <= 0) return error.UnsupportedShape;
                    elem_count *= @as(usize, @intCast(dim));
                }
                const out = try allocator.alloc(f32, elem_count);
                try quant_codec.dequantizeToFloat32(storage.tensor_type, storage.raw_bytes, out);
                return out;
            }
            return convertTensorToOwnedF32(allocator, &loaded.tensor);
        }

        self.data.prefetch.lock();
        defer self.data.prefetch.unlock();
        try ensureLazyWeightLoadedLocked(self.data, self.run_budget, entry);
        if (entry.loaded) |*loaded| {
            if (loaded.quantized_storage) |*storage| {
                var elem_count: usize = 1;
                for (storage.shape) |dim| {
                    if (dim <= 0) return error.UnsupportedShape;
                    elem_count *= @as(usize, @intCast(dim));
                }
                const out = try allocator.alloc(f32, elem_count);
                try quant_codec.dequantizeToFloat32(storage.tensor_type, storage.raw_bytes, out);
                return out;
            }
            return convertTensorToOwnedF32(allocator, &loaded.tensor);
        }
    }
    if (buf.data.len == 0 and buf.name.len == 0) {
        return allocator.dupe(f32, buf.data);
    }
    return error.MissingWeight;
}

fn splitLastDim3Op(ctx: *anyopaque, input: CT, rows: usize, dim: usize) anyerror!ops.SplitLastDim3Result {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const total = std.math.mul(usize, rows, dim) catch return error.UnexpectedOutputShape;
    const input_total = std.math.mul(usize, total, 3) catch return error.UnexpectedOutputShape;
    const shape = [_]i64{
        std.math.cast(i64, rows) orelse return error.UnexpectedOutputShape,
        std.math.cast(i64, dim) orelse return error.UnexpectedOutputShape,
    };
    const data = try getDataChecked(input);
    if (data.len != input_total) return error.UnexpectedOutputShape;

    // Splitting preserves token-major [rows, dim] storage. In particular,
    // SDPA uses this shape to distinguish it from head-major input.
    var outputs: [3]CT = undefined;
    var initialized: usize = 0;
    errdefer for (outputs[0..initialized]) |output| freeTensor(self, output);
    for (&outputs, 0..) |*output, part| {
        const values = try self.allocator.alloc(f32, total);
        output.* = try self.makeOwnedBuf(values);
        initialized += 1;
        output.* = try self.withLogicalShape(output.*, &shape);
        for (0..rows) |row| {
            const src = row * dim * 3 + part * dim;
            @memcpy(values[row * dim ..][0..dim], data[src..][0..dim]);
        }
    }

    return .{
        .first = outputs[0],
        .second = outputs[1],
        .third = outputs[2],
    };
}

fn takeRowsOp(ctx: *anyopaque, request: *const ops.TakeRowsRequest) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (request.dim == 0 or request.rows != request.row_ids.len) return error.InvalidTensorShape;
    const input = toBuf(request.input);
    if (input.quantized_storage != null or (input.source_tensor != null and input.data.len == 0)) return null;
    if (input.view_strides != null) try materializeViewData(input);
    const data = input.data;
    if (data.len % request.dim != 0) return error.InvalidTensorShape;
    const total_rows = data.len / request.dim;
    for (request.row_ids) |row| {
        if (row >= total_rows) return error.InvalidTensorShape;
    }
    const count = std.math.mul(usize, request.rows, request.dim) catch return error.InvalidTensorShape;
    const shape = [_]i64{
        std.math.cast(i64, request.rows) orelse return error.InvalidTensorShape,
        std.math.cast(i64, request.dim) orelse return error.InvalidTensorShape,
    };
    const output = try self.allocator.alloc(f32, count);
    const tensor = try self.makeOwnedBuf(output);
    errdefer freeTensor(ctx, tensor);
    for (request.row_ids, 0..) |row, index| {
        @memcpy(output[index * request.dim ..][0..request.dim], data[@as(usize, row) * request.dim ..][0..request.dim]);
    }
    return try self.withLogicalShape(tensor, &shape);
}

test "Florence native row gather preserves row identity and independent storage" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();
    var data = [_]f32{ 1, 2, 3, 4, 5, 6 };
    const input = try compute.makeBuf(&data, false);
    defer freeTensor(&compute, input);
    const output = (try takeRowsOp(&compute, &.{
        .input = input,
        .row_ids = &.{ 2, 0, 2 },
        .rows = 3,
        .dim = 2,
    })).?;
    defer freeTensor(&compute, output);
    try std.testing.expectEqualSlices(f32, &.{ 5, 6, 1, 2, 5, 6 }, getData(output));
    getData(output)[0] = 99;
    try std.testing.expectEqual(@as(f32, 5), data[4]);
    try std.testing.expectError(error.InvalidTensorShape, takeRowsOp(&compute, &.{
        .input = input,
        .row_ids = &.{3},
        .rows = 1,
        .dim = 2,
    }));
}

fn allocUninitF32ShapeOp(ctx: *anyopaque, shape: []const i32) anyerror!?CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (shape.len == 0 or shape.len > 8) return error.InvalidTensorShape;
    var logical: [8]i64 = undefined;
    var count: usize = 1;
    for (shape, logical[0..shape.len]) |dim, *dest| {
        if (dim < 0) return error.InvalidTensorShape;
        dest.* = dim;
        count = try std.math.mul(usize, count, @intCast(dim));
    }
    const data = try self.allocator.alloc(f32, count);
    const tensor = try self.makeOwnedBuf(data);
    errdefer freeTensor(self, tensor);
    return self.withLogicalShape(tensor, logical[0..shape.len]);
}
fn copyRows2DOp(ctx: *anyopaque, dst: CT, dst_row: usize, src: CT, src_row: usize, rows: usize, cols: usize) anyerror!bool {
    _ = ctx;
    const target = toBuf(dst);
    // Never mutate immutable weight storage, strided views or shared aliases.
    if (!target.owned or target.source_tensor != null or target.view_strides != null or target.weight_handle_name != null or
        (target.shared_data_refcount != null and target.shared_data_refcount.?.* != 1)) return error.InvalidTensorShape;
    const source = try getDataChecked(src);
    const region = kernel_geometry.RowCopy.init(target.data.len, source.len, dst_row, src_row, rows, cols) catch |err| switch (err) {
        error.InvalidShape => return error.InvalidTensorShape,
        else => return err,
    };
    const output = target.data[region.destination..][0..region.elements];
    const input = source[region.source..][0..region.elements];
    if (@intFromPtr(output.ptr) > @intFromPtr(input.ptr)) std.mem.copyBackwards(f32, output, input) else std.mem.copyForwards(f32, output, input);
    return true;
}

fn concatRows2DOp(ctx: *anyopaque, a: CT, b: CT, rows_a: usize, rows_b: usize, cols: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const a_data = getData(a);
    const b_data = getData(b);
    if (a_data.len != rows_a * cols or b_data.len != rows_b * cols) return error.UnexpectedOutputShape;

    const out = try self.allocator.alloc(f32, (rows_a + rows_b) * cols);
    errdefer self.allocator.free(out);
    @memcpy(out[0..a_data.len], a_data);
    @memcpy(out[a_data.len..][0..b_data.len], b_data);
    return self.makeBuf(out, true);
}

fn sliceRows2DOp(ctx: *anyopaque, input: CT, start_row: usize, row_count: usize, cols: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const parent = toBuf(input);
    if (cols == 0) return error.UnexpectedOutputShape;
    const total_rows = if (parent.source_tensor) |source| @as(usize, @intCast(source.shape[0])) else @divExact(getData(input).len, cols);
    if (cols == 0 or start_row > total_rows or row_count > total_rows - start_row) return error.UnexpectedOutputShape;
    const view = if (parent.source_tensor) |source| blk: {
        if (source.shape.len != 2 or source.shape[1] != cols) return error.UnexpectedOutputShape;
        var tensor = source.borrowedView(source.name);
        const row_bytes = try source.dtype.byteCount(cols);
        tensor.data = source.data[start_row * row_bytes ..][0 .. row_count * row_bytes];
        tensor.shape = try self.allocator.dupe(i64, &.{ @intCast(row_count), @intCast(cols) });
        tensor.allocator = self.allocator;
        tensor.owns_data = false;
        tensor.owns_shape = true;
        break :blk try self.makeBufWithOwnedSourceTensor(tensor);
    } else try self.makeBuf(getData(input)[start_row * cols ..][0 .. row_count * cols], false);
    errdefer freeTensor(self, view);
    _ = try self.withLogicalShape(view, &.{ @intCast(row_count), @intCast(cols) });
    parent.tensor_refs += 1;
    toBuf(view).retained_parent = input;
    toBuf(view).name = parent.name;
    toBuf(view).source_row = parent.source_row + start_row;
    return view;
}

fn exportDenseTensorBytes(
    allocator: std.mem.Allocator,
    tensor: *const tensor_mod.Tensor,
) !?ops.ExportTensorData {
    const expected_bytes = tensorExpectedDenseByteLen(tensor) orelse return error.InvalidTensorShape;
    if (tensor.data.len != expected_bytes) return error.InvalidTensorShape;
    return switch (tensor.dtype) {
        .f32, .f16, .bf16, .f64, .i8, .i16, .i32, .i64, .u8, .bool_ => .{
            .dtype = tensor.dtype,
            .payload = .{ .bytes = try allocator.dupe(u8, tensor.data) },
        },
    };
}

fn tensorExpectedDenseByteLen(tensor: *const tensor_mod.Tensor) ?usize {
    var element_count: usize = 1;
    for (tensor.shape) |dim| {
        if (dim < 0) return null;
        element_count = std.math.mul(usize, element_count, @intCast(dim)) catch return null;
    }
    return tensor.dtype.byteCount(element_count) catch null;
}

fn exportQuantizedTensorStorage(
    allocator: std.mem.Allocator,
    storage: *const QuantizedStorage,
) !ops.ExportTensorData {
    return .{
        .dtype = .f32,
        .payload = .{
            .quantized_f32 = .{
                .tensor_type = storage.tensor_type,
                .raw_bytes = try allocator.dupe(u8, storage.raw_bytes),
                .shape = try allocator.dupe(i64, storage.shape),
            },
        },
    };
}

fn exportDenseTensorDType(tensor: *const tensor_mod.Tensor) tensor_mod.DType {
    return tensor.dtype;
}

fn exportTensorDataOp(ctx: *anyopaque, tensor: CT, allocator: std.mem.Allocator) anyerror!?ops.ExportTensorData {
    if (@intFromPtr(tensor) == 0) return error.InvalidTensorHandle;
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const buf = toBuf(tensor);

    if (buf.name.len > 0) {
        if (self.data.resident_weights.getPtr(buf.name)) |weight| {
            if (weight.quantized_storage) |*storage| {
                return try exportQuantizedTensorStorage(allocator, storage);
            }
            if (weight.tensor.data.len > 0) {
                return try exportDenseTensorBytes(allocator, &weight.tensor);
            }
        }

        self.data.prefetch.lock();
        defer self.data.prefetch.unlock();
        if (self.data.lazy_weights.getPtr(buf.name)) |entry| {
            if (entry.loaded) |*loaded| {
                if (loaded.quantized_storage) |*storage| {
                    return try exportQuantizedTensorStorage(allocator, storage);
                }
                if (loaded.tensor.data.len > 0) {
                    return try exportDenseTensorBytes(allocator, &loaded.tensor);
                }
            }
        }
    }

    if (buf.quantized_storage) |storage| {
        return try exportQuantizedTensorStorage(allocator, storage);
    }

    if (buf.source_tensor) |source| {
        return try exportDenseTensorBytes(allocator, source);
    }

    if (buf.data.len > 0) {
        const dense = try getDataChecked(tensor);
        return .{
            .dtype = .f32,
            .payload = .{ .bytes = try allocator.dupe(u8, std.mem.sliceAsBytes(dense)) },
        };
    }

    return null;
}

fn tensorDTypeOp(ctx: *anyopaque, tensor: CT) anyerror!tensor_mod.DType {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const buf = toBuf(tensor);

    if (buf.name.len > 0) {
        if (self.data.resident_weights.getPtr(buf.name)) |weight| {
            if (weight.tensor.data.len > 0) {
                return exportDenseTensorDType(&weight.tensor);
            }
        }

        self.data.prefetch.lock();
        defer self.data.prefetch.unlock();
        if (self.data.lazy_weights.getPtr(buf.name)) |entry| {
            if (entry.loaded) |*loaded| {
                if (loaded.tensor.data.len > 0) {
                    return exportDenseTensorDType(&loaded.tensor);
                }
            }
        }
    }

    if (buf.source_tensor) |source| return exportDenseTensorDType(source);
    if (buf.declared_dtype) |dtype| return dtype;
    if (buf.data.len > 0) return .f32;
    if (buf.quantized_storage != null) return .f32;
    return error.UnsupportedTensorType;
}

fn tensorShapeOp(_: *anyopaque, tensor: CT, allocator: std.mem.Allocator) anyerror![]i64 {
    const buf = toBuf(tensor);
    if (buf.logical_shape) |shape| return allocator.dupe(i64, shape);
    if (buf.quantized_storage) |storage| return allocator.dupe(i64, storage.shape);
    if (buf.source_tensor) |source| return allocator.dupe(i64, source.shape);
    if (buf.lazy_entry) |entry| {
        if (entry.loaded) |*loaded| {
            if (loaded.quantized_storage) |*storage| return allocator.dupe(i64, storage.shape);
            return allocator.dupe(i64, loaded.tensor.shape);
        }
    }
    return error.UnsupportedShape;
}

fn tensorShapeMatchesOp(_: *anyopaque, tensor: CT, shape: []const i64) anyerror!?bool {
    const buf = toBuf(tensor);
    const actual = if (buf.logical_shape) |logical|
        logical
    else if (buf.quantized_storage) |storage|
        storage.shape
    else if (buf.source_tensor) |source|
        source.shape
    else
        return null;
    if (actual.len != shape.len) return false;
    for (actual, shape) |actual_dim, expected_dim| {
        if (actual_dim != expected_dim) return false;
    }
    return true;
}

fn sliceLastDimOp(ctx: *anyopaque, tensor: CT, start: usize, stop: usize) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const input = toBuf(tensor);
    const shape = input.logical_shape orelse return error.UnsupportedShape;
    if (shape.len != 2) return error.UnsupportedShape;
    const input_data = try getDataChecked(tensor);
    const rows = std.math.cast(usize, shape[0]) orelse return error.InvalidTensorShape;
    const cols = std.math.cast(usize, shape[1]) orelse return error.InvalidTensorShape;
    if (start > stop or stop > cols) return error.OutOfBounds;
    const out_cols = stop - start;
    var owned: ?[]f32 = try self.allocator.alloc(f32, try std.math.mul(usize, rows, out_cols));
    errdefer if (owned) |data| self.allocator.free(data);
    for (0..rows) |row| @memcpy(owned.?[row * out_cols ..][0..out_cols], input_data[row * cols + start .. row * cols + stop]);
    // Reshape/last-use consumers must share ownership of these rows. A legacy
    // owned Buf without a refcount turns reshape into a dangling borrowed view.
    const result = try self.makeBuf(owned.?, true);
    owned = null;
    errdefer freeTensor(self, result);
    return self.withLogicalShape(result, &.{ @intCast(rows), @intCast(out_cols) });
}

fn evalTensorOp(_: *anyopaque, _: CT) anyerror!void {}

fn argmaxLastRowOp(_: *anyopaque, tensor: CT, rows: usize, dim: usize) anyerror!?u32 {
    const data = getData(tensor);
    if (rows == 0 or dim == 0) return error.InvalidTensorShape;
    if (data.len != rows * dim) return error.InvalidTensorShape;
    const last_row = data[(rows - 1) * dim ..][0..dim];
    return @intCast(activations_mod.argmax(last_row));
}

fn argmaxRowsOp(
    ctx: *anyopaque,
    tensor: CT,
    row_start: usize,
    row_count: usize,
    dim: usize,
    allocator: std.mem.Allocator,
) anyerror!?[]u32 {
    return argmaxRowsSuppressOp(ctx, tensor, row_start, row_count, dim, &.{}, allocator);
}

fn argmaxRowsSuppressOp(
    _: *anyopaque,
    tensor: CT,
    row_start: usize,
    row_count: usize,
    dim: usize,
    suppress_token_ids: []const i32,
    allocator: std.mem.Allocator,
) anyerror!?[]u32 {
    if (row_count == 0 or dim == 0) return error.InvalidTensorShape;
    const row_end = std.math.add(usize, row_start, row_count) catch return error.InvalidTensorShape;
    const elem_count = std.math.mul(usize, row_end, dim) catch return error.InvalidTensorShape;
    const data = getData(tensor);
    if (data.len < elem_count) return error.InvalidTensorShape;

    const tokens = try allocator.alloc(u32, row_count);
    errdefer allocator.free(tokens);
    for (tokens, 0..) |*token, row_idx| {
        const row = data[(row_start + row_idx) * dim ..][0..dim];
        var best_idx: u32 = 0;
        var best_val: f32 = -std.math.inf(f32);
        var found = false;
        for (row, 0..) |value, idx| {
            if (found and !(value > best_val)) continue;
            var suppressed = false;
            for (suppress_token_ids) |raw| {
                if (raw >= 0 and @as(usize, @intCast(raw)) == idx) {
                    suppressed = true;
                    break;
                }
            }
            if (suppressed) continue;
            found = true;
            best_val = value;
            best_idx = @intCast(idx);
        }
        token.* = best_idx;
    }
    return tokens;
}

test "linear q8_0 kernel computes direct matmul" {
    var input: [32]f32 = @as([32]f32, @splat(1.0));
    var output: [2]f32 = [_]f32{ 0.0, 0.0 };
    var weight_raw: [68]u8 = @as([68]u8, @splat(0));

    // Row 0: scale 1.0, all quantized values 1.
    weight_raw[0] = 0x00;
    weight_raw[1] = 0x3C;
    for (0..32) |i| weight_raw[2 + i] = @bitCast(@as(i8, 1));

    // Row 1: scale 1.0, all quantized values 2.
    weight_raw[34] = 0x00;
    weight_raw[35] = 0x3C;
    for (0..32) |i| weight_raw[36 + i] = @bitCast(@as(i8, 2));

    try linearNoBiasQuantizedGeneric(null, &input, &weight_raw, &output, 1, 32, 2, .{ .known = .Q8_0 }, &dotQ8_0Block);
    try std.testing.expectApproxEqAbs(@as(f32, 32.0), output[0], 1e-4);
    try std.testing.expectApproxEqAbs(@as(f32, 64.0), output[1], 1e-4);
}

test "linear q8_0 ranged columns match full output" {
    const rows = 2;
    const in_dim = 32;
    const out_dim = 5;
    const block_size = 34;
    var input: [rows * in_dim]f32 = undefined;
    for (&input, 0..) |*value, idx| {
        const signed: i32 = @intCast(idx % 11);
        value.* = @floatFromInt(signed - 5);
    }

    var weight_raw: [out_dim * block_size]u8 = @as([(out_dim * block_size)]u8, @splat(0));
    for (0..out_dim) |row| {
        const base = row * block_size;
        weight_raw[base] = 0x00;
        weight_raw[base + 1] = 0x3C;
        for (0..32) |i| {
            const q: i8 = @intCast(@as(i32, @intCast((row + i) % 9)) - 4);
            weight_raw[base + 2 + i] = @bitCast(q);
        }
    }

    var full: [rows * out_dim]f32 = @as([(rows * out_dim)]f32, @splat(0.0));
    var ranged: [rows * out_dim]f32 = @as([(rows * out_dim)]f32, @splat(-999.0));
    linearQ8_0Range(&input, &weight_raw, &full, rows, in_dim, out_dim, 0, out_dim, null);
    linearQ8_0Range(&input, &weight_raw, &ranged, rows, in_dim, out_dim, 0, 2, null);
    linearQ8_0Range(&input, &weight_raw, &ranged, rows, in_dim, out_dim, 2, out_dim, null);

    for (full, ranged) |want, got| {
        try std.testing.expectApproxEqAbs(want, got, 1e-4);
    }
}

