test "linear tl1 kernel computes direct matmul" {
    const allocator = std.testing.allocator;
    const out_dim = 1536;
    const in_dim = 1536;
    const input = try allocator.alloc(f32, in_dim);
    defer allocator.free(input);
    @memset(input, 1.0);

    const output = try allocator.alloc(f32, out_dim);
    defer allocator.free(output);
    @memset(output, 0.0);

    const packed_len = out_dim * in_dim / 4;
    var weight_raw = try allocator.alloc(u8, packed_len + 32);
    defer allocator.free(weight_raw);
    @memset(weight_raw, 0x44);
    weight_raw[0] = 0x84;
    std.mem.writeInt(u32, weight_raw[packed_len..][0..4], @bitCast(@as(f32, 2.0)), .little);

    const shape = [_]i64{ out_dim, in_dim };
    var storage: QuantizedStorage = .{
        .tensor_type = .{ .known = .TL1 },
        .raw_bytes = weight_raw,
        .shape = &shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    try std.testing.expect(try linearNoBiasQuantized(null, &storage, input, output, 1, in_dim, out_dim));
    try std.testing.expectApproxEqAbs(@as(f32, 4.0), output[0], 1e-4);
    try std.testing.expectApproxEqAbs(@as(f32, 0.0), output[1], 1e-4);
}

