        .shape = &shape,
        .raw_owned = false,
        .allocator = allocator,
    };
    var storage_b: QuantizedStorage = .{
        .tensor_type = .bitnet_tl2,
        .raw_bytes = weight_raw_b,
        .shape = &shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    try std.testing.expect(try linearNoBiasQuantizedPair(null, allocator, &storage_a, &storage_b, input, output_a, output_b, 1, in_dim, out_dim));
    try std.testing.expect(try linearNoBiasQuantized(null, &storage_a, input, ref_a, 1, in_dim, out_dim));
    try std.testing.expect(try linearNoBiasQuantized(null, &storage_b, input, ref_b, 1, in_dim, out_dim));
    try std.testing.expectEqualSlices(f32, ref_a, output_a);
    try std.testing.expectEqualSlices(f32, ref_b, output_b);
}

test "linear q4_0 kernel computes direct matmul" {
    var input: [32]f32 = @as([32]f32, @splat(1.0));
    var output: [2]f32 = [_]f32{ 0.0, 0.0 };
    var weight_raw: [36]u8 = @as([36]u8, @splat(0x88));

    // Row 0: scale 1.0, all quantized values decode to 0.
    weight_raw[0] = 0x00;
    weight_raw[1] = 0x3C;

    // Row 1: scale 1.0, all quantized values decode to 1.
    weight_raw[18] = 0x00;
    weight_raw[19] = 0x3C;
    for (20..36) |i| weight_raw[i] = 0x99;

    try linearNoBiasQuantizedGeneric(null, &input, &weight_raw, &output, 1, 32, 2, .{ .known = .Q4_0 }, &dotQ4_0Block);
    try std.testing.expectApproxEqAbs(@as(f32, 0.0), output[0], 1e-4);
    try std.testing.expectApproxEqAbs(@as(f32, 32.0), output[1], 1e-4);
}

