test "q6_k prepared q8_k grouped pair and triple panel16 paths match singles" {
    const allocator = std.testing.allocator;
    const rows: usize = 5;
    const in_dim: usize = 768;
    const out_dim: usize = 512;
    const row_blocks = in_dim / 256;
    const tensor_type: gguf_tensor_types.TensorType = .{ .known = .Q6_K };

    try std.testing.expect(shouldUseQ6_KQ8KActivationQuant(rows, out_dim, row_blocks));

    const input = try allocator.alloc(f32, rows * in_dim);
    defer allocator.free(input);
    for (input, 0..) |*value, idx| {
        const signed: i32 = @intCast((idx * 13 + (idx / in_dim) * 7 + 5) % 47);
        value.* = @as(f32, @floatFromInt(signed - 23)) / 31.0;
    }

    const weight_f32_a = try allocator.alloc(f32, out_dim * in_dim);
    defer allocator.free(weight_f32_a);
    const weight_f32_b = try allocator.alloc(f32, out_dim * in_dim);
    defer allocator.free(weight_f32_b);
    const weight_f32_c = try allocator.alloc(f32, out_dim * in_dim);
    defer allocator.free(weight_f32_c);
    for (0..(out_dim * in_dim)) |idx| {
        const signed_a: i32 = @intCast((idx * 11 + 3) % 41);
        const signed_b: i32 = @intCast((idx * 17 + 13) % 43);
        const signed_c: i32 = @intCast((idx * 19 + 29) % 53);
        weight_f32_a[idx] = @as(f32, @floatFromInt(signed_a - 20)) / 23.0;
        weight_f32_b[idx] = @as(f32, @floatFromInt(signed_b - 21)) / 29.0;
        weight_f32_c[idx] = @as(f32, @floatFromInt(signed_c - 26)) / 37.0;
    }

    const raw_a = try quant_codec.quantizeQ6_KFromF32(allocator, weight_f32_a);
    const raw_b = try quant_codec.quantizeQ6_KFromF32(allocator, weight_f32_b);
