test "q6_k q8_k activation dot matches q8 dequantized input dot" {
    const allocator = std.testing.allocator;
    var input: [256]f32 = undefined;
    for (&input, 0..) |*value, idx| {
        const signed: i32 = @intCast(idx % 29);
        value.* = @as(f32, @floatFromInt(signed - 14)) * 0.2;
    }

    const q8_raw = try quant_codec.quantizeQ8_KFromF32(allocator, &input);
    defer allocator.free(q8_raw);

    var q8_dequant: [256]f32 = undefined;
    try quant_codec.dequantizeToFloat32(.{ .known = .Q8_K }, q8_raw, &q8_dequant);

    const q6_type: gguf_tensor_types.TensorType = .{ .known = .Q6_K };
    var q6_raw = try allocator.alloc(u8, gguf_tensor_types.bytesPerBlock(q6_type).?);
    defer allocator.free(q6_raw);
    for (q6_raw, 0..) |*byte, idx| byte.* = @truncate((idx * 31 + 7) & 0xFF);
    q6_raw[208] = 0x00;
    q6_raw[209] = 0x3C; // d = 1.0

    const expected = dotQ6_KBlock(&q8_dequant, q6_raw);
    const actual = dotQ6_KQ8_KBlock(q8_raw, q6_raw);
    try std.testing.expectApproxEqAbs(expected, actual, 2e-2);
}

test "q8_k activation quantization overwrites destination bytes" {
    var input: [256]f32 = undefined;
    for (&input, 0..) |*value, idx| {
        const signed: i32 = @intCast((idx * 7 + 3) % 31);
        value.* = @as(f32, @floatFromInt(signed - 15)) / 13.0;
    }

    var expected: [292]u8 = @as([292]u8, @splat(0x00));
    var poisoned: [292]u8 = @as([292]u8, @splat(0xA5));
    quant_codec.quantizeQ8_KBlock(&input, &expected);
    quant_codec.quantizeQ8_KBlock(&input, &poisoned);
    try std.testing.expectEqualSlices(u8, &expected, &poisoned);
}

