        try std.testing.expectEqualSlices(f32, &expected, getData(result)[output_row * 32 ..][0..32]);
    }
    freeTensor(&compute, weight);
    released = true;
    try std.testing.expectEqual(@as(usize, 0), budget.host_weight_bytes);
}

test "native gather lazy handles retain pins and allow later matrix preparation" {
    const allocator = std.testing.allocator;
    const name = "embedding.weight";
    const dense = @as([128]f32, @splat(1));
    const raw = try quant_codec.quantizeQ8_0FromF32(allocator, &dense);
    defer allocator.free(raw);
    const shape = [_]i64{ 4, 32 };
    var store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    defer {
        deinitPrefetchQueue(&store);
        store.lazy_weights.getPtr(name).?.loaded.?.quantized_storage.?.prepared.deinit(allocator);
        store.lazy_weights.deinit(allocator);
    }
    try store.lazy_weights.put(allocator, name, .{
        .tensor_ref = .{ .name = name, .byte_len = raw.len },
        .loaded = .{
            .tensor = .{
                .data = &.{},
                .shape = &.{},
                .dtype = .f32,
                .name = name,
                .allocator = allocator,
                .owns_data = false,
                .owns_shape = false,
            },
            .quantized = true,
            .quantized_storage = .{
                .tensor_type = .{ .known = .Q8_0 },
                .raw_bytes = raw,
                .shape = &shape,
                .raw_owned = false,
                .allocator = allocator,
            },
        },
        .loaded_bytes = raw.len,
        .active_tier = .host,
    });
    var budget = run_memory.RunBudget.init(.{ .host_limit_bytes = 4096 });
    var compute = NativeCompute.init(allocator, &store, &budget);
    defer compute.deinit();
    const first = try getEmbeddingWeight(&compute, name);
    var first_live = true;
    defer if (first_live) freeTensor(&compute, first);
    const second = try getEmbeddingWeight(&compute, name);
    var second_live = true;
    defer if (second_live) freeTensor(&compute, second);
    try std.testing.expect(first != second);
    const entry = store.lazy_weights.getPtr(name).?;
    try std.testing.expectEqual(@as(usize, 2), entry.pin_count);
    try std.testing.expectEqual(raw.len, entry.loaded_bytes);
    try std.testing.expectEqual(@as(usize, 0), entry.loaded.?.quantized_storage.?.prepared.ownedBytes());
    freeTensor(&compute, first);
    first_live = false;
    try std.testing.expectEqual(@as(usize, 1), entry.pin_count);
    try std.testing.expectEqual(raw.len, budget.host_weight_bytes);
    const matrix = try acquireWeight(&compute, name);
    var matrix_live = true;
    defer if (matrix_live) freeTensor(&compute, matrix);
    try std.testing.expect(entry.loaded.?.quantized_storage.?.prepared.ownedBytes() > 0);
    try std.testing.expectEqual(quantizedStorageBudgetBytes(&entry.loaded.?.quantized_storage.?), entry.loaded_bytes);
    try std.testing.expectEqual(entry.loaded_bytes, budget.host_weight_bytes);
    try std.testing.expectEqual(@as(usize, 2), entry.pin_count);
    freeTensor(&compute, matrix);
    matrix_live = false;
    freeTensor(&compute, second);
    second_live = false;
    try std.testing.expectEqual(@as(usize, 0), entry.pin_count);
    try std.testing.expectEqual(@as(usize, 0), budget.host_weight_bytes);
}

test "native typed BF16 lazy weight stays pinned until all handles are freed" {
    const allocator = std.testing.allocator;
    const name = "model.layers.0.mlp.up_proj.weight";
    var bits = [_]u16{ 0x3f80, 0x4000, 0x4040, 0x4080 };
    const shape = [_]i64{ 2, 2 };
    var store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    defer {
        deinitPrefetchQueue(&store);
        store.lazy_weights.deinit(allocator);
    }
    try store.lazy_weights.put(allocator, name, .{
        .tensor_ref = .{ .name = name, .byte_len = 8 },
        .loaded = .{ .tensor = .{
            .data = std.mem.sliceAsBytes(&bits),
            .shape = &shape,
            .dtype = .bf16,
            .name = name,
            .allocator = allocator,
            .owns_data = false,
            .owns_shape = false,
        } },
        .loaded_bytes = 8,
        .active_tier = .host,
    });
    var budget = run_memory.RunBudget.init(.{ .host_limit_bytes = 8 });
    var compute = NativeCompute.init(allocator, &store, &budget);
    compute.borrow_bf16_linear_weights = true;
    defer compute.deinit();
    var first: ?CT = try getWeight(&compute, name);
    defer if (first) |weight| freeTensor(&compute, weight);
    var shared: ?CT = try getWeight(&compute, name);
    defer if (shared) |weight| freeTensor(&compute, weight);
    var second: ?CT = try acquireWeight(&compute, name);
    defer if (second) |weight| freeTensor(&compute, weight);
    try std.testing.expectEqual(first.?, shared.?);
    try std.testing.expect(first.? != second.?);
    const entry = store.lazy_weights.getPtr(name).?;
    try std.testing.expectEqual(@as(usize, 2), entry.pin_count);
    try std.testing.expectEqual(@as(usize, 8), budget.host_weight_bytes);
    try std.testing.expect(toBuf(first.?).source_tensor == &entry.loaded.?.tensor);
    freeTensor(&compute, first.?);
    first = null;
    try std.testing.expectEqual(@as(usize, 2), entry.pin_count);
    try std.testing.expectEqual(@as(usize, 8), budget.host_weight_bytes);
    try std.testing.expect(toBuf(shared.?).source_tensor == &entry.loaded.?.tensor);
    freeTensor(&compute, shared.?);
    shared = null;
    try std.testing.expectEqual(@as(usize, 1), entry.pin_count);
    try std.testing.expectEqual(@as(usize, 8), budget.host_weight_bytes);
    freeTensor(&compute, second.?);
    second = null;
    try std.testing.expectEqual(@as(usize, 0), entry.pin_count);
    try std.testing.expectEqual(@as(usize, 0), budget.host_weight_bytes);
    try std.testing.expect(entry.loaded != null);
}

test "native typed BF16 linear panels preserve output tails" {
    const allocator = std.testing.allocator;
    const rows = 2;
    const in_dim = 16385;
    const out_dim = 129;
    const bits = try allocator.alloc(u16, in_dim * out_dim);
    defer allocator.free(bits);
    @memset(bits, 0x3f80);
    for (0..out_dim) |column| bits[column * in_dim] = if (column % 2 == 0) 0x4000 else 0xbf80;
    const input = try allocator.alloc(f32, rows * in_dim);
    defer allocator.free(input);
    @memset(input, 0);
    input[0] = 1;
    input[in_dim - 1] = 0.5;
    input[in_dim] = -2;
    input[2 * in_dim - 1] = 0.25;
    var output = @as([(rows * out_dim + 2)]f32, @splat(99));
    const shape = [_]i64{ out_dim, in_dim };
    const tensor = tensor_mod.Tensor{
        .data = std.mem.sliceAsBytes(bits),
        .shape = &shape,
        .dtype = .bf16,
        .name = "model.layers.0.self_attn.o_proj.weight",
        .allocator = allocator,
        .owns_data = false,
        .owns_shape = false,
    };
    var store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var budget = run_memory.RunBudget.init(.{ .scratch_limit_bytes = 8 * 1024 * 1024 });
    var compute = NativeCompute.init(allocator, &store, &budget);
    defer compute.deinit();
    try linearNoBiasSourceTensorChunked(&compute, input, &tensor, output[1 .. output.len - 1], rows, in_dim, out_dim);
    try std.testing.expectEqual(@as(f32, 99), output[0]);
    try std.testing.expectEqual(@as(f32, 99), output[output.len - 1]);
    for (0..rows) |row| {
        for (0..out_dim) |column| {
            const value: f32 = if (column % 2 == 0) 2 else -1;
            const expected = value * input[row * in_dim] + input[(row + 1) * in_dim - 1];
            try std.testing.expectApproxEqAbs(expected, output[1 + row * out_dim + column], 1e-6);
        }
    }
    try std.testing.expectEqual(@as(usize, 0), budget.host_scratch_bytes);
    try std.testing.expect(budget.peak_host_total_bytes <= 8 * 1024 * 1024);
}

test "embeddingLookup dequantizes quantized GGUF rows" {
    const allocator = std.testing.allocator;

    var dense = @as([64]f32, @splat(0));
    for (0..32) |i| dense[i] = @floatFromInt(i);
    for (0..32) |i| dense[32 + i] = @floatFromInt(100 + i);

    const raw = try quant_codec.quantizeQ8_0FromF32(allocator, &dense);
    defer allocator.free(raw);

    const shape = [_]i64{ 2, 32 };
    var storage = QuantizedStorage{
        .tensor_type = .{ .known = .Q8_0 },
        .raw_bytes = raw,
        .shape = &shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    var weight_store = WeightStore{
        .allocator = allocator,
        .resident_weights = .{},
        .lazy_weights = .{},
    };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();
    const cb = compute.computeBackend();

    const weight_ct = try compute.makeBufWithEntry(empty_f32[0..], false, "token_embd.weight", null, &storage, null);
    defer cb.free(weight_ct);

    const ids = [_]i64{ 1, 0 };
    const out_ct = try cb.embeddingLookup(weight_ct, &ids, ids.len, 32);
    defer cb.free(out_ct);

    const out = getData(out_ct);
    var expected_row = @as([32]f32, @splat(0));
    try quant_codec.dequantizeRow(.{ .known = .Q8_0 }, raw, 32, 1, &expected_row);
    for (out[0..32], expected_row) |actual, expected| {
        try std.testing.expectApproxEqAbs(expected, actual, 1e-4);
    }
    try quant_codec.dequantizeRow(.{ .known = .Q8_0 }, raw, 32, 0, &expected_row);
    for (out[32..64], expected_row) |actual, expected| {
        try std.testing.expectApproxEqAbs(expected, actual, 1e-4);
    }

    var dense_q4 = @as([256]f32, @splat(0));
    for (&dense_q4, 0..) |*value, i| value.* = @as(f32, @floatFromInt(i)) / 17.0 - 4.0;
    const raw_q4 = try quant_codec.quantizeQ4_KFromF32(allocator, &dense_q4);
    defer allocator.free(raw_q4);

    const rank3_shape = [_]i64{ 1, 1, 256 };
    var q4_storage = QuantizedStorage{
        .tensor_type = .{ .known = .Q4_K },
        .raw_bytes = raw_q4,
        .shape = &rank3_shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    const q4_weight_ct = try compute.makeBufWithEntry(empty_f32[0..], false, "count_embed.pos_embedding.weight", null, &q4_storage, null);
    defer cb.free(q4_weight_ct);

    const q4_ids = [_]i64{ 0, 0 };
    const q4_out_ct = try cb.embeddingLookup(q4_weight_ct, &q4_ids, q4_ids.len, 256);
    defer cb.free(q4_out_ct);

    var expected_q4 = @as([256]f32, @splat(0));
    try quant_codec.dequantizeRow(.{ .known = .Q4_K }, raw_q4, 256, 0, &expected_q4);
    const q4_out = getData(q4_out_ct);
    for (q4_out[0..256], expected_q4) |actual, expected| {
        try std.testing.expectApproxEqAbs(expected, actual, 1e-4);
    }
    for (q4_out[256..512], expected_q4) |actual, expected| {
        try std.testing.expectApproxEqAbs(expected, actual, 1e-4);
    }
}

test "native stack teardown releases empty lookup caches and outstanding reservations" {
    const allocator = std.testing.allocator;
    var store = WeightStore{ .allocator = allocator, .resident_weights = .empty, .lazy_weights = .empty };
    defer store.prefetch.deinit();
    var budget = run_memory.RunBudget.init(.{ .host_limit_bytes = 96 });
    var compute = NativeCompute.init(allocator, &store, &budget);
    defer compute.deinit();
    try std.testing.expectError(error.MissingWeight, compute.computeBackend().getWeight("missing"));
    try std.testing.expect(compute.weight_handles.capacity() > 0);
    _ = try acquireWeightReservation(&compute, "reserved", 64);
    try std.testing.expectEqual(@as(usize, 64), budget.host_weight_bytes);

    compute.deinit();
    try std.testing.expectEqual(@as(usize, 0), compute.weight_handles.capacity());
    try std.testing.expectEqual(@as(usize, 0), compute.weight_reservations.capacity());
    try std.testing.expectEqual(@as(usize, 0), budget.host_weight_bytes);
    // The context teardown leaves the shared model store's lifetime to its owner.
    try std.testing.expect(store.prefetch_initialized);
}

fn testWeightHandleLifetime(allocator: std.mem.Allocator, lazy: bool, stack_owned: bool) !void {
    var bytes = [_]u8{ 0x80, 0x3f, 0x20, 0xc0, 0x00, 0x3f, 0x40, 0x40 };
    var shape = [_]i64{ 2, 2 };
    const weight = LoadedWeight{ .tensor = .{
        .data = &bytes,
        .shape = &shape,
        .dtype = .bf16,
        .name = "weight",
        .allocator = allocator,
        .owns_data = false,
        .owns_shape = false,
    } };
    var store = WeightStore{ .allocator = allocator, .resident_weights = .empty, .lazy_weights = .empty };
    defer store.resident_weights.deinit(allocator);
    defer store.lazy_weights.deinit(allocator);
    if (lazy) {
        try store.lazy_weights.put(allocator, "weight", .{
            .tensor_ref = .{ .name = "weight" },
            .loaded = weight,
            .loaded_bytes = bytes.len,
        });
    } else {
        try store.resident_weights.put(allocator, "weight", weight);
    }
    var budget = run_memory.RunBudget.init(.{ .host_limit_bytes = 64 });
    {
        var stack_compute: NativeCompute = undefined;
        const compute = if (stack_owned) &stack_compute else try allocator.create(NativeCompute);
        compute.* = NativeCompute.init(allocator, &store, &budget);
        defer store.prefetch.deinit();
        defer if (stack_owned) compute.deinit() else deinitBackend(compute);
        const first = try getWeight(compute, "weight");
        {
            const owned = try acquireWeight(compute, "weight");
            defer freeTensor(compute, owned);
            const other = try acquireWeight(compute, "weight");
            defer freeTensor(compute, other);
            try std.testing.expect(first != owned and owned != other and first != other);
            try std.testing.expectEqualSlices(f32, getData(first), getData(owned));
            if (lazy) try std.testing.expectEqual(@as(usize, 3), store.lazy_weights.get("weight").?.pin_count);
            try std.testing.expectEqual(@as(usize, 3), compute.weight_reservations.get("weight").?.count);
            try std.testing.expectEqual(@as(?CT, null), try unaryConsumeOp(compute, .relu, owned));
        }
        const alias = if (!lazy) try aliasDenseBufWithShape(compute, first, &.{4}) else null;
        defer if (alias) |view| freeTensor(compute, view);
        for (0..1000) |_| try std.testing.expectEqual(first, try getWeight(compute, "weight"));
        try std.testing.expectEqual(@as(usize, 1), compute.weight_handles.count());
        try std.testing.expectEqual(@as(usize, 1), compute.weight_reservations.count());
        if (lazy) try std.testing.expectEqual(@as(usize, 1), store.lazy_weights.get("weight").?.pin_count);
        try std.testing.expectEqualSlices(f32, &.{ 1, -2.5, 0.5, 3 }, getData(first));
        try std.testing.expectEqual(@as(?CT, null), try unaryConsumeOp(compute, .relu, first));
        // Releasing one caller must not invalidate the other borrowers.
        for (0..1000) |_| freeTensor(compute, first);
        try std.testing.expectEqualSlices(f32, &.{ 1, -2.5, 0.5, 3 }, getData(first));
        freeTensor(compute, first);
        if (alias) |view| {
            try std.testing.expectEqualSlices(f32, &.{ 1, -2.5, 0.5, 3 }, getData(view));
            try std.testing.expectEqualStrings("weight", toBuf(view).name);
            try std.testing.expectEqual(@as(?CT, null), try unaryConsumeOp(compute, .relu, view));
        }
        try std.testing.expectEqual(@as(usize, 0), compute.weight_handles.count());
        try std.testing.expectEqual(@as(usize, 0), budget.host_weight_bytes);
        if (lazy) try std.testing.expectEqual(@as(usize, 0), store.lazy_weights.get("weight").?.pin_count);
        // Florence-style callers leave their lookups to backend teardown.
        _ = try getWeight(compute, "weight");
        _ = try getWeight(compute, "weight");
    }
    try std.testing.expectEqual(@as(usize, 0), budget.host_weight_bytes);
    if (lazy) try std.testing.expectEqual(@as(usize, 0), store.lazy_weights.get("weight").?.pin_count);
}

test "native weight handle lifetime is bounded and releases reservations and lazy pins" {
    inline for (.{ false, true }) |stack_owned| {
        try testWeightHandleLifetime(std.testing.allocator, false, stack_owned);
        try testWeightHandleLifetime(std.testing.allocator, true, stack_owned);
    }
}

test "native weight handle lifetime unwinds allocation failures" {
    inline for (.{ false, true }) |stack_owned| {
        try @import("antfly_platform").allocator.checkAllAllocationFailures(std.testing.allocator, testWeightHandleLifetime, .{ false, stack_owned });
        try @import("antfly_platform").allocator.checkAllAllocationFailures(std.testing.allocator, testWeightHandleLifetime, .{ true, stack_owned });
    }
}

test "getWeight preserves resident dense tensor shape metadata" {
    const allocator = std.testing.allocator;

    var resident_weights = std.StringHashMapUnmanaged(LoadedWeight){};
    defer {
        var it = resident_weights.iterator();
        while (it.next()) |entry| {
            allocator.free(entry.key_ptr.*);
            entry.value_ptr.deinit();
        }
        resident_weights.deinit(allocator);
    }

    const name = try allocator.dupe(u8, "h.0.mlp.c_proj.weight");
    errdefer allocator.free(name);

    const shape = try allocator.dupe(i64, &[_]i64{ 12, 4 });
    errdefer allocator.free(shape);
    const elem_count: usize = @intCast(shape[0] * shape[1]);
    const data = try allocator.alloc(u8, elem_count * @sizeOf(f32));
    errdefer allocator.free(data);
    @memset(data, 0);

    try resident_weights.put(allocator, name, .{
        .tensor = .{
            .data = data,
            .shape = shape,
            .dtype = .f32,
            .name = name,
            .allocator = allocator,
            .owns_data = true,
            .owns_shape = true,
        },
        .quantized_storage = null,
    });

    var weight_store = WeightStore{
        .allocator = allocator,
        .resident_weights = resident_weights,
        .lazy_weights = .{},
    };
    var run_budget = run_memory.RunBudget.init(.{ .host_limit_bytes = 1024 });
    var compute = NativeCompute.init(allocator, &weight_store, &run_budget);
    defer compute.deinit();
    const cb = compute.computeBackend();

    const weight = try cb.getWeight(name);
    errdefer cb.free(weight);
    try std.testing.expectEqual(elem_count * @sizeOf(f32), run_budget.host_weight_bytes);

    const got_shape = try cb.tensorShape(weight, allocator);
    defer allocator.free(got_shape);

    try std.testing.expectEqualDeep(&[_]i64{ 12, 4 }, got_shape);
    try std.testing.expectEqual(tensor_mod.DType.f32, try cb.tensorDType(weight));
    cb.free(weight);
    try std.testing.expectEqual(@as(usize, 0), run_budget.host_weight_bytes);
}

