    try std.testing.expectApproxEqAbs(@as(f32, 50.0), out[4], 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, -6.0), out[5], 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, -7.0), out[6], 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, 80.0), out[7], 1e-6);
