test "reshape preserves symbolic target shape when dims remain unresolved" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();

    var data = @as([(76 * 8 * 76 * 64)]f32, @splat(0.0));
    const in_ct = try compute.makeBuf(data[0..], false);
    defer freeTensor(&compute, in_ct);

    const reshaped = try primReshapeOp(&compute, in_ct, &.{ -1, 8, -1, 64 });
    defer freeTensor(&compute, reshaped);

    try std.testing.expectEqualSlices(i64, &.{ -1, 8, -1, 64 }, tensorStoredShape(reshaped).?);
}

test "inferReshapeShape collapses extra inferred dims when known dims already match numel" {
    const resolved = inferReshapeShape(&.{ 64, 4, 64, 64 }, &.{ -1, 64, 4, 64, 64 }) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(i64, &.{ 1, 64, 4, 64, 64 }, resolved[0..5]);
}

test "inferReshapeShape restores leading singleton before splitting hidden size" {
    const resolved = inferReshapeShape(&.{ 77, 512 }, &.{ 1, -1, -1, 64 }) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(i64, &.{ 1, 77, 8, 64 }, resolved[0..4]);
}

test "inferReshapeShape ignores collapsed singleton when restoring attention heads" {
    const resolved = inferReshapeShapeWithNumel(&.{ 77, 1, 512 }, &.{ 1, -1, -1, 64 }, 77 * 512) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(i64, &.{ 1, 77, 8, 64 }, resolved[0..4]);
}

test "reshape resolves symbolic source dims using data len" {
    const allocator = std.testing.allocator;
