    var data = @as([(77 * 512)]f32, @splat(0.0));
    const raw = try compute.makeBuf(data[0..], false);
    defer freeTensor(&compute, raw);
    const symbolic = try compute.withLogicalShape(raw, &.{ -1, -1, 512 });
    defer if (symbolic != raw) freeTensor(&compute, symbolic);

    const reshaped = try primReshapeOp(&compute, symbolic, &.{ 1, -1, -1, 64 });
    defer freeTensor(&compute, reshaped);

    try std.testing.expectEqualSlices(i64, &.{ 1, 77, 8, 64 }, tensorStoredShape(reshaped).?);
}

