test "reshape aliases owned backing storage" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();

    const owned = try allocator.dupe(f32, &.{ 1, 2, 3, 4, 5, 6 });
    const in_ct = try compute.makeBuf(owned, true);
    const original_data = getData(in_ct);

    const reshaped = try primReshapeOp(&compute, in_ct, &.{ 2, 3 });
    defer freeTensor(&compute, reshaped);

    try std.testing.expectEqual(@intFromPtr(original_data.ptr), @intFromPtr(getData(reshaped).ptr));
    try std.testing.expectEqualSlices(i64, &.{ 2, 3 }, tensorStoredShape(reshaped).?);

    freeTensor(&compute, in_ct);
    try std.testing.expectEqualSlices(f32, &.{ 1, 2, 3, 4, 5, 6 }, getData(reshaped));
}

