test "sdpaOp respects flattened batch-head layout" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();

    const batch: usize = 2;
    const seq_len: usize = 3;
    const num_heads: usize = 2;
    const head_dim: usize = 4;
    const bh = batch * num_heads;
    const total = bh * seq_len * head_dim;

    const q_data = try allocator.alloc(f32, total);
    defer allocator.free(q_data);
    const k_data = try allocator.alloc(f32, total);
    defer allocator.free(k_data);
    const v_data = try allocator.alloc(f32, total);
    defer allocator.free(v_data);
    const bias_data = try allocator.alloc(f32, bh * seq_len * seq_len);
    defer allocator.free(bias_data);
    const mask = [_]i64{
        1, 1, 0,
        1, 0, 0,
    };

    for (0..bh) |bh_idx| {
        for (0..seq_len) |s| {
            for (0..head_dim) |d| {
                const idx = (bh_idx * seq_len + s) * head_dim + d;
                q_data[idx] = @as(f32, @floatFromInt(@as(i32, @intCast(1 + bh_idx * 17 + s * 5 + d))));
                k_data[idx] = @as(f32, @floatFromInt(@as(i32, @intCast(2 + bh_idx * 13 + s * 7 + d * 2)))) * 0.5;
                v_data[idx] = @as(f32, @floatFromInt(@as(i32, @intCast(bh_idx * 11 + s * 3)) - @as(i32, @intCast(d)) - 3));
            }
        }
    }
    for (0..bh) |bh_idx| {
        for (0..seq_len) |qi| {
            for (0..seq_len) |ki| {
                const idx = (bh_idx * seq_len + qi) * seq_len + ki;
                const centered: i32 = @as(i32, @intCast(qi)) - @as(i32, @intCast(ki));
                bias_data[idx] = @as(f32, @floatFromInt(centered)) * 0.125;
            }
        }
    }

    const q_ct = try compute.makeBuf(q_data, false);
    defer freeTensor(&compute, q_ct);
    const k_ct = try compute.makeBuf(k_data, false);
    defer freeTensor(&compute, k_ct);
    const v_ct = try compute.makeBuf(v_data, false);
    defer freeTensor(&compute, v_ct);
    const bias_ct = try compute.makeBuf(bias_data, false);
    defer freeTensor(&compute, bias_ct);

    const out_ct = try sdpaOp(&compute, q_ct, k_ct, v_ct, &mask, bias_ct, batch, seq_len, num_heads, head_dim);
    defer freeTensor(&compute, out_ct);
    const out = getData(out_ct);

    const ref = try allocator.alloc(f32, total);
    defer allocator.free(ref);
    @memset(ref, 0.0);

    const score_row = try allocator.alloc(f32, seq_len);
    defer allocator.free(score_row);
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));

    for (0..bh) |bh_idx| {
        const b = bh_idx / num_heads;
        for (0..seq_len) |qi| {
            var row_max: f32 = -std.math.inf(f32);
            for (0..seq_len) |ki| {
                if (mask[b * seq_len + ki] == 0) {
                    score_row[ki] = -std.math.inf(f32);
                    continue;
                }
                const q_base = (bh_idx * seq_len + qi) * head_dim;
                const k_base = (bh_idx * seq_len + ki) * head_dim;
                var dot: f32 = 0.0;
                for (0..head_dim) |d| {
                    dot += q_data[q_base + d] * k_data[k_base + d];
                }
                score_row[ki] = dot * scale + bias_data[(bh_idx * seq_len + qi) * seq_len + ki];
                row_max = @max(row_max, score_row[ki]);
            }

            var sum_exp: f32 = 0.0;
            for (0..seq_len) |ki| {
                if (score_row[ki] == -std.math.inf(f32)) {
                    score_row[ki] = 0.0;
                } else {
                    score_row[ki] = @exp(score_row[ki] - row_max);
                    sum_exp += score_row[ki];
                }
            }
            if (sum_exp > 0.0) {
                for (0..seq_len) |ki| score_row[ki] /= sum_exp;
            }

            const out_base = (bh_idx * seq_len + qi) * head_dim;
            for (0..seq_len) |vi| {
                const weight = score_row[vi];
                if (weight == 0.0) continue;
                const v_base = (bh_idx * seq_len + vi) * head_dim;
                for (0..head_dim) |d| {
                    ref[out_base + d] += weight * v_data[v_base + d];
                }
            }
        }
    }

    for (0..total) |i| {
        try std.testing.expectApproxEqAbs(ref[i], out[i], 1e-4);
    }
}

test "sdpaOp preserves 4d logical shape from query input" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();

    const batch: usize = 1;
    const seq_len: usize = 3;
    const num_heads: usize = 2;
    const head_dim: usize = 4;
    const total = batch * num_heads * seq_len * head_dim;

    const q_data = try allocator.alloc(f32, total);
    defer allocator.free(q_data);
    const k_data = try allocator.alloc(f32, total);
    defer allocator.free(k_data);
    const v_data = try allocator.alloc(f32, total);
    defer allocator.free(v_data);
    for (0..total) |i| {
        q_data[i] = @floatFromInt((i % 7) + 1);
        k_data[i] = @floatFromInt((i % 5) + 1);
        v_data[i] = @floatFromInt(@as(i32, @intCast(i % 11)) - 5);
    }
    const mask = [_]i64{ 1, 1, 1 };

    const raw_q = try compute.makeBuf(q_data, false);
    defer freeTensor(&compute, raw_q);
    const q_ct = try compute.withLogicalShape(raw_q, &.{ 1, 2, 3, 4 });
    const raw_k = try compute.makeBuf(k_data, false);
    defer freeTensor(&compute, raw_k);
    const k_ct = try compute.withLogicalShape(raw_k, &.{ 1, 2, 3, 4 });
    const raw_v = try compute.makeBuf(v_data, false);
    defer freeTensor(&compute, raw_v);
    const v_ct = try compute.withLogicalShape(raw_v, &.{ 1, 2, 3, 4 });

    const out_ct = try sdpaOp(&compute, q_ct, k_ct, v_ct, &mask, null, batch, seq_len, num_heads, head_dim);
    defer freeTensor(&compute, out_ct);

    try std.testing.expectEqualSlices(i64, &.{ 1, 2, 3, 4 }, tensorStoredShape(out_ct).?);
}

test "invalid lazy view materialization does not panic" {
    const allocator = std.testing.allocator;
    var data = [_]f32{ 1.0, 2.0 };
    var buf = Buf{
        .data = data[0..],
        .allocator = allocator,
        .owned = false,
    };
    buf.inline_logical_shape[0] = 2;
    buf.inline_logical_shape[1] = 2;
    buf.logical_shape = buf.inline_logical_shape[0..2];
    buf.logical_shape_inline = true;
    buf.view_strides = try allocator.dupe(usize, &.{ 3, 3 });
    buf.view_base_offset = 1;

    const out = getData(@ptrCast(&buf));
    try std.testing.expectEqual(@as(usize, 0), out.len);
    try std.testing.expect(buf.view_strides == null);
    try std.testing.expect(buf.logical_shape == null);
    try std.testing.expect(!buf.owned);
}

fn expectApproxEqSlice(expected: []const f32, actual: []const f32, tolerance: f32) !void {
    try std.testing.expectEqual(expected.len, actual.len);
    for (expected, actual) |want, got| {
        try std.testing.expectApproxEqAbs(want, got, tolerance);
    }
}

fn referenceBidirectionalHeadMajorAttention(
    allocator: std.mem.Allocator,
    q_data: []const f32,
    k_data: []const f32,
    v_data: []const f32,
    bias_data: ?[]const f32,
    mask: []const i64,
    batch: usize,
    seq_len: usize,
    num_heads: usize,
    head_dim: usize,
) ![]f32 {
    const bh = batch * num_heads;
    const total = bh * seq_len * head_dim;
    const ref = try allocator.alloc(f32, total);
    errdefer allocator.free(ref);
    @memset(ref, 0.0);

    const score_row = try allocator.alloc(f32, seq_len);
    defer allocator.free(score_row);
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));
    const bias_shared_len = num_heads * seq_len * seq_len;
    const bias_batched_len = batch * bias_shared_len;

    for (0..bh) |bh_idx| {
        const b = bh_idx / num_heads;
        const h = bh_idx % num_heads;
        const bias_offset: ?usize = if (bias_data) |bias|
            if (bias.len == bias_batched_len)
                bh_idx * seq_len * seq_len
            else if (bias.len == bias_shared_len)
                h * seq_len * seq_len
            else
                null
        else
            null;

        for (0..seq_len) |qi| {
            var row_max: f32 = -std.math.inf(f32);
            for (0..seq_len) |ki| {
                if (mask[b * seq_len + ki] == 0) {
                    score_row[ki] = -std.math.inf(f32);
                    continue;
                }
                const q_base = (bh_idx * seq_len + qi) * head_dim;
                const k_base = (bh_idx * seq_len + ki) * head_dim;
                var dot: f32 = 0.0;
                for (0..head_dim) |d| dot += q_data[q_base + d] * k_data[k_base + d];
                var score = dot * scale;
                if (bias_data) |bias| if (bias_offset) |off| {
                    score += bias[off + qi * seq_len + ki];
                };
                score_row[ki] = score;
                row_max = @max(row_max, score);
            }

            var sum_exp: f32 = 0.0;
            for (0..seq_len) |ki| {
                if (score_row[ki] == -std.math.inf(f32)) {
                    score_row[ki] = 0.0;
                } else {
                    score_row[ki] = @exp(score_row[ki] - row_max);
                    sum_exp += score_row[ki];
                }
            }
            if (sum_exp > 0.0) {
                for (0..seq_len) |ki| score_row[ki] /= sum_exp;
            }

            const out_base = (bh_idx * seq_len + qi) * head_dim;
            for (0..seq_len) |vi| {
                const weight = score_row[vi];
                if (weight == 0.0) continue;
                const v_base = (bh_idx * seq_len + vi) * head_dim;
                for (0..head_dim) |d| ref[out_base + d] += weight * v_data[v_base + d];
            }
        }
    }

    return ref;
}

fn referenceCausalSeqMajorAttention(
    allocator: std.mem.Allocator,
    q_data: []const f32,
    k_data: []const f32,
    v_data: []const f32,
    bias_data: ?[]const f32,
    batch: usize,
    seq_len: usize,
    num_heads: usize,
    head_dim: usize,
) ![]f32 {
    const H = num_heads * head_dim;
    const total = batch * seq_len * H;
    const ref = try allocator.alloc(f32, total);
    errdefer allocator.free(ref);
    @memset(ref, 0.0);

    const score_row = try allocator.alloc(f32, seq_len);
    defer allocator.free(score_row);
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));

    for (0..batch) |b| {
        for (0..num_heads) |h| {
            for (0..seq_len) |qi| {
                var row_max: f32 = -std.math.inf(f32);
                for (0..seq_len) |ki| {
                    if (ki > qi) {
                        score_row[ki] = -std.math.inf(f32);
                        continue;
                    }
                    const q_base = (b * seq_len + qi) * H + h * head_dim;
                    const k_base = (b * seq_len + ki) * H + h * head_dim;
                    var dot: f32 = 0.0;
                    for (0..head_dim) |d| dot += q_data[q_base + d] * k_data[k_base + d];
                    var score = dot * scale;
                    if (bias_data) |bias| score += bias[h * seq_len * seq_len + qi * seq_len + ki];
                    score_row[ki] = score;
                    row_max = @max(row_max, score);
                }

                var sum_exp: f32 = 0.0;
                for (0..seq_len) |ki| {
                    if (score_row[ki] == -std.math.inf(f32)) {
                        score_row[ki] = 0.0;
                    } else {
                        score_row[ki] = @exp(score_row[ki] - row_max);
                        sum_exp += score_row[ki];
                    }
                }
                if (sum_exp > 0.0) {
                    for (0..seq_len) |ki| score_row[ki] /= sum_exp;
                }

                const out_base = (b * seq_len + qi) * H + h * head_dim;
                for (0..seq_len) |vi| {
                    const weight = score_row[vi];
                    if (weight == 0.0) continue;
                    const v_base = (b * seq_len + vi) * H + h * head_dim;
                    for (0..head_dim) |d| ref[out_base + d] += weight * v_data[v_base + d];
                }
            }
        }
    }

    return ref;
}

fn referenceCrossSeqMajorAttention(
    allocator: std.mem.Allocator,
    q_data: []const f32,
    k_data: []const f32,
    v_data: []const f32,
    enc_mask: []const i64,
    batch: usize,
    dec_seq: usize,
    enc_seq: usize,
    num_heads: usize,
    head_dim: usize,
) ![]f32 {
    const H = num_heads * head_dim;
    const total = batch * dec_seq * H;
    const ref = try allocator.alloc(f32, total);
    errdefer allocator.free(ref);
    @memset(ref, 0.0);

    const score_row = try allocator.alloc(f32, enc_seq);
    defer allocator.free(score_row);
    const scale: f32 = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));

    for (0..batch) |b| {
        for (0..num_heads) |h| {
            for (0..dec_seq) |qi| {
                var row_max: f32 = -std.math.inf(f32);
                for (0..enc_seq) |ki| {
                    if (enc_mask[b * enc_seq + ki] == 0) {
                        score_row[ki] = -std.math.inf(f32);
                        continue;
                    }
                    const q_base = (b * dec_seq + qi) * H + h * head_dim;
                    const k_base = (b * enc_seq + ki) * H + h * head_dim;
                    var dot: f32 = 0.0;
                    for (0..head_dim) |d| dot += q_data[q_base + d] * k_data[k_base + d];
                    score_row[ki] = dot * scale;
                    row_max = @max(row_max, score_row[ki]);
                }

                var sum_exp: f32 = 0.0;
                for (0..enc_seq) |ki| {
                    if (score_row[ki] == -std.math.inf(f32)) {
                        score_row[ki] = 0.0;
                    } else {
                        score_row[ki] = @exp(score_row[ki] - row_max);
                        sum_exp += score_row[ki];
                    }
                }
                if (sum_exp > 0.0) {
                    for (0..enc_seq) |ki| score_row[ki] /= sum_exp;
                }

                const out_base = (b * dec_seq + qi) * H + h * head_dim;
                for (0..enc_seq) |vi| {
                    const weight = score_row[vi];
                    if (weight == 0.0) continue;
                    const v_base = (b * enc_seq + vi) * H + h * head_dim;
                    for (0..head_dim) |d| ref[out_base + d] += weight * v_data[v_base + d];
                }
            }
        }
    }

    return ref;
}

test "packTokenMajorHeads reorders per-token head slices" {
    const allocator = std.testing.allocator;
    // 1 batch, 2 tokens, 2 heads, head_dim 2: token-major rows are
    // [t0h0a, t0h0b, t0h1a, t0h1b], [t1h0a, ...].
    const tok = [_]f32{ 1, 2, 3, 4, 5, 6, 7, 8 };
    const packed_hm = try packTokenMajorHeads(allocator, &tok, 1, 2, 2, 2);
    defer allocator.free(packed_hm);
    // head-major: h0 rows for both tokens first, then h1 rows.
    try std.testing.expectEqualSlices(f32, &[_]f32{ 1, 2, 5, 6, 3, 4, 7, 8 }, packed_hm);
    const roundtrip = try unpackHeadMajorTokens(allocator, packed_hm, 1, 2, 2, 2);
    defer allocator.free(roundtrip);
    try std.testing.expectEqualSlices(f32, &tok, roundtrip);
}

test "native splitLastDim3 preserves token-major layout through multihead sdpa" {
    const allocator = std.testing.allocator;
    var store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    defer store.deinitOwned();
    var compute = NativeCompute.init(allocator, &store, null);
    defer compute.deinit();
    const cb = compute.computeBackend();
    const batch = 2;
    const seq_len = 3;
    const heads = 2;
    const head_dim = 3;
    const hidden = heads * head_dim;
    const rows = batch * seq_len;
    const total = rows * hidden;
    var q: [total]f32 = undefined;
    var k: [total]f32 = undefined;
    var v: [total]f32 = undefined;
    for (0..total) |i| {
        q[i] = @as(f32, @floatFromInt(@as(i32, @intCast((i * 7) % 23)) - 11)) * 0.07;
        k[i] = @as(f32, @floatFromInt(@as(i32, @intCast((i * 5) % 19)) - 9)) * 0.09;
        v[i] = @as(f32, @floatFromInt(@as(i32, @intCast((i * 3) % 17)) - 8)) * 0.11;
    }
    var packed_qkv: [total * 3]f32 = undefined;
    for (0..rows) |row| {
        @memcpy(packed_qkv[row * hidden * 3 ..][0..hidden], q[row * hidden ..][0..hidden]);
        @memcpy(packed_qkv[row * hidden * 3 + hidden ..][0..hidden], k[row * hidden ..][0..hidden]);
        @memcpy(packed_qkv[row * hidden * 3 + hidden * 2 ..][0..hidden], v[row * hidden ..][0..hidden]);
    }
    const input = try cb.fromFloat32Shape(&packed_qkv, &.{ rows, hidden * 3 });
    defer cb.free(input);
    const split = try cb.splitLastDim3(allocator, input, rows, hidden);
    defer cb.free(split.first);
    defer cb.free(split.second);
    defer cb.free(split.third);
    const shape = [_]i64{ rows, hidden };
    for ([_]CT{ split.first, split.second, split.third }) |output| {
        try std.testing.expectEqualSlices(i64, &shape, tensorStoredShape(output).?);
    }
    try std.testing.expectEqualSlices(f32, &q, getData(split.first));
    try std.testing.expectEqualSlices(f32, &k, getData(split.second));
    try std.testing.expectEqualSlices(f32, &v, getData(split.third));

    // Independent scalar token-major attention, with distinct rows, channels,
    // and batch masks. A head-major interpretation produces different values.
    const mask = [_]i64{ 1, 0, 1, 0, 1, 1 };
    const expected = try referenceCrossSeqMajorAttention(allocator, &q, &k, &v, &mask, batch, seq_len, seq_len, heads, head_dim);
    defer allocator.free(expected);
    const actual = try cb.scaledDotProductAttention(split.first, split.second, split.third, &mask, null, batch, seq_len, heads, head_dim);
    defer cb.free(actual);
    try std.testing.expectEqualSlices(i64, &shape, tensorStoredShape(actual).?);
    try expectApproxEqSlice(expected, getData(actual), 1e-5);
}

fn testNativeSplitLastDim3Lifetime(allocator: std.mem.Allocator, view_input: bool) !void {
    var store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    defer store.deinitOwned();
    var compute = NativeCompute.init(allocator, &store, null);
    defer compute.deinit();
    const cb = compute.computeBackend();
    var values: [18]f32 = undefined;
    for (&values, 0..) |*value, i| value.* = @floatFromInt(i + 1);
    const source = try cb.fromFloat32Shape(&values, if (view_input) &.{ 6, 3 } else &.{ 3, 6 });
    defer cb.free(source);
    const input = if (view_input) try primTransposeOp(&compute, source, &.{ 1, 0 }, &.{ 6, 3 }) else source;
    defer if (view_input) cb.free(input);
    // Repeated construction must leave the source intact after releasing all
    // three output owners, including a materialized transpose input.
    for (0..2) |_| {
        const split = try cb.splitLastDim3(allocator, input, 3, 2);
        defer cb.free(split.first);
        defer cb.free(split.second);
        defer cb.free(split.third);
        for ([_]CT{ split.first, split.second, split.third }, 0..) |output, part| {
            try std.testing.expectEqualSlices(i64, &.{ 3, 2 }, tensorStoredShape(output).?);
            for (getData(output), 0..) |value, i| {
                const row = i / 2;
                const col = part * 2 + i % 2;
                const original = if (view_input) col * 3 + row else row * 6 + col;
                try std.testing.expectEqual(values[original], value);
            }
        }
    }
    try std.testing.expectError(error.UnexpectedOutputShape, cb.splitLastDim3(allocator, input, 4, 2));
    try std.testing.expectError(error.UnexpectedOutputShape, cb.splitLastDim3(allocator, input, std.math.maxInt(usize), 2));
    try std.testing.expectEqualSlices(f32, &values, try getDataChecked(source));
}

test "native splitLastDim3 allocation failures preserve input and release partial outputs" {
    for ([_]bool{ false, true }) |view_input| {
        try @import("antfly_platform").allocator.checkAllAllocationFailures(std.testing.allocator, testNativeSplitLastDim3Lifetime, .{view_input});
        try testNativeSplitLastDim3Lifetime(std.testing.allocator, view_input);
    }
}

test "sdpa token-major 2d layout matches head-major reference" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();
    const cb = ComputeBackend{ .ptr = &compute, .vtable = &vtable_impl };

    // seq 40 exercises the flash path, seq 8 the legacy materialized path.
    for ([_]usize{ 40, 8 }) |seq_len| {
        const batch: usize = 1;
        const num_heads: usize = 3;
        const head_dim: usize = 4;
        const hidden = num_heads * head_dim;
        const total = batch * seq_len * hidden;

        const q_tok = try allocator.alloc(f32, total);
        defer allocator.free(q_tok);
        const k_tok = try allocator.alloc(f32, total);
        defer allocator.free(k_tok);
        const v_tok = try allocator.alloc(f32, total);
        defer allocator.free(v_tok);
        for (0..total) |i| {
            q_tok[i] = @as(f32, @floatFromInt(@as(i32, @intCast((i * 7) % 23)) - 11)) * 0.07;
            k_tok[i] = @as(f32, @floatFromInt(@as(i32, @intCast((i * 5) % 19)) - 9)) * 0.09;
            v_tok[i] = @as(f32, @floatFromInt(@as(i32, @intCast((i * 3) % 17)) - 8)) * 0.11;
        }
        const mask = try allocator.alloc(i64, batch * seq_len);
        defer allocator.free(mask);
        @memset(mask, 1);

        const token_shape = [_]i64{ @intCast(batch * seq_len), @intCast(hidden) };
        const q_ct = try compute.withLogicalShape(try compute.makeBuf(q_tok, false), &token_shape);
        defer freeTensor(&compute, q_ct);
        const k_ct = try compute.withLogicalShape(try compute.makeBuf(k_tok, false), &token_shape);
        defer freeTensor(&compute, k_ct);
        const v_ct = try compute.withLogicalShape(try compute.makeBuf(v_tok, false), &token_shape);
        defer freeTensor(&compute, v_ct);

        const out_ct = try cb.scaledDotProductAttention(q_ct, k_ct, v_ct, mask, null, batch, seq_len, num_heads, head_dim);
        defer freeTensor(&compute, out_ct);

        const q_hm = try packTokenMajorHeads(allocator, q_tok, batch, seq_len, num_heads, head_dim);
        defer allocator.free(q_hm);
        const k_hm = try packTokenMajorHeads(allocator, k_tok, batch, seq_len, num_heads, head_dim);
        defer allocator.free(k_hm);
        const v_hm = try packTokenMajorHeads(allocator, v_tok, batch, seq_len, num_heads, head_dim);
        defer allocator.free(v_hm);
        const ref_hm = try referenceBidirectionalHeadMajorAttention(allocator, q_hm, k_hm, v_hm, null, mask, batch, seq_len, num_heads, head_dim);
        defer allocator.free(ref_hm);
        const ref_tok = try unpackHeadMajorTokens(allocator, ref_hm, batch, seq_len, num_heads, head_dim);
        defer allocator.free(ref_tok);

        try expectApproxEqSlice(ref_tok, getData(out_ct), 1e-4);
    }
}

test "sdpa rejects mixed token-major and head-major layouts" {
    const allocator = std.testing.allocator;
    var weight_store = WeightStore{ .allocator = allocator, .resident_weights = .{}, .lazy_weights = .{} };
    var compute = NativeCompute.init(allocator, &weight_store, null);
    defer compute.deinit();

    var data = @as([8]f32, @splat(0));
    const q_ct = try compute.withLogicalShape(try compute.makeBuf(&data, false), &.{ 2, 4 });
    defer freeTensor(&compute, q_ct);
    const k_ct = try compute.withLogicalShape(try compute.makeBuf(&data, false), &.{ 1, 2, 2, 2 });
    defer freeTensor(&compute, k_ct);
