            defer cb.free(input);
            const output = (try packedGeluMultiplyOp(&compute, input, 2, 2)).?;
            defer cb.free(output);
            const gate = try cb.fromFloat32Shape(&.{ -2, 1, 0.5, -0.25 }, &.{ 2, 2 });
            defer cb.free(gate);
