}

test "embeddinggemma2 canonical CPU panels own typed grouped weights without dense mirrors" {
    const Case = struct {
        fn run(a: std.mem.Allocator, exercise_dispatch: bool) !void {
            const names = [_][]const u8{ "language_model.layers.0.mlp.gate_proj.weight", "language_model.layers.0.mlp.up_proj.weight" };
            var store = WeightStore{ .allocator = a, .resident_weights = .empty, .lazy_weights = .empty, .tier_cache = tier_cache_mod.SharedCache.init(.{ .host_limit_bytes = 32768 }) };
            initPrefetchQueue(&store, a);
            defer deinitPrefetchQueue(&store);
            defer store.resident_weights.deinit(a);
            var raw: [2][64 * 64]u16 = .{ @splat(0x3f80), @splat(0x4000) };
            for (names, 0..) |name, i| try store.resident_weights.put(a, name, .{ .tensor = .{ .data = std.mem.sliceAsBytes(&raw[i]), .shape = &.{ 64, 64 }, .dtype = .bf16, .name = name, .allocator = a, .owns_data = false, .owns_shape = false } });
            var compute = NativeCompute.init(a, &store, null);
            var live = true;
            defer if (live) compute.deinit();
            compute.cache_embeddinggemma2_bf16_weights = true;
            const panels = (try canonicalCpuPanels(&compute, &names, 64)).?;
            @memset(&raw[0], 0);
            @memset(&raw[1], 0);
            const warm = (try canonicalCpuPanels(&compute, &names, 64)).?;
            try std.testing.expectEqual(panels.data.ptr, warm.data.ptr);
            try std.testing.expectEqual(@as(usize, 0), store.embeddinggemma2_f32_cache.count());
            try std.testing.expectEqual(@as(usize, 32768), store.tier_cache.?.host_bytes);
            var input: [2 * 64]f32 = @splat(1);
            var output: [2 * 128]f32 = undefined;
            try linalg.sgemmPrepared(null, 2, panels, &input, &output);
            for (0..2) |r| {
                for (output[r * 128 ..][0..64]) |v| try std.testing.expectEqual(@as(f32, 64), v);
                for (output[r * 128 + 64 ..][0..64]) |v| try std.testing.expectEqual(@as(f32, 128), v);
            }
            if (exercise_dispatch and !native.useBlas()) {
                const cb = compute.computeBackend();
                const x = try cb.fromFloat32Shape(&input, &.{ 2, 64 });
                defer cb.free(x);
                const up = try cb.getWeight(names[1]);
                defer cb.free(up);
                const y = try cb.linearNoBias(x, up, 2, 64, 64);
                defer cb.free(y);
                for (getData(y)) |v| try std.testing.expectEqual(@as(f32, 128), v);
                const grouped = (try cb.linearPackedNamed(x, &names, &.{ 64, 64 }, 2, 64)).?;
                defer cb.free(grouped);
                try std.testing.expectEqualSlices(f32, &output, getData(grouped));
                try std.testing.expectEqual(@as(usize, 1), store.embeddinggemma2_canonical_panels.count());
            }
            try std.testing.expectEqual(@as(usize, 0), reclaimEmbeddingGemma2Weights(&store, .language));
            compute.deinit();
            live = false;
            try std.testing.expectEqual(@as(usize, 32768), reclaimEmbeddingGemma2Weights(&store, .language));
            try std.testing.expectEqual(@as(usize, 0), store.tier_cache.?.host_bytes);
            store.tier_cache.?.budget.host_limit_bytes = 32767;
            var denied = NativeCompute.init(a, &store, null);
            defer denied.deinit();
            denied.cache_embeddinggemma2_bf16_weights = true;
            try std.testing.expect(try canonicalCpuPanels(&denied, &names, 64) == null);
            try std.testing.expectEqual(@as(usize, 0), store.embeddinggemma2_canonical_panels.count());
            try std.testing.expectEqual(@as(usize, 0), store.embeddinggemma2_f32_readers);
            try std.testing.expectEqual(@as(usize, 0), store.tier_cache.?.host_bytes);
            if (exercise_dispatch) {
                const source = &store.resident_weights.getPtr(names[0]).?.tensor;
                source.data = source.data[0 .. source.data.len - 2];
                try std.testing.expectError(error.InvalidTensorShape, canonicalCpuPanels(&denied, &names, 64));
                try std.testing.expectEqual(@as(usize, 0), store.embeddinggemma2_canonical_panels.count());
            }
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Case.run, .{false});
    try Case.run(std.testing.allocator, true);
}

test "embeddinggemma2 video host borrows avoid copies and writable views reject shared ownership" {
    const a = std.testing.allocator;
    var store = WeightStore{ .allocator = a, .resident_weights = .{}, .lazy_weights = .{} };
    defer store.deinitOwned();
    var compute = NativeCompute.init(a, &store, null);
    defer compute.deinit();
    const cb = compute.computeBackend();
    var values = [_]f32{ 1, 2, 3, 4, 5, 6 };
    const borrowed = try cb.fromBorrowedFloat32Shape(&values, &.{ 2, 3 });
    try std.testing.expectEqual(values[0..].ptr, (try cb.hostFloat32Read(borrowed)).?.ptr);
    try std.testing.expectEqual(@as(?[]f32, null), try cb.hostFloat32Write(borrowed));
    try std.testing.expectError(error.InvalidShape, cb.fromBorrowedFloat32Shape(&values, &.{ 3, 3 }));
    cb.free(borrowed); // Borrowed stack storage remains caller owned.
    try std.testing.expectEqual(@as(f32, 6), values[5]);
    const output = (try cb.allocUninitF32Shape(&.{ 2, 3 })).?;
    const target = (try cb.hostFloat32Write(output)).?;
    @memcpy(target, &values);
    const view = try cb.sliceRows2D(a, output, 1, 1, 3);
    try std.testing.expectEqual(@as(?[]f32, null), try cb.hostFloat32Write(output));
    try std.testing.expectEqual(@as(?[]f32, null), try cb.hostFloat32Write(view));
    try std.testing.expectEqualSlices(f32, &.{ 4, 5, 6 }, (try cb.hostFloat32Read(view)).?);
    cb.free(output); // The retained row still owns the parent allocation.
    try std.testing.expectEqualSlices(f32, &.{ 4, 5, 6 }, (try cb.hostFloat32Read(view)).?);
    cb.free(view);
}

fn physicalTensorViewOp(ctx: *anyopaque, request: ops.physical_storage.View) anyerror!?CT {
    if (request.dtype != .f32) return null;
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const source = toBuf(request.storage.tensor);
    var count: usize = 1;
    if (request.shape.len > 8 or source.view_strides != null) return null;
    var shape: [8]i64 = undefined;
    for (request.shape, 0..) |dim, i| {
        if (dim <= 0) return error.InvalidShape;
        count = try std.math.mul(usize, count, @intCast(dim));
        shape[i] = dim;
    }
    if (count > source.data.len) return error.InvalidShape;
    const view = try self.makeBuf(source.data[0..count], false);
    errdefer freeTensor(self, view);
    _ = try self.withLogicalShape(view, shape[0..request.shape.len]);
    request.storage.retain();
    toBuf(view).physical_lease = request.storage;
    return view;
}

fn runAssignedKernelOp(ctx: *anyopaque, request: ops.kernel_descriptor.Invocation) anyerror!bool {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    const descriptor = request.descriptor;
    if (descriptor.operation == .transpose or descriptor.operation == .broadcast or descriptor.operation == .concat or descriptor.operation == .slice or descriptor.operation == .gather) return false;
    if (request.inputs.len != descriptor.input_count) return error.InvalidTensorShape;
    for (request.inputs, 0..) |input, i| {
        const buf = toBuf(input);
        if (descriptor.operation == .linear and i == 1 and buf.view_strides == null) {
            if (buf.quantized_storage) |storage| {
                const linear = descriptor.operation.linear;
                if (storage.packed_expert != null or storage.shape.len != 2 or storage.shape[0] != linear.out_dim or storage.shape[1] != linear.in_dim) return false;
                const selected = nativeQuantMatmulOperatorPlanForTensor(input, linear.rows, linear.in_dim, linear.out_dim) orelse return false;
                try validateQuantLinearPlan(request.operatorPlan() orelse selected, storage, linear.rows, linear.in_dim, linear.out_dim);
                continue;
            }
            if (buf.source_tensor) |tensor| {
                if (tensor.elementCount() == descriptor.input_shapes[i].numElements().? and
                    (tensor.dtype == .f32 or tensor.dtype == .f16 or tensor.dtype == .bf16)) continue;
            }
        }
        if (buf.view_strides != null or (buf.declared_dtype != null and buf.declared_dtype != .f32) or
            buf.data.len != descriptor.input_shapes[i].numElements().?) return false;
    }
    if (descriptor.operation == .dot and (toBuf(request.inputs[0]).quantized_storage != null or toBuf(request.inputs[1]).quantized_storage != null)) return false;
    if (descriptor.operation == .rope and (request.auxiliaries.len != 0 or !descriptor.operation.rope.valid(descriptor.output_shape.dims[0..descriptor.output_shape.rank()], descriptor.elements()))) return false;
    const output_ct = request.output orelse return true;
    const target = toBuf(output_ct);
    const output = target.data;
    if (target.physical_lease == null or output.len != descriptor.elements()) return error.InvalidTensorShape;
    if (descriptor.operation == .rope) {
        const source = toBuf(request.inputs[0]).data;
        if (kernel_geometry.byteRangesOverlap(@intFromPtr(source.ptr), source.len * 4, @intFromPtr(output.ptr), output.len * 4)) return error.InvalidAssignedAlias;
    }
    switch (descriptor.operation) {
        .transpose, .broadcast, .concat, .slice, .gather => unreachable,
        .dot => |dot| denseDotInto(toBuf(request.inputs[0]).data, toBuf(request.inputs[1]).data, output, dot),
        .reduction => |reduction| reduceInto(toBuf(request.inputs[0]).data, output, reduction.geometry, reduction.mode),
        .rope => |rope_request| try ropeInto(self, request.inputs[0], output, rope_request),
        .norm => |norm| {
            const input = toBuf(request.inputs[0]).data;
            if (output.ptr != input.ptr) @memcpy(output, input);
            defer maybeDiscardMappedWeightAfterUse(self, request.inputs[1]);
            if (norm.kind == .layer) {
                defer maybeDiscardMappedWeightAfterUse(self, request.inputs[2]);
                activations_mod.layerNorm(output, getData(request.inputs[1]), getData(request.inputs[2]), norm.dim, norm.eps);
            } else activations_mod.rmsNorm(output, getData(request.inputs[1]), norm.dim, norm.eps);
        },
        .softmax => |softmax| {
            const input = toBuf(request.inputs[0]).data;
            if (softmax.logarithmic) {
                if (output.ptr != input.ptr) @memcpy(output, input);
                activations_mod.logSoftmaxInPlace(output, softmax.width);
            } else softmaxInto(input, output, kernel_geometry.DenseRows.init(input.len, softmax.width) catch unreachable);
        },
        .linear => |linear| {
            const bias = if (linear.bias) request.inputs[2] else null;
            if (toBuf(request.inputs[1]).quantized_storage != null) {
                const selected = request.operatorPlan() orelse nativeQuantMatmulOperatorPlanForTensor(request.inputs[1], linear.rows, linear.in_dim, linear.out_dim).?;
                try plannedQuantLinearInto(self, request.inputs[0], request.inputs[1], bias, linear.rows, linear.in_dim, linear.out_dim, output, selected);
            } else if (linear.bias) try linearInto(ctx, request.inputs[0], request.inputs[1], request.inputs[2], linear.rows, linear.in_dim, linear.out_dim, output) else try linearNoBiasInto(ctx, request.inputs[0], request.inputs[1], linear.rows, linear.in_dim, linear.out_dim, output);
        },
        .unary => |op| switch (op) {
            .gelu, .gelu_exact, .relu, .silu => {
                const input = toBuf(request.inputs[0]).data;
                if (output.ptr != input.ptr) @memcpy(output, input);
                switch (op) {
                    .gelu => try applyGeluForSession(self, output),
                    .gelu_exact => activations_mod.geluExact(output),
                    .relu => activations_mod.relu(output),
                    .silu => activations_mod.silu(output),
                    else => unreachable,
                }
            },
            inline else => |tag| primitiveUnaryInto(tag, toBuf(request.inputs[0]).data, output),
        },
        .binary => |op| {
            const a = toBuf(request.inputs[0]).data;
            const b = toBuf(request.inputs[1]).data;
            const scalar_a = a[0];
            const scalar_b = b[0];
            inline for (comptime std.meta.tags(ops.kernel_descriptor.Binary)) |kind| {
                if (op == kind) {
                    var i: usize = 0;
                    while (i + VEC_LEN <= output.len) : (i += VEC_LEN) {
                        const av: F32xN = if (a.len == 1) @splat(scalar_a) else a[i..][0..VEC_LEN].*;
                        const bv: F32xN = if (b.len == 1) @splat(scalar_b) else b[i..][0..VEC_LEN].*;
                        output[i..][0..VEC_LEN].* = denseArithmetic(kind, av, bv);
                    }
                    while (i < output.len) : (i += 1) {
                        const av = if (a.len == 1) scalar_a else a[i];
                        const bv = if (b.len == 1) scalar_b else b[i];
                        output[i] = denseArithmetic(kind, av, bv);
                    }
                    break;
                }
            }
        },
    }
    return true;
}

fn allocateLinearOutput(ctx: *anyopaque, input: CT, weight: CT, bias: ?CT, rows: usize, in_dim: usize, out_dim: usize) anyerror!CT {
    return allocateLinearOutputWithPlan(ctx, input, weight, bias, rows, in_dim, out_dim, null);
}
fn allocateLinearOutputWithPlan(ctx: *anyopaque, input: CT, weight: CT, bias: ?CT, rows: usize, in_dim: usize, out_dim: usize, plan: ?ops.OperatorPlan) anyerror!CT {
    const self: *NativeCompute = @ptrCast(@alignCast(ctx));
    if (plan) |selected| if (toBuf(weight).quantized_storage) |storage| try validateQuantLinearPlan(selected, storage, rows, in_dim, out_dim);
    var owned: ?[]f32 = try self.allocator.alloc(f32, try std.math.mul(usize, rows, out_dim));
    errdefer if (owned) |data| self.allocator.free(data);
    if (plan != null and toBuf(weight).quantized_storage != null) {
        try plannedQuantLinearInto(self, input, weight, bias, rows, in_dim, out_dim, owned.?, plan.?);
    } else if (bias) |value| try linearInto(ctx, input, weight, value, rows, in_dim, out_dim, owned.?) else try linearNoBiasInto(ctx, input, weight, rows, in_dim, out_dim, owned.?);
    const result = try self.makeBuf(owned.?, true);
    owned = null;
    errdefer freeTensor(ctx, result);
    return self.withLogicalShape(result, &.{ @intCast(rows), @intCast(out_dim) });
}

test "shared packed projection schedules cover arities raw prepared bias and column tails" {
    const a = std.testing.allocator;
    const rows = 5;
    const in_dim = 512;
    const out_dim = 19;
    const first = 1;
    const last = 18;
    const shape = [_]i64{ out_dim, in_dim };
    var input: [rows * in_dim]f32 = undefined;
    fillNativeQuantDispatchValues(&input, 31, 0.03);
    inline for (.{ gguf_tensor_types.KnownTensorType.Q8_0, .Q4_K, .Q5_K }) |kind| {
        var storage: [3]QuantizedStorage = undefined;
        var initialized: usize = 0;
        defer for (storage[0..initialized]) |*item| item.deinit();
        var raw_weights: [3][]const u8 = undefined;
        var prepared: [3][]const u8 = undefined;
        var panels: [3][]const u8 = undefined;
        var bias: [3][out_dim]f32 = undefined;
        var bias_views: [3]?[]const f32 = undefined;
        var expected: [3][rows * out_dim]f32 = @splat(@splat(-12345));
        var actual = expected;
        var outputs: [3][]f32 = undefined;
        for (0..3) |pidx| {
            var values: [out_dim * in_dim]f32 = undefined;
            fillNativeQuantDispatchValues(&values, pidx + 7, 0.005);
            const raw = try quantizeNativeDispatchWeight(a, kind, &values);
            errdefer if (initialized <= pidx) a.free(raw);
            const owned_shape = try a.dupe(i64, &shape);
            storage[pidx] = .{ .allocator = a, .tensor_type = .{ .known = kind }, .raw_bytes = raw, .shape = owned_shape, .raw_owned = true };
            initialized += 1;
            try prepareNativeQuantizedStorage(&storage[pidx]);
            raw_weights[pidx] = raw;
            prepared[pidx] = storage[pidx].preparedBytes(.row_major_blocks).?;
            if (kind != .Q8_0) panels[pidx] = storage[pidx].preparedBytes(.panel8).?;
            fillNativeQuantDispatchValues(&bias[pidx], pidx + 19, 0.01);
            bias_views[pidx] = if (pidx == 1) null else &bias[pidx];
            outputs[pidx] = &actual[pidx];
        }
        if (kind == .Q8_0) {
            var quantized: [rows * in_dim]u8 = undefined;
            var scales: [rows * (in_dim / 32)]f32 = undefined;
            quantizeQ8_0ActivationRows(&input, &quantized, &scales, rows, in_dim, in_dim / 32);
            inline for (.{ false, true }) |use_prepared| {
                const weights = if (use_prepared) prepared else raw_weights;
                for (0..3) |pidx| linearQ8_0QuantizedInputGroupedRange(use_prepared, 1, &quantized, &scales, .{weights[pidx]}, .{null}, .{bias_views[pidx]}, .{&expected[pidx]}, rows, in_dim, out_dim, first, last);
                inline for (.{ 2, 3 }) |arity| {
                    actual = @splat(@splat(-12345));
                    linearQ8_0QuantizedInputSpecializedRange(use_prepared, arity, &quantized, &scales, weights[0..arity].*, @splat(null), bias_views[0..arity].*, outputs[0..arity].*, rows, in_dim, out_dim, first, last);
                    inline for (0..arity) |pidx| try std.testing.expectEqualSlices(f32, &expected[pidx], &actual[pidx]);
                    if (arity == 2) for (actual[2]) |value| try std.testing.expectEqual(@as(f32, -12345), value);
                }
            }
            for (0..4) |mode| {
                var optional_blocks: [3]?[]const u8 = undefined;
                for (0..3) |pidx| optional_blocks[pidx] = if (mode == 1 or (mode >= 2 and pidx == mode - 2)) prepared[pidx] else null;
                expected = @splat(@splat(-12345));
                for (0..3) |pidx| q8_0ActivationApply(&quantized, &scales, raw_weights[pidx], optional_blocks[pidx], null, null, bias_views[pidx], &expected[pidx], rows, in_dim, out_dim, first, last);
                inline for (.{ 2, 3 }) |arity| {
                    actual = @splat(@splat(-12345));
                    q8_0ActivationGroupedApply(arity, &quantized, &scales, raw_weights[0..arity].*, optional_blocks[0..arity].*, @splat(null), @splat(null), bias_views[0..arity].*, outputs[0..arity].*, rows, in_dim, out_dim, first, last);
                    inline for (0..arity) |pidx| try std.testing.expectEqualSlices(f32, &expected[pidx], &actual[pidx]);
                }
            }
        } else {
            var quantized: [rows * (in_dim / 256) * 292]u8 = undefined;
            quantizeQ8_KActivationRows(&input, &quantized, rows, in_dim, in_dim / 256);
            for (0..3) |pidx| linearQ4Q5KPreparedQ8KActivationRange(&quantized, prepared[pidx], null, null, null, null, &expected[pidx], rows, in_dim, out_dim, first, last, kind);
            inline for (.{ 2, 3 }) |arity| {
                actual = @splat(@splat(-12345));
                linearQ4Q5KPreparedQ8KActivationGroupedPanel8Range(arity, &quantized, prepared[0..arity].*, panels[0..arity].*, outputs[0..arity].*, rows, in_dim, out_dim, first, last);
                inline for (0..arity) |pidx| try std.testing.expectEqualSlices(f32, &expected[pidx], &actual[pidx]);
                if (arity == 2) for (actual[2]) |value| try std.testing.expectEqual(@as(f32, -12345), value);
            }
        }
    }
}

