test "Q8K wide native specialization independent oracle and benchmark" {
    @setEvalBranchQuota(200_000);
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        weights: [16][292]u8 align(64) = @splat(@splat(0)),
        panel8: [prepared_q8_k_panel8_block_bytes]u8 align(64) = undefined,
        panel16: [prepared_q8_k_panel16_block_bytes]u8 align(64) = undefined,

        inline fn run(self: *@This(), comptime mr: usize, comptime layout: usize) [mr][if (layout == 16) 16 else 8]f32 {
            if (comptime layout == 0) {
                const w: [8][]const u8 = .{ &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3], &self.weights[4], &self.weights[5], &self.weights[6], &self.weights[7] };
                if (comptime mr == 1) return .{dotQ8KQ8KBlock8Blocks(&self.inputs[0], w)};
                if (comptime mr == 2) {
                    const v = dotQ8KQ8KBlock8MR2Blocks(&self.inputs[0], &self.inputs[1], w);
                    return .{ v.r0, v.r1 };
                }
                const v = dotQ8KQ8KBlock8MR4Blocks(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], w);
                return .{ v.r0, v.r1, v.r2, v.r3 };
            }
            if (comptime layout == 8) {
                if (comptime mr == 1) return .{dotQ8KQ8KBlock8(&self.inputs[0], &self.panel8)};
                if (comptime mr == 2) {
                    const v = dotQ8KQ8KBlock8MR2(&self.inputs[0], &self.inputs[1], &self.panel8);
                    return .{ v.r0, v.r1 };
                }
                const v = dotQ8KQ8KBlock8MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel8);
                return .{ v.r0, v.r1, v.r2, v.r3 };
            }
            if (comptime mr == 1) return .{dotQ8KQ8KBlock16(&self.inputs[0], &self.panel16)};
            if (comptime mr == 2) {
                const v = dotQ8KQ8KBlock16MR2(&self.inputs[0], &self.inputs[1], &self.panel16);
                return .{ v.r0, v.r1 };
            }
            const v = dotQ8KQ8KBlock16MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel16);
            return .{ v.r0, v.r1, v.r2, v.r3 };
        }

        noinline fn measure(self: *@This(), comptime mr: usize, comptime layout: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..2001) |_| {
                self.inputs[0][4] +%= 1;
                std.mem.doNotOptimizeAway(self.run(mr, layout));
            }
            return @intCast(@divTrunc(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start, 2001));
        }
    };
    var state: State = .{};
    for (&state.inputs, 0..) |*input, row| {
        const scale: f32 = @as(f32, @floatFromInt(row + 1)) * (if (row % 2 == 0) @as(f32, 0.125) else -0.125);
        std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
        for (0..256) |i| input[4 + i] = @bitCast(@as(i8, @intCast(@as(i32, @intCast((i * 13 + row * 7) % 255)) - 127)));
    }
    for (&state.weights, 0..) |*weight, col| {
        const scale: f32 = @as(f32, @floatFromInt(col + 1)) * 0.0625;
        std.mem.writeInt(u32, weight[0..4], @bitCast(scale), .little);
        for (0..256) |i| weight[4 + i] = @bitCast(@as(i8, @intCast(@as(i32, @intCast((i * 11 + col * 3) % 255)) - 127)));
        if (col < 8) {
            @memcpy(state.panel8[prepared_q8_k_panel8_dsc_offset + col * 4 ..][0..4], weight[0..4]);
            for (0..8) |chunk| @memcpy(state.panel8[prepared_q8_k_panel8_values_offset + (chunk * 8 + col) * 32 ..][0..32], weight[4 + chunk * 32 ..][0..32]);
        }
        @memcpy(state.panel16[prepared_q8_k_panel16_dsc_offset + col * 4 ..][0..4], weight[0..4]);
        for (0..8) |chunk| @memcpy(state.panel16[prepared_q8_k_panel16_values_offset + (chunk * 16 + col) * 32 ..][0..32], weight[4 + chunk * 32 ..][0..32]);
    }
    inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 8, 16 }) |layout| {
        const output = state.run(mr, layout);
        for (output, 0..) |row, r| for (row, 0..) |got, c| {
            var dot: f64 = 0;
            for (0..256) |i| dot += @as(f64, @floatFromInt(@as(i8, @bitCast(state.inputs[r][4 + i])))) * @as(f64, @floatFromInt(@as(i8, @bitCast(state.weights[c][4 + i]))));
            const expected: f32 = @floatCast((@as(f64, readF32Le(state.inputs[r][0..4])) * @as(f64, readF32Le(state.weights[c][0..4]))) * dot);
            try std.testing.expectEqual(expected, got);
        };
    };
    if (platform.env.getenvBool("ANTFLY_Q8_WIDE_BENCH")) {
        inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 8, 16 }) |layout| {
            for (0..10) |_| _ = state.measure(mr, layout);
            var times: [21]u64 = undefined;
            for (&times) |*sample| sample.* = state.measure(mr, layout);
            std.mem.sort(u64, &times, {}, std.sort.asc(u64));
            std.debug.print("q8_wide mr={d} layout={d} p50_ns={d} p95_ns={d}\n", .{ mr, layout, times[10], times[19] });
        };
    }
}

test "native K16 and Q8 narrow panels independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        k16: [prepared_k16_panel8_block_bytes]u8 align(64) = @splat(0),
        q8: [prepared_q8_k_panel4_block_bytes]u8 align(64) = @splat(0),
        noinline fn run(self: *@This(), comptime mr: usize, comptime kind: usize) [mr * (if (kind == 2) 4 else 8)]f32 {
            if (comptime kind == 2) {
                if (comptime mr == 1) return dotQ8KQ8KPanel4(&self.inputs[0], &self.q8);
                if (comptime mr == 2) return dotQ8KQ8KPanel4MR2(&self.inputs[0], &self.inputs[1], &self.q8);
                return dotQ8KQ8KPanel4MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.q8);
            }
            var rows: [mr]F32x8 = undefined;
            if (comptime mr == 1) {
                rows[0] = dotK16PreparedQ8KPanel8Vec(kind == 1, &self.inputs[0], &self.k16);
            } else if (comptime mr == 2) {
                const sums = dotK16PreparedQ8KPanel8MR2Vec(kind == 1, &self.inputs[0], &self.inputs[1], &self.k16);
                rows = .{ sums.r0, sums.r1 };
            } else {
                const sums = dotK16PreparedQ8KPanel8MR4Vec(kind == 1, &self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.k16);
                rows = .{ sums.r0, sums.r1, sums.r2, sums.r3 };
            }
            var output: [mr * 8]f32 = undefined;
            inline for (0..mr) |row| {
                const values = f32x8ToArray(rows[row]);
                @memcpy(output[row * 8 ..][0..8], &values);
            }
            return output;
        }
        noinline fn measure(self: *@This(), comptime mr: usize, comptime kind: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..20001) |_| {
                self.inputs[0][4] +%= 1;
                std.mem.doNotOptimizeAway(self.run(mr, kind));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    for (&state.inputs, 0..) |*input, row| {
        std.mem.writeInt(u32, input[0..4], @bitCast(@as(f32, @floatFromInt(row + 1)) * (if (row % 2 == 0) @as(f32, 0.125) else -0.125)), .little);
        for (0..16) |sub| {
            var sum: i16 = 0;
            for (0..16) |i| {
                const x: i8 = @intCast(@as(i32, @intCast((sub * 16 + i * 7 + row * 3) % 16)) - 8);
                input[4 + sub * 16 + i] = @bitCast(x);
                sum += x;
            }
            std.mem.writeInt(i16, input[260 + sub * 2 ..][0..2], sum, .little);
        }
    }
    for (0..16) |sub| for (0..8) |col| {
        const dsc: f32 = @as(f32, @floatFromInt(col + sub + 1)) * 0.125;
        const dmn: f32 = @as(f32, @floatFromInt(col + 1)) * 0.0625;
        std.mem.writeInt(u32, state.k16[prepared_k16_panel8_dsc_offset + (sub * 8 + col) * 4 ..][0..4], @bitCast(dsc), .little);
        std.mem.writeInt(u32, state.k16[prepared_k16_panel8_dmn_offset + (sub * 8 + col) * 4 ..][0..4], @bitCast(dmn), .little);
        for (0..16) |i| state.k16[prepared_k16_panel8_values_offset + (sub * 8 + col) * 16 + i] = @bitCast(@as(i8, @intCast(@as(i32, @intCast((sub * 3 + i * 5 + col) % 16)) - 8)));
    };
    for (0..4) |col| {
        std.mem.writeInt(u32, state.q8[prepared_q8_k_panel4_dsc_offset + col * 4 ..][0..4], @bitCast(@as(f32, @floatFromInt(col + 1)) * 0.0625), .little);
        for (0..8) |chunk| for (0..32) |i| {
            state.q8[prepared_q8_k_panel4_values_offset + (chunk * 4 + col) * 32 + i] = @bitCast(@as(i8, @intCast(@as(i32, @intCast((chunk * 3 + i * 5 + col) % 16)) - 8)));
        };
    }
    inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 1, 2 }) |kind| {
        const output = state.run(mr, kind);
        const nr = if (kind == 2) 4 else 8;
        for (0..mr) |row| for (0..nr) |col| {
            var expected: f64 = 0;
            for (0..256) |i| {
                const x: f64 = @floatFromInt(@as(i8, @bitCast(state.inputs[row][4 + i])));
                const weight: f64 = if (kind == 2)
                    @as(f64, readF32Le(state.q8[prepared_q8_k_panel4_dsc_offset + col * 4 ..][0..4])) * @as(f64, @floatFromInt(@as(i8, @bitCast(state.q8[prepared_q8_k_panel4_values_offset + ((i / 32) * 4 + col) * 32 + i % 32]))))
                else
                    @as(f64, readF32Le(state.k16[prepared_k16_panel8_dsc_offset + ((i / 16) * 8 + col) * 4 ..][0..4])) * @as(f64, @floatFromInt(@as(i8, @bitCast(state.k16[prepared_k16_panel8_values_offset + ((i / 16) * 8 + col) * 16 + i % 16])))) - (if (kind == 1) @as(f64, readF32Le(state.k16[prepared_k16_panel8_dmn_offset + ((i / 16) * 8 + col) * 4 ..][0..4])) else 0);
                expected += x * weight;
            }
            expected *= @as(f64, readF32Le(state.inputs[row][0..4]));
            try std.testing.expectEqual(@as(f32, @floatCast(expected)), output[row * nr + col]);
        };
    };
    if (platform.env.getenvBool("ANTFLY_PANEL_NATIVE_BENCH")) {
        inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 1, 2 }) |kind| {
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(mr, kind);
            var times: [21]u64 = undefined;
            for (&times) |*sample| sample.* = state.measure(mr, kind);
            std.mem.sort(u64, &times, {}, std.sort.asc(u64));
            std.debug.print("panel_native mr={d} kind={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=20001\n", .{ mr, kind, @as(f64, @floatFromInt(times[10])) / 20001.0, @as(f64, @floatFromInt(times[19])) / 20001.0, times[10], times[19] });
        };
    }
}

test "Q8 four column families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        weights: [4][292]u8 align(64) = @splat(@splat(0)),
        panel: [prepared_q8_k_panel4_block_bytes]u8 align(64) = @splat(0),
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                const scale: f32 = (if ((seed + row) % 2 == 0) @as(f32, 0.125) else -0.25);
                std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
                for (0..256) |i| input[4 + i] = @bitCast(@as(i8, @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 255)) - 127)));
            }
            for (&self.weights, 0..) |*weight, col| {
                const scale: f32 = (if ((seed + col) % 2 == 0) @as(f32, 0.0625) else -0.125);
                std.mem.writeInt(u32, weight[0..4], @bitCast(scale), .little);
                std.mem.writeInt(u32, self.panel[prepared_q8_k_panel4_dsc_offset + col * 4 ..][0..4], @bitCast(scale), .little);
                for (0..256) |i| {
                    const x: i8 = @intCast(@as(i32, @intCast((i * 29 + col * 19 + seed * 13) % 255)) - 127);
                    weight[4 + i] = @bitCast(x);
                    self.panel[prepared_q8_k_panel4_values_offset + ((i / 32) * 4 + col) * 32 + i % 32] = @bitCast(x);
                }
            }
        }
        inline fn flatten(comptime mr: usize, values: anytype) [mr * 4]f32 {
            var result: [mr * 4]f32 = undefined;
            inline for (0..mr * 4) |i| result[i] = values[i];
            return result;
        }
        noinline fn run(self: *@This(), comptime mr: usize, comptime kind: usize) [mr * 4]f32 {
            if (comptime kind == 2) {
                if (comptime mr == 1) return dotQ8KQ8KPanel4(&self.inputs[0], &self.panel);
                if (comptime mr == 2) return dotQ8KQ8KPanel4MR2(&self.inputs[0], &self.inputs[1], &self.panel);
                return dotQ8KQ8KPanel4MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel);
            }
            if (comptime kind == 1) {
                if (comptime mr == 1) return flatten(mr, dotQ8KQ8KBlock4FusedSdot(&self.inputs[0], &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]));
                if (comptime mr == 2) return flatten(mr, dotQ8KQ8KBlock4MR2FusedSdot(&self.inputs[0], &self.inputs[1], &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]));
                return dotQ8KQ8KBlock4MR4FusedSdot(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]);
            }
            if (comptime mr == 1) return flatten(mr, dotQ8KQ8KBlock4(&self.inputs[0], &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]));
            if (comptime mr == 2) return flatten(mr, dotQ8KQ8KBlock4MR2(&self.inputs[0], &self.inputs[1], &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]));
            return dotQ8KQ8KBlock4MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]);
        }
        noinline fn measure(self: *@This(), comptime mr: usize, comptime kind: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..20001) |_| {
                self.inputs[0][4] +%= 1;
                std.mem.doNotOptimizeAway(self.run(mr, kind));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 1, 2 }) |kind| {
            const output = state.run(mr, kind);
            for (0..mr) |row| for (0..4) |col| {
                var dot: f64 = 0;
                for (0..256) |i| dot += @as(f64, @floatFromInt(@as(i8, @bitCast(state.inputs[row][4 + i])))) * @as(f64, @floatFromInt(@as(i8, @bitCast(state.weights[col][4 + i]))));
                const expected: f32 = @floatCast(@as(f64, readF32Le(state.inputs[row][0..4])) * @as(f64, readF32Le(state.weights[col][0..4])) * dot);
                try std.testing.expectEqual(@as(u32, @bitCast(expected)), @as(u32, @bitCast(output[row * 4 + col])));
            };
        };
    }
    if (platform.env.getenvBool("ANTFLY_Q8_FOUR_BENCH")) {
        state.initialize(1);
        inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 1, 2 }) |kind| {
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(mr, kind);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(mr, kind);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("q8_four mr={d} kind={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=20001\n", .{ mr, kind, @as(f64, @floatFromInt(samples[10])) / 20001.0, @as(f64, @floatFromInt(samples[19])) / 20001.0, samples[10], samples[19] });
        };
    }
}

test "Q6 panel8 row families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        panel: [prepared_q6_k_panel8_block_bytes]u8 align(64) = @splat(0),
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                const scale: f32 = if ((seed + row) % 2 == 0) 0.125 else -0.25;
                std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
                for (0..256) |i| {
                    const value: i8 = if (seed == 0) 0 else if (seed == 1) (if (i % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 256)) - 128);
                    input[4 + i] = @bitCast(value);
                }
            }
            for (0..8) |col| {
                const scale: f32 = if ((seed + col) % 2 == 0) 0.0625 else -0.125;
                std.mem.writeInt(u32, self.panel[prepared_q6_k_panel8_d_offset + col * 4 ..][0..4], @bitCast(scale), .little);
                for (0..16) |sub| {
                    const qscale: i8 = if (seed == 1) (if (col % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((sub * 23 + col * 31 + seed * 7) % 256)) - 128);
                    self.panel[prepared_q6_k_panel8_scales_offset + sub * 8 + col] = @bitCast(qscale);
                    for (0..16) |i| {
                        const weight: i8 = if (seed == 1) (if (i % 2 == 0) -32 else 31) else @intCast(@as(i32, @intCast((i * 7 + col * 13 + sub * 19 + seed * 3) % 64)) - 32);
                        self.panel[prepared_q6_k_panel8_values_offset + (sub * 8 + col) * 16 + i] = @bitCast(weight);
                    }
                }
            }
        }
        noinline fn run(self: *@This(), comptime mr: usize, comptime kind: usize) [mr]F32x8 {
            if (comptime kind == 1 and native_aarch64_dotprod) {
                if (comptime mr == 1) return .{dotQ6KPreparedQ8KPanel8VecFusedSdot(&self.inputs[0], &self.panel)};
                if (comptime mr == 2) {
                    const d = dotQ6KPreparedQ8KPanel8MR2VecFusedSdot(&self.inputs[0], &self.inputs[1], &self.panel);
                    return .{ d.r0, d.r1 };
                }
                const d = dotQ6KPreparedQ8KPanel8MR4VecFusedSdot(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel);
                return .{ d.r0, d.r1, d.r2, d.r3 };
            }
            if (comptime mr == 1) return .{dotQ6KPreparedQ8KPanel8Vec(&self.inputs[0], &self.panel)};
            if (comptime mr == 2) {
                const d = dotQ6KPreparedQ8KPanel8MR2Vec(&self.inputs[0], &self.inputs[1], &self.panel);
                return .{ d.r0, d.r1 };
            }
            const d = dotQ6KPreparedQ8KPanel8MR4Vec(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel);
            return .{ d.r0, d.r1, d.r2, d.r3 };
        }
        noinline fn measure(self: *@This(), comptime mr: usize, comptime kind: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..20001) |_| {
                self.inputs[0][4] +%= 1;
                std.mem.doNotOptimizeAway(self.run(mr, kind));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    // The ordinary entry must exercise its original non-fused schedule.
    setQ6KPanel8FusedSdotOverrideForBench(false);
    defer setQ6KPanel8FusedSdotOverrideForBench(null);
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 1 }) |kind| {
            const output = state.run(mr, kind);
            for (0..mr) |row| for (0..8) |col| {
                var sum: f64 = 0;
                for (0..16) |sub| {
                    var dot: f64 = 0;
                    for (0..16) |i| dot += @as(f64, @floatFromInt(@as(i8, @bitCast(state.inputs[row][4 + sub * 16 + i])))) * @as(f64, @floatFromInt(@as(i8, @bitCast(state.panel[prepared_q6_k_panel8_values_offset + (sub * 8 + col) * 16 + i]))));
                    sum += dot * @as(f64, @floatFromInt(@as(i8, @bitCast(state.panel[prepared_q6_k_panel8_scales_offset + sub * 8 + col]))));
                }
                const expected: f32 = @floatCast(@as(f64, readF32Le(state.inputs[row][0..4])) * @as(f64, readF32Le(state.panel[prepared_q6_k_panel8_d_offset + col * 4 ..][0..4])) * sum);
                try std.testing.expectEqual(@as(u32, @bitCast(expected)), @as(u32, @bitCast(f32x8ToArray(output[row])[col])));
            };
        };
    }
    if (platform.env.getenvBool("ANTFLY_Q6_PANEL_BENCH")) {
        state.initialize(3);
        inline for (.{ 1, 2, 4 }) |mr| inline for (.{ 0, 1 }) |kind| {
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(mr, kind);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(mr, kind);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("q6_panel mr={d} kind={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=20001\n", .{ mr, kind, @as(f64, @floatFromInt(samples[10])) / 20001.0, @as(f64, @floatFromInt(samples[19])) / 20001.0, samples[10], samples[19] });
        };
    }
}

test "integer tile owners independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const profiles = .{
        .{ .mr = 1, .nc = 4, .bytes = 16, .arm = false },
        .{ .mr = 2, .nc = 4, .bytes = 16, .arm = false },
        .{ .mr = 1, .nc = 8, .bytes = 16, .arm = false },
        .{ .mr = 1, .nc = 4, .bytes = 32, .arm = false },
        .{ .mr = 1, .nc = 4, .bytes = 32, .arm = true },
        .{ .mr = 2, .nc = 4, .bytes = 32, .arm = false },
        .{ .mr = 2, .nc = 4, .bytes = 32, .arm = true },
        .{ .mr = 2, .nc = 8, .bytes = 32, .arm = true },
        .{ .mr = 4, .nc = 4, .bytes = 32, .arm = true },
        .{ .mr = 2, .nc = 8, .bytes = 32, .arm = true },
        .{ .mr = 2, .nc = 8, .bytes = 32, .arm = true },
        .{ .mr = 2, .nc = 8, .bytes = 16, .arm = false },
    };
    const State = struct {
        inputs: [4][32]u8 align(64) = @splat(@splat(0)),
        weights: [8][32]u8 align(64) = @splat(@splat(0)),
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| for (0..32) |i| {
                const value: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + row) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 256)) - 128);
                input[i] = @bitCast(value);
            };
            for (&self.weights, 0..) |*weight, col| for (0..32) |i| {
                const value: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + col) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 29 + col * 19 + seed * 13) % 256)) - 128);
                weight[i] = @bitCast(value);
            };
        }
        noinline fn run(self: *@This(), comptime profile: usize) [profiles[profile].mr * profiles[profile].nc]i32 {
            if (comptime profile == 0) {
                const values = dotI8I8Block4_16(self.inputs[0][0..16], self.weights[0][0..16], self.weights[1][0..16], self.weights[2][0..16], self.weights[3][0..16]);
                var output: [4]i32 = undefined;
                inline for (0..4) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 1) {
                const values = dotI8I8Block4MR2_16(self.inputs[0][0..16], self.inputs[1][0..16], self.weights[0][0..16], self.weights[1][0..16], self.weights[2][0..16], self.weights[3][0..16]);
                var output: [8]i32 = undefined;
                inline for (0..8) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 2) {
                const values = dotI8I8Block8_16Vec(self.inputs[0][0..16], self.weights[0][0..16], self.weights[1][0..16], self.weights[2][0..16], self.weights[3][0..16], self.weights[4][0..16], self.weights[5][0..16], self.weights[6][0..16], self.weights[7][0..16]);
                var output: [8]i32 = undefined;
                inline for (0..8) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 3) {
                const values = dotI8I8Block4Portable(self.inputs[0][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32]);
                var output: [4]i32 = undefined;
                inline for (0..4) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 4) {
                const values = dotI8I8Block4Aarch64Sdot(self.inputs[0][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32]);
                var output: [4]i32 = undefined;
                inline for (0..4) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 5) {
                const values = dotI8I8Block4MR2Portable(self.inputs[0][0..32], self.inputs[1][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32]);
                var output: [8]i32 = undefined;
                inline for (0..8) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 6) {
                const values = dotI8I8Block4MR2Aarch64Sdot(self.inputs[0][0..32], self.inputs[1][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32]);
                var output: [8]i32 = undefined;
                inline for (0..8) |i| output[i] = values[i];
                return output;
            }
            if (comptime profile == 7) {
                const values = dotI8I8Block8MR2Aarch64Sdot(self.inputs[0][0..32], self.inputs[1][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32], self.weights[4][0..32], self.weights[5][0..32], self.weights[6][0..32], self.weights[7][0..32]);
                return values;
            }
            if (comptime profile == 8) {
                const values = dotI8I8Block4MR4Aarch64Sdot(self.inputs[0][0..32], self.inputs[1][0..32], self.inputs[2][0..32], self.inputs[3][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32]);
                return values;
            }
            if (comptime profile == 9) {
                const values = dotI8I8Block8MR2RowsVecAarch64Sdot(self.inputs[0][0..32], self.inputs[1][0..32], self.weights[0][0..32], self.weights[1][0..32], self.weights[2][0..32], self.weights[3][0..32], self.weights[4][0..32], self.weights[5][0..32], self.weights[6][0..32], self.weights[7][0..32]);
                var output: [16]i32 = undefined;
                inline for (0..8) |col| output[0 + col] = values.r0[col];
                inline for (0..8) |col| output[8 + col] = values.r1[col];
                return output;
            }
            if (comptime profile == 10) {
                const values = dotI8I8Block8MR2RowsContiguousVecAarch64Sdot(self.inputs[0][0..32], self.inputs[1][0..32], std.mem.asBytes(&self.weights));
                var output: [16]i32 = undefined;
                inline for (0..8) |col| output[0 + col] = values.r0[col];
                inline for (0..8) |col| output[8 + col] = values.r1[col];
                return output;
            }
            if (comptime profile == 11) {
                const values = dotI8I8Block8MR2RowsVec16(self.inputs[0][0..16], self.inputs[1][0..16], self.weights[0][0..16], self.weights[1][0..16], self.weights[2][0..16], self.weights[3][0..16], self.weights[4][0..16], self.weights[5][0..16], self.weights[6][0..16], self.weights[7][0..16]);
                var output: [16]i32 = undefined;
                inline for (0..8) |col| output[0 + col] = values.r0[col];
                inline for (0..8) |col| output[8 + col] = values.r1[col];
                return output;
            }
            unreachable;
        }
        noinline fn measure(self: *@This(), comptime profile: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..20001) |_| {
                self.inputs[0][0] +%= 1;
                std.mem.doNotOptimizeAway(self.run(profile));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (0..profiles.len) |profile| {
            const p = profiles[profile];
            if (comptime p.arm and !native_aarch64_dotprod) continue;
            const output = state.run(profile);
            for (0..p.mr) |row| for (0..p.nc) |col| {
                var expected: i64 = 0;
                for (0..p.bytes) |i| expected += @as(i64, @as(i8, @bitCast(state.inputs[row][i]))) * @as(i64, @as(i8, @bitCast(state.weights[col][i])));
                try std.testing.expectEqual(@as(i32, @intCast(expected)), output[row * p.nc + col]);
            };
        }
    }
    if (platform.env.getenvBool("ANTFLY_INTEGER_TILE_BENCH")) {
        state.initialize(3);
        inline for (0..profiles.len) |profile| {
            const p = profiles[profile];
            if (comptime p.arm and !native_aarch64_dotprod) continue;
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(profile);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(profile);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("integer_tile profile={d} mr={d} nc={d} bytes={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=20001\n", .{ profile, p.mr, p.nc, p.bytes, @as(f64, @floatFromInt(samples[10])) / 20001.0, @as(f64, @floatFromInt(samples[19])) / 20001.0, samples[10], samples[19] });
        }
    }
}

test "Q4Q5 panel accumulation independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const profiles = .{
        .{ .mr = 1, .cached = false, .external = false, .result = false },
        .{ .mr = 1, .cached = true, .external = false, .result = false },
        .{ .mr = 2, .cached = false, .external = false, .result = false },
        .{ .mr = 2, .cached = true, .external = false, .result = false },
        .{ .mr = 4, .cached = false, .external = false, .result = false },
        .{ .mr = 4, .cached = true, .external = true, .result = false },
        .{ .mr = 8, .cached = true, .external = true, .result = false },
        .{ .mr = 2, .cached = true, .external = false, .result = true },
        .{ .mr = 4, .cached = true, .external = false, .result = true },
    };
    const State = struct {
        inputs: [8][292]u8 align(64) = @splat(@splat(0)),
        panel: [prepared_k_panel16_block_bytes]u8 align(64) = @splat(0),
        sums: [8][8]F32x8 align(64) = undefined,
        scales: [8]F32x8 align(64) = undefined,
        fn bias(half: usize, row: usize, lane: usize) f32 {
            return @as(f32, @floatFromInt(@as(i32, @intCast((half * 3 + row * 5 + lane) % 9)) - 4)) * 0.125;
        }
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                const scale: f32 = if ((seed + row) % 2 == 0) 0.125 else -0.25;
                std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
                for (0..256) |i| {
                    const value: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + row) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 256)) - 128);
                    input[4 + i] = @bitCast(value);
                }
                for (0..16) |group| {
                    var sum: i16 = 0;
                    for (0..16) |i| sum += @as(i8, @bitCast(input[4 + group * 16 + i]));
                    std.mem.writeInt(i16, input[260 + group * 2 ..][0..2], sum, .little);
                }
                inline for (0..8) |lane| self.scales[row][lane] = if (seed == 3) (if (lane % 2 == 0) 0.125 else -0.25) else scale;
                for (0..8) |sub| {
                    var sum: i32 = 0;
                    for (0..32) |i| sum += @as(i8, @bitCast(input[4 + sub * 32 + i]));
                    inline for (0..8) |lane| self.sums[row][sub][lane] = @floatFromInt(sum + (if (seed == 3) @as(i32, lane) - 3 else 0));
                }
            }
            for (0..8) |sub| for (0..16) |col| {
                const dsc: f32 = if ((sub + col + seed) % 2 == 0) 0.015625 else -0.0078125;
                const dmn: f32 = if ((sub + col + seed) % 3 == 0) 0.00390625 else -0.001953125;
                std.mem.writeInt(u32, self.panel[prepared_k_panel16_dsc_offset + (sub * 16 + col) * 4 ..][0..4], @bitCast(dsc), .little);
                std.mem.writeInt(u32, self.panel[prepared_k_panel16_dmn_offset + (sub * 16 + col) * 4 ..][0..4], @bitCast(dmn), .little);
                for (0..32) |i| self.panel[prepared_k_panel16_values_offset + (sub * 16 + col) * 32 + i] = @intCast((i * 7 + sub * 11 + col * 13 + seed * 17) % (if (seed % 2 == 0) @as(usize, 16) else 32));
            };
        }
        noinline fn run(self: *@This(), comptime profile: usize) [2][profiles[profile].mr]F32x8 {
            const mr = profiles[profile].mr;
            var acc: [2][mr]F32x8 = undefined;
            inline for (0..2) |half| inline for (0..mr) |row| inline for (0..8) |lane| {
                acc[half][row][lane] = bias(half, row, lane);
            };
            if (comptime profile == 0) accumulateQ4Q5KPreparedQ8KPanel16MR1Block(&self.inputs[0], &self.panel, &acc[0][0], &acc[1][0]);
            if (comptime profile == 1) accumulateQ4Q5KPreparedQ8KPanel16MR1BlockPreparedSums(&self.inputs[0], &self.sums[0], &self.panel, &acc[0][0], &acc[1][0]);
            if (comptime profile == 2) accumulateQ4Q5KPreparedQ8KPanel16MR2Block(&self.inputs[0], &self.inputs[1], &self.panel, &acc[0][0], &acc[1][0], &acc[0][1], &acc[1][1]);
            if (comptime profile == 3) accumulateQ4Q5KPreparedQ8KPanel16MR2BlockPreparedSums(&self.inputs[0], &self.inputs[1], &self.sums[0], &self.sums[1], &self.panel, &acc[0][0], &acc[1][0], &acc[0][1], &acc[1][1]);
            if (comptime profile == 4) accumulateQ4Q5KPreparedQ8KPanel16MR4Block(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel, &acc[0][0], &acc[1][0], &acc[0][1], &acc[1][1], &acc[0][2], &acc[1][2], &acc[0][3], &acc[1][3]);
            if (comptime profile == 5) accumulateQ4Q5KPreparedQ8KPanel16MR4BlockPreparedSums(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.sums[0], &self.sums[1], &self.sums[2], &self.sums[3], self.scales[0], self.scales[1], self.scales[2], self.scales[3], &self.panel, &acc[0][0], &acc[1][0], &acc[0][1], &acc[1][1], &acc[0][2], &acc[1][2], &acc[0][3], &acc[1][3]);
            if (comptime profile == 6) accumulateQ4Q5KPreparedQ8KPanel16MR8BlockPreparedSums(.{ &self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.inputs[4], &self.inputs[5], &self.inputs[6], &self.inputs[7] }, .{ &self.sums[0], &self.sums[1], &self.sums[2], &self.sums[3], &self.sums[4], &self.sums[5], &self.sums[6], &self.sums[7] }, self.scales, &self.panel, &acc[0], &acc[1]);
            if (comptime profile == 7) {
                const values = dotQ4Q5KPreparedQ8KPanel16MR2PreparedSums(&self.inputs[0], &self.inputs[1], &self.sums[0], &self.sums[1], &self.panel);
                inline for (0..8) |lane| {
                    acc[0][0][lane] = values.r0[lane];
                    acc[1][0][lane] = values.r0[lane + 8];
                }
                inline for (0..8) |lane| {
                    acc[0][1][lane] = values.r1[lane];
                    acc[1][1][lane] = values.r1[lane + 8];
                }
            }
            if (comptime profile == 8) {
                const values = dotQ4Q5KPreparedQ8KPanel16MR4PreparedSums(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.sums[0], &self.sums[1], &self.sums[2], &self.sums[3], &self.panel);
                inline for (0..8) |lane| {
                    acc[0][0][lane] = values.r0[lane];
                    acc[1][0][lane] = values.r0[lane + 8];
                }
                inline for (0..8) |lane| {
                    acc[0][1][lane] = values.r1[lane];
                    acc[1][1][lane] = values.r1[lane + 8];
                }
                inline for (0..8) |lane| {
                    acc[0][2][lane] = values.r2[lane];
                    acc[1][2][lane] = values.r2[lane + 8];
                }
                inline for (0..8) |lane| {
                    acc[0][3][lane] = values.r3[lane];
                    acc[1][3][lane] = values.r3[lane + 8];
                }
            }
            return acc;
        }
        noinline fn measure(self: *@This(), comptime profile: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..1001) |_| {
                self.inputs[0][3] ^= 0x80;
                self.scales[0] = -self.scales[0];
                std.mem.doNotOptimizeAway(self.run(profile));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (0..profiles.len) |profile| {
            const p = profiles[profile];
            const output = state.run(profile);
            for (0..2) |half| for (0..p.mr) |row| for (0..8) |lane| {
                const col = half * 8 + lane;
                var expected: f64 = if (p.result) 0 else State.bias(half, row, lane);
                const scale: f64 = if (p.external) f32x8ToArray(state.scales[row])[lane] else readF32Le(state.inputs[row][0..4]);
                for (0..8) |sub| {
                    var dot: i64 = 0;
                    var input_sum: i32 = 0;
                    for (0..32) |i| {
                        const input: i8 = @bitCast(state.inputs[row][4 + sub * 32 + i]);
                        dot += @as(i64, input) * @as(i64, @as(i8, @bitCast(state.panel[prepared_k_panel16_values_offset + (sub * 16 + col) * 32 + i])));
                        input_sum += input;
                    }
                    const sum: f64 = if (p.cached) f32x8ToArray(state.sums[row][sub])[lane] else @floatFromInt(input_sum);
                    const dsc: f64 = readF32Le(state.panel[prepared_k_panel16_dsc_offset + (sub * 16 + col) * 4 ..][0..4]);
                    const dmn: f64 = readF32Le(state.panel[prepared_k_panel16_dmn_offset + (sub * 16 + col) * 4 ..][0..4]);
                    expected += scale * (dsc * @as(f64, @floatFromInt(dot)) - dmn * sum);
                }
                const want: f32 = @floatCast(expected);
                try std.testing.expectEqual(@as(u32, @bitCast(want)), @as(u32, @bitCast(f32x8ToArray(output[half][row])[lane])));
            };
        }
    }
    if (platform.env.getenvBool("ANTFLY_PANEL_ACC_BENCH")) {
        state.initialize(2);
        inline for (0..profiles.len) |profile| {
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(profile);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(profile);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("panel_acc profile={d} mr={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=1001\n", .{ profile, profiles[profile].mr, @as(f64, @floatFromInt(samples[10])) / 1001.0, @as(f64, @floatFromInt(samples[19])) / 1001.0, samples[10], samples[19] });
        }
    }
}

test "Q4Q5 narrow and Q6 wide panels independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const profiles = .{ .{ .mr = 1, .nr = 8 }, .{ .mr = 2, .nr = 8 }, .{ .mr = 1, .nr = 16 }, .{ .mr = 2, .nr = 16 }, .{ .mr = 4, .nr = 16 } };
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        panel: [prepared_k_panel16_block_bytes]u8 align(64) = @splat(0),
        fn initialize(self: *@This(), comptime nr: usize, seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                const scale: f32 = if ((seed + row) % 2 == 0) 0.125 else -0.25;
                std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
                for (0..256) |i| {
                    const value: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + row) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 256)) - 128);
                    input[4 + i] = @bitCast(value);
                }
                for (0..16) |group| {
                    var sum: i16 = 0;
                    for (0..16) |i| sum += @as(i8, @bitCast(input[4 + group * 16 + i]));
                    std.mem.writeInt(i16, input[260 + group * 2 ..][0..2], sum, .little);
                }
            }
            const width = if (nr == 16) 16 else 32;
            for (0..256 / width) |sub| for (0..nr) |col| {
                const dsc: f32 = if ((sub + col + seed) % 2 == 0) 0.015625 else -0.0078125;
                std.mem.writeInt(u32, self.panel[(sub * nr + col) * 4 ..][0..4], @bitCast(dsc), .little);
                if (nr == 8) {
                    const dmn: f32 = if ((sub + col + seed) % 3 == 0) 0.00390625 else -0.001953125;
                    std.mem.writeInt(u32, self.panel[(8 * nr + sub * nr + col) * 4 ..][0..4], @bitCast(dmn), .little);
                }
                for (0..width) |i| {
                    const value: i8 = if (nr == 16) @intCast(@as(i32, @intCast((i * 7 + sub * 11 + col * 13 + seed * 17) % 64)) - 32) else @intCast((i * 7 + sub * 11 + col * 13 + seed * 17) % (if (seed % 2 == 0) @as(usize, 16) else 32));
                    self.panel[16 * nr * 4 + (sub * nr + col) * width + i] = @bitCast(value);
                }
            };
        }
        noinline fn run(self: *@This(), comptime profile: usize) [profiles[profile].mr][profiles[profile].nr]f32 {
            const p = profiles[profile];
            const panel = self.panel[0..if (p.nr == 8) prepared_k_panel8_block_bytes else prepared_k_panel16_block_bytes];
            if (p.mr == 1) return .{if (p.nr == 8) dotQ4Q5KPreparedQ8KPanel8(&self.inputs[0], panel) else dotQ6KPreparedQ8KPanel16(&self.inputs[0], panel)};
            const values = if (p.nr == 8) dotQ4Q5KPreparedQ8KPanel8MR2(&self.inputs[0], &self.inputs[1], panel) else if (p.mr == 2) dotQ6KPreparedQ8KPanel16MR2(&self.inputs[0], &self.inputs[1], panel) else dotQ6KPreparedQ8KPanel16MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], panel);
            var result: [p.mr][p.nr]f32 = undefined;
            inline for (0..p.mr) |row| result[row] = @field(values, ([_][]const u8{ "r0", "r1", "r2", "r3" })[row]);
            return result;
        }
        noinline fn measure(self: *@This(), comptime profile: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..1001) |_| {
                self.inputs[0][3] ^= 0x80;
                std.mem.doNotOptimizeAway(self.run(profile));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    inline for (0..profiles.len) |profile| {
        const p = profiles[profile];
        for (0..4) |seed| {
            state.initialize(p.nr, seed);
            const output = state.run(profile);
            for (0..p.mr) |row| for (0..p.nr) |col| {
                const width = if (p.nr == 16) 16 else 32;
                var expected: f64 = 0;
                const scale: f64 = readF32Le(state.inputs[row][0..4]);
                for (0..256 / width) |sub| {
                    var dot: i64 = 0;
                    var sum: i32 = 0;
                    for (0..width) |i| {
                        const x: i8 = @bitCast(state.inputs[row][4 + sub * width + i]);
                        const w: i8 = @bitCast(state.panel[16 * p.nr * 4 + (sub * p.nr + col) * width + i]);
                        dot += @as(i64, x) * @as(i64, w);
                        sum += x;
                    }
                    const dsc: f64 = readF32Le(state.panel[(sub * p.nr + col) * 4 ..][0..4]);
                    const correction: f64 = if (p.nr == 16) 0 else @as(f64, readF32Le(state.panel[(8 * p.nr + sub * p.nr + col) * 4 ..][0..4])) * @as(f64, @floatFromInt(sum));
                    expected += scale * (dsc * @as(f64, @floatFromInt(dot)) - correction);
                }
                const want: f32 = @floatCast(expected);
                try std.testing.expectEqual(@as(u32, @bitCast(want)), @as(u32, @bitCast(output[row][col])));
            };
        }
        if (platform.env.getenvBool("ANTFLY_PANEL_GEOMETRY_BENCH")) {
            state.initialize(p.nr, 2);
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(profile);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(profile);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("panel_geometry profile={d} mr={d} nr={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=1001\n", .{ profile, p.mr, p.nr, @as(f64, @floatFromInt(samples[10])) / 1001.0, @as(f64, @floatFromInt(samples[19])) / 1001.0, samples[10], samples[19] });
        }
    }
}

test "K16 block row families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const profiles = .{ .{ .mr = 1, .kind = 0 }, .{ .mr = 1, .kind = 1 }, .{ .mr = 1, .kind = 2 }, .{ .mr = 2, .kind = 0 }, .{ .mr = 2, .kind = 1 }, .{ .mr = 2, .kind = 2 }, .{ .mr = 4, .kind = 0 }, .{ .mr = 4, .kind = 1 }, .{ .mr = 4, .kind = 2 } };
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        weights: [4][prepared_k16_block_bytes]u8 align(64) = @splat(@splat(0)),
        sums: [4][16]f32 = undefined,
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                const scale: f32 = if ((seed + row) % 2 == 0) 0.125 else -0.25;
                std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
                for (0..256) |i| {
                    const x: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + row) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 256)) - 128);
                    input[4 + i] = @bitCast(x);
                }
                for (0..16) |sub| {
                    var sum: i16 = 0;
                    for (0..16) |i| sum += @as(i8, @bitCast(input[4 + sub * 16 + i]));
                    std.mem.writeInt(i16, input[260 + sub * 2 ..][0..2], sum, .little);
                    self.sums[row][sub] = @floatFromInt(@as(i32, sum) + (if (seed == 3) @as(i32, @intCast((sub + row) % 7)) - 3 else 0));
                }
            }
            for (&self.weights, 0..) |*weight, col| for (0..16) |sub| {
                const dsc: f32 = if ((sub + col + seed) % 2 == 0) 0.00390625 else -0.001953125;
                const dmn: f32 = if ((sub + col + seed) % 3 == 0) 0.015625 else -0.0078125;
                std.mem.writeInt(u32, weight[sub * 4 ..][0..4], @bitCast(dsc), .little);
                std.mem.writeInt(u32, weight[64 + sub * 4 ..][0..4], @bitCast(dmn), .little);
                for (0..16) |i| {
                    const w: i8 = if (seed == 1) (if ((i + col) % 2 == 0) -128 else 127) else if (seed == 2) @intCast(@as(i32, @intCast((i * 7 + sub * 11 + col * 13) % 64)) - 32) else @intCast(@as(i32, @intCast((i * 7 + sub * 11 + col * 13) % 256)) - 128);
                    weight[128 + sub * 16 + i] = @bitCast(w);
                }
            };
        }
        noinline fn run(self: *@This(), comptime profile: usize) [profiles[profile].mr * 4]f32 {
            const p = profiles[profile];
            const cached = p.kind == 2;
            const s0: ?*const [16]f32 = if (cached) &self.sums[0] else null;
            const s1: ?*const [16]f32 = if (cached) &self.sums[1] else null;
            if (p.mr == 4) return dotK16PreparedQ8KBlock4MR4WithSums(p.kind != 0, &self.inputs[0], s0, &self.inputs[1], s1, &self.inputs[2], if (cached) &self.sums[2] else null, &self.inputs[3], if (cached) &self.sums[3] else null, &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]);
            const values = if (p.mr == 1) dotK16PreparedQ8KBlock4WithSums(p.kind != 0, &self.inputs[0], s0, &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]) else dotK16PreparedQ8KBlock4MR2WithSums(p.kind != 0, &self.inputs[0], s0, &self.inputs[1], s1, &self.weights[0], &self.weights[1], &self.weights[2], &self.weights[3]);
            var result: [p.mr * 4]f32 = undefined;
            inline for (0..p.mr * 4) |i| result[i] = @field(values, ([_][]const u8{ "0", "1", "2", "3", "4", "5", "6", "7" })[i]);
            return result;
        }
        noinline fn measure(self: *@This(), comptime profile: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..1001) |_| {
                self.inputs[0][3] ^= 0x80;
                std.mem.doNotOptimizeAway(self.run(profile));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (0..profiles.len) |profile| {
            const p = profiles[profile];
            const output = state.run(profile);
            for (0..p.mr) |row| for (0..4) |col| {
                var expected: f64 = 0;
                for (0..16) |sub| {
                    var dot: i64 = 0;
                    var sum: i32 = 0;
                    for (0..16) |i| {
                        const x: i8 = @bitCast(state.inputs[row][4 + sub * 16 + i]);
                        const w: i8 = @bitCast(state.weights[col][128 + sub * 16 + i]);
                        dot += @as(i64, x) * @as(i64, w);
                        sum += x;
                    }
                    const dsc: f64 = readF32Le(state.weights[col][sub * 4 ..][0..4]);
                    const dmn: f64 = readF32Le(state.weights[col][64 + sub * 4 ..][0..4]);
                    const correction: f64 = if (p.kind == 0) 0 else dmn * (if (p.kind == 2) @as(f64, state.sums[row][sub]) else @as(f64, @floatFromInt(sum)));
                    expected += dsc * @as(f64, @floatFromInt(dot)) - correction;
                }
                const want: f32 = @floatCast(@as(f64, readF32Le(state.inputs[row][0..4])) * expected);
                try std.testing.expectEqual(@as(u32, @bitCast(want)), @as(u32, @bitCast(output[row * 4 + col])));
            };
        }
    }
    if (platform.env.getenvBool("ANTFLY_K16_BLOCK_BENCH")) {
        state.initialize(2);
        inline for (0..profiles.len) |profile| {
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(profile);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(profile);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("k16_block profile={d} mr={d} kind={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=1001\n", .{ profile, profiles[profile].mr, profiles[profile].kind, @as(f64, @floatFromInt(samples[10])) / 1001.0, @as(f64, @floatFromInt(samples[19])) / 1001.0, samples[10], samples[19] });
        }
    }
}

test "packed QKV row families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const Module = @This();
    const old_interface = @sizeOf(PackedQKVPanel16SubProjectionView) == 6 * @sizeOf([]const u8);
    const profiles = .{
        .{ .mr = 1, .mode = 0 },
        .{ .mr = 1, .mode = 1 },
        .{ .mr = 1, .mode = 2 },
        .{ .mr = 1, .mode = 3 },
        .{ .mr = 1, .mode = 4 },
        .{ .mr = 2, .mode = 0 },
        .{ .mr = 2, .mode = 1 },
        .{ .mr = 2, .mode = 2 },
        .{ .mr = 2, .mode = 3 },
        .{ .mr = 2, .mode = 4 },
        .{ .mr = 4, .mode = 0 },
        .{ .mr = 4, .mode = 1 },
        .{ .mr = 4, .mode = 2 },
        .{ .mr = 4, .mode = 3 },
        .{ .mr = 4, .mode = 4 },
        .{ .mr = 8, .mode = 0 },
        .{ .mr = 8, .mode = 1 },
        .{ .mr = 8, .mode = 2 },
        .{ .mr = 8, .mode = 3 },
        .{ .mr = 8, .mode = 4 },
    };
    const State = struct {
        inputs: [8][256]u8 align(64) = @splat(@splat(0)),
        qinput: [8 * 292]u8 align(64) = @splat(0),
        biases: [3][16]f32 = undefined,
        panel: [prepared_k_qkv_panel16_block_bytes]u8 align(64) = @splat(0),
        scales: [8]F32x8 = undefined,
        sums: [8][8]F32x8 = undefined,
        fn bias(projection: usize, half: usize, row: usize, lane: usize) f32 {
            return @as(f32, @floatFromInt(@as(i32, @intCast((projection * 7 + half * 3 + row * 5 + lane) % 9)) - 4)) * 0.125;
        }
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                for (0..256) |i| {
                    const x: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + row) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 37 + seed * 11) % 256)) - 128);
                    input[i] = @bitCast(x);
                }
                inline for (0..8) |lane| self.scales[row][lane] = if (seed == 3) (if (lane % 2 == 0) 0.125 else -0.25) else (if ((seed + row) % 2 == 0) 0.125 else -0.25);
                for (0..8) |sub| {
                    var sum: i32 = 0;
                    for (0..32) |i| sum += @as(i8, @bitCast(input[sub * 32 + i]));
                    inline for (0..8) |lane| self.sums[row][sub][lane] = @floatFromInt(sum + (if (seed == 3) @as(i32, lane) - 3 else 0));
                }
            }
            for (0..8) |row| {
                const dest = self.qinput[row * 292 ..][0..292];
                const scale: f32 = if ((seed + row) % 2 == 0) 0.125 else -0.25;
                std.mem.writeInt(u32, dest[0..4], @bitCast(scale), .little);
                @memcpy(dest[4..260], &self.inputs[row]);
                for (0..16) |sub| {
                    var sum: i16 = 0;
                    for (0..16) |i| sum += @as(i8, @bitCast(self.inputs[row][sub * 16 + i]));
                    std.mem.writeInt(i16, dest[260 + sub * 2 ..][0..2], sum, .little);
                }
            }
            for (0..3) |proj| for (0..16) |col| {
                self.biases[proj][col] = bias(proj, col / 8, 0, col % 8);
            };
            for (0..8) |sub| for (0..3) |proj| for (0..16) |col| {
                const lane = (sub * 3 + proj) * 16 + col;
                const dsc: f32 = if ((sub + proj + col + seed) % 2 == 0) 0.015625 else -0.0078125;
                const dmn: f32 = if ((sub + proj + col + seed) % 3 == 0) 0.00390625 else -0.001953125;
                std.mem.writeInt(u32, self.panel[lane * 4 ..][0..4], @bitCast(dsc), .little);
                std.mem.writeInt(u32, self.panel[8 * 3 * 16 * 4 + lane * 4 ..][0..4], @bitCast(dmn), .little);
                for (0..32) |i| self.panel[16 * 3 * 16 * 4 + lane * 32 + i] = @intCast((i * 7 + sub * 11 + proj * 19 + col * 13 + seed * 17) % (if (seed % 2 == 0) @as(usize, 16) else 32));
            };
        }
        noinline fn run(self: *@This(), comptime profile: usize) [if (profiles[profile].mode >= 3) 3 else 1][2][profiles[profile].mr]F32x8 {
            const mr = profiles[profile].mr;
            const mode = profiles[profile].mode;
            const projections = if (mode >= 3) 3 else 1;
            if (comptime mode == 4) {
                var outputs: [3][mr * 16]f32 = undefined;
                linearQ4Q5KPreparedQ8KActivationTriplePanel16Range(self.qinput[0 .. mr * 292], &.{}, &.{}, &self.biases[0], &outputs[0], &.{}, &.{}, &self.biases[1], &outputs[1], &.{}, &.{}, &self.biases[2], &outputs[2], &self.panel, true, mr == 8, mr, 256, 16, 0, 16);
                var result: [3][2][mr]F32x8 = undefined;
                inline for (0..3) |proj| inline for (0..2) |half| inline for (0..mr) |row| inline for (0..8) |lane| {
                    result[proj][half][row][lane] = outputs[proj][row * 16 + half * 8 + lane];
                };
                return result;
            }
            var acc: [projections][2][mr]F32x8 = undefined;
            inline for (0..projections) |index| inline for (0..2) |half| inline for (0..mr) |row| inline for (0..8) |lane| {
                acc[index][half][row][lane] = bias(if (mode >= 3) index else mode, half, row, lane);
            };
            var scales: [mr]F32x8 = undefined;
            inline for (0..mr) |row| scales[row] = self.scales[row];
            for (0..8) |sub| {
                var q: [mr]*const [32]u8 = undefined;
                var sums: [mr]F32x8 = undefined;
                inline for (0..mr) |row| {
                    q[row] = self.inputs[row][sub * 32 ..][0..32];
                    sums[row] = self.sums[row][sub];
                }
                inline for (0..projections) |index| {
                    const proj = if (mode >= 3) index else mode;
                    const view = packedQKVPanel16SubProjectionView(&self.panel, sub, proj);
                    if (comptime old_interface) {
                        if (mr == 1) Module.accumulateQ4Q5KPackedQKVPanel16NR16MR1(&self.inputs[0], sub * 32, scales[0], sums[0], &self.panel, sub, proj, &acc[index][0][0], &acc[index][1][0]);
                        if (mr == 2) Module.accumulateQ4Q5KPackedQKVPanel16NR16MR2(&self.inputs[0], &self.inputs[1], sub * 32, scales[0], scales[1], sums[0], sums[1], &self.panel, sub, proj, &acc[index][0][0], &acc[index][1][0], &acc[index][0][1], &acc[index][1][1]);
                        if (mr == 4) Module.accumulateQ4Q5KPackedQKVPanel16NR16MR4ProjectionView(q[0], q[1], q[2], q[3], scales[0], scales[1], scales[2], scales[3], sums[0], sums[1], sums[2], sums[3], view, &acc[index][0][0], &acc[index][1][0], &acc[index][0][1], &acc[index][1][1], &acc[index][0][2], &acc[index][1][2], &acc[index][0][3], &acc[index][1][3]);
                        if (mr == 8) Module.accumulateQ4Q5KPackedQKVPanel16NR16MR8ProjectionView(q, scales, sums, view, &acc[index][0], &acc[index][1]);
                    } else {
                        var outputs: [2][mr]*F32x8 = undefined;
                        inline for (0..2) |half| inline for (0..mr) |row| {
                            outputs[half][row] = &acc[index][half][row];
                        };
                        Module.q4q5PanelSubAccumulate(16, mr, .ready, true, q, scales, sums, view, outputs);
                    }
                }
            }
            return acc;
        }
        noinline fn measure(self: *@This(), comptime profile: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..1001) |_| {
                self.scales[0] = -self.scales[0];
                self.qinput[3] ^= 0x80;
                std.mem.doNotOptimizeAway(self.run(profile));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (0..profiles.len) |profile| {
            const mr = profiles[profile].mr;
            const mode = profiles[profile].mode;
            const output = state.run(profile);
            inline for (0..if (mode >= 3) 3 else 1) |index| {
                const proj = if (mode >= 3) index else mode;
                for (0..2) |half| for (0..mr) |row| for (0..8) |lane| {
                    const col = half * 8 + lane;
                    var expected: f64 = if (mode == 4) 0 else State.bias(proj, half, row, lane);
                    const scale: f64 = if (mode == 4) readF32Le(state.qinput[row * 292 ..][0..4]) else f32x8ToArray(state.scales[row])[lane];
                    for (0..8) |sub| {
                        const weight_lane = (sub * 3 + proj) * 16 + col;
                        var dot: i64 = 0;
                        var input_sum: i32 = 0;
                        for (0..32) |i| {
                            const x: i8 = @bitCast(state.inputs[row][sub * 32 + i]);
                            dot += @as(i64, x) * @as(i64, state.panel[16 * 3 * 16 * 4 + weight_lane * 32 + i]);
                            input_sum += x;
                        }
                        const dsc: f64 = readF32Le(state.panel[weight_lane * 4 ..][0..4]);
                        const dmn: f64 = readF32Le(state.panel[8 * 3 * 16 * 4 + weight_lane * 4 ..][0..4]);
                        const sum: f64 = if (mode == 4) @floatFromInt(input_sum) else f32x8ToArray(state.sums[row][sub])[lane];
                        expected += scale * (dsc * @as(f64, @floatFromInt(dot)) - dmn * sum);
                    }
                    if (mode == 4) expected += state.biases[proj][col];
                    const want: f32 = @floatCast(expected);
                    try std.testing.expectEqual(@as(u32, @bitCast(want)), @as(u32, @bitCast(f32x8ToArray(output[index][half][row])[lane])));
                };
            }
        }
    }
    std.debug.print("packed_qkv_descriptor bytes={d}\n", .{@sizeOf(PackedQKVPanel16SubProjectionView)});
    if (platform.env.getenvBool("ANTFLY_PACKED_QKV_BENCH")) {
        state.initialize(2);
        inline for (0..profiles.len) |profile| {
            const warmup_start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - warmup_start < 25_000_000) _ = state.measure(profile);
            var samples: [21]u64 = undefined;
            for (&samples) |*sample| sample.* = state.measure(profile);
            std.mem.sort(u64, &samples, {}, std.sort.asc(u64));
            std.debug.print("packed_qkv profile={d} mr={d} mode={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=1001\n", .{ profile, profiles[profile].mr, profiles[profile].mode, @as(f64, @floatFromInt(samples[10])) / 1001.0, @as(f64, @floatFromInt(samples[19])) / 1001.0, samples[10], samples[19] });
        }
    }
}

test "Q3 four column rows independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const State = struct {
        inputs: [4][292]u8 align(64) = @splat(@splat(0)),
        panel: [prepared_q3_k_panel_block_bytes]u8 align(64) = @splat(0),
        fn initialize(self: *@This(), seed: usize) void {
            for (&self.inputs, 0..) |*input, row| {
                const scale: f32 = if (row % 2 == 0) 0.125 else -0.25;
                std.mem.writeInt(u32, input[0..4], @bitCast(scale), .little);
                for (0..256) |i| {
                    const value: i8 = if (seed == 0) 0 else if (seed == 1) (if ((i + row) % 2 == 0) -128 else 127) else @intCast(@as(i32, @intCast((i * 17 + row * 31 + seed) % 256)) - 128);
                    input[4 + i] = @bitCast(value);
                }
            }
            for (0..16) |sub| for (0..4) |col| {
                const scale: f32 = @as(f32, @floatFromInt(@as(i32, @intCast((sub + col * 3) % 11)) - 5)) * 0.125;
                // Literal panel offsets give the oracle independent physical addressing.
                std.mem.writeInt(u32, self.panel[(sub * 4 + col) * 4 ..][0..4], @bitCast(scale), .little);
                for (0..16) |i| {
                    const value: i8 = if (seed == 0) 0 else if (seed == 1) (if ((sub + col + i) % 2 == 0) -4 else 3) else @intCast(@as(i32, @intCast((sub * 7 + col * 3 + i * 5 + seed) % 8)) - 4);
                    self.panel[256 + (sub * 4 + col) * 16 + i] = @bitCast(value);
                }
            };
        }
        noinline fn run(self: *@This(), comptime mr: usize) [mr * 4]f32 {
            const result = if (mr == 1) dotQ3KNoDmnPanel4(&self.inputs[0], &self.panel) else if (mr == 2) dotQ3KNoDmnPanel4MR2(&self.inputs[0], &self.inputs[1], &self.panel) else dotQ3KNoDmnPanel4MR4(&self.inputs[0], &self.inputs[1], &self.inputs[2], &self.inputs[3], &self.panel);
            var out: [mr * 4]f32 = undefined;
            inline for (0..mr * 4) |i| out[i] = result[i];
            return out;
        }
        noinline fn measure(self: *@This(), comptime mr: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..2001) |_| {
                self.inputs[0][4] +%= 1;
                std.mem.doNotOptimizeAway(self.run(mr));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    try std.testing.expectEqual(@as(usize, 1280), prepared_q3_k_panel_block_bytes);
    try std.testing.expectEqual(@as(usize, 0), prepared_q3_k_panel_dsc_offset);
    try std.testing.expectEqual(@as(usize, 256), prepared_q3_k_panel_values_offset);
    var state: State = .{};
    for (0..4) |seed| {
        state.initialize(seed);
        inline for (.{ 1, 2, 4 }) |mr| {
            const result = state.run(mr);
            for (0..mr) |row| for (0..4) |col| {
                var expected: f64 = 0;
                for (0..16) |sub| {
                    var dot: i64 = 0;
                    for (0..16) |i| dot += @as(i64, @as(i8, @bitCast(state.inputs[row][4 + sub * 16 + i]))) * @as(i64, @as(i8, @bitCast(state.panel[256 + (sub * 4 + col) * 16 + i])));
                    const scale = @as(f32, @bitCast(std.mem.readInt(u32, state.panel[(sub * 4 + col) * 4 ..][0..4], .little)));
                    expected += @as(f64, scale) * @as(f64, @floatFromInt(dot));
                }
                const scale = @as(f32, @bitCast(std.mem.readInt(u32, state.inputs[row][0..4], .little)));
                try std.testing.expectEqual(@as(f32, @floatCast(expected * @as(f64, scale))), result[row * 4 + col]);
            };
        }
    }
    if (platform.env.getenvBool("ANTFLY_Q3_FOUR_BENCH")) inline for (.{ 1, 2, 4 }) |mr| {
        const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
        while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - start < 25_000_000) _ = state.measure(mr);
        var times: [21]u64 = undefined;
        for (&times) |*sample| sample.* = state.measure(mr);
        std.mem.sort(u64, &times, {}, std.sort.asc(u64));
        std.debug.print("q3_four mr={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=2001\n", .{ mr, @as(f64, @floatFromInt(times[10])) / 2001.0, @as(f64, @floatFromInt(times[19])) / 2001.0, times[10], times[19] });
    };
}
test "prepared float four column families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const State = struct {
        inputs: [2][256]f32 align(64) = @splat(@splat(0)),
        blocks: [4][320]u8 align(64) = @splat(@splat(0)),
        fn initialize(self: *@This(), comptime kind: usize, seed: usize) void {
            for (&self.inputs, 0..) |*input, row| for (input, 0..) |*x, i| {
                x.* = if (seed == 0) 0 else @as(f32, @floatFromInt(@as(i32, @intCast((i * 17 + row * 31 + seed) % 33)) - 16)) * 0.125;
            };
            for (&self.blocks, 0..) |*block, col| {
                @memset(block, 0);
                for (0..(if (kind == 2) @as(usize, 16) else 8)) |sub| {
                    const scale: f32 = @as(f32, @floatFromInt(@as(i32, @intCast((sub + col * 3 + seed) % 11)) - 5)) * 0.125;
                    const minimum: f32 = @as(f32, @floatFromInt(@as(i32, @intCast((sub * 3 + col + seed) % 9)) - 4)) * 0.0625;
                    std.mem.writeInt(u32, block[sub * 4 ..][0..4], @bitCast(scale), .little);
                    if (kind != 2) std.mem.writeInt(u32, block[32 + sub * 4 ..][0..4], @bitCast(minimum), .little);
                }
                for (0..256) |i| {
                    if (kind == 2) {
                        const value: i8 = if (seed == 1) (if ((i + col) % 2 == 0) -32 else 31) else @intCast(@as(i32, @intCast((i * 7 + col * 13 + seed) % 64)) - 32);
                        block[64 + i] = @bitCast(value);
                    } else {
                        const maximum: usize = if (kind == 0) 15 else 31;
                        block[64 + i] = @intCast(if (seed == 1) (if ((i + col) % 2 == 0) 0 else maximum) else (i * 7 + col * 13 + seed) % (maximum + 1));
                    }
                }
            }
        }
        noinline fn run(self: *@This(), comptime mr: usize, comptime kind: usize) [mr][4]F32xN {
            var acc: [mr][4]F32xN = undefined;
            inline for (0..mr) |row| inline for (0..4) |col| {
                inline for (0..VEC_LEN) |lane| acc[row][col][lane] = @as(f32, @floatFromInt(row * 11 + col * 3 + lane)) * 0.0625;
            };
            if (kind == 2) {
                if (mr == 1) accumulateQ6KPreparedBlock4MR1(&self.inputs[0], &self.blocks[0], &self.blocks[1], &self.blocks[2], &self.blocks[3], &acc[0][0], &acc[0][1], &acc[0][2], &acc[0][3]) else accumulateQ6KPreparedBlock4MR2(&self.inputs[0], &self.inputs[1], &self.blocks[0], &self.blocks[1], &self.blocks[2], &self.blocks[3], &acc[0][0], &acc[0][1], &acc[0][2], &acc[0][3], &acc[1][0], &acc[1][1], &acc[1][2], &acc[1][3]);
            } else {
                if (mr == 1) accumulateQ4KPreparedBlock4MR1(&self.inputs[0], &self.blocks[0], &self.blocks[1], &self.blocks[2], &self.blocks[3], &acc[0][0], &acc[0][1], &acc[0][2], &acc[0][3]) else accumulateQ4KPreparedBlock4MR2(&self.inputs[0], &self.inputs[1], &self.blocks[0], &self.blocks[1], &self.blocks[2], &self.blocks[3], &acc[0][0], &acc[0][1], &acc[0][2], &acc[0][3], &acc[1][0], &acc[1][1], &acc[1][2], &acc[1][3]);
            }
            return acc;
        }
        noinline fn full(self: *@This(), comptime mr: usize, comptime kind: usize) [mr * 4]f32 {
            var output: [mr * 4]f32 = undefined;
            const input = @as([*]const f32, @ptrCast(&self.inputs))[0 .. mr * 256];
            const blocks = std.mem.asBytes(&self.blocks);
            if (kind == 2) linearQ6KPreparedTiledRange(input, blocks, &output, mr, 256, 4, 0, 4) catch unreachable else linearQ4KPreparedTiledRange(input, blocks, &output, mr, 256, 4, 0, 4) catch unreachable;
            return output;
        }
        noinline fn measure(self: *@This(), comptime mr: usize, comptime kind: usize, comptime whole: bool) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..2001) |_| {
                self.inputs[0][0] = -self.inputs[0][0];
                if (whole) std.mem.doNotOptimizeAway(self.full(mr, kind)) else std.mem.doNotOptimizeAway(self.run(mr, kind));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    try std.testing.expectEqual(@as(usize, 64), prepared_q4_k_header_bytes);
    try std.testing.expectEqual(@as(usize, 320), prepared_q4_k_block_bytes);
    var state: State = .{};
    inline for (.{ 0, 1, 2 }) |kind| {
        for (0..4) |seed| {
            state.initialize(kind, seed);
            inline for (.{ 1, 2 }) |mr| {
                const actual = state.run(mr, kind);
                const full = state.full(mr, kind);
                var reference: [mr * 4]f64 = @splat(0);

                for (0..mr) |row| for (0..4) |col| inline for (0..VEC_LEN) |lane| {
                    var expected: f64 = @as(f64, @floatFromInt(row * 11 + col * 3 + lane)) * 0.0625;
                    var i = lane;
                    while (i < 256) : (i += VEC_LEN) {
                        const sub = i / (if (kind == 2) @as(usize, 16) else 32);
                        const scale = @as(f32, @bitCast(std.mem.readInt(u32, state.blocks[col][sub * 4 ..][0..4], .little)));
                        const minimum: f32 = if (kind == 2) 0 else @bitCast(std.mem.readInt(u32, state.blocks[col][32 + sub * 4 ..][0..4], .little));
                        const value: i32 = if (kind == 2) @as(i8, @bitCast(state.blocks[col][64 + i])) else state.blocks[col][64 + i];
                        expected += @as(f64, state.inputs[row][i]) * (@as(f64, scale) * @as(f64, @floatFromInt(value)) - @as(f64, minimum));
                    }
                    try std.testing.expectEqual(@as(f32, @floatCast(expected)), actual[row][col][lane]);
                    reference[row * 4 + col] += expected - @as(f64, @floatFromInt(row * 11 + col * 3 + lane)) * 0.0625;
                };
                for (full, reference) |got, want| try std.testing.expectEqual(@as(f32, @floatCast(want)), got);
            }
        }
    }
    if (platform.env.getenvBool("ANTFLY_PREPARED_FLOAT_BENCH")) inline for (.{ 0, 1, 2 }) |kind| {
        state.initialize(kind, 3);
        inline for (.{ 1, 2 }) |mr| inline for (.{ false, true }) |whole| {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - start < 25_000_000) _ = state.measure(mr, kind, whole);
            var times: [21]u64 = undefined;
            for (&times) |*sample| sample.* = state.measure(mr, kind, whole);
            std.mem.sort(u64, &times, {}, std.sort.asc(u64));
            std.debug.print("prepared_float mr={d} kind={d} whole={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=2001\n", .{ mr, kind, @intFromBool(whole), @as(f64, @floatFromInt(times[10])) / 2001.0, @as(f64, @floatFromInt(times[19])) / 2001.0, times[10], times[19] });
        };
    };
}

test "prepared float scalar families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const State = struct {
        inputs: [2][256]f32 align(64) = @splat(@splat(0)),
        blocks: [4][320]u8 align(64) = @splat(@splat(0)),
        fn initialize(self: *@This(), comptime kind: usize, seed: usize) void {
            for (&self.inputs, 0..) |*input, row| for (input, 0..) |*x, i| {
                x.* = if (seed == 0) 0 else @as(f32, @floatFromInt(@as(i32, @intCast((i * 17 + row * 31 + seed) % 33)) - 16)) * 0.125;
            };
            for (&self.blocks, 0..) |*block, col| {
                @memset(block, 0);
                for (0..(if (kind == 2) @as(usize, 16) else 8)) |sub| {
                    const scale: f32 = @as(f32, @floatFromInt(@as(i32, @intCast((sub + col * 3 + seed) % 11)) - 5)) * 0.125;
                    const minimum: f32 = @as(f32, @floatFromInt(@as(i32, @intCast((sub * 3 + col + seed) % 9)) - 4)) * 0.0625;
                    std.mem.writeInt(u32, block[sub * 4 ..][0..4], @bitCast(scale), .little);
                    if (kind != 2) std.mem.writeInt(u32, block[32 + sub * 4 ..][0..4], @bitCast(minimum), .little);
                }
                for (0..256) |i| {
                    if (kind == 2) {
                        const value: i8 = if (seed == 1) (if ((i + col) % 2 == 0) -32 else 31) else @intCast(@as(i32, @intCast((i * 7 + col * 13 + seed) % 64)) - 32);
                        block[64 + i] = @bitCast(value);
                    } else {
                        const maximum: usize = if (kind == 0) 15 else 31;
                        block[64 + i] = @intCast(if (seed == 1) (if ((i + col) % 2 == 0) 0 else maximum) else (i * 7 + col * 13 + seed) % (maximum + 1));
                    }
                }
            }
        }
        noinline fn run(self: *@This(), comptime mr: usize, comptime kind: usize) [mr]f32 {
            if (mr == 1) return .{if (kind == 2) dotQ6KPreparedBlock(&self.inputs[0], &self.blocks[0]) else dotQ4KPreparedBlock(&self.inputs[0], &self.blocks[0])};
            const sums = if (kind == 2) dotQ6KPreparedBlockMR2NR1(&self.inputs[0], &self.inputs[1], &self.blocks[0]) else dotQ4KPreparedBlockMR2NR1(&self.inputs[0], &self.inputs[1], &self.blocks[0]);
            return .{ sums[0], sums[1] };
        }
        noinline fn measure(self: *@This(), comptime mr: usize, comptime kind: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..2001) |_| {
                self.inputs[0][0] = -self.inputs[0][0];
                std.mem.doNotOptimizeAway(self.run(mr, kind));
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    var state: State = .{};
    inline for (.{ 0, 1, 2 }) |kind| {
        for (0..4) |seed| {
            state.initialize(kind, seed);
            inline for (.{ 1, 2 }) |mr| {
                const actual = state.run(mr, kind);
                for (0..mr) |row| {
                    var expected: f64 = 0;
                    for (0..256) |i| {
                        const sub = i / (if (kind == 2) @as(usize, 16) else 32);
                        const scale = @as(f32, @bitCast(std.mem.readInt(u32, state.blocks[0][sub * 4 ..][0..4], .little)));
                        const minimum: f32 = if (kind == 2) 0 else @bitCast(std.mem.readInt(u32, state.blocks[0][32 + sub * 4 ..][0..4], .little));
                        const value: i32 = if (kind == 2) @as(i8, @bitCast(state.blocks[0][64 + i])) else state.blocks[0][64 + i];
                        expected += @as(f64, state.inputs[row][i]) * (@as(f64, scale) * @as(f64, @floatFromInt(value)) - @as(f64, minimum));
                    }
                    try std.testing.expectEqual(@as(f32, @floatCast(expected)), actual[row]);
                }
            }
        }
    }
    if (platform.env.getenvBool("ANTFLY_PREPARED_SCALAR_BENCH")) inline for (.{ 0, 1, 2 }) |kind| {
        state.initialize(kind, 3);
        inline for (.{ 1, 2 }) |mr| {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - start < 25_000_000) _ = state.measure(mr, kind);
            var times: [21]u64 = undefined;
            for (&times) |*sample| sample.* = state.measure(mr, kind);
            std.mem.sort(u64, &times, {}, std.sort.asc(u64));
            std.debug.print("prepared_scalar mr={d} kind={d} p50_ns={d:.6} p95_ns={d:.6} p50_batch_ns={d} p95_batch_ns={d} measure_iters=2001\n", .{ mr, kind, @as(f64, @floatFromInt(times[10])) / 2001.0, @as(f64, @floatFromInt(times[19])) / 2001.0, times[10], times[19] });
        }
    };
}

test "wide grouped projection families independent oracle and benchmark" {
    @setEvalBranchQuota(500_000);
    const width = 512;
    const cols = 33;
    const max_rows = 9;
    const State = struct {
        input: [max_rows * 584]u8 align(64) = @splat(0),
        storage: [3]QuantizedStorage = undefined,
        decoded: [3][cols * width]f32 = undefined,
        output: [3][max_rows * cols + 2]f32 = undefined,
        bias: [3][cols]f32 = undefined,
        fn initialize(self: *@This(), comptime q8: bool) !void {
            const allocator = std.testing.allocator;
            for (0..max_rows * 2) |block| {
                const bytes = self.input[block * 292 ..][0..292];
                const scale: f32 = if (block % 2 == 0) 0.03125 else -0.0625;
                std.mem.writeInt(u32, bytes[0..4], @bitCast(scale), .little);
                for (0..256) |i| bytes[4 + i] = @bitCast(@as(i8, @intCast(@as(i32, @intCast((i * 17 + block * 13) % 255)) - 127)));
                for (0..16) |sub| {
                    var sum: i16 = 0;
                    for (0..16) |i| sum += @as(i8, @bitCast(bytes[4 + sub * 16 + i]));
                    std.mem.writeInt(i16, bytes[260 + sub * 2 ..][0..2], sum, .little);
                }
            }
            for (&self.storage, &self.decoded, &self.bias, 0..) |*storage, *weights, *bias, projection| {
                for (weights, 0..) |*value, i| value.* = @as(f32, @floatFromInt(@as(i32, @intCast((i * 19 + projection * 31) % 67)) - 33)) * 0.03125;
                for (bias, 0..) |*value, i| value.* = @as(f32, @floatFromInt(@as(i32, @intCast((i + projection * 3) % 17)) - 8)) * 0.125;
                storage.* = .{
                    .tensor_type = .{ .known = if (q8) .Q8_K else .Q6_K },
                    .raw_bytes = if (q8) try quant_codec.quantizeQ8_KFromF32(allocator, weights) else try quant_codec.quantizeQ6_KFromF32(allocator, weights),
                    .shape = try allocator.dupe(i64, &.{ cols, width }),
                    .raw_owned = true,
                    .allocator = allocator,
                };
                try quant_codec.dequantizeToFloat32(storage.tensor_type, storage.raw_bytes, weights);
                try prepareNativeQuantizedStorage(storage);
                if (q8) {
                    try prepareQ8_KPanel8PackedStorage(storage);
                    try prepareQ8_KPanel16PackedStorage(storage);
                } else {
                    try preparePreparedKPanel8PackedStorage(storage);
                    try preparePreparedKPanel16PackedStorage(storage);
                }
            }
        }
        noinline fn run(self: *@This(), comptime q8: bool, comptime nr: usize, comptime projections: usize, rows: usize, first: usize, end: usize) void {
            var weights: [projections][]const u8 = undefined;
            var panel4: [projections]?[]const u8 = undefined;
            var panel8: [projections]?[]const u8 = undefined;
            var panel16: [projections]?[]const u8 = undefined;
            var outputs: [projections][]f32 = undefined;
            var biases: [projections]?[]const f32 = undefined;
            inline for (0..projections) |i| {
                weights[i] = if (q8) self.storage[i].raw_bytes else self.storage[i].preparedBytes(.row_major_blocks).?;
                panel4[i] = self.storage[i].preparedBytes(.panel4);
                panel8[i] = if (nr == 8) self.storage[i].preparedBytes(.panel8).? else null;
                panel16[i] = if (nr == 16) self.storage[i].preparedBytes(.panel16).? else null;
                outputs[i] = self.output[i][1 .. 1 + max_rows * cols];
                biases[i] = &self.bias[i];
            }
            if (q8) linearQ8KQ8KActivationGroupedRange(projections, &self.input, weights, panel4, panel8, panel16, outputs, biases, rows, width, cols, first, end) else linearQ6KPreparedQ8KActivationGroupedRange(projections, &self.input, weights, panel4, panel8, panel16, outputs, rows, width, cols, first, end);
        }
        fn check(self: *@This(), comptime q8: bool, comptime nr: usize, comptime projections: usize, rows: usize, first: usize, end: usize) !void {
            for (&self.output) |*out| @memset(out, 12345.0);
            self.run(q8, nr, projections, rows, first, end);
            for (0..3) |projection| {
                try std.testing.expectEqual(@as(f32, 12345), self.output[projection][0]);
                try std.testing.expectEqual(@as(f32, 12345), self.output[projection][max_rows * cols + 1]);
                for (0..max_rows) |row| for (0..cols) |column| {
                    const actual = self.output[projection][1 + row * cols + column];
                    if (projection >= projections or row >= rows or column < first or column >= end) {
                        try std.testing.expectEqual(@as(f32, 12345), actual);
                        continue;
                    }
                    var expected: f64 = if (q8) self.bias[projection][column] else 0;
                    for (0..width) |i| {
                        const block = self.input[row * 584 + i / 256 * 292 ..][0..292];
                        const scale: f32 = @bitCast(std.mem.readInt(u32, block[0..4], .little));
                        const value: i8 = @bitCast(block[4 + i % 256]);
                        expected += @as(f64, scale) * @as(f64, @floatFromInt(value)) * @as(f64, self.decoded[projection][column * width + i]);
                    }
                    try std.testing.expectApproxEqAbs(@as(f32, @floatCast(expected)), actual, 0.0002);
                };
            }
        }
        noinline fn measure(self: *@This(), comptime q8: bool, comptime nr: usize, comptime projections: usize, comptime rows: usize) u64 {
            const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
            for (0..201) |_| {
                self.input[3] ^= 0x80;
                self.run(q8, nr, projections, rows, 0, cols);
                std.mem.doNotOptimizeAway(&self.output);
            }
            return @intCast(std.Io.Clock.awake.now(std.testing.io).nanoseconds - start);
        }
    };
    inline for (.{ false, true }) |q8| {
        const state = try std.testing.allocator.create(State);
        defer std.testing.allocator.destroy(state);
        state.* = .{};
        try state.initialize(q8);
        defer for (&state.storage) |*storage| storage.deinit();
        inline for (.{ 8, 16 }) |nr| inline for (.{ 1, 2, 3 }) |projections| {
            for ([_]usize{ 1, 2, 4, 5, 9 }) |rows| {
                try state.check(q8, nr, projections, rows, 0, cols);
                try state.check(q8, nr, projections, rows, 5, cols - 1);
            }
            if (platform.env.getenvBool("ANTFLY_WIDE_PROJECTION_BENCH")) inline for (.{ 1, 2, 4 }) |rows| {
                const start = std.Io.Clock.awake.now(std.testing.io).nanoseconds;
                while (std.Io.Clock.awake.now(std.testing.io).nanoseconds - start < 25_000_000) _ = state.measure(q8, nr, projections, rows);
                var times: [21]u64 = undefined;
                for (&times) |*sample| sample.* = state.measure(q8, nr, projections, rows);
                std.mem.sort(u64, &times, {}, std.sort.asc(u64));
                std.debug.print("wide_projection q8={} nr={d} projections={d} rows={d} p50_ns={d:.6} p95_ns={d:.6} measure_iters=201\n", .{ q8, nr, projections, rows, @as(f64, @floatFromInt(times[10])) / 201.0, @as(f64, @floatFromInt(times[19])) / 201.0 });
            };
        };
    }
}

test "explicit dense workload overrides checkpoint names without a kernel fork" {
    setQuantizedDequantSgemmOverrideForBench(false);
    defer setQuantizedDequantSgemmOverrideForBench(null);
    var storage = QuantizedStorage{ .tensor_type = .{ .known = .Q4_K }, .raw_bytes = &.{}, .shape = &.{}, .raw_owned = false, .allocator = std.testing.allocator, .dense_workload = .encoder };
    try std.testing.expect(shouldUseQuantizedDequantSgemm("new_checkpoint.weight", 16, 512, &storage));
    try std.testing.expect(!shouldUseQuantizedDequantSgemm("new_checkpoint.weight", 15, 512, &storage));
    storage.dense_workload = .direct;
    try std.testing.expect(!shouldUseQuantizedDequantSgemm("span_rep.weight", 16, 512, &storage));
    storage.dense_workload = null;
    try std.testing.expect(shouldUseQuantizedDequantSgemm("span_rep.weight", 16, 512, &storage));
}
